INSERT INTO courses (id, slug, title, status, subject, description, position, requires) VALUES ('aab40d79-a597-4e18-a656-b6cc3a29ad47', 'first-lemonade-stand', '{"en-US": "My First Lemonade Stand", "es-MX": "Mi Primer Puesto de Limonada", "pt-BR": "Minha Primeira Banca de Limonada"}', 'published', 'mixed', '{"en-US": "Liruf opens a lemonade stand and you help: count coins, give exact change, set a fair price, tell needs from wants, and save what is left. One small money skill per lesson.", "es-MX": "Liruf abre un puesto de limonada y tú lo ayudas: contar monedas, dar el cambio exacto, poner un precio justo, distinguir necesidades de deseos y ahorrar lo que sobra. Una habilidad de dinero por lección.", "pt-BR": "Liruf abre uma banca de limonada e você ajuda: contar moedas, dar o troco exato, definir um preço justo, separar necessidades de desejos e poupar o que sobra. Uma habilidade de dinheiro por lição."}', '0', '[]') ON CONFLICT (id) DO NOTHING;
INSERT INTO adventures (id, course_id, position, slug, title, description, narrative_arc, theme, age_tier, status) VALUES ('2c90f904-3896-409b-aab8-7c0ecc7ab2bf', 'aab40d79-a597-4e18-a656-b6cc3a29ad47', '1', 'estacion-de-pruebas', '{"en-US": "Liruf''s Lemonade Stand", "es-MX": "El Puesto de Limonada de Liruf", "pt-BR": "A Barraca de Limonada do Liruf"}', '{"en-US": "Liruf opens his first lemonade stand and learns to count money, set prices, save, and sell — one small skill at a time.", "es-MX": "Liruf abre su primer puesto de limonada y aprende a contar dinero, poner precios, ahorrar y vender — una habilidad pequeña a la vez.", "pt-BR": "Liruf abre sua primeira barraca de limonada e aprende a contar dinheiro, definir preços, poupar e vender — uma habilidade de cada vez."}', 'Liruf quiere una guitarra que cuesta 80 pesos. Con ayuda de Dina, Rho y Zara decide ganarse el dinero con un puesto de limonada: primero imagina la idea, luego cuenta sus monedas, arma el puesto, fija un precio justo de 5 pesos por vaso, atiende a sus primeros clientes, aprende de sus errores de cuentas y, día a día, ahorra sus ganancias hasta acercarse a su meta.', 'city', 'tier2', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO sagas (id, adventure_id, position, slug, title, description, icon, status) VALUES ('9ffbe461-9967-4037-93cf-9f30b50790c7', '2c90f904-3896-409b-aab8-7c0ecc7ab2bf', '2', 'secuencias-y-repaso', '{"en-US": "Sale Days & Review", "es-MX": "Días de Venta y Repaso", "pt-BR": "Dias de Venda e Revisão"}', '{"en-US": "Full sale days that mix skills, and quick reviews to make them stick.", "es-MX": "Días de venta completos que mezclan habilidades, y repasos veloces para que se queden.", "pt-BR": "Dias de venda completos que misturam habilidades, e revisões rápidas para fixá-las."}', 'repeat', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO sagas (id, adventure_id, position, slug, title, description, icon, status) VALUES ('3467f69b-7248-4910-aec2-720d49b2db00', '2c90f904-3896-409b-aab8-7c0ecc7ab2bf', '1', 'camara-de-tipos', '{"en-US": "Opening the Stand", "es-MX": "Abrir el Puesto", "pt-BR": "Abrindo a Barraca"}', '{"en-US": "From the first idea to the first sale: money basics, one skill per lesson.", "es-MX": "De la primera idea a la primera venta: fundamentos del dinero, una habilidad por lección.", "pt-BR": "Da primeira ideia à primeira venda: fundamentos do dinheiro, uma habilidade por lição."}', 'storefront', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status, kind, review_of) VALUES ('c0517497-736c-4d14-b8d4-86e2777d7554', '3467f69b-7248-4910-aec2-720d49b2db00', '3', 'tipos-input', '{"en-US": "Stand Accounts", "es-MX": "Las Cuentas del Puesto", "pt-BR": "As Contas da Barraca"}', 'Escribir y calcular números reales del puesto: cuántos limones hay, cuánto se ganó, cuánto falta para la meta.', '{"en-US": "Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20).", "es-MX": "Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20).", "pt-BR": "Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20)."}', '["suma", "total", "contar"]', 'El precio de 5 pesos por vaso y la meta de 80.', 'published', 'teaching', '[]') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status, kind, review_of) VALUES ('46ef76be-b497-4863-b868-2baa537fd2c2', '3467f69b-7248-4910-aec2-720d49b2db00', '1', 'tipos-story', '{"en-US": "The Big Idea", "es-MX": "La Gran Idea", "pt-BR": "A Grande Ideia"}', 'Ganar dinero empieza con una idea: Liruf quiere una guitarra de 80 pesos y decide vender limonada al vecindario en lugar de solo esperar.', '{"en-US": "Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar.", "es-MX": "Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar.", "pt-BR": "Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."}', '["meta", "ganar", "vender"]', 'Ninguno — es el inicio del curso.', 'published', 'teaching', '[]') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status, kind, review_of) VALUES ('b2f8b049-5c84-4bf4-ab53-e30a7ab4563e', '3467f69b-7248-4910-aec2-720d49b2db00', '2', 'tipos-choice', '{"en-US": "Seller''s Choices", "es-MX": "Decisiones de Vendedor", "pt-BR": "Decisões do Vendedor"}', 'Un vendedor toma decisiones todo el día: qué precio poner, dónde guardar el dinero, a qué cliente atender primero y qué gastos valen la pena.', '{"en-US": "Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo.", "es-MX": "Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo.", "pt-BR": "Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo."}', '["precio", "decisión", "seguro"]', 'La meta de 80 pesos y el precio de 5 pesos por vaso.', 'published', 'teaching', '[]') ON CONFLICT (id) DO NOTHING;
