INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "¿Cuánto cuesta un vaso?", "locale": "es-MX", "subject": "money", "objectives": ["Elegir el precio justo para un vaso de limonada comparando opciones exageradas."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "title": "El precio del vaso", "payload": {"options": [{"id": "opt-1", "text_md": "1 peso", "rationale_md": "1 peso es muy barato: no alcanza para comprar los limones, y Liruf perdería dinero."}, {"id": "opt-5", "text_md": "5 pesos"}, {"id": "opt-50", "text_md": "50 pesos", "rationale_md": "50 pesos es demasiado caro: los clientes no pagarían tanto y se irían sin comprar."}], "shuffle": true}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf vende limonada. ¿Qué precio le pones a cada vaso?", "difficulty": 1, "explanation_md": "5 pesos es un precio justo: cubre el costo de los limones y los clientes lo pagan sin problema.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "opt-5"}}', '{"units": {"s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/6387874743eb20bf4c98926f8aa6a11683f4160f603ba39b95574df33a87b01d.mp3", "hash": "31a018e802a2012a5ebb2e72ba2ff69e203c35586e7cbcff664c25b55eab5b49", "bytes": 27216, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6387874743eb20bf4c98926f8aa6a11683f4160f603ba39b95574df33a87b01d.mp3", "duration_ms": 4480}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/586be3b1e40a348ff706b12fab66cef9e6371ff009045489b7d60800992b5131.mp3", "hash": "29a7937c377101cf5a65b74c2619c343da6e942da0095b3c8850409221e79335", "bytes": 19584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/586be3b1e40a348ff706b12fab66cef9e6371ff009045489b7d60800992b5131.mp3", "duration_ms": 3200}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/bf77fb9d8437dd844d389cbe5f7003b52b1886e473ce521f68f4544f65d0d1f6.mp3", "hash": "3f438fcfd020cd5922ec89f51c206ebd5e394d09d7bcad0b44e70f412c3dcec9", "bytes": 39168, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bf77fb9d8437dd844d389cbe5f7003b52b1886e473ce521f68f4544f65d0d1f6.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "¿Cierto o falso? El ahorro que crece", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si la afirmación sobre el ahorro es cierta o falsa."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "tf-ahorro", "xp": 10, "type": "true_false", "title": "Atrapa la frase", "payload": {"statement_md": "Si guardo 5 pesos de cada venta, mi ahorro crece cada día.", "justifications": [{"id": "j1", "text_md": "El ahorro crece solo si guardas todo lo de la venta, no basta con 5 pesos."}, {"id": "j2", "text_md": "Cada venta añade 5 pesos al ahorro, así que poco a poco va aumentando."}, {"id": "j3", "text_md": "5 pesos es muy poquito dinero; el ahorro no crece con monedas pequeñas."}, {"id": "j4", "text_md": "Solo crece si vendes todos los días, y la frase no lo dice."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Zara dice: ''Si guardo 5 pesos de cada venta, mi ahorro crece cada día.'' ¿Es cierto o falso?", "difficulty": 1, "explanation_md": "Guardar 5 pesos de cada venta sí hace crecer tu ahorro, porque cada 5 pesos se suman. Así, día a día el total guardado aumenta. ¡Poco a poco se logra mucho!", "audio_segment_id": "tf-ahorro.prompt"}], "schema_version": 1}', '{"tf-ahorro": {"is_true": true, "correct_justification_id": "j2"}}', '{"units": {"tf-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/c3aef74ee03b2794c9d085fdc72ff05827e46922899bc6b372e87c8517c47c16.mp3", "hash": "cb87937cb798600c9436021715a07cdca459a563d45428a0ac267d7d9733956a", "bytes": 44928, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c3aef74ee03b2794c9d085fdc72ff05827e46922899bc6b372e87c8517c47c16.mp3", "duration_ms": 7440}, "tf-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/f818bfc21f7875b63f6eab5000858afe7ee81e2cf5b8c6dbbc1fc5c69929caad.mp3", "hash": "709c576e9493ec615c4b372c8f31e95348872520af41b6159341e43a13e1213e", "bytes": 74736, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f818bfc21f7875b63f6eab5000858afe7ee81e2cf5b8c6dbbc1fc5c69929caad.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "fill-blank", "title": "Complete the profit", "locale": "en-US", "subject": "mixed", "objectives": ["Write the profit amount from a sale by subtracting the cost of the ingredients."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fill-blank", "xp": 5, "type": "fill_blank", "hints": ["Subtract the cost of ingredients from the price of the cup to find out how much she has left."], "title": "Complete the profit", "payload": {"mode": "typed", "text_md": "I sold a cup for 5 dollars, the ingredients cost 2, my profit is {{1}} dollars."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina sold a cup for 5 dollars and spent 2 on ingredients. Complete the sentence with her profit.", "difficulty": 1, "explanation_md": "Profit is what''s left after paying expenses: 5 dollars from the cup minus 2 for ingredients leaves 3 dollars.", "audio_segment_id": "s1-fill-blank.prompt"}], "schema_version": 1}', '{"s1-fill-blank": {"gaps": [{"gap": 1, "accept": ["3"]}]}}', '{"units": {"s1-fill-blank.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d2570362b84ea0c3b385f165fcb5901cfa6dfb2238e2eb36abfcf4fa6e2ecd03.mp3", "hash": "42861b0496d849c57fe0f6169b71c0a431660a065379b3a4c7a52e90008201fb", "bytes": 26208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d2570362b84ea0c3b385f165fcb5901cfa6dfb2238e2eb36abfcf4fa6e2ecd03.mp3", "duration_ms": 4320}, "s1-fill-blank.prompt": {"url": "http://localhost:4006/files/lesson-audio/1e7f3976e46eb17c83d3ea60063c00c7572f141ef77a2783d8b7cd309d5c16ae.mp3", "hash": "965519f03dc142f6cd24b718fc4fb2b24315768e3c75525e7e50bf33b84f67c4", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1e7f3976e46eb17c83d3ea60063c00c7572f141ef77a2783d8b7cd309d5c16ae.mp3", "duration_ms": 5360}, "s1-fill-blank.explanation": {"url": "http://localhost:4006/files/lesson-audio/205ca771b84f154c673985e2498df41cc27dea6f556120cd4b4c4cc5b190e324.mp3", "hash": "39f8cf342da6182144b7c1afad78b9be9b0e0d7d0b69c57b5e32a621ea1e56ce", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/205ca771b84f154c673985e2498df41cc27dea6f556120cd4b4c4cc5b190e324.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "checkpoint", "title": "Ganar dinero empieza con una idea", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "title": "La gran idea de Liruf", "payload": {"recap_md": "Liruf quiere una guitarra de juguete que cuesta 80 pesos. Para ganar ese dinero, decidió vender limonada a 5 pesos el vaso. De cada vaso que venda, lo que sobre después de pagar el costo (limones, azúcar, vasos) es su ganancia, y esa ganancia va directo a su frasco... ¡cada vez más cerca de la guitarra!", "mood_prompt_md": "¿Crees que Liruf ya siente la guitarra más cerca? 🌟"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Repasa el plan de Liruf.", "difficulty": 1, "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/0ba50182f69831a5dc2f8373c709a4877e5def222bc55cfd7d4e211fb0a1df19.mp3", "hash": "e233392ca43d31a489e73f8fb5822b7c51b7dac7708ab4569cced777d17940ad", "bytes": 119376, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ba50182f69831a5dc2f8373c709a4877e5def222bc55cfd7d4e211fb0a1df19.mp3", "duration_ms": 19840}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/38a9ec8c1a02178c0f55ea663d65b71357f42a1324c960c5604ad70286555117.mp3", "hash": "70695a7ac8e758765180be97cd7da5c7e8a1d9c9985df5fb79dedad9bf98066c", "bytes": 10944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/38a9ec8c1a02178c0f55ea663d65b71357f42a1324c960c5604ad70286555117.mp3", "duration_ms": 1760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "La guitarra de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir que el dinero para la guitarra se puede ganar vendiendo limonada, no solo esperar un regalo."], "estimated_minutes": 3}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-intro", "xp": 0, "type": "story_dialogue", "title": "La guitarra de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Qué padre está esa guitarra… pero cuesta 80 pesos. Yo no tengo tanto dinero.", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Oye, Liruf, ¿y si tú mismo la ganas vendiendo limonada? ¡Podrías juntar los 80 pesos!", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "¡Órale! ¿Crees que pueda? ¿A poco la gente compraría limonada?", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Claro que sí. Si preparas buena limonada y la vendes a 5 pesos el vaso, ¡vas a ver qué rápido juntas la meta!", "character": "dina"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/13ad009caae0689b6b46350635f5cfa1004ebc7f4ef7b4b7004f176cee8bedde.webp", "prompt_md": "Escucha la conversación entre Dina y Liruf.", "difficulty": 1, "audio_segment_id": "s1-intro.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-intro.line.0": {"url": "http://localhost:4006/files/lesson-audio/7c60b15d655f752d747aeaedac6035b368137ce6c0c594ca2d387e49e734d17c.mp3", "hash": "c6c5d2fc7918f23ac9d29919576d595e83f697e4ceb313deb596034d605a6c62", "bytes": 35856, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7c60b15d655f752d747aeaedac6035b368137ce6c0c594ca2d387e49e734d17c.mp3", "duration_ms": 5920}, "s1-intro.line.1": {"url": "http://localhost:4006/files/lesson-audio/1ef3ea40838dd00c0ee4738f5380cf037d36106110dbd484946e479178a087ff.mp3", "hash": "fef36b369224356fc18716b6bad94c8606179d66cecd16ca5b17636b4d96a205", "bytes": 42624, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1ef3ea40838dd00c0ee4738f5380cf037d36106110dbd484946e479178a087ff.mp3", "duration_ms": 7040}, "s1-intro.line.2": {"url": "http://localhost:4006/files/lesson-audio/4d64d6d76ddea1f05c25fa6ebf45311da5ed54702bd5ce1b2571b54315af069c.mp3", "hash": "aa988884a63dbf0fc62588816e6de1fd9ae7b95539afdf2bd343ca389a1be518", "bytes": 27648, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4d64d6d76ddea1f05c25fa6ebf45311da5ed54702bd5ce1b2571b54315af069c.mp3", "duration_ms": 4560}, "s1-intro.line.3": {"url": "http://localhost:4006/files/lesson-audio/2c267c56c5cc02755a67bc3e15e7a3345bde57f3ae35dcc612012d4879894909.mp3", "hash": "55826f0b4613d64fc69e29dfacde22ed332cfa350a7a018073e6b7c7b7a09368", "bytes": 46368, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2c267c56c5cc02755a67bc3e15e7a3345bde57f3ae35dcc612012d4879894909.mp3", "duration_ms": 7680}, "s1-intro.prompt": {"url": "http://localhost:4006/files/lesson-audio/d6b8aabdf694ab4d66eb52740d862ef12d894384d21e988b4bcf3f04f30c2401.mp3", "hash": "aa2b617d603ea157ebbfb55a0afd62d1ed7594dab7d8b337f1b46c9795c43d9c", "bytes": 17568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d6b8aabdf694ab4d66eb52740d862ef12d894384d21e988b4bcf3f04f30c2401.mp3", "duration_ms": 2880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-branch", "title": "The Price Decision", "locale": "en-US", "subject": "mixed", "objectives": ["Making a price decision by seeing the consequences on profits."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-decision", "xp": 0, "type": "story_branch", "title": "How much to charge?", "payload": {"nodes": [{"id": "decision", "choices": [{"id": "precio5", "next": "outcome5", "text_md": "5 dollars (the usual)"}, {"id": "precio3", "next": "outcome3", "text_md": "3 dollars (cheap)"}, {"id": "precio10", "next": "outcome10", "text_md": "10 dollars (double the price)"}], "emotion": "thinking", "text_md": "Liruf thinks: each glass costs 2 dollars to make. If I charge more, I earn more per glass… but will everyone buy? What price brings me closer to the 80-dollar guitar?", "character": "liruf"}, {"id": "outcome5", "choices": [{"id": "fin5", "next": null, "text_md": "Continue"}], "emotion": "happy", "text_md": "The 6 neighbors buy. Liruf earns 3 dollars per glass (5-2=3). In total, 18 dollars. Good progress toward the guitar!", "character": "dina"}, {"id": "outcome3", "choices": [{"id": "fin3", "next": null, "text_md": "Continue"}], "emotion": "surprised", "text_md": "The happy neighbors all buy, but Liruf only earns 1 dollar per glass. He earns 6 dollars in total, almost nothing toward the guitar.", "character": "dina"}, {"id": "outcome10", "choices": [{"id": "fin10", "next": null, "text_md": "Continue"}], "emotion": "surprised", "text_md": "The neighbors make a ''so expensive!'' face and go to the ice cream shop. Liruf sells nothing. Zero dollars for the guitar.", "character": "dina"}], "start_node": "decision"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f50e7c6688467e323319afec8f3e3e21ac38d982c301186f28f32cc457ef53a1.webp", "prompt_md": "Liruf has 6 thirsty neighbors in line and each glass costs him 2 dollars. At what price does he sell it to get closer to the 80-dollar guitar?", "difficulty": 1, "explanation_md": "With 5 dollars, Liruf earns 18 dollars in total and makes good progress toward the guitar. Lower or higher prices gave him less profit.", "audio_segment_id": "s1-precio-decision.prompt"}], "schema_version": 1}', '{"s1-precio-decision": {"qualities": [{"score": 100, "node_id": "decision", "choice_id": "precio5"}, {"score": 20, "node_id": "decision", "choice_id": "precio3"}, {"score": 0, "node_id": "decision", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/d88f5b7862938acf3aa54794ee0c2327b2980dc75af0ef20220e625261143d2b.mp3", "hash": "0eb95ae39697616b497fd34e56a45a3a52ad559952229bd3b180388b839bcefb", "bytes": 44928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d88f5b7862938acf3aa54794ee0c2327b2980dc75af0ef20220e625261143d2b.mp3", "duration_ms": 7440}, "s1-precio-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/2065ae410cb7152b4122b0f8bb806aaa22b9852bc3fdebd199824c52aff0ab85.mp3", "hash": "151aa39c3ac6f53cf9db6015772c18276f46902ac6f9ee4758f5eb47e3be16f0", "bytes": 48384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2065ae410cb7152b4122b0f8bb806aaa22b9852bc3fdebd199824c52aff0ab85.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Budget for the lemonade stand", "locale": "en-US", "subject": "money", "objectives": ["Count money with coins of 1, 2, 5, and 10, calculate change from a 20-dollar bill, and plan how many weeks are left to reach the goal."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 25, "type": "budget_fit", "hints": ["First add up what the lemons and sugar cost, then see how much you have left.", "With what''s left, try adding items one by one without going over 20."], "title": "What are we buying for tomorrow?", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Lemons", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/8e2114763dacc523d4ae74e3cb87a6557b23665ecac524fcf96298651f8b62d1.webp"}, {"id": "azucar", "icon": "coffee", "need": true, "label": "Sugar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/0491cbc67e39281f347d48a3d5fbbab8a095f324096e2746453caaabb636dc86.webp"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Ice", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/9574dc6da4a543fb842926fee0c40acde530504fa7bc70718d4270fb4a8cc69f.webp"}, {"id": "popotes", "icon": "fastfood", "need": false, "label": "Straws", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/914c8736ac650c278a905f84c142ce4aac7340881dbc35f379ad43aa78f258fb.webp"}, {"id": "jarra", "icon": "water_bottle", "need": false, "label": "Pretty pitcher", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/4052aa568eb6daeeedb7576aff035a3dc05800b16079ef4a7d3426062b135373.webp"}], "budget": 20, "currency": "USD", "must_buy_needs": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has $20. He needs to buy lemons ($8) and sugar ($6). What else can he get without going over?", "difficulty": 3, "explanation_md": "Liruf made sure to have lemons and sugar to make lemonade. If he had gone over $20, the vendor would make him return something and tomorrow they wouldn''t have lemonade to sell. And the 80-dollar guitar would get farther away!", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/285b39a838b294fd730a15580db33ee67231ef68db50dba7098ac24f10614260.mp3", "hash": "190a0c4ec5678beba6c9556a22cd2a85f9e8f4c8e60b22331f57b89baebc257f", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/285b39a838b294fd730a15580db33ee67231ef68db50dba7098ac24f10614260.mp3", "duration_ms": 4480}, "s1-budget-fit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ff9845720355f6d86817ad03fdf3930ad9678a2b51bf1fbc8d11a033c572bff7.mp3", "hash": "04f64fe2cb4126ba523541f41ae8623ef092aa8195f7d81848dd5c75ecc61231", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ff9845720355f6d86817ad03fdf3930ad9678a2b51bf1fbc8d11a033c572bff7.mp3", "duration_ms": 3760}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/008e54f45cd2f92a58458659484120b896a142cbddd71972a25619488dec0544.mp3", "hash": "dcc39d274d47bc5883bc2e0d1e977f09f8594d276f18ce095438c4ce4c399008", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/008e54f45cd2f92a58458659484120b896a142cbddd71972a25619488dec0544.mp3", "duration_ms": 7280}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/212ec17f4a7eee7d724f5a75870dd8f99dc3a25d9a5676ed38b32d367ee9ca5f.mp3", "hash": "4e5c3fd4200f1b6ae6a8506b432183a80ac99931669cf2830edcee5d9a288993", "bytes": 68544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/212ec17f4a7eee7d724f5a75870dd8f99dc3a25d9a5676ed38b32d367ee9ca5f.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "concept-reveal", "title": "Cost and Profit", "locale": "en-US", "subject": "mixed", "objectives": ["Understand the meaning of cost and profit in a lemonade business."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "concept-reveal-cost-ganancia", "xp": 0, "type": "concept_reveal", "title": "Cost and Profit", "payload": {"cards": [{"icon": "shopping_bag", "back_md": "It''s what you spend to make lemonade: lemons, sugar, cups.", "front_md": "COST", "image_url": "http://localhost:4006/files/lesson-images/7173825680a30310360248399acf0530638eac901929db1b77118bac8c141222.webp"}, {"icon": "savings", "back_md": "It''s the money you have left after paying the cost.", "front_md": "PROFIT", "image_url": "http://localhost:4006/files/lesson-images/1c3214489aab355b04677f5b88ae3587d5477eb25222f98eb5cc7febcb6cfa9b.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "To earn money and buy the guitar for 80 dollars, you need to know the cost and profit. Tap each card.", "difficulty": 1, "explanation_md": "The cost is what you spend. Profit is what you really earn after paying the cost. That''s how you know if your business works!", "audio_segment_id": "concept-reveal-cost-ganancia.prompt"}], "schema_version": 1}', '{}', '{"units": {"concept-reveal-cost-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/0b09d2ae1c4b252eaff37c7750b5edaf742df57cc10d02ea0d936bec47d12c52.mp3", "hash": "0031f70a9a71c532eea7d9d0fb851216e2c6143d0b3e941b6caab454952810c9", "bytes": 38736, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0b09d2ae1c4b252eaff37c7750b5edaf742df57cc10d02ea0d936bec47d12c52.mp3", "duration_ms": 6400}, "concept-reveal-cost-ganancia.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/9fbdb894012eebc9be6fdc98bddb49e83cc8352ade329ad0b261b408a6fd737d.mp3", "hash": "60638c1780b2eeabccc21de9da8868da3ae0593f6dfe4e0a209f38246c35e127", "bytes": 28656, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/9fbdb894012eebc9be6fdc98bddb49e83cc8352ade329ad0b261b408a6fd737d.mp3", "duration_ms": 4720}, "concept-reveal-cost-ganancia.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/3654facd829c757489cad8a33ef4835a1e39db359d359221e3164a9c40db4283.mp3", "hash": "16090943e10313d42435a656925bf19acce2bf976bbc495ba2eb06c80484f92a", "bytes": 18576, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/3654facd829c757489cad8a33ef4835a1e39db359d359221e3164a9c40db4283.mp3", "duration_ms": 3040}, "concept-reveal-cost-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/43b3dc130e794c1c2b2427ec571339287cc78036163595eb76e6bff8eb676c5e.mp3", "hash": "c133eda98379b72713b696996c84e815e3b7fdefcc46fceedd6c7d0c206d0cb4", "bytes": 44496, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/43b3dc130e794c1c2b2427ec571339287cc78036163595eb76e6bff8eb676c5e.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Write the numerical answer", "locale": "en-US", "subject": "mixed", "objectives": ["Write exact numerical answers about saving."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-answer", "xp": 5, "type": "type_answer", "title": "How much do you save?", "payload": {"max_chars": 5, "placeholder": "Write the number"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Selling 2 cups gives 10 dollars. Rho saves 15 dollars today and 10 tomorrow. Total saved?", "difficulty": 1, "explanation_md": "15 + 10 = 25. That money you save for later is called ''savings''. You already have 25 dollars saved for your goal!", "audio_segment_id": "s1-type-answer.prompt"}], "schema_version": 1}', '{"s1-type-answer": {"accept": ["25"], "keywords": ["25", "veinticinco"], "case_sensitive": false}}', '{"units": {"s1-type-answer.prompt": {"url": "http://localhost:4006/files/lesson-audio/8533f5704079ee3ef8349558faaeb88d7ca5876c6864f4fc2f02cf3e0c3d14f5.mp3", "hash": "2c28ca68933c22ee3b9e8408d367a432a9979df6e7c671a292138e10adc711d7", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8533f5704079ee3ef8349558faaeb88d7ca5876c6864f4fc2f02cf3e0c3d14f5.mp3", "duration_ms": 6320}, "s1-type-answer.explanation": {"url": "http://localhost:4006/files/lesson-audio/2883558cdb07880c63db5a1de8bf9c6f37d7397585435e01d117518bdd1799a6.mp3", "hash": "2eb63838f2544c999e9a512bb8e1167b8632d3334a105bca23391d46ec34c70a", "bytes": 50688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2883558cdb07880c63db5a1de8bf9c6f37d7397585435e01d117518bdd1799a6.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "The Money Combo", "locale": "en-US", "subject": "mixed", "objectives": ["Practice counting coins, giving change, and planning savings for a goal."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 5, "type": "coin_count", "hints": [], "title": "Closing the Register", "payload": {"target": 20, "currency": "USD", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/01cbd3a29d5ef2658b5ab7094bb51c960825465bd5125bd779b8c2d5a68b8731.webp", "prompt_md": "Count the coins the customers left. How much did Liruf collect today?", "difficulty": 1, "explanation_md": "Today, 20 dollars came in. Two 10-dollar coins add up super quickly. 💰", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 10, "type": "make_change", "hints": ["Subtract the price from the bill: 20 minus 5."], "title": "Change for the Customer", "payload": {"price": 5, "currency": "USD", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/64c8e964a1a3ef5ba6929adad07a1b48e0269d1a3915432224bc7a849faa8388.webp", "prompt_md": "The customer paid 5 dollars with a 20-dollar bill. Give her change.", "difficulty": 2, "explanation_md": "The exact change is 15 dollars. With 10 and 5, or three 5s, or any combination that makes 15. ✅", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 10, "type": "savings_goal", "hints": [], "title": "Sundays for the Guitar", "payload": {"goal": 40, "currency": "USD", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf needs 40 more dollars. They save 20 every Sunday. How many Sundays?", "difficulty": 2, "explanation_md": "At 20 per Sunday, in 2 Sundays they gather 40, just the rest for the guitar. Way to go, Liruf! 🎉", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/6c3980829930dac1f5c76162e4cd8fb25fef1b8aa5df10f1da14ff65db4c6873.mp3", "hash": "0526dfdd0a81a8fbbadad7e83bc2411e900f0b7354bcfa08c37083c8a4f0cf96", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6c3980829930dac1f5c76162e4cd8fb25fef1b8aa5df10f1da14ff65db4c6873.mp3", "duration_ms": 3760}, "s2-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/752616d0ff34ca21188237f6fd8d743b28078fc9fd2860413c7a2b2a13716b9e.mp3", "hash": "7151849aa335b9669680875d762718f797ebfcd0e1948a0080dd3b93ca341e3d", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/752616d0ff34ca21188237f6fd8d743b28078fc9fd2860413c7a2b2a13716b9e.mp3", "duration_ms": 3200}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/c24a7d412994d02023c2339301dd41f366b9591db9817f280c544f5a836c3e66.mp3", "hash": "fcf203ae1862ee443ac04f11b93a8685fab132f02d53983aad358acbaf016f5f", "bytes": 23904, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c24a7d412994d02023c2339301dd41f366b9591db9817f280c544f5a836c3e66.mp3", "duration_ms": 3920}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/a78d8ceb3c8c3440df746c1cc7d6848be2a55addb4ba1739891d1e474f8abb87.mp3", "hash": "58f55336499d0918ca21d485664163cff7adb44567f031c2bea4b895341f5251", "bytes": 31104, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a78d8ceb3c8c3440df746c1cc7d6848be2a55addb4ba1739891d1e474f8abb87.mp3", "duration_ms": 5120}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/25b8a49de8d1ea9d3eea47658e7972428a410c546bf0e20eceaf9f207b5fd049.mp3", "hash": "541e7f284010cf55b30ba05c4c3ca14e40b7ee709ac48d7108e5ca4ac2ce53d9", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/25b8a49de8d1ea9d3eea47658e7972428a410c546bf0e20eceaf9f207b5fd049.mp3", "duration_ms": 4480}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/c1ad43dc8f584fe1d33fadac467dc690e8a4e8a8b0c98bf43dac09827363aad0.mp3", "hash": "b46091b9efe360f48204178d88fd9a001f3236fb94ed87c8b74ef4020270a98d", "bytes": 39744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c1ad43dc8f584fe1d33fadac467dc690e8a4e8a8b0c98bf43dac09827363aad0.mp3", "duration_ms": 6560}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/1baff0b4b3862233f58e911827d6fbc5486356bb010a874d60c899f1c18540cd.mp3", "hash": "99607cd443a5d53734ef1675774557e9acd5fe5216402a7f96b55b01596d9fe2", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1baff0b4b3862233f58e911827d6fbc5486356bb010a874d60c899f1c18540cd.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "picture-choice", "title": "Onde guardar o dinheiro?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o lugar mais seguro para guardar os ganhos do dia."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 8, "type": "picture_choice", "title": "O lugar seguro", "payload": {"options": [{"id": "opt1", "icon": "wallet", "label": "Bolso furado", "image_url": "http://localhost:4006/files/lesson-images/4e2abf237219b8117084640a1b04964166d8a54edd652fb5fcf751357019ea9b.webp", "rationale_md": "O dinheiro poderia cair pelo buraco."}, {"id": "opt2", "icon": "savings", "label": "Cofrinho com chave", "image_url": "http://localhost:4006/files/lesson-images/9681bc52834c92a8becdd0f2853e569f8a065b99bd2ee43b8bdacc1f103ff2d3.webp"}, {"id": "opt3", "icon": "table_restaurant", "label": "Mesa da barraca", "image_url": "http://localhost:4006/files/lesson-images/c7a7477fa0d906300135e0eb029415c13f98959267fe79c5560159025bd2faee.webp", "rationale_md": "Qualquer um que passar poderia pegá-lo sem você perceber."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf terminou de vender limonada e tem 20 reais. Onde é mais seguro guardá-los?", "difficulty": 1, "explanation_md": "O cofrinho com chave mantém o dinheiro seguro; no bolso furado poderia cair e na mesa qualquer um poderia pegá-lo.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt2"}}', '{"units": {"s1-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/1765d9685ad74d8a33c21087d452a4db8b5832576cdb3b1f958848b97f2f02db.mp3", "hash": "6b1d3e2353aec04112b7643a82746a4e6cfaf8fe6af8dbe149240f078ffb624f", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1765d9685ad74d8a33c21087d452a4db8b5832576cdb3b1f958848b97f2f02db.mp3", "duration_ms": 7040}, "s1-picture-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/6335678751b51ae7ef4a9409cd0db5b6f08656732be8f6049b5f313021cc6590.mp3", "hash": "f90fb0e6e88aec37f1e130fc2fb62ef42d5869b2bbd8cb97b91c59ddfdf0bee2", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6335678751b51ae7ef4a9409cd0db5b6f08656732be8f6049b5f313021cc6590.mp3", "duration_ms": 4960}, "s1-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/7246deea3e89629171a8db0816fd967a51d05315c2ab30c529b51dcd4a8d01ef.mp3", "hash": "ea07c834a43ad926ed394cdd499738e4d35a82e501308cf28382bbb14a2b57d9", "bytes": 47808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7246deea3e89629171a8db0816fd967a51d05315c2ab30c529b51dcd4a8d01ef.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Quanto custa um copo?", "locale": "pt-BR", "subject": "money", "objectives": ["Escolher o preço justo para um copo de limonada comparando opções exageradas."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "title": "O preço do copo", "payload": {"options": [{"id": "opt-1", "text_md": "1 real", "rationale_md": "1 real é muito barato: não dá para comprar os limões, e Liruf perderia dinheiro."}, {"id": "opt-5", "text_md": "5 reais"}, {"id": "opt-50", "text_md": "50 reais", "rationale_md": "50 reais é muito caro: os clientes não pagariam tanto e iriam embora sem comprar."}], "shuffle": true}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf vende limonada. Que preço você dá para cada copo?", "difficulty": 1, "explanation_md": "5 reais é um preço justo: cobre o custo dos limões e os clientes o pagam sem problema.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "opt-5"}}', '{"units": {"s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/87ef1e99696020396944af8700582451f32f12502694ee080659efa505dd3eda.mp3", "hash": "50c568dbbdfe73ccee816c8a30b7488b25a1c74eb77f5381635db7a7622568fc", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/87ef1e99696020396944af8700582451f32f12502694ee080659efa505dd3eda.mp3", "duration_ms": 4800}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/71201d12fa3197fb59ba4669cddf6d564b77bebe6c323f74922b8de3c932e596.mp3", "hash": "237f2b4438b57a29800abc0965b26cd0f2abeabe724717a77258c5c111ec38ce", "bytes": 19584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/71201d12fa3197fb59ba4669cddf6d564b77bebe6c323f74922b8de3c932e596.mp3", "duration_ms": 3200}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/76cc13bdaa4c771271ea8169dfc61b69be1c09e6de9256b4203bbd6d390e1d0d.mp3", "hash": "e35538726e24a5b9c2a16850239af5b9087c0add05b087a8ebb3996e6cbae5d5", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/76cc13bdaa4c771271ea8169dfc61b69be1c09e6de9256b4203bbd6d390e1d0d.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-branch", "title": "A decisão do preço", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar uma decisão de preço vendo as consequências nos lucros."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-decision", "xp": 0, "type": "story_branch", "title": "Quanto cobrar?", "payload": {"nodes": [{"id": "decision", "choices": [{"id": "precio5", "next": "outcome5", "text_md": "5 reais (o de sempre)"}, {"id": "precio3", "next": "outcome3", "text_md": "3 reais (barato)"}, {"id": "precio10", "next": "outcome10", "text_md": "10 reais (o dobro)"}], "emotion": "thinking", "text_md": "Liruf pensa: cada copo custa 2 reais para fazer. Se eu cobro mais, ganho mais por copo… mas será que todos vão comprar? Qual preço me aproxima mais da guitarra de 80 reais?", "character": "liruf"}, {"id": "outcome5", "choices": [{"id": "fin5", "next": null, "text_md": "Continuar"}], "emotion": "happy", "text_md": "Os 6 vizinhos compram. Liruf ganha 3 reais por copo (5-2=3). No total, 18 reais. Bom avanço em direção à guitarra!", "character": "dina"}, {"id": "outcome3", "choices": [{"id": "fin3", "next": null, "text_md": "Continuar"}], "emotion": "surprised", "text_md": "Os vizinhos felizes compram todos, mas Liruf só ganha 1 real por copo. Ganha 6 reais no total, quase nada em direção à guitarra.", "character": "dina"}, {"id": "outcome10", "choices": [{"id": "fin10", "next": null, "text_md": "Continuar"}], "emotion": "surprised", "text_md": "Os vizinhos fazem cara de ''tão caro!'' e vão para a sorveteria. Liruf não vende nada. Zero reais para a guitarra.", "character": "dina"}], "start_node": "decision"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f50e7c6688467e323319afec8f3e3e21ac38d982c301186f28f32cc457ef53a1.webp", "prompt_md": "Liruf tem 6 vizinhos sedentos na fila e cada copo lhe custa 2 reais. A que preço ele vende para se aproximar da guitarra de 80 reais?", "difficulty": 1, "explanation_md": "Com 5 reais, Liruf ganha 18 reais no total e avança bem em direção à guitarra. Preços mais baixos ou mais altos lhe deram menos lucros.", "audio_segment_id": "s1-precio-decision.prompt"}], "schema_version": 1}', '{"s1-precio-decision": {"qualities": [{"score": 100, "node_id": "decision", "choice_id": "precio5"}, {"score": 20, "node_id": "decision", "choice_id": "precio3"}, {"score": 0, "node_id": "decision", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/feb654f03e9a51c799c8ee8765ca4c2d28cf1ed9405ee27b1a486641cd051fd6.mp3", "hash": "9a032461cf692d14a612010a43230e8de410b1929f981114a1a3bf63d759fabe", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/feb654f03e9a51c799c8ee8765ca4c2d28cf1ed9405ee27b1a486641cd051fd6.mp3", "duration_ms": 10880}, "s1-precio-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/82455de7c3027acde6489d515fa18e926bbbf91d8be9c834e53035ead9d6d23d.mp3", "hash": "8b6e2a8304803c7b03a1c84a770aeebc7565ff70f90972668cbb135e57bf0ff4", "bytes": 68544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/82455de7c3027acde6489d515fa18e926bbbf91d8be9c834e53035ead9d6d23d.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparing suppliers", "locale": "en-US", "subject": "mixed", "objectives": ["Read and compare prices and quantities in a table to choose the best buying option."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 5, "type": "compare_table", "hints": ["Look at which supplier sells the cheapest limes."], "title": "Suppliers table", "payload": {"cols": [{"id": "precio", "label": "Price"}, {"id": "cantidad", "label": "Quantity"}, {"id": "mejor-opcion", "label": "Best option"}], "rows": [{"id": "donia-lula", "label": "Doña Lula"}, {"id": "don-pepe", "label": "Don Pepe"}], "tokens": [{"id": "t1", "text_md": "5 dollars"}, {"id": "t4", "text_md": "10 limes"}, {"id": "t2", "text_md": "12 limes"}, {"id": "t3", "text_md": "6 dollars"}, {"id": "t5", "text_md": "Doña Lula"}, {"id": "t6", "text_md": "Don Pepe"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/40cbfa7b95b10b885675502cc827869da5057251fe86cacc07e877cb073286bd.webp", "prompt_md": "Doña Lula sells 12 limes for 5 dollars. Don Pepe sells 10 limes for 6 dollars. Fill in the table and choose the best option.", "difficulty": 1, "explanation_md": "Doña Lula sells 12 limes for 5 dollars, while Don Pepe sells only 10 for 6 dollars. More limes and cheaper! 🍋", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"don-pepe:precio": "t3", "don-pepe:cantidad": "t4", "donia-lula:precio": "t1", "donia-lula:cantidad": "t2", "donia-lula:mejor-opcion": "t5"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ebbec8497ace4d681bf56153c516d054f5c38e6691bef2a08f0e4d89345a35c5.mp3", "hash": "849495176e85a6ee8d476ac1c02b0e098609677799706678eaa8617d25080548", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ebbec8497ace4d681bf56153c516d054f5c38e6691bef2a08f0e4d89345a35c5.mp3", "duration_ms": 2880}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/d74f6db468f90e20f8d33b5ff5702fcde1e4996d38b9a0694ad4838da1480317.mp3", "hash": "a0db8919d92d75c326dca4bb1c491548735e82a4a078d486e1b418988685e077", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d74f6db468f90e20f8d33b5ff5702fcde1e4996d38b9a0694ad4838da1480317.mp3", "duration_ms": 7920}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/747ab0ecc2cbcfa73fc9f65c718c0a09ffa3a27fa344db38c35fb20974f86fca.mp3", "hash": "a85c83562e395dba0139847fddb8cba612749ab6544300e646cfb6a44db261f0", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/747ab0ecc2cbcfa73fc9f65c718c0a09ffa3a27fa344db38c35fb20974f86fca.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "cause-effect", "title": "Causa e efeito na barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Conectar eventos para entender como o clima afeta as vendas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 5, "type": "cause_effect", "hints": ["Pense na ordem: o que acontece primeiro? O que acontece depois? Qual é o resultado?"], "title": "O que aconteceu primeiro?", "payload": {"slots": 3, "events": [{"id": "sol", "text_md": "O dia está ensolarado e faz calor"}, {"id": "sed", "text_md": "As pessoas têm mais sede"}, {"id": "ventas", "text_md": "Liruf vende mais copos de limonada"}, {"id": "precio", "text_md": "Liruf sobe o preço para 10 reais cada copo"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ordene os eventos para mostrar como um dia ensolarado afeta as vendas de Liruf.", "difficulty": 1, "explanation_md": "Quando está calor, as pessoas têm mais sede e procuram bebidas frescas. Por isso Liruf vendeu mais limonada. Que legal! Um dia ensolarado pode ser um bom dia de vendas.", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["sol", "sed", "ventas"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/87c49f67c3847fd9abbd17088da0839dc0d200a4a0d530d2183479c24938e064.mp3", "hash": "59f785d15ebcbfb821f462f7a34dbbdd17e1381862f55658063f051edb5fbda1", "bytes": 39168, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/87c49f67c3847fd9abbd17088da0839dc0d200a4a0d530d2183479c24938e064.mp3", "duration_ms": 6480}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/700ed1f0ba1686a60438c2bc000d3e82c215f7d233dcd0b5ba104ff0bc7c77d3.mp3", "hash": "4b50f53ca9ca78f34d81eb873641fd0be49bb0c143ba5e17a4944b95f6fb0c17", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/700ed1f0ba1686a60438c2bc000d3e82c215f7d233dcd0b5ba104ff0bc7c77d3.mp3", "duration_ms": 5840}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/60bf9ba4d4fb5f56cfb91b9646bc9d2f88cfd38b1917977337c719a8abf02a0f.mp3", "hash": "a708b5327e2255c8730158c9b844e369f5c50b7baa7f2eb4017642d3b4c49453", "bytes": 69984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/60bf9ba4d4fb5f56cfb91b9646bc9d2f88cfd38b1917977337c719a8abf02a0f.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "flash-match", "title": "Flash Match de conceptos del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Relacionar a toda velocidad cada palabra del puesto con su ejemplo (ahorro→alcancía, costo→limones, ganancia→lo que sobra)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "title": "¡Emparejamiento rápido!", "payload": {"left": [{"id": "ahorro", "icon": "savings", "text_md": "Ahorro", "image_url": "http://localhost:4006/files/lesson-images/0ffd40525f559f89a315c28cefae3c02f0b06eb86bb5bca46e6212cc64565c29.webp"}, {"id": "costo", "icon": "payments", "text_md": "Costo", "image_url": "http://localhost:4006/files/lesson-images/0d509723d405ac4490776ca106a380b1285ea97752afcbfb4031a751741ffb42.webp"}, {"id": "ganancia", "icon": "trending_up", "text_md": "Ganancia", "image_url": "http://localhost:4006/files/lesson-images/9d42d4f12229d80a4c4fabb3876248a54911c4f019921e8a6490615204aadcc2.webp"}], "right": [{"id": "alcancia", "icon": "savings_outlined", "text_md": "Alcancía"}, {"id": "limones", "icon": "eco", "text_md": "Limones"}, {"id": "sobra", "icon": "monetization_on", "text_md": "Lo que sobra"}], "seconds": 20}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Relaciona cada palabra del puesto con su ejemplo.", "difficulty": 1, "explanation_md": "¡Bien hecho! Ahorro se relaciona con alcancía porque es donde guardas dinero para el futuro. Costo con limones porque son un gasto necesario. Ganancia con lo que sobra después de pagar los costos.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "sobra"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/bd96a0785779cf35b70cbb34a6c0099202a21b6cedab04581a21f7ffcf3d408e.mp3", "hash": "87fadf483bf978563570758b79706defe75428ea6adeb91b602c5f03ceca903d", "bytes": 18144, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/bd96a0785779cf35b70cbb34a6c0099202a21b6cedab04581a21f7ffcf3d408e.mp3", "duration_ms": 2960}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/052e74dcf7d690e62357b2c16cfcee2023d871210e1c4378a222d622c1c3ec49.mp3", "hash": "afb7016cf0349bc4fe1424de5b580c2470325de9b80169fd59e18cb514514cb3", "bytes": 68976, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/052e74dcf7d690e62357b2c16cfcee2023d871210e1c4378a222d622c1c3ec49.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Liruf''s Guitar", "locale": "en-US", "subject": "mixed", "objectives": ["Discovering that money for the guitar can be earned by selling lemonade, not just waiting for a gift."], "estimated_minutes": 3}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-intro", "xp": 0, "type": "story_dialogue", "title": "Liruf''s Guitar", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "That guitar is so cool... but it costs 80 dollars. I don''t have that much money.", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Hey, Liruf, what if you earn it yourself by selling lemonade? You could save up the 80 dollars!", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "No way! Do you think I could? Would people really buy lemonade?", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Of course! If you make good lemonade and sell it for 5 dollars a glass, you''ll see how fast you reach your goal!", "character": "dina"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/13ad009caae0689b6b46350635f5cfa1004ebc7f4ef7b4b7004f176cee8bedde.webp", "prompt_md": "Listen to the conversation between Dina and Liruf.", "difficulty": 1, "audio_segment_id": "s1-intro.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-intro.line.0": {"url": "http://localhost:4006/files/lesson-audio/5ca6e6f2a6bd9872a07071f0d31e8fa27274cca61a1ed900d1df9991be1c6e70.mp3", "hash": "8d43e319496688b9f3bb8a052c3df54e23a0c0bb187d19a51118d7b674af98e1", "bytes": 32544, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5ca6e6f2a6bd9872a07071f0d31e8fa27274cca61a1ed900d1df9991be1c6e70.mp3", "duration_ms": 5360}, "s1-intro.line.1": {"url": "http://localhost:4006/files/lesson-audio/cf7c150692dad1b05cd17cc91e6f8daf3595144bea0f160cbc16ce52d2f5a9dd.mp3", "hash": "995d29981a2d27976c9f61d39eb0f07219be6af34f03f82a8651d6e46a4ac0ae", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cf7c150692dad1b05cd17cc91e6f8daf3595144bea0f160cbc16ce52d2f5a9dd.mp3", "duration_ms": 4880}, "s1-intro.line.2": {"url": "http://localhost:4006/files/lesson-audio/29659f019127a3b457bdd2553d8546a2fd1a085526134d5d9aef49f9b4b43d5f.mp3", "hash": "bcddaedf3300c65e312e640d4f1e514cfe80dc8ec3c87c27b900daba6004bd26", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/29659f019127a3b457bdd2553d8546a2fd1a085526134d5d9aef49f9b4b43d5f.mp3", "duration_ms": 3920}, "s1-intro.line.3": {"url": "http://localhost:4006/files/lesson-audio/c4e5a22317cd4beb696ecbc95276465cd1e8f25dfe0c6fdeecb7d9a4405f4754.mp3", "hash": "03f4d65760f05ff9faa8964e76c806d938ca32e7756d913382f7179de1b8c46e", "bytes": 38736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c4e5a22317cd4beb696ecbc95276465cd1e8f25dfe0c6fdeecb7d9a4405f4754.mp3", "duration_ms": 6400}, "s1-intro.prompt": {"url": "http://localhost:4006/files/lesson-audio/aff25132ff104a3c4dd325a6b867ea86b82977701c91300df80ea00bb7bbf7c4.mp3", "hash": "1fb99e0fe0f70f2cd5bcc280b6326508b9dca4a7a2256b8938c6f05d4122a5b3", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/aff25132ff104a3c4dd325a6b867ea86b82977701c91300df80ea00bb7bbf7c4.mp3", "duration_ms": 2720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "number-input", "title": "Calculate total earnings", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate and write how much Liruf earned in total if they sold 4 cups at 5 dollars each (20 dollars)."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 5, "type": "number_input", "title": "The stand''s earnings", "payload": {"unit": "dollars", "decimals_hint": 0}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8bfcfe08cca66252ce7fe00d4a13461325c23b2e58f2af5bcecbda0e9383e6d2.webp", "prompt_md": "After learning about earnings, Liruf wants to calculate how much they earned today. They sold 4 cups at 5 dollars each. How much did they earn in total?", "difficulty": 1, "explanation_md": "Liruf sold 4 cups at 5 dollars each, so they earned 20 dollars in total: 4 times 5 equals 20.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 20, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/b0141f637a75953276a2851361a384acf9ce7c5d9004baef64fe547cb8a500ce.mp3", "hash": "a27e2ade67a47105064cc69643f6bfd34d3f468c2bbef5c0afa66bbb91474930", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b0141f637a75953276a2851361a384acf9ce7c5d9004baef64fe547cb8a500ce.mp3", "duration_ms": 8080}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/d1dae943e1bf2682aed3efe5989990c3d67c41093a2846e928b75e9c3271c837.mp3", "hash": "cdd682746a55752384d4adbcb4e28c38c9a0fd0e0bc709f1610d99df4eecd72e", "bytes": 40176, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d1dae943e1bf2682aed3efe5989990c3d67c41093a2846e928b75e9c3271c837.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "order-steps", "title": "Prioridad de compras en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar compras por prioridad de venta (primero lo que genera ingresos)", "Distinguir entre necesidades esenciales y gustos que pueden esperar"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-priority-order", "xp": 15, "type": "order_steps", "hints": ["Piensa: ¿qué necesita Liruf para poder vender limonada hoy?"], "title": "El orden de las compras", "payload": {"items": [{"id": "calcomanias", "icon": "sticky_note_2", "text_md": "Calcomanías", "image_url": "http://localhost:4006/files/lesson-images/fc123b0b72dab8a58fa5c6f187bd42c09dac17902915f6669601732854c960fc.webp"}, {"id": "azucar", "icon": "cookie", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/19a0bb5beaf6d69b100b43441414f87e1f2c9950d211918df0fadb7a3c1afe61.webp"}, {"id": "vasos", "icon": "local_drink", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/4ad037f5498f6f3336634dc26b700671f304edf3cee5f8580d49cb81d079bc71.webp"}, {"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/aaba518fa154db8e4e43213decf74dcc3f438cd9441885b9a5a8faf03fd2a962.webp"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Liruf tiene 20 pesos para comprar lo del puesto. Ordena las compras de la más urgente a la que puede esperar.", "difficulty": 2, "explanation_md": "¡Los limones y los vasos son indispensables para vender hoy! El azúcar ayuda a que la limonada sepa rica y se venda más, pero puede esperar después de tener lo básico. Las calcomanías son un gusto que no ayuda a ganar dinero hoy, así que van al último.", "audio_segment_id": "s1-priority-order.prompt"}], "schema_version": 1}', '{"s1-priority-order": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-priority-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d3a7d33adfe34b335e7cf5cfc510d539b2ab8d9c861a232bb3c2b1c6a96a578c.mp3", "hash": "6a9f708f3e3981ec1d6e3c8aade35a36ebf333ac5e7112cf8c5f9602a7625e9d", "bytes": 23904, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d3a7d33adfe34b335e7cf5cfc510d539b2ab8d9c861a232bb3c2b1c6a96a578c.mp3", "duration_ms": 3920}, "s1-priority-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/9b3d23d2def104be281b14804137dc7aafab87616f639c57b2493182d446f8c1.mp3", "hash": "5dfe5b3a6a521eb150e4d79758fc9945b5c820803c45d5ea3520968ae9cdcc37", "bytes": 40608, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/9b3d23d2def104be281b14804137dc7aafab87616f639c57b2493182d446f8c1.mp3", "duration_ms": 6720}, "s1-priority-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/0e944f5395a62ca814824066d54f48e492f6534fd2c04de95c9e0d1180c35299.mp3", "hash": "95bac8b33829f4b3ee889f01e88a013201aca571ab8a534bf5cc70c9e91ffd5b", "bytes": 89568, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/0e944f5395a62ca814824066d54f48e492f6534fd2c04de95c9e0d1180c35299.mp3", "duration_ms": 14880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "flash-match", "title": "Flash Match de conceitos da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Relacionar a toda velocidade cada palavra da barraca com seu exemplo (poupança→cofrinho, custo→limões, lucro→o que sobra)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "title": "Emparelhamento rápido!", "payload": {"left": [{"id": "ahorro", "icon": "savings", "text_md": "Poupança", "image_url": "http://localhost:4006/files/lesson-images/0ffd40525f559f89a315c28cefae3c02f0b06eb86bb5bca46e6212cc64565c29.webp"}, {"id": "costo", "icon": "payments", "text_md": "Custo", "image_url": "http://localhost:4006/files/lesson-images/0d509723d405ac4490776ca106a380b1285ea97752afcbfb4031a751741ffb42.webp"}, {"id": "ganancia", "icon": "trending_up", "text_md": "Lucro", "image_url": "http://localhost:4006/files/lesson-images/9d42d4f12229d80a4c4fabb3876248a54911c4f019921e8a6490615204aadcc2.webp"}], "right": [{"id": "alcancia", "icon": "savings_outlined", "text_md": "Cofrinho"}, {"id": "limones", "icon": "eco", "text_md": "Limões"}, {"id": "sobra", "icon": "monetization_on", "text_md": "O que sobra"}], "seconds": 20}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Relacione cada palavra da barraca com seu exemplo.", "difficulty": 1, "explanation_md": "Muito bem! Poupança se relaciona com cofrinho porque é onde você guarda dinheiro para o futuro. Custo com limões porque são um gasto necessário. Lucro com o que sobra depois de pagar os custos.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "sobra"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/b1d6ae5bb00542f518c6dcf989e2fe682ce1eeb24c08ac0fd1a5d789f66c86b1.mp3", "hash": "3a905e197d3142e0595de9f9411984f7787b37aaa5284cee78d7794904e53b9a", "bytes": 20016, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b1d6ae5bb00542f518c6dcf989e2fe682ce1eeb24c08ac0fd1a5d789f66c86b1.mp3", "duration_ms": 3280}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/f05b98644bcc0a38e56d77ac6400fda3cef34054787c0bb18c8cce18919ef333.mp3", "hash": "d333003a34ab8a0a910a0737cf40fa6623f4cd768dee8c283e0e10bdfa95bb2f", "bytes": 74304, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/f05b98644bcc0a38e56d77ac6400fda3cef34054787c0bb18c8cce18919ef333.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "make-change", "title": "O troco exato", "locale": "pt-BR", "subject": "money", "objectives": ["Dar o troco exato com moedas brasileiras."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "make-change-1", "xp": 15, "type": "make_change", "hints": ["Primeiro, quanto custam juntos o copo e o biscoito?"], "title": "O troco do Seu Beto", "payload": {"price": 8, "currency": "BRL", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1ec2980cf3606b107e29793911a8353d6e52db87692285a5a7f745091f28ee47.webp", "prompt_md": "Seu Beto comprou 1 copo de limonada (5 reais) e 1 biscoito (3 reais). Pagou com uma nota de 20 reais. Toque nas moedas para dar o troco exato.", "difficulty": 2, "explanation_md": "A compra do Seu Beto somou 8 reais (5 do copo + 3 do biscoito). Como pagou com 20 reais, o troco exato é 20 - 8 = 12 reais. Com as moedas que você usou, você deu exatamente esses 12 reais.", "audio_segment_id": "make-change-1.prompt"}], "schema_version": 1}', '{"make-change-1": {}}', '{"units": {"make-change-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dd5423b12b0238bd5a4ee35fd27aa5b6fdac14c2edd866e7a31cf527cd47bece.mp3", "hash": "fd6da3b84c860f51acb564ce51c4901af4a61950e70ad28d8df66dc7e8095cd3", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dd5423b12b0238bd5a4ee35fd27aa5b6fdac14c2edd866e7a31cf527cd47bece.mp3", "duration_ms": 4000}, "make-change-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/92d96329e51279182ba249fa35a9083d6ce0a3c532fceaed4e7ddae9ff2e69d7.mp3", "hash": "acebb9fff81249422797c67d9d96619ba3c31499d3d5786332fc51e36d063b29", "bytes": 72288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/92d96329e51279182ba249fa35a9083d6ce0a3c532fceaed4e7ddae9ff2e69d7.mp3", "duration_ms": 12000}, "make-change-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/9b0bf2cc45f568600f833bcd3d29faf20e850236bab4859430e75aca7b6999bd.mp3", "hash": "0a94596400f86537c70bd30439fb8772c41f4c1accac0fc8a2bb36e8fb167932", "bytes": 101664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9b0bf2cc45f568600f833bcd3d29faf20e850236bab4859430e75aca7b6999bd.mp3", "duration_ms": 16880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "measure-read", "title": "The measuring cup", "locale": "en-US", "subject": "mixed", "objectives": ["Read measurements on a measuring cup to ensure fair portions."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-jarra", "xp": 15, "type": "measure_read", "hints": ["Count the marks every 50 ml: 0, 50, 100... Notice where the surface is."], "title": "The measuring cup", "payload": {"max": 500, "min": 0, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/c78198cd49aa96de68bc80d197c016ba65b7e276a975bd12c4d3dafc6c0dffe6.webp", "prompt_md": "Rho brought the measuring cup. Look at how far the liquid rose. How many milliliters does it show?", "difficulty": 2, "explanation_md": "The liquid reaches 250 ml. Liruf makes sure each glass is the same, just like the barter scale!", "audio_segment_id": "s1-jarra.prompt"}], "schema_version": 1}', '{"s1-jarra": {"value": 250, "tolerance": 0}}', '{"units": {"s1-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f860af7d85229651a62d3d7a5359403c9b46603e3fedf11faf2d9b3f48786f69.mp3", "hash": "a0f8a5536259fdd7c8cda587ec8c7c609e40a88c62cc8639e54a5f2e50b1cd8c", "bytes": 43056, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/f860af7d85229651a62d3d7a5359403c9b46603e3fedf11faf2d9b3f48786f69.mp3", "duration_ms": 7120}, "s1-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/6197e34eb6366e9f4f6bbc9930cb2b408c21db1a305c377aa3094d40e8359ed5.mp3", "hash": "d548cca993c81b291d5d289d5412fc0bf8c6780b9d85fd7ec32027c3a60185e3", "bytes": 39744, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6197e34eb6366e9f4f6bbc9930cb2b408c21db1a305c377aa3094d40e8359ed5.mp3", "duration_ms": 6560}, "s1-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/c1e461defa2ead80ae2e2e50b5db82a866df7da6c86f542195398c67d5296ca4.mp3", "hash": "95a6e44a2e60a11b2eae4e154e4e38c6fb8cd2819feaf8d3a9f708f994c328de", "bytes": 52704, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c1e461defa2ead80ae2e2e50b5db82a866df7da6c86f542195398c67d5296ca4.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "¿Ayuda o no ayuda?", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 25, "type": "yes_no_cases", "hints": ["Piensa: si compras esto, ¿te ayuda a hacer más limonada o a vender más?", "Los gastos que no ayudan al puesto no te traerán más dinero."], "title": "Gastos que ayudan al puesto", "payload": {"cases": [{"id": "c1", "icon": "eco", "text_md": "Más limones", "image_url": "http://localhost:4006/files/lesson-images/955e4f80e4c7384ac08886b5553fa555adec21de7ad26d190e21a81335f7d17a.webp"}, {"id": "c2", "icon": "emoji_objects", "text_md": "Un juguete nuevo", "image_url": "http://localhost:4006/files/lesson-images/8054ead296dd0a5b0b8ea33bea639f333c1aa41948435d21f358e6aaad20bf0b.webp"}, {"id": "c3", "icon": "local_cafe", "text_md": "Vasos de plástico", "image_url": "http://localhost:4006/files/lesson-images/3818e7f79ddd9376bc369a651642533f74a3c5426c897b460e779476fc2cc649.webp"}, {"id": "c4", "icon": "icecream", "text_md": "Una paleta de dulce", "image_url": "http://localhost:4006/files/lesson-images/f15bd865f72931445f6294e51726e53d627f9ad6599408a65f47c485287824e7.webp"}, {"id": "c5", "icon": "ac_unit", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/b871b823e74f2e0ab53bafbedcce60ab0c087a15ff1a90c2ac522a37ce9ed2c7.webp"}, {"id": "c6", "icon": "sticky_note_2", "text_md": "Un cartel para anunciar", "image_url": "http://localhost:4006/files/lesson-images/bc3a1368c1355f5a7a642d797747a809e54bcb9e4ff8cb65ecda234fdedf6bed.webp"}], "rule_md": "Gasta dinero solo en cosas que ayudan a vender más limonada."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de contar el cambio justo, Liruf revisa sus gastos. ¿Ayudan a vender más limonada?", "difficulty": 3, "explanation_md": "¡Liruf aprendió a gastar en lo que ayuda al puesto! Un juguete nuevo no le dará más ventas. 🍋", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3", "c5", "c6"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/105e36c267201df5cd7ae50b9840d77241900178f98e7ba02ab3bedc4c37dc5e.mp3", "hash": "669f14ac09927214f0e7ae7ac14ada7c367e5f43445b3521c3852d6c5a2bda6b", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/105e36c267201df5cd7ae50b9840d77241900178f98e7ba02ab3bedc4c37dc5e.mp3", "duration_ms": 5120}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/95cf338213f0c32fd0b78aa03650c24f1cd6abe7210d769eee0ce01fda182a0b.mp3", "hash": "99bcc68a3fb3cf7ee1132b3ec6cce7896f99d65fb14f369e5a17b3f12d53273d", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/95cf338213f0c32fd0b78aa03650c24f1cd6abe7210d769eee0ce01fda182a0b.mp3", "duration_ms": 4400}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/37f70d403311eb8758f05c5d717f9fec341957fc1066a24eed22a8ca567e7483.mp3", "hash": "ebbfaa79e5d20cdce8f45b82bff8a3b5ef5a78461ca18eb9eb649b832d888422", "bytes": 42624, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/37f70d403311eb8758f05c5d717f9fec341957fc1066a24eed22a8ca567e7483.mp3", "duration_ms": 7040}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/a3e68f687a24e22d4ae4604c458eb1c97b9c07da9b0de70acf5adaff47954d3b.mp3", "hash": "2331edf4f9bb4af1ecea5375d290611c0c216fd6c948597d2f47252f72574aab", "bytes": 51696, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a3e68f687a24e22d4ae4604c458eb1c97b9c07da9b0de70acf5adaff47954d3b.mp3", "duration_ms": 8560}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/9771b9dce0d92f4bc3ec701b3f176000d4d7a69bff8c14ef73fda09141211f57.mp3", "hash": "5d18170ca1147a01e091bee575c7d343a3a670cb8bb0ec73b60281c5df2572bc", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9771b9dce0d92f4bc3ec701b3f176000d4d7a69bff8c14ef73fda09141211f57.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Ajuda ou não ajuda?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões simples de dinheiro comparando opções: preço justo, lugar seguro para guardar e distinguir um bom negócio de um mau negócio."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 25, "type": "yes_no_cases", "hints": ["Pense: se comprar isso, ajuda a fazer mais limonada ou a vender mais?", "Os gastos que não ajudam a barraca não vão trazer mais dinheiro."], "title": "Gastos que ajudam a barraca", "payload": {"cases": [{"id": "c1", "icon": "eco", "text_md": "Mais limões", "image_url": "http://localhost:4006/files/lesson-images/955e4f80e4c7384ac08886b5553fa555adec21de7ad26d190e21a81335f7d17a.webp"}, {"id": "c2", "icon": "emoji_objects", "text_md": "Um brinquedo novo", "image_url": "http://localhost:4006/files/lesson-images/8054ead296dd0a5b0b8ea33bea639f333c1aa41948435d21f358e6aaad20bf0b.webp"}, {"id": "c3", "icon": "local_cafe", "text_md": "Copos de plástico", "image_url": "http://localhost:4006/files/lesson-images/3818e7f79ddd9376bc369a651642533f74a3c5426c897b460e779476fc2cc649.webp"}, {"id": "c4", "icon": "icecream", "text_md": "Um pirulito", "image_url": "http://localhost:4006/files/lesson-images/f15bd865f72931445f6294e51726e53d627f9ad6599408a65f47c485287824e7.webp"}, {"id": "c5", "icon": "ac_unit", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/b871b823e74f2e0ab53bafbedcce60ab0c087a15ff1a90c2ac522a37ce9ed2c7.webp"}, {"id": "c6", "icon": "sticky_note_2", "text_md": "Um cartaz para anunciar", "image_url": "http://localhost:4006/files/lesson-images/bc3a1368c1355f5a7a642d797747a809e54bcb9e4ff8cb65ecda234fdedf6bed.webp"}], "rule_md": "Gaste dinheiro apenas em coisas que ajudam a vender mais limonada."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de contar o troco justo, Liruf revisa seus gastos. Ajudam a vender mais limonada?", "difficulty": 3, "explanation_md": "Liruf aprendeu a gastar no que ajuda a barraca! Um brinquedo novo não lhe dará mais vendas. 🍋", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3", "c5", "c6"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4c4c60ccba1e40fabacc404fe8de158e656ce7df164c4716ad9adf645692fd1e.mp3", "hash": "859c616e3dcae366887e0e99fbe7b316ee6ef7e82f978ac9c443fa18a6feb38f", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4c4c60ccba1e40fabacc404fe8de158e656ce7df164c4716ad9adf645692fd1e.mp3", "duration_ms": 5440}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7436dc8cca45a44232b7b30692249408ea901181fced5d151a9f5e48bc276c75.mp3", "hash": "11be83551e5742cf657efd39b847d05c97fb84f06e0ec062f6b90844971f4062", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7436dc8cca45a44232b7b30692249408ea901181fced5d151a9f5e48bc276c75.mp3", "duration_ms": 4080}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/bdf0590f831c0307ab8b65e50f340469761fd5f25996df1e6378910add3b521e.mp3", "hash": "af8f64a35bcaf382a6d708e7ed2c9586603a2789f65816eb11544a45b1a53051", "bytes": 39168, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bdf0590f831c0307ab8b65e50f340469761fd5f25996df1e6378910add3b521e.mp3", "duration_ms": 6480}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/19b89a7feedcbb9456d296e5d05f12237d1819b684eb7f24e0516cf68d3e0383.mp3", "hash": "609a334dda39387edbc6c1e3cee2a3cdb11c5bc4030fd9f87e6df1227f538918", "bytes": 48816, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/19b89a7feedcbb9456d296e5d05f12237d1819b684eb7f24e0516cf68d3e0383.mp3", "duration_ms": 8080}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/3f0e55683a2588bebd6428ab1fef3266c7d39182b5d56397c58cc1bd68fa3944.mp3", "hash": "aaf428d2b23319a6b3818134f40db475ff4a4a617cb4ad1b6c88196158163e54", "bytes": 38736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3f0e55683a2588bebd6428ab1fef3266c7d39182b5d56397c58cc1bd68fa3944.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "number-input", "title": "Calcular ganhos totais", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular e escrever quanto Liruf ganhou no total se vendeu 4 copos a 5 reais cada um (20 reais)."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 5, "type": "number_input", "title": "Os ganhos da barraca", "payload": {"unit": "reais", "decimals_hint": 0}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8bfcfe08cca66252ce7fe00d4a13461325c23b2e58f2af5bcecbda0e9383e6d2.webp", "prompt_md": "Depois de aprender sobre ganhos, Liruf quer calcular quanto ganhou hoje. Vendeu 4 copos a 5 reais cada um. Quanto ganhou no total?", "difficulty": 1, "explanation_md": "Liruf vendeu 4 copos a 5 reais cada um, então ganhou 20 reais no total: 4 vezes 5 é igual a 20.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 20, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/8344468e5c6de34c65b90a70cc80bf21f130ff0599333745062eb44692568109.mp3", "hash": "3d461034b4a7ef9f4546f61fe29263a10f14e2b4530e9934f0f88c63b4ec3933", "bytes": 63648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8344468e5c6de34c65b90a70cc80bf21f130ff0599333745062eb44692568109.mp3", "duration_ms": 10560}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/4095930957a2a0243ba6145bedc4ef60cb474ea4f39b112eb0eb9f0d6860f7d9.mp3", "hash": "0cbc35d7baaeb5b2c02f3fc7d0ebfd48b8a0ecb907c099cf1a379440c91bf02d", "bytes": 53136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4095930957a2a0243ba6145bedc4ef60cb474ea4f39b112eb0eb9f0d6860f7d9.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "confidence-quiz", "title": "How much did Liruf earn?", "locale": "en-US", "subject": "mixed", "objectives": ["Practice quick addition with money and assess confidence in the answers."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confianza", "xp": 10, "type": "confidence_quiz", "title": "Confidence in Addition", "payload": {"options": [{"id": "opt5", "text_md": "5 dollars", "rationale_md": "You only counted one glass. They were two glasses at 5 dollars each."}, {"id": "opt10", "text_md": "10 dollars"}, {"id": "opt15", "text_md": "15 dollars", "rationale_md": "You counted three glasses. You only sold two glasses."}, {"id": "opt25", "text_md": "25 dollars", "rationale_md": "You multiplied 5 by 5, but they were two glasses at 5 dollars each."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf sold two glasses of lemonade at 5 dollars each. How much money did he earn?", "difficulty": 1, "explanation_md": "Two glasses at 5 dollars each add up to 10 dollars. Liruf earned 10 dollars from those two sales! 🍋", "audio_segment_id": "s1-confianza.prompt"}], "schema_version": 1}', '{"s1-confianza": {"correct_option_id": "opt10"}}', '{"units": {"s1-confianza.prompt": {"url": "http://localhost:4006/files/lesson-audio/90d44881111872c8e817749dd2e7ebdcd606bea9327909737a4d1da69195885e.mp3", "hash": "f502908f8e4efb083eaf837b51c5f8e53891d614fcb6cb3f5d91313b5f08d815", "bytes": 31968, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/90d44881111872c8e817749dd2e7ebdcd606bea9327909737a4d1da69195885e.mp3", "duration_ms": 5280}, "s1-confianza.choices": {"url": "http://localhost:4006/files/lesson-audio/55fd0b1b16e5b566da2bb989f19e6e03b27c6cf22637c37b6b181c3d08ede18e.mp3", "hash": "52202eb43f0857178758fb7c92ff3b491362fe79c6389ad3406d8a63cf9a554d", "bytes": 25776, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/55fd0b1b16e5b566da2bb989f19e6e03b27c6cf22637c37b6b181c3d08ede18e.mp3", "duration_ms": 4240}, "s1-confianza.explanation": {"url": "http://localhost:4006/files/lesson-audio/166dc1f46c1cff11de0e577e3788b73f24f8735e082d56fc29e535cd5acdea44.mp3", "hash": "c1da7c61b1918bdf422e87764baf78075d19c894713c7eb8c9d1fbd4dbb41885", "bytes": 42048, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/166dc1f46c1cff11de0e577e3788b73f24f8735e082d56fc29e535cd5acdea44.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "confidence-quiz", "title": "¿Cuánto ganó Liruf?", "locale": "es-MX", "subject": "mixed", "objectives": ["Practicar sumas rápidas con dinero y evaluar la seguridad en las respuestas."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confianza", "xp": 10, "type": "confidence_quiz", "title": "Confianza en la suma", "payload": {"options": [{"id": "opt5", "text_md": "5 pesos", "rationale_md": "Solo contaste un vaso. Eran dos vasos de 5 pesos."}, {"id": "opt10", "text_md": "10 pesos"}, {"id": "opt15", "text_md": "15 pesos", "rationale_md": "Contaste tres vasos. Solo vendiste dos vasos."}, {"id": "opt25", "text_md": "25 pesos", "rationale_md": "Multiplicaste 5 por 5, pero fueron dos vasos de 5 pesos."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf vendió dos vasos de limonada a 5 pesos cada uno. ¿Cuánto dinero ganó?", "difficulty": 1, "explanation_md": "Dos vasos de 5 pesos cada uno suman 10 pesos. ¡Liruf ganó 10 pesos con esas dos ventas! 🍋", "audio_segment_id": "s1-confianza.prompt"}], "schema_version": 1}', '{"s1-confianza": {"correct_option_id": "opt10"}}', '{"units": {"s1-confianza.prompt": {"url": "http://localhost:4006/files/lesson-audio/8a688555ab385de51946ce1d1cb1ce207104c1c46cf499d89a065148f8544c57.mp3", "hash": "887508f037867cece9baea217dd8b415b77d2fcd50cc7c5e64853ca10076b006", "bytes": 36288, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/8a688555ab385de51946ce1d1cb1ce207104c1c46cf499d89a065148f8544c57.mp3", "duration_ms": 6000}, "s1-confianza.choices": {"url": "http://localhost:4006/files/lesson-audio/3302dc201d4251de6ddaa20234b0adafa2c2b6e4ba07ed3a79a3cd1c3c376c52.mp3", "hash": "9f8d271cd0a2be384f002d91107db909118febce31063dfd5019b627b7bcadc0", "bytes": 30528, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/3302dc201d4251de6ddaa20234b0adafa2c2b6e4ba07ed3a79a3cd1c3c376c52.mp3", "duration_ms": 5040}, "s1-confianza.explanation": {"url": "http://localhost:4006/files/lesson-audio/825ddeecc15702330edf1b3b884d59c0436a334254a56085595bc9031f1effbe.mp3", "hash": "36f18a135cb88a013889ebb3807485cb521ca4737205e3f23888581487396fa5", "bytes": 46368, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/825ddeecc15702330edf1b3b884d59c0436a334254a56085595bc9031f1effbe.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "memory-flip", "title": "Jogo da memória de preços da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combine cada produto com o pagamento exato usando os preços da barraca."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "memory-flip-prices", "xp": 15, "type": "memory_flip", "hints": ["Os preços de ontem: biscoito 3, copo pequeno 5, jarra 20."], "title": "Combine os preços", "payload": {"pairs": [{"a_md": "Biscoito", "b_md": "1 e 2 reais", "a_icon": "cookie", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/7e08eb104527f9e19b43e6f4c46fde6f687edc06508a674a213c437a2c701052.webp", "b_image_url": "http://localhost:4006/files/lesson-images/e612cd7c6ecc289a9dc1586e5016094c1bf5a4a67f986825c198db17d1822f4b.webp"}, {"a_md": "Copo pequeno", "b_md": "5 reais", "a_icon": "local_drink", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/c4981a45d33ffb26545f219cc83c32f909327aab9e0dffe06b21aa4828b8feac.webp", "b_image_url": "http://localhost:4006/files/lesson-images/e0347735f17251ad0deaff00ce72847ee14f922161da80b671936a4bab1502ef.webp"}, {"a_md": "Jarra grande", "b_md": "10 e 10 reais", "a_icon": "local_bar", "b_icon": "currency_exchange", "a_image_url": "http://localhost:4006/files/lesson-images/73e4853ef3cef5374997f20b8ace852298c49c69573a6c420466638c0e6e57a7.webp", "b_image_url": "http://localhost:4006/files/lesson-images/cffded90b4eb127e36abec5e5b25c697762bb2b09e64fbf01bf6fe8ab0495a2d.webp"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Combine cada produto com as moedas que o pagam.", "difficulty": 2, "explanation_md": "O biscoito custa 3 reais, o copo pequeno 5 e a jarra 20. Saber os preços de memória te torna um caixa veloz!", "audio_segment_id": "memory-flip-prices.prompt"}], "schema_version": 1}', '{}', '{"units": {"memory-flip-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/662bca26bfa0c8c150a90d4efb8547950d4c08693e475eb301ea46f7b1666ced.mp3", "hash": "fdfb963eb4792a275309770ac1ddf9cac028a58125ff4b4877886cb74f4ad78a", "bytes": 31104, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/662bca26bfa0c8c150a90d4efb8547950d4c08693e475eb301ea46f7b1666ced.mp3", "duration_ms": 5120}, "memory-flip-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc3969ce56b287d27a40183556dceb318c922c2e9b04c903c1f9d4387f815318.mp3", "hash": "d9f995b0cc06dbf951e5575a20039a5f4ede06736e2adbc5b4a80ba261b2fa2a", "bytes": 18144, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/fc3969ce56b287d27a40183556dceb318c922c2e9b04c903c1f9d4387f815318.mp3", "duration_ms": 2960}, "memory-flip-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/9c89a8d1bc556ace59f2e970f8721f46e1db29b9749da02feb28bfe3a0caa6fb.mp3", "hash": "ca3cf5bd30a229d01438f73fd113012407e96e802320822c826b0864c8a37d81", "bytes": 55008, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/9c89a8d1bc556ace59f2e970f8721f46e1db29b9749da02feb28bfe3a0caa6fb.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "coin-count", "title": "Counting coins for Liruf", "locale": "en-US", "subject": "money", "objectives": ["Count coins of 1 and 2 dollars to make exactly 5 dollars."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "coin-count-1", "xp": 10, "type": "coin_count", "hints": ["You can combine 1 and 2 dollar coins to reach 5."], "title": "Let''s count coins!", "payload": {"target": 5, "currency": "USD", "denominations": [1, 2]}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/39d8853ecca3654b562f001ec0a643790e936fb5734778b4d10e0dd0313ec9dc.webp", "prompt_md": "A customer paid with 1 and 2 dollar coins. Combine the coins to make exactly 5 dollars.", "difficulty": 1, "explanation_md": "The cup costs 5 dollars. With 1 and 2 dollar coins, one way to combine them is 2+2+1 or 1+1+1+1+1. You decide how!", "audio_segment_id": "coin-count-1.prompt"}], "schema_version": 1}', '{"coin-count-1": {}}', '{"units": {"coin-count-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/db8b810af6cb7e1174075942e1050051bc112b5b54dfedc20bf172f0713f295d.mp3", "hash": "2e3bf8663c909d987cef0f572e31828ac0c3510fb1cc054eecbe2029511051dd", "bytes": 21888, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/db8b810af6cb7e1174075942e1050051bc112b5b54dfedc20bf172f0713f295d.mp3", "duration_ms": 3600}, "coin-count-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/27de0d7aa61d05fbad447da5902ee6ae1cded6047f45bd6dbfe80d338fe88c8a.mp3", "hash": "3cb1878a48df9a993781029151ca794a698187b53fbb677393302791c49a5e7c", "bytes": 36288, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/27de0d7aa61d05fbad447da5902ee6ae1cded6047f45bd6dbfe80d338fe88c8a.mp3", "duration_ms": 6000}, "coin-count-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/649806659848d160300510151d5df377de881bd98e463b97986f603cec7a2c0e.mp3", "hash": "afc4e79f74411bec6c9e631c9c21011184f6ee7d22a691ba09d55b67df474d6b", "bytes": 69408, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/649806659848d160300510151d5df377de881bd98e463b97986f603cec7a2c0e.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "number-line", "title": "La recta del ahorro", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar en la recta numérica del 0 al 100 dónde va el ahorro de Liruf (20 pesos) y dónde la meta (80): ver cuánto falta."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 5, "type": "number_line", "title": "¿Cuánto falta?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Después de agrupar monedas y billetes, Liruf quiere ver cuánto le falta. Coloca su ahorro (20 pesos) en la recta.", "difficulty": 1, "explanation_md": "Liruf ya tiene 20 pesos. La meta es 80, que está mucho más a la derecha. ¡Le faltan 60 pesos para la patineta! 🎉", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 0, "zero_credit_delta": 10}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/9cb49807a9df802a2bf4605faa8019f33370cd671c3d8c428583706fae9f7b9e.mp3", "hash": "59e20a250ae7d9bc5fad8f4dc79a4069bf34d9fa4f0e15f2d32dc53190092cce", "bytes": 52704, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9cb49807a9df802a2bf4605faa8019f33370cd671c3d8c428583706fae9f7b9e.mp3", "duration_ms": 8720}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/5d7294a010501a9239707130a7041ea02e121c0fc850d8cbed66c6d6ed6c0b18.mp3", "hash": "ab4a6178fed90fea4e7966d797831b7d8cd829d3e57e695236ce27c7c3cc165b", "bytes": 60768, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5d7294a010501a9239707130a7041ea02e121c0fc850d8cbed66c6d6ed6c0b18.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "best-decision", "title": "A melhor decisão ao dar troco", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher a melhor decisão quando um cliente paga com nota de 20 por um copo de 5: contar o troco com calma (não adivinhar nem ficar com ele)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 10, "type": "best_decision", "title": "O troco de Liruf", "payload": {"options": [{"id": "count-change", "text_md": "Contar o troco: 15 reais em moedas", "rationale_md": "Contar o troco com calma garante que o cliente receba a quantia exata e mantém a confiança na barraquinha."}, {"id": "guess-change", "text_md": "Adivinhar e dar 10 reais", "rationale_md": "É tentador adivinhar para ser rápido, mas você daria R$5 a menos e o cliente iria embora com menos dinheiro do que merece."}, {"id": "keep-change", "text_md": "Ficar com a nota e não dar troco", "rationale_md": "É tentador ficar com tudo, mas é desonesto e o cliente ficaria bravo, além de você perder um cliente."}], "scenario_md": "Liruf está em sua barraquinha de limonada. A primeira cliente chega e pede um copo de R$5. Ela entrega uma nota de R$20. Liruf fica nervoso, mas deve dar o troco correto."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cc47c359a84dd0eafde1bda6a8e9076e41f27e33f53112d10df9eaa2136f9160.webp", "prompt_md": "A cliente paga com nota de R$20 por um copo de R$5. O que Liruf deve fazer?", "difficulty": 1, "explanation_md": "Contar o troco de R$15 com calma é a melhor decisão: o cliente recebe o que é justo e Liruf ganha confiança.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"keep-change": 0, "count-change": 100, "guess-change": 30}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/c861456ef936367e1c6ec9767693c528516165a0fbc4998d1b53bf9b14f4157e.mp3", "hash": "c4d21fb3e0579dc113ff8b9b7fe3006f83e9a0c9b65b0cf246dcb324bcfc2211", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c861456ef936367e1c6ec9767693c528516165a0fbc4998d1b53bf9b14f4157e.mp3", "duration_ms": 7280}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/7aba3941f8ee484d62c77909f2fe3ac8d4a819764abcfcc58db40d22745bb2e7.mp3", "hash": "d3c3d3544d45ccc9aa9a6f5f16713878a809d607325d2a4e381384731a977dfc", "bytes": 49248, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7aba3941f8ee484d62c77909f2fe3ac8d4a819764abcfcc58db40d22745bb2e7.mp3", "duration_ms": 8160}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/304621010d29a8c04433612e18ffab81c57421b259982d36570c817f403c402a.mp3", "hash": "bb6553b139a40660a5f213060d35ef65f7099af70d66bba384d3d90224f48fcf", "bytes": 50256, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/304621010d29a8c04433612e18ffab81c57421b259982d36570c817f403c402a.mp3", "duration_ms": 8320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "dialogue-choice", "title": "El puesto de limonada: ¡A negociar con clientes!", "locale": "es-MX", "subject": "money", "objectives": ["Elegir qué responderle a un cliente que pide rebaja: negociar con amabilidad sin regalar la ganancia."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-cliente", "xp": 15, "type": "dialogue_choice", "hints": [], "title": "Negocia con el cliente", "payload": {"turns": [{"id": "turn1", "npc_md": "Cliente: ''Oye, ¿me dejas la limonada en 3 pesos? Solo traigo eso.''", "replies": [{"id": "r1a", "text_md": "Claro, te la dejo en 3 pesos."}, {"id": "r1b", "text_md": "Lo siento, no bajo el precio. Si compras dos vasos, te regalo uno extra."}, {"id": "r1c", "text_md": "Ni modo, a 5 pesos está. Si no te gusta, ¡adiós!"}]}, {"id": "turn2", "npc_md": "Un niño se acerca y te dice: ''¿Me regalas un vasito? No traigo dinero.''", "replies": [{"id": "r2a", "text_md": "Claro, toma uno gratis."}, {"id": "r2b", "text_md": "No puedo regalarlo, pero si me ayudas a repartir volantes, te doy un vaso."}, {"id": "r2c", "text_md": "Lo siento, necesito cobrar para ahorrar. ¡Puedes traer dinero mañana!"}]}], "persona": {"name": "Liruf", "role_md": "Dueño del puesto de limonada", "character": "liruf"}, "opening_md": "Es un día soleado y Liruf vende vasos de limonada a $5 cada uno en su puesto."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/a36c247b50458699884b93ae81561c81d5274e31b8e2cfb97e81ce57aab10551.webp", "prompt_md": "Liruf debe atender dos clientes. Toca la mejor respuesta en cada caso.", "difficulty": 2, "explanation_md": "Cuando un cliente pide rebaja, Liruf puede ofrecer más en lugar de bajar el precio. Así todos ganan y él sigue ahorrando para su guitarra.", "audio_segment_id": "s1-dialogo-cliente.prompt"}], "schema_version": 1}', '{"s1-dialogo-cliente": {"turns": [{"turn_id": "turn1", "qualities": {"r1a": 30, "r1b": 100, "r1c": 10}, "reactions": {"r1a": "¡Gracias! Eres muy amable.", "r1b": "¡Qué buena oferta! Llevo dos entonces.", "r1c": "Qué malo, me voy a otro puesto."}}, {"turn_id": "turn2", "qualities": {"r2a": 20, "r2b": 100, "r2c": 50}, "reactions": {"r2a": "¡Gracias! Eres el mejor.", "r2b": "¡Trato hecho! Dame volantes y te ayudo.", "r2c": "Está bien, entiendo. Mañana traigo dinero."}}]}}', '{"units": {"s1-dialogo-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/070540ffdd97b5a5928d105828d61db6ddda64510b8f7f4618c2a835687df488.mp3", "hash": "cac491c8b48d00b876b65923186b26d89e6eab8e8ccb125d1fb75e7bc5c3494b", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/070540ffdd97b5a5928d105828d61db6ddda64510b8f7f4618c2a835687df488.mp3", "duration_ms": 5520}, "s1-dialogo-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/817397b8f571a981a27d7dde2ed7d485c85da821163e31ee0ef20adb975c6b5e.mp3", "hash": "83b869e32eb9a4848cbfa4bb6963c1915f7898e81d0a918f0726eb57b05c1952", "bytes": 54576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/817397b8f571a981a27d7dde2ed7d485c85da821163e31ee0ef20adb975c6b5e.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "measure-read", "title": "A jarra medidora", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler medidas em uma jarra para garantir porções justas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-jarra", "xp": 15, "type": "measure_read", "hints": ["Conte as marcas a cada 50 ml: 0, 50, 100... Veja onde está a superfície."], "title": "A jarra medidora", "payload": {"max": 500, "min": 0, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/c78198cd49aa96de68bc80d197c016ba65b7e276a975bd12c4d3dafc6c0dffe6.webp", "prompt_md": "Rho trouxe a jarra medidora. Observe até onde o líquido subiu. Quantos mililitros marca?", "difficulty": 2, "explanation_md": "O líquido chega aos 250 ml. Liruf garante que cada copo fique igual, como a balança do escambo!", "audio_segment_id": "s1-jarra.prompt"}], "schema_version": 1}', '{"s1-jarra": {"value": 250, "tolerance": 0}}', '{"units": {"s1-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6509058b373e1b41c7898c477c4e1cb4cc09dd2e87aa2469958ee82016e10e49.mp3", "hash": "10f50def73c909c66c270fe5064bc575dc8a59159c3810fa14185f97945a5235", "bytes": 49248, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/6509058b373e1b41c7898c477c4e1cb4cc09dd2e87aa2469958ee82016e10e49.mp3", "duration_ms": 8160}, "s1-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/ff1e3c421c518828d5360a3f0392030fa5c4f9f5bb90b34469d408a0d93d08cc.mp3", "hash": "3ac68f2ad8fd9829755bffa258e5b605d551cf6fa798a94205557d2ef737b2e2", "bytes": 43488, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ff1e3c421c518828d5360a3f0392030fa5c4f9f5bb90b34469d408a0d93d08cc.mp3", "duration_ms": 7200}, "s1-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/4da81e19dceb393cb2de7a546c8e7d89da6c0ccdd19ebd85466fddce7a719cf4.mp3", "hash": "3b63a65e6a08216ecc3f5c4ecff1b454851a8f280e4c54988b24d085b477faf2", "bytes": 50688, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4da81e19dceb393cb2de7a546c8e7d89da6c0ccdd19ebd85466fddce7a719cf4.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "timeline-order", "title": "Liruf''s first day", "locale": "en-US", "subject": "mixed", "objectives": ["Put the steps of a sales day in the correct order."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 5, "type": "timeline_order", "hints": [], "title": "Order of the day", "payload": {"events": [{"id": "ev-buy", "icon": "shopping_cart", "text_md": "Buy lemons and sugar at the market", "image_url": "http://localhost:4006/files/lesson-images/b5257743949c3ffb95f5508b07209f4282c2ce7a2752db4fe60a162538cf2f54.webp"}, {"id": "ev-prepare", "icon": "blender", "text_md": "Make fresh lemonade", "image_url": "http://localhost:4006/files/lesson-images/f69d8b420be568820316e6c161e739d9713ac70d6ded82df0b593726d6a76fa7.webp"}, {"id": "ev-sell", "icon": "storefront", "text_md": "Sell cups of lemonade at noon", "image_url": "http://localhost:4006/files/lesson-images/7645b91a3c5675f0c17e109394272aecaf29c412d306ad2fb832141a1793a40e.webp"}, {"id": "ev-count", "icon": "calculate", "text_md": "Count the money and save the earnings", "image_url": "http://localhost:4006/files/lesson-images/1e2d2f4bc1bac9bf39d0bcdd5e0998b0f63cb777d94627b9e23cb6fe6b322d0a.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf remembers their first full day. Put the photos of the day in order, from morning to night.", "difficulty": 1, "explanation_md": "This was Liruf''s first day: they bought lemons and sugar in the morning, made the lemonade, sold it at noon, and counted their earnings at closing.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["ev-buy", "ev-prepare", "ev-sell", "ev-count"]}}', '{"units": {"s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/686723936ccfad2211d706da9d96a56c2a4e21908a6f32ee10622d436180d0fe.mp3", "hash": "9d027d98f328a371488fc072c170c1576ec0990c81043baa1b904adbe8bcc3f9", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/686723936ccfad2211d706da9d96a56c2a4e21908a6f32ee10622d436180d0fe.mp3", "duration_ms": 5200}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/54fc3d76b294fbc0d0b49bf2d32cc4fa8c64afe09978c49f09b16ede498e45a9.mp3", "hash": "12f3cc636553014a6d2ea3451d81288e162b6af657924930e11bfe9c9cd3111a", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/54fc3d76b294fbc0d0b49bf2d32cc4fa8c64afe09978c49f09b16ede498e45a9.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "El Puesto de Liruf: Lo que Dicen los Vecinos", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar.", "Escuchar a dos clientes conversar sobre la limonada y responder dos preguntas seguidas: una de cierto/falso y una con imágenes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "title": "En la mesa de al lado", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "¿Ya viste el puesto de limonada de Liruf?", "character": "rho"}, {"action": "idle", "emotion": "neutral", "text_md": "¡Sí! Venden a 5 pesos el vaso. ¡Qué barato!", "character": "zara"}, {"action": "idle", "emotion": "thinking", "text_md": "¡Les gusta mi limonada!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/5973990d23e9d6037d1f1337c4438acf809bdeca0c8fe394ad0ffded88aa6907.webp", "prompt_md": "Liruf está en su puesto y escucha a dos vecinos.", "difficulty": 1, "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-verdadero-falso", "xp": 15, "type": "true_false", "title": "¿Qué dijeron?", "payload": {"statement_md": "El precio de un vaso de limonada en el puesto de Liruf es 10 pesos.", "justifications": [{"id": "just-1", "text_md": "El vaso cuesta 5 pesos, como dijeron los vecinos."}, {"id": "just-2", "text_md": "Es falso, pero el cliente debería pagar 10 pesos porque la limonada es premium."}]}, "prompt_md": "¿Los vecinos dicen que el vaso cuesta 10 pesos?", "difficulty": 2, "explanation_md": "El vaso de limonada cuesta 5 pesos, así que la afirmación es falsa.", "audio_segment_id": "s2-verdadero-falso.prompt"}, {"id": "s3-imagen", "xp": 15, "type": "picture_choice", "title": "El pago exacto", "payload": {"options": [{"id": "coin-5", "icon": "monetization_on", "label": "Moneda de 5 pesos", "image_url": "http://localhost:4006/files/lesson-images/652da598efa28187d0fceeed66bf0f59a603bfbe50aa719aebe3bc5a5ba4042c.webp"}, {"id": "coin-1", "icon": "monetization_on", "label": "Moneda de 1 peso", "image_url": "http://localhost:4006/files/lesson-images/ee3d0b75d271db35c43d7e527fa6c03d5748be55399a0882abda359685c7c726.webp", "rationale_md": "Falta dinero: solo cubrirías 1 peso de los 5 necesarios."}, {"id": "coin-10", "icon": "monetization_on", "label": "Moneda de 10 pesos", "image_url": "http://localhost:4006/files/lesson-images/b555ba34ba4bab919345899f7d495c6b513ad119f0476731740013d29ffcbce9.webp", "rationale_md": "Te sobraría dinero y no es el pago exacto que pide el ejercicio."}, {"id": "coin-2", "icon": "monetization_on", "label": "Moneda de 2 pesos", "image_url": "http://localhost:4006/files/lesson-images/cd4f65198305aaf25134cd8f3e095704d69c21b048a0b5109c67f3314b29e4be.webp", "rationale_md": "Falta dinero: solo pagarías 2 pesos de 5."}]}, "prompt_md": "Un cliente quiere pagar un vaso de limonada de 5 pesos con la moneda exacta. ¿Cuál moneda debe usar?", "difficulty": 2, "explanation_md": "La moneda de 5 pesos paga justo lo que cuesta un vaso de limonada.", "audio_segment_id": "s3-imagen.prompt"}], "schema_version": 1}', '{"s3-imagen": {"correct_option_id": "coin-5"}, "s2-verdadero-falso": {"is_true": false, "correct_justification_id": "just-1"}}', '{"units": {"s3-imagen.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d9ef49da5ec938346a99099f61c2200b644df23699a98e0b7b8fe41292bbc46.mp3", "hash": "8ac0b35f643f531acb2d73b1a287878f81c5c2be9b6db77b7e386bda9062dcb1", "bytes": 32976, "voice": "Li", "file_id": "lesson-audio/8d9ef49da5ec938346a99099f61c2200b644df23699a98e0b7b8fe41292bbc46.mp3", "duration_ms": 5440}, "s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/3030c1876eb96a6881b7dd22db9d74ca25abecf79544e5a840d30068af62dc83.mp3", "hash": "e0a999734137c22f3e22b47d5ea0a2d1911efc75bb847a7849ec58695b76daac", "bytes": 17136, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3030c1876eb96a6881b7dd22db9d74ca25abecf79544e5a840d30068af62dc83.mp3", "duration_ms": 2800}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/12b5e06c32df07e39ab0ce050ad78972f633e60de986f621b40793152e7245a0.mp3", "hash": "e225215d81aa17c2e30771d89a2291aaab1fa07431b1ac704f02672ab1652b96", "bytes": 20016, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/12b5e06c32df07e39ab0ce050ad78972f633e60de986f621b40793152e7245a0.mp3", "duration_ms": 3280}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/cb2f294d4aa8a6995d596f75e76aff7185812b4ef9c95ef2a850a428ef2f918f.mp3", "hash": "ceee999860536135063ef7b313e8bbd4928cd9e46ad746170a177026a1652c33", "bytes": 10368, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/cb2f294d4aa8a6995d596f75e76aff7185812b4ef9c95ef2a850a428ef2f918f.mp3", "duration_ms": 1680}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/e33f7e4c0bf75ab7a4f556ffd01869ff0dd52bd04b2c6bf2b01e4665c9810f34.mp3", "hash": "ab196c82147d9247f3b71688519e6942fd9267bf03ab31e736aaa7b58b570784", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e33f7e4c0bf75ab7a4f556ffd01869ff0dd52bd04b2c6bf2b01e4665c9810f34.mp3", "duration_ms": 3440}, "s3-imagen.choices": {"url": "http://localhost:4006/files/lesson-audio/8973405e010e8440b0051e71b3e72469179abf3a2f08de1a942545eb5eab991f.mp3", "hash": "9b531fb17a039aba9bb6cb8d1945b4192a85a1e05753f2252afb108447978cb6", "bytes": 37728, "voice": "Li", "file_id": "lesson-audio/8973405e010e8440b0051e71b3e72469179abf3a2f08de1a942545eb5eab991f.mp3", "duration_ms": 6240}, "s3-imagen.explanation": {"url": "http://localhost:4006/files/lesson-audio/501731ad66ea5d2bc5cef244406d4bba5e0ac231d27758e29f071320f2326fde.mp3", "hash": "c0b627549004af58743f89237159f7f0b7bf538daa6777c271667c2f1c139ba5", "bytes": 24768, "voice": "Li", "file_id": "lesson-audio/501731ad66ea5d2bc5cef244406d4bba5e0ac231d27758e29f071320f2326fde.mp3", "duration_ms": 4080}, "s2-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/33688fc9867d33987d3ea0aca1f85c5909b7925cf3e0db44388f82e2d81bf4b9.mp3", "hash": "f4ee91075fa2a15ff9c61d4a03d4d190ef68c3ddb662f5f1a3ccc3750c875768", "bytes": 15264, "voice": "Li", "file_id": "lesson-audio/33688fc9867d33987d3ea0aca1f85c5909b7925cf3e0db44388f82e2d81bf4b9.mp3", "duration_ms": 2480}, "s2-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/e79f7039ed27887d8ba3adc9a4f0a1e3303ad99de8f5753ef75e395751dd6b3b.mp3", "hash": "9eb4f40a098b193b68e869faa105281cf5e12f413b907495fd4931a95bed57cf", "bytes": 22896, "voice": "Li", "file_id": "lesson-audio/e79f7039ed27887d8ba3adc9a4f0a1e3303ad99de8f5753ef75e395751dd6b3b.mp3", "duration_ms": 3760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "build-sentence", "title": "El combo de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-letrero", "xp": 15, "type": "build_sentence", "hints": ["Piensa: ¿cuánto cuestan dos vasos si uno cuesta 5 pesos?"], "title": "Letrero del combo", "payload": {"slots": 5, "tokens": [{"id": "t2", "text_md": "2"}, {"id": "tv", "text_md": "vasos"}, {"id": "tp", "text_md": "por"}, {"id": "t10", "text_md": "10"}, {"id": "tpe", "text_md": "pesos"}, {"id": "t5", "text_md": "5"}, {"id": "t15", "text_md": "15"}, {"id": "t20", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf vende cada vaso a 5 pesos. Quiere un letrero: ''2 vasos por ___ pesos''. Arma el letrero con las fichas.", "difficulty": 2, "explanation_md": "Dos vasos de 5 pesos cada uno suman 10 pesos. Por eso el letrero dice ''2 vasos por 10 pesos''. La ficha 5 olvida que son dos; 15 es más de lo que cuesta; 20 es mucho más.", "audio_segment_id": "s1-letrero.prompt"}], "schema_version": 1}', '{"s1-letrero": {"order": ["t2", "tv", "tp", "t10", "tpe"]}}', '{"units": {"s1-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ac508171155260cc5e62638bccc22f4d0d21cfa2879232600e4bdef698d74647.mp3", "hash": "fffcaf89a77fa83f5a3c133701df266bfcee5c66889ec80b0639c98fe273be35", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ac508171155260cc5e62638bccc22f4d0d21cfa2879232600e4bdef698d74647.mp3", "duration_ms": 4800}, "s1-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/32de149403818eb59923273819a377b484430c09f5aa57d2c39b3ddfc97065f6.mp3", "hash": "dee946109227614930b03cdb0d85378c2abb16a5a20059f3d0a244b9d7319ebe", "bytes": 54576, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/32de149403818eb59923273819a377b484430c09f5aa57d2c39b3ddfc97065f6.mp3", "duration_ms": 9040}, "s1-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/e304f810b9d9418fed96dd3cf2a795c8477ef4034da978305933ac85d750c7c8.mp3", "hash": "57088503fbd377846e2cc2ec5128b22ea92182b50ec45b4c092f8082f4bace34", "bytes": 85248, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e304f810b9d9418fed96dd3cf2a795c8477ef4034da978305933ac85d750c7c8.mp3", "duration_ms": 14160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Liruf''s Stand: What the Neighbors Say", "locale": "en-US", "subject": "mixed", "objectives": ["Chain several skills in the same lesson: listen to the situation, decide, calculate, and collect payment.", "Listen to two customers talk about the lemonade and answer two questions in a row: one true/false and one with images."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "title": "At the next table", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Have you seen Liruf''s lemonade stand yet?", "character": "rho"}, {"action": "idle", "emotion": "neutral", "text_md": "Yes! They sell a glass for 5 dollars. How cheap!", "character": "zara"}, {"action": "idle", "emotion": "thinking", "text_md": "They like my lemonade!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/5973990d23e9d6037d1f1337c4438acf809bdeca0c8fe394ad0ffded88aa6907.webp", "prompt_md": "Liruf is at his stand and listens to two neighbors.", "difficulty": 1, "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-verdadero-falso", "xp": 15, "type": "true_false", "title": "What did they say?", "payload": {"statement_md": "The price of a glass of lemonade at Liruf''s stand is 10 dollars.", "justifications": [{"id": "just-1", "text_md": "The glass costs 5 dollars, just like the neighbors said."}, {"id": "just-2", "text_md": "It''s false, but the customer would have to pay 10 dollars because the lemonade is premium."}]}, "prompt_md": "Do the neighbors say that the glass costs 10 dollars?", "difficulty": 2, "explanation_md": "The glass of lemonade costs 5 dollars, so the statement is false.", "audio_segment_id": "s2-verdadero-falso.prompt"}, {"id": "s3-imagen", "xp": 15, "type": "picture_choice", "title": "The exact payment", "payload": {"options": [{"id": "coin-5", "icon": "monetization_on", "label": "5-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/652da598efa28187d0fceeed66bf0f59a603bfbe50aa719aebe3bc5a5ba4042c.webp"}, {"id": "coin-1", "icon": "monetization_on", "label": "1-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/ee3d0b75d271db35c43d7e527fa6c03d5748be55399a0882abda359685c7c726.webp", "rationale_md": "Not enough money: you would only cover 1 dollar out of the 5 needed."}, {"id": "coin-10", "icon": "monetization_on", "label": "10-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/b555ba34ba4bab919345899f7d495c6b513ad119f0476731740013d29ffcbce9.webp", "rationale_md": "You would have money left over and it''s not the exact payment the exercise asks for."}, {"id": "coin-2", "icon": "monetization_on", "label": "2-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/cd4f65198305aaf25134cd8f3e095704d69c21b048a0b5109c67f3314b29e4be.webp", "rationale_md": "Not enough money: you would only pay 2 dollars out of 5."}]}, "prompt_md": "A customer wants to pay for a 5-dollar glass of lemonade with the exact coin. Which coin should they use?", "difficulty": 2, "explanation_md": "The 5-dollar coin pays exactly what a glass of lemonade costs.", "audio_segment_id": "s3-imagen.prompt"}], "schema_version": 1}', '{"s3-imagen": {"correct_option_id": "coin-5"}, "s2-verdadero-falso": {"is_true": false, "correct_justification_id": "just-1"}}', '{"units": {"s3-imagen.prompt": {"url": "http://localhost:4006/files/lesson-audio/8b744c688c67140a9003baa2c0b95ee913d69b728b529a7933ec8308730590ce.mp3", "hash": "f778c779f17f68589bd9df6680d066343c67630490c8cecca4063cbfa906e0ad", "bytes": 38304, "voice": "Jennifer", "file_id": "lesson-audio/8b744c688c67140a9003baa2c0b95ee913d69b728b529a7933ec8308730590ce.mp3", "duration_ms": 6320}, "s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/c86712f37c4bb75a99fa96932b27e213a907d9c959699948ce58655aabab7c24.mp3", "hash": "c16096bc82c3f748978a6431874d25c5b306faad8849127e966484d4421a39ad", "bytes": 17136, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c86712f37c4bb75a99fa96932b27e213a907d9c959699948ce58655aabab7c24.mp3", "duration_ms": 2800}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/92b922abff4b418d1708b5f118e2f9d114244593d683e6d96e8f4a97ec938074.mp3", "hash": "899f1a78a042605a9f6c34ffb98634baed4dab998ce6af9e12183a1ee62d84c8", "bytes": 24768, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/92b922abff4b418d1708b5f118e2f9d114244593d683e6d96e8f4a97ec938074.mp3", "duration_ms": 4080}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/ee5136cbd5774a7d93787427e87998df2b074f746ead1d7ea8380b80150e86a6.mp3", "hash": "4403d16a960cd5b9a50f2e9774e6533cfa34104eb420f79786f48bbc56707dcf", "bytes": 8928, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ee5136cbd5774a7d93787427e87998df2b074f746ead1d7ea8380b80150e86a6.mp3", "duration_ms": 1440}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/9f4b13348103e08bee652465c89cffc74a999c1202a1cdf64e14a7e2ca1b4a36.mp3", "hash": "56b3a244e6fe53bd88dcf4e78424373a4fbd530f9281ed9205838589065e6086", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9f4b13348103e08bee652465c89cffc74a999c1202a1cdf64e14a7e2ca1b4a36.mp3", "duration_ms": 2880}, "s3-imagen.choices": {"url": "http://localhost:4006/files/lesson-audio/19d58f8568d8ecfa015b98e06edc30523a8db0ffe806996b93c70674dd00cd85.mp3", "hash": "45daf877de0715345448b2035c3fcd771628733d57f68050203f844059c73391", "bytes": 31968, "voice": "Jennifer", "file_id": "lesson-audio/19d58f8568d8ecfa015b98e06edc30523a8db0ffe806996b93c70674dd00cd85.mp3", "duration_ms": 5280}, "s3-imagen.explanation": {"url": "http://localhost:4006/files/lesson-audio/434c0dcf821fbb29b4bcf0ad760bb5c308c4c517e1af83b58a3667ef3c84059b.mp3", "hash": "fe2c56a5717dab989ba84f98d712615cea415def7631e5c66abbe0e9c4a14f12", "bytes": 23328, "voice": "Jennifer", "file_id": "lesson-audio/434c0dcf821fbb29b4bcf0ad760bb5c308c4c517e1af83b58a3667ef3c84059b.mp3", "duration_ms": 3840}, "s2-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/72be82da3cbf291b7c75d2f11d4935597d60bef1267dff738699f05594e73f91.mp3", "hash": "01b5bdfc284b6b57ee29718388259245a79b58fa6a7deae7816058c910e1da30", "bytes": 17136, "voice": "Jennifer", "file_id": "lesson-audio/72be82da3cbf291b7c75d2f11d4935597d60bef1267dff738699f05594e73f91.mp3", "duration_ms": 2800}, "s2-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/61713f4361913511ba6f106a17a1b22c261dc98c03e76c5e97aa7b86a2ff4975.mp3", "hash": "deb594b7decf21c5508ea8e77a2c395bf9895906acee0df2074ff5791bf98949", "bytes": 23904, "voice": "Jennifer", "file_id": "lesson-audio/61713f4361913511ba6f106a17a1b22c261dc98c03e76c5e97aa7b86a2ff4975.mp3", "duration_ms": 3920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "How much does a glass cost?", "locale": "en-US", "subject": "money", "objectives": ["Choosing the fair price for a glass of lemonade by comparing exaggerated options."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "title": "The price of the glass", "payload": {"options": [{"id": "opt-1", "text_md": "1 dollar", "rationale_md": "1 dollar is too cheap: it''s not enough to buy the lemons, and Liruf would lose money."}, {"id": "opt-5", "text_md": "5 dollars"}, {"id": "opt-50", "text_md": "50 dollars", "rationale_md": "50 dollars is too expensive: customers wouldn''t pay that much and would leave without buying."}], "shuffle": true}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf sells lemonade. What price do you set for each glass?", "difficulty": 1, "explanation_md": "5 dollars is a fair price: it covers the cost of the lemons and customers pay it without problem.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "opt-5"}}', '{"units": {"s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/cf8f69070a59efd70f0c3ddf7ec79299b5c4de6712665f05c2d51f5be63cf397.mp3", "hash": "a7eaaebed39cdf8004061d9e58856bfe9bf79290b556ddc100b605ccc6dd568d", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cf8f69070a59efd70f0c3ddf7ec79299b5c4de6712665f05c2d51f5be63cf397.mp3", "duration_ms": 3680}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/bdda95ed53ccd91740357aebf1467ca6f2ffa3326d658f2b58067c7d7cea1a60.mp3", "hash": "1b69dcc75d0f3d9f4713bda7973765ff9fb35c50ec2d85f37dde3c6c70a12945", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bdda95ed53ccd91740357aebf1467ca6f2ffa3326d658f2b58067c7d7cea1a60.mp3", "duration_ms": 2640}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/95af4e434548bbee8a1354647003b9432451f14f3d8bd71bda884753cc365b92.mp3", "hash": "4754e1d8df43edd20026dd082d28d20b31ca17ea3b434f0906bacfdf3e5018be", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/95af4e434548bbee8a1354647003b9432451f14f3d8bd71bda884753cc365b92.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escreva a resposta numérica", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escrever respostas numéricas exatas sobre a poupança."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-answer", "xp": 5, "type": "type_answer", "title": "Quanto você poupa?", "payload": {"max_chars": 5, "placeholder": "Escreva o número"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Vender 2 copos dá 10 reais. Rho poupa 15 reais hoje e 10 amanhã. Total poupado?", "difficulty": 1, "explanation_md": "15 + 10 = 25. Esse dinheiro que você guarda para depois se chama ''poupança''. Você já tem 25 reais guardados para sua meta!", "audio_segment_id": "s1-type-answer.prompt"}], "schema_version": 1}', '{"s1-type-answer": {"accept": ["25"], "keywords": ["25", "veinticinco"], "case_sensitive": false}}', '{"units": {"s1-type-answer.prompt": {"url": "http://localhost:4006/files/lesson-audio/2d6c05d300aacc6edb920df93c1a12e5f0ac6a6b9b5a4f3a61cdda3dad832bd8.mp3", "hash": "f03aeb7c3a10e7741d78c8a0dd40e9befb917ee9aebaaf46eb8a49b6bfbff09d", "bytes": 48816, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2d6c05d300aacc6edb920df93c1a12e5f0ac6a6b9b5a4f3a61cdda3dad832bd8.mp3", "duration_ms": 8080}, "s1-type-answer.explanation": {"url": "http://localhost:4006/files/lesson-audio/99d6ee8925c6ba517ab7ff0b6e0664c88ef995fbc58ecdba93e01fb6dbedd107.mp3", "hash": "3d7ea6bf9531967bb64fec860589de9c7ff97715d3ca4da038784d93524271b3", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/99d6ee8925c6ba517ab7ff0b6e0664c88ef995fbc58ecdba93e01fb6dbedd107.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "¿Hoy o la próxima semana?", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones financieras con consecuencias a corto y largo plazo."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "w1-dilema", "xp": 0, "type": "would_you_rather", "title": "Vender ahora o después", "payload": {"a": {"icon": "today", "text_md": "Vender hoy por 10 pesos", "image_url": "http://localhost:4006/files/lesson-images/26993af9e646e8264e32ead105433d7a9254c4b054b8c0d971b067e206666dd5.webp"}, "b": {"icon": "schedule", "text_md": "Esperar una semana por 20 pesos", "image_url": "http://localhost:4006/files/lesson-images/3e0f982b4b45ff9b7bcf1fa432200c01c859e94a8267078f1d0bc6410bf40c5f.webp"}, "followup_md": "¿Por qué elegiste esa opción?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf puede vender hoy y ganar 10 pesos, o esperar una semana y ganar 20. ¿Qué harías?", "difficulty": 1, "explanation_md": "Si vendes hoy, tienes dinero seguro, pero pierdes la oportunidad de juntar el doble para algo más grande. Esperar requiere paciencia, pero al final tendrás 20 pesos en lugar de 10. 💡", "audio_segment_id": "w1-dilema.prompt"}], "schema_version": 1}', '{"w1-dilema": {"qualities": {"a": 15, "b": 95}, "reveal_md": "Al vender hoy aseguras 10 pesos, pero pierdes la oportunidad de ganar el doble. Esperar te da 20 pesos, aunque hoy no recibes nada."}}', '{"units": {"w1-dilema.prompt": {"url": "http://localhost:4006/files/lesson-audio/9ff83e7ce6842eba74ee884be3b140c9df9cfaa1b3f7b4ffacf9068e648282db.mp3", "hash": "84e1f58457149f4f2f76e29d973f9dfa691003076aef3d696fe18df7a1153c7e", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9ff83e7ce6842eba74ee884be3b140c9df9cfaa1b3f7b4ffacf9068e648282db.mp3", "duration_ms": 7360}, "w1-dilema.choices": {"url": "http://localhost:4006/files/lesson-audio/7ff77fbdb4818bf5eee5aa70844df740ed56c073f60fb09571a0b8164c73e25c.mp3", "hash": "8f153e94a57411e6844387b8bc35c48332daf823a22d1e5f8210bf126f239531", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7ff77fbdb4818bf5eee5aa70844df740ed56c073f60fb09571a0b8164c73e25c.mp3", "duration_ms": 4400}, "w1-dilema.explanation": {"url": "http://localhost:4006/files/lesson-audio/caa557a8071e154f255777ab6c763f35c25c841dc5728c64a4b51fccc05ea032.mp3", "hash": "d915c278d70f2c2c2a906d0e290c36968fec8b39ffb530c9bd4c80c09219c817", "bytes": 73296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/caa557a8071e154f255777ab6c763f35c25c841dc5728c64a4b51fccc05ea032.mp3", "duration_ms": 12160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "fill-blank", "title": "Completa la ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Escribir la ganancia numérica de una venta restando el costo de los ingredientes."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fill-blank", "xp": 5, "type": "fill_blank", "hints": ["Resta los ingredientes al precio del vaso para saber cuánto le queda."], "title": "Completa la ganancia", "payload": {"mode": "typed", "text_md": "Vendí un vaso en 5 pesos, los ingredientes costaron 2, mi ganancia es {{1}} pesos."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina vendió un vaso a 5 pesos y gastó 2 en ingredientes. Completa la frase con su ganancia.", "difficulty": 1, "explanation_md": "La ganancia es lo que queda después de pagar los gastos: 5 pesos del vaso menos 2 de ingredientes deja 3 pesos.", "audio_segment_id": "s1-fill-blank.prompt"}], "schema_version": 1}', '{"s1-fill-blank": {"gaps": [{"gap": 1, "accept": ["3"]}]}}', '{"units": {"s1-fill-blank.hint.0": {"url": "http://localhost:4006/files/lesson-audio/28cecb10080485b0d50c6f6498f090ef004ace062ce0e1629995372bb6dbe189.mp3", "hash": "e7cabfe279f367088a55fac8e4a1726ba4291ef8cc0c09bb168d951ded494af2", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/28cecb10080485b0d50c6f6498f090ef004ace062ce0e1629995372bb6dbe189.mp3", "duration_ms": 4160}, "s1-fill-blank.prompt": {"url": "http://localhost:4006/files/lesson-audio/09e7be9ca179ba7f85c942cdbb827d406ac7d49cfcf1750a5de8edcae5d11f34.mp3", "hash": "de9a34101505b02539506f1718b1f38e83b28778b5af3887b463235ec4f99da5", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/09e7be9ca179ba7f85c942cdbb827d406ac7d49cfcf1750a5de8edcae5d11f34.mp3", "duration_ms": 6720}, "s1-fill-blank.explanation": {"url": "http://localhost:4006/files/lesson-audio/d9eb848b310b836af3f01939e4c53f39688856fcfd10c145f376adaf858395f6.mp3", "hash": "82f0525939332ce4f9d8d819895d6efcc1167509bc2039c0a20b6a126e28eb77", "bytes": 47376, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d9eb848b310b836af3f01939e4c53f39688856fcfd10c145f376adaf858395f6.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "dialogue-choice", "title": "The lemonade stand: Time to negotiate with customers!", "locale": "en-US", "subject": "money", "objectives": ["Choose how to respond to a customer asking for a discount: negotiate kindly without giving away the profit."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-cliente", "xp": 15, "type": "dialogue_choice", "hints": [], "title": "Negotiate with the customer", "payload": {"turns": [{"id": "turn1", "npc_md": "Customer: ''Hey, can you let me have the lemonade for 3 dollars? I only brought that much.''", "replies": [{"id": "r1a", "text_md": "Sure, I''ll give it to you for 3 dollars."}, {"id": "r1b", "text_md": "Sorry, I can''t lower the price. If you buy two glasses, I''ll give you an extra one for free."}, {"id": "r1c", "text_md": "No way, it''s 5 dollars. If you don''t like it, goodbye!"}]}, {"id": "turn2", "npc_md": "A kid approaches and says: ''Can you give me a small glass? I don''t have any money.''", "replies": [{"id": "r2a", "text_md": "Sure, have one for free."}, {"id": "r2b", "text_md": "I can''t give it away, but if you help me hand out flyers, I''ll give you a glass."}, {"id": "r2c", "text_md": "Sorry, I need to charge to save up. You can bring money tomorrow!"}]}], "persona": {"name": "Liruf", "role_md": "Owner of the lemonade stand", "character": "liruf"}, "opening_md": "It''s a sunny day and Liruf is selling glasses of lemonade for $5 each at his stand."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/a36c247b50458699884b93ae81561c81d5274e31b8e2cfb97e81ce57aab10551.webp", "prompt_md": "Liruf must serve two customers. Tap the best response in each case.", "difficulty": 2, "explanation_md": "When a customer asks for a discount, Liruf can offer more instead of lowering the price. That way everyone wins and he keeps saving for his guitar.", "audio_segment_id": "s1-dialogo-cliente.prompt"}], "schema_version": 1}', '{"s1-dialogo-cliente": {"turns": [{"turn_id": "turn1", "qualities": {"r1a": 30, "r1b": 100, "r1c": 10}, "reactions": {"r1a": "¡Gracias! Eres muy amable.", "r1b": "¡Qué buena oferta! Llevo dos entonces.", "r1c": "Qué malo, me voy a otro puesto."}}, {"turn_id": "turn2", "qualities": {"r2a": 20, "r2b": 100, "r2c": 50}, "reactions": {"r2a": "¡Gracias! Eres el mejor.", "r2b": "¡Trato hecho! Dame volantes y te ayudo.", "r2c": "Está bien, entiendo. Mañana traigo dinero."}}]}}', '{"units": {"s1-dialogo-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/95bf5415ff44e2b068ffdbe0b606ab6df4ed0b1c62a7dc5102d65c9f25ddc73e.mp3", "hash": "9884d1c238157280e9aafcf8874331bb4b21c5dbb4504965bc5857d52fd90f0d", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/95bf5415ff44e2b068ffdbe0b606ab6df4ed0b1c62a7dc5102d65c9f25ddc73e.mp3", "duration_ms": 4080}, "s1-dialogo-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/f254581d159bd763cc863689809f84587879cd29f1ff186298461db4ae356325.mp3", "hash": "36bdf365d787909677738e6c4bc3e3cde88140f8e26ed7872e08532b8ea9e512", "bytes": 48384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f254581d159bd763cc863689809f84587879cd29f1ff186298461db4ae356325.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estima los vasos", "locale": "es-MX", "subject": "mixed", "objectives": ["Estimar con la barra cuántos vasos salen de una jarra grande."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-cups", "xp": 15, "type": "estimate_slider", "hints": ["Imagina el tamaño de una jarra común en casa y los vasos que usas. ¿Cuántos llenarías?"], "title": "¿Cuántos vasos salen?", "payload": {"max": 20, "min": 0, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "excited", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/4e19821d41322fa6ac9721b7cdf6f33027e8e7b198351670b0c25a3f7e679255.webp", "prompt_md": "Zara preparó la jarra del día. Sin contar, estima cuántos vasos puede llenar.", "difficulty": 2, "explanation_md": "Zara sabe que su jarra rinde 8 vasos aproximadamente. ¡Buen ojo! 🎉", "audio_segment_id": "s1-estimate-cups.prompt"}], "schema_version": 1}', '{"s1-estimate-cups": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-cups.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2ad9cddc6a6a26c534426313297a92d80a1921354d87acffb775b83fe97a9518.mp3", "hash": "fde7baa93b428c5bed8a22edffc2f85a1a4f655630c98966cfdb372294cd7d8f", "bytes": 34848, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/2ad9cddc6a6a26c534426313297a92d80a1921354d87acffb775b83fe97a9518.mp3", "duration_ms": 5760}, "s1-estimate-cups.prompt": {"url": "http://localhost:4006/files/lesson-audio/28efac2d05242d6ebf15797d7f9bec60f5f2017b500eb96a4cadc8597784a1dd.mp3", "hash": "be19aeec61ab194a4d4216deda8f757131371757caa1ab02e6b9b2ba94039e1c", "bytes": 29664, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/28efac2d05242d6ebf15797d7f9bec60f5f2017b500eb96a4cadc8597784a1dd.mp3", "duration_ms": 4880}, "s1-estimate-cups.explanation": {"url": "http://localhost:4006/files/lesson-audio/6e3558455c7c28a149eb1453b8e4b28de6dad3495ac8257b56f8d203d9739268.mp3", "hash": "1e09dbc7e26e5431b7cf8cb0a921bc30febb28626532f1e5391e90914799e993", "bytes": 27648, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/6e3558455c7c28a149eb1453b8e4b28de6dad3495ac8257b56f8d203d9739268.mp3", "duration_ms": 4560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Hoje ou na próxima semana?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões financeiras com consequências de curto e longo prazo."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "w1-dilema", "xp": 0, "type": "would_you_rather", "title": "Vender agora ou depois", "payload": {"a": {"icon": "today", "text_md": "Vender hoje por 10 reais", "image_url": "http://localhost:4006/files/lesson-images/26993af9e646e8264e32ead105433d7a9254c4b054b8c0d971b067e206666dd5.webp"}, "b": {"icon": "schedule", "text_md": "Esperar uma semana por 20 reais", "image_url": "http://localhost:4006/files/lesson-images/3e0f982b4b45ff9b7bcf1fa432200c01c859e94a8267078f1d0bc6410bf40c5f.webp"}, "followup_md": "Por que você escolheu essa opção?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf pode vender hoje e ganhar 10 reais, ou esperar uma semana e ganhar 20. O que você faria?", "difficulty": 1, "explanation_md": "Se você vender hoje, tem dinheiro garantido, mas perde a oportunidade de juntar o dobro para algo maior. Esperar requer paciência, mas no final você terá 20 reais em vez de 10. 💡", "audio_segment_id": "w1-dilema.prompt"}], "schema_version": 1}', '{"w1-dilema": {"qualities": {"a": 15, "b": 95}, "reveal_md": "Al vender hoy aseguras 10 pesos, pero pierdes la oportunidad de ganar el doble. Esperar te da 20 pesos, aunque hoy no recibes nada."}}', '{"units": {"w1-dilema.prompt": {"url": "http://localhost:4006/files/lesson-audio/7a6930bcb77511eb46c70a9c396304de8a8729e54e154257024d1ae7f57d464f.mp3", "hash": "50bd27ec6f31c25b299b11801dfa43a45125f1927ab1804d3f6de99e321b41e9", "bytes": 48384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7a6930bcb77511eb46c70a9c396304de8a8729e54e154257024d1ae7f57d464f.mp3", "duration_ms": 8000}, "w1-dilema.choices": {"url": "http://localhost:4006/files/lesson-audio/abb11ba5c9d16982abeda3b28015a1531cbba685a0d669ed1b5d6264067ce05b.mp3", "hash": "d803c92eb5b959e1251685a9e78f6e09129d88d8169ad029e1e484178424659b", "bytes": 28224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/abb11ba5c9d16982abeda3b28015a1531cbba685a0d669ed1b5d6264067ce05b.mp3", "duration_ms": 4640}, "w1-dilema.explanation": {"url": "http://localhost:4006/files/lesson-audio/a8a35c0bb785edb53d5c47f4b48d3032286aac48e2ba392d24de8f612fa719a6.mp3", "hash": "2639d20a91383802fed9cc4da3e4b1392ff8d00763c78a2b79efeafe5850f6f6", "bytes": 74736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a8a35c0bb785edb53d5c47f4b48d3032286aac48e2ba392d24de8f612fa719a6.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Hechos vs Opiniones en el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Diferenciar entre hechos y opiniones en las frases de un puesto de limonada."], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "fact-opinion-1", "xp": 15, "type": "fact_opinion", "hints": ["Un hecho se puede probar si es verdad o mentira. Una opinión es lo que alguien siente o piensa."], "title": "Hechos vs Opiniones", "payload": {"statements": [{"id": "s1", "text_md": "El vaso de limonada cuesta 5 pesos."}, {"id": "s2", "text_md": "Es la mejor limonada de la ciudad."}, {"id": "s3", "text_md": "Nuestra receta lleva azúcar, limones y agua."}, {"id": "s4", "text_md": "Abrimos de lunes a viernes."}, {"id": "s5", "text_md": "Nuestros clientes dicen que les encanta."}, {"id": "s6", "text_md": "Sabe a puro verano."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/eb4e702c560cdfd7763ee9145bee9fd6e471318213ecde375f8a6c9a91027c84.webp", "prompt_md": "Para no caer en trampas, fíjate en lo que es un hecho comprobable. Toca las frases que son HECHOS en el puesto de Liruf.", "difficulty": 2, "explanation_md": "Tu amiga Liruf dice que su limonada cuesta 5 pesos: eso es un hecho. Pero que sea ''la mejor'' es su opinión, porque para otros puede no serlo. ¡Fíjate en lo que se puede comprobar!", "audio_segment_id": "fact-opinion-1.prompt"}], "schema_version": 1}', '{"fact-opinion-1": {"fact_ids": ["s1", "s3", "s4"]}}', '{"units": {"fact-opinion-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/33e1c17a6882ebb7b5ff0421a7dd3026b190bfaa36aa737db9b4140d0b0fa5ed.mp3", "hash": "5a09f7767f221d7860b1880fa973068f478868f5f2253b5dce07acf829aec094", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/33e1c17a6882ebb7b5ff0421a7dd3026b190bfaa36aa737db9b4140d0b0fa5ed.mp3", "duration_ms": 5520}, "fact-opinion-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/42c338f7891f295094221171980acd5e6840abf35d9c3e85b2fe51baf2548826.mp3", "hash": "0d42c1a13247ffccbfb31ac59ef0a391fc4c621738353fc73b223b842141a85a", "bytes": 43056, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/42c338f7891f295094221171980acd5e6840abf35d9c3e85b2fe51baf2548826.mp3", "duration_ms": 7120}, "fact-opinion-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/fa9158e2b4e2613eec347ba1cfb04b7fc7846eb1889fb4849aa75d590107532e.mp3", "hash": "fdeaee242f977b8646776741a99cd8fb98ef80834f926eca4d67063ceb5581e3", "bytes": 68976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fa9158e2b4e2613eec347ba1cfb04b7fc7846eb1889fb4849aa75d590107532e.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "confidence-quiz", "title": "Quanto Liruf ganhou?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Praticar somas rápidas com dinheiro e avaliar a segurança nas respostas."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confianza", "xp": 10, "type": "confidence_quiz", "title": "Confiança na soma", "payload": {"options": [{"id": "opt5", "text_md": "5 reais", "rationale_md": "Você só contou um copo. Eram dois copos de 5 reais."}, {"id": "opt10", "text_md": "10 reais"}, {"id": "opt15", "text_md": "15 reais", "rationale_md": "Você contou três copos. Você só vendeu dois copos."}, {"id": "opt25", "text_md": "25 reais", "rationale_md": "Você multiplicou 5 por 5, mas foram dois copos de 5 reais."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf vendeu dois copos de limonada a 5 reais cada um. Quanto dinheiro ele ganhou?", "difficulty": 1, "explanation_md": "Dois copos de 5 reais cada um somam 10 reais. Liruf ganhou 10 reais com essas duas vendas! 🍋", "audio_segment_id": "s1-confianza.prompt"}], "schema_version": 1}', '{"s1-confianza": {"correct_option_id": "opt10"}}', '{"units": {"s1-confianza.prompt": {"url": "http://localhost:4006/files/lesson-audio/ee10801be5c674b66685cf9f26b41f6250fb039abc1d7cfb8247c8c3f13e9885.mp3", "hash": "b0c455d0e0567b63f7711385780a9110381e8cccffc33f7b801c3262eea3be46", "bytes": 41616, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ee10801be5c674b66685cf9f26b41f6250fb039abc1d7cfb8247c8c3f13e9885.mp3", "duration_ms": 6880}, "s1-confianza.choices": {"url": "http://localhost:4006/files/lesson-audio/94ff60f0383045f57a2f7721ace965e4cd4a592ba4525105b5f774b678d89636.mp3", "hash": "9dc22f18c94731bd4bba96c1778e344dee5aae5084cbd2d8d78f58110aa1f306", "bytes": 35856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/94ff60f0383045f57a2f7721ace965e4cd4a592ba4525105b5f774b678d89636.mp3", "duration_ms": 5920}, "s1-confianza.explanation": {"url": "http://localhost:4006/files/lesson-audio/1f7b66827aa9e3c86071ec639788025438ec060a5c4aa8efbb488f38d58ca5d3.mp3", "hash": "18d93ffdd9e93b8a72c1eab3c0a320d3ca01504d35a5a1ba56ec5123519392b4", "bytes": 45936, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/1f7b66827aa9e3c86071ec639788025438ec060a5c4aa8efbb488f38d58ca5d3.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Ronda relámpago: cambio rápido", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el cambio exacto en ventas de limonada para llenar el frasco de la guitarra."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-1", "xp": 15, "type": "lightning_round", "title": "Ronda relámpago", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1_a", "icon": "paid", "text_md": "10 pesos"}, {"id": "q1_b", "icon": "paid", "text_md": "15 pesos"}, {"id": "q1_c", "icon": "paid", "text_md": "20 pesos"}, {"id": "q1_d", "icon": "paid", "text_md": "0 pesos"}], "prompt_md": "Doña Rosa pide 2 vasos y paga con 20 pesos. ¿Cuál es su cambio?"}, {"id": "q2", "options": [{"id": "q2_a", "icon": "paid", "text_md": "5 pesos"}, {"id": "q2_b", "icon": "paid", "text_md": "10 pesos"}, {"id": "q2_c", "icon": "paid", "text_md": "15 pesos"}, {"id": "q2_d", "icon": "paid", "text_md": "0 pesos"}], "prompt_md": "Don Pepe pide 1 vaso y paga con 10 pesos. ¿Cuál es su cambio?"}, {"id": "q3", "options": [{"id": "q3_a", "icon": "paid", "text_md": "5 pesos"}, {"id": "q3_b", "icon": "paid", "text_md": "15 pesos"}, {"id": "q3_c", "icon": "paid", "text_md": "20 pesos"}, {"id": "q3_d", "icon": "paid", "text_md": "10 pesos"}], "prompt_md": "La niña pide 3 vasos y paga con 20 pesos. ¿Cuál es su cambio?"}, {"id": "q4", "options": [{"id": "q4_a", "icon": "paid", "text_md": "15 pesos"}, {"id": "q4_b", "icon": "paid", "text_md": "10 pesos"}, {"id": "q4_c", "icon": "paid", "text_md": "20 pesos"}, {"id": "q4_d", "icon": "paid", "text_md": "5 pesos"}], "prompt_md": "El señor pide 1 vaso y paga con 20 pesos. ¿Cuál es su cambio?"}, {"id": "q5", "options": [{"id": "q5_a", "icon": "cancel", "text_md": "No necesita cambio"}, {"id": "q5_b", "icon": "paid", "text_md": "5 pesos"}, {"id": "q5_c", "icon": "paid", "text_md": "10 pesos"}, {"id": "q5_d", "icon": "paid", "text_md": "15 pesos"}], "prompt_md": "Doña Lula pide 2 vasos y paga con 10 pesos justos. ¿Cuál es su cambio?"}], "seconds_per_q": 15}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Zara canta los pedidos: cada vaso cuesta 5 pesos. ¡Calcula rápido el cambio antes de que el cliente se vaya!", "difficulty": 2, "explanation_md": "Primero suma el costo de los vasos: 1 vaso = 5 pesos, 2 vasos = 10 pesos, 3 vasos = 15 pesos. Luego resta ese total del billete que pagó. Por ejemplo, si paga con 20 por 2 vasos: 20 - 10 = 10 pesos de cambio. ¡Cada acierto acerca la guitarra de 80 pesos!", "audio_segment_id": "lightning-round-1.prompt"}], "schema_version": 1}', '{"lightning-round-1": {"correct": {"q1": "q1_a", "q2": "q2_a", "q3": "q3_a", "q4": "q4_a", "q5": "q5_a"}}}', '{"units": {"lightning-round-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/45731d0dd4222b5e18c42ce689563b12cda2e3f3307c5cc78c7346a723d1485f.mp3", "hash": "578005a58822b561f07072d9c71e0d22181e18c680deea9151cb0a5f600c6100", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/45731d0dd4222b5e18c42ce689563b12cda2e3f3307c5cc78c7346a723d1485f.mp3", "duration_ms": 8400}, "lightning-round-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/78bae822c993002b09b9be284344356ab68f44f97bb39de47f33712d9cd177bd.mp3", "hash": "217019aedafadfb734fa948f419e02e1f9498e0dfb019c18d926641cbb19c2f7", "bytes": 120816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/78bae822c993002b09b9be284344356ab68f44f97bb39de47f33712d9cd177bd.mp3", "duration_ms": 20080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Repaso: Ganancia por vaso", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar el cálculo de ganancia por vaso en el puesto de limonada."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-ganancia", "xp": 10, "type": "quiz_mcq", "title": "Repaso rápido de ganancia", "payload": {"options": [{"id": "opt-2", "text_md": "5 pesos", "rationale_md": "Parece correcto porque es el precio de venta, pero la ganancia es lo que queda después de pagar los ingredientes."}, {"id": "opt-4", "text_md": "7 pesos", "rationale_md": "Sumar el precio y el costo da 7, pero para calcular la ganancia hay que restar el costo al precio, no sumarlos."}, {"id": "opt-1", "text_md": "3 pesos"}, {"id": "opt-3", "text_md": "2 pesos", "rationale_md": "Los 2 pesos son el costo de los ingredientes, no la ganancia. La ganancia es lo que sobra después de restar el costo."}], "shuffle": false}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina le pregunta a Liruf: ''Si vendes cada vaso en 5 pesos y te cuesta 2 pesos hacerlo, ¿cuánto ganas por vaso?''", "difficulty": 1, "explanation_md": "La ganancia por vaso es el precio de venta menos el costo: 5 - 2 = 3 pesos. Así Liruf sabe cuánto crece su ahorro por cada vaso vendido. 💰", "audio_segment_id": "s1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"s1-repaso-ganancia": {"correct_option_id": "opt-1"}}', '{"units": {"s1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/007a33e98dc460bff7c8ed866499adf4678d9c5711267f0c6f4a62995765fdd8.mp3", "hash": "474648fc798bda6bc7496d2a2fad6a358719f23b005fffd108f5d9d0f35fd9e2", "bytes": 50256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/007a33e98dc460bff7c8ed866499adf4678d9c5711267f0c6f4a62995765fdd8.mp3", "duration_ms": 8320}, "s1-repaso-ganancia.choices": {"url": "http://localhost:4006/files/lesson-audio/618d2c8b4792c2dbb20768800cc5bbaca419d985a83a17c2fdb42aad6179f311.mp3", "hash": "8a74aa330be382991825de1ecb1728d6f64534722956aa405a63382550f9ab2f", "bytes": 28656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/618d2c8b4792c2dbb20768800cc5bbaca419d985a83a17c2fdb42aad6179f311.mp3", "duration_ms": 4720}, "s1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/218671bd17e615a814b7c88c6cfa9a0a7563da9edbe62bc037ddbaea46e3c004.mp3", "hash": "3cc50353f21e308c6e46f5c316737db9918411009545905bef6400ed36851a3d", "bytes": 70848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/218671bd17e615a814b7c88c6cfa9a0a7563da9edbe62bc037ddbaea46e3c004.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "El dinero paciente crece", "locale": "es-MX", "subject": "mixed", "objectives": ["Predecir cuánto crece un ahorro cuando se deja en una alcancía que da una recompensa semanal."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 15, "type": "interest_peek", "title": "¡Crece de a poquito!", "payload": {"periods": 4, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"max": 50, "min": 0, "kind": "slider"}}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf mete 20 pesos en la alcancía que ''agradece'' cada semana. ¿Cuánto tendrá después de 4 semanas?", "difficulty": 2, "explanation_md": "La alcancía agregó 2 pesos cada semana. Después de 4 semanas, Liruf tiene 28 pesos. La paciencia hizo crecer su dinero rumbo a la guitarra.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 28, "tolerance": 2}}', '{"units": {"s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/c577f206655f1ee3673bc00caa8e2cbfce862ea85383e4031a2a82677843bf6d.mp3", "hash": "de7bc99b469b786a7289df555fd4e8dec038355a0683d0e5dc93523b25509ef4", "bytes": 44064, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c577f206655f1ee3673bc00caa8e2cbfce862ea85383e4031a2a82677843bf6d.mp3", "duration_ms": 7280}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/54aa5f2619bbe97ddb96a67316c9784520d8c32b3f0aa1dc7b0c804b28e681c6.mp3", "hash": "874685136a1ea0dac3c18a30c1ff99eacd13e5a9b92cc000ce776c0c03ccfdb1", "bytes": 68544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/54aa5f2619bbe97ddb96a67316c9784520d8c32b3f0aa1dc7b0c804b28e681c6.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "Purchase Priority", "locale": "en-US", "subject": "mixed", "objectives": ["Sort purchases by priority for a lemonade stand."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-prioridad-compras", "xp": 15, "type": "rank_choices", "hints": ["What does Liruf need to make and sell lemonade today?"], "title": "What to buy first?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/6ad40b2c2e0471ceb46eb797ec1e710adc0e382335357f4029bbe7d7975c2613.webp"}, {"id": "vasos", "icon": "local_cafe", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/cf2539f3a8470d1d2cf979f08c7595260a5979a77e53c5b6d12ea44030223555.webp"}, {"id": "adornos", "icon": "palette", "text_md": "Decor", "image_url": "http://localhost:4006/files/lesson-images/fb304b7220b14c6096253d5425742b194ff02d0556b92acfe1b4ea7e0a2eb61c.webp"}], "criterion_md": "Top: most urgent"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf learned that purchase order matters. With $20, they prioritize purchases.", "difficulty": 2, "explanation_md": "Lemons are the most urgent because without them there''s no lemonade to sell. Cups come next for serving. Decorations can wait.", "audio_segment_id": "s1-prioridad-compras.prompt"}], "schema_version": 1}', '{"s1-prioridad-compras": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-prioridad-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6cffe8b1db9928792ca40139afbf8a962438314e39af5ebc2a8b367ef12945db.mp3", "hash": "8f5069c413d1b2532f6ecf61a0a530f11cc9a8cbf9748d05e8136402a5294dab", "bytes": 22896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6cffe8b1db9928792ca40139afbf8a962438314e39af5ebc2a8b367ef12945db.mp3", "duration_ms": 3760}, "s1-prioridad-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/2dd45e5aa17f94b4d2d5b5314d4b03df8c5131afc591e24486a7c4987502d660.mp3", "hash": "e796160ef89b76d86f7df035e2407d3ea49e5c9c9ff74f9d4ab5f23a639ee41c", "bytes": 39168, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2dd45e5aa17f94b4d2d5b5314d4b03df8c5131afc591e24486a7c4987502d660.mp3", "duration_ms": 6480}, "s1-prioridad-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/b4c3dd7ac3c4fb92fb1028941ed0c14dcd82b5fd245d9ed140bfa8eb32b5679d.mp3", "hash": "7076e57369f479b9ee07eada466d84e9f0f127e783d15ef24c16da462e9d5ca4", "bytes": 55008, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b4c3dd7ac3c4fb92fb1028941ed0c14dcd82b5fd245d9ed140bfa8eb32b5679d.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "Prioridad de compras", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar compras por prioridad para un puesto de limonada."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-prioridad-compras", "xp": 15, "type": "rank_choices", "hints": ["¿Qué necesita Liruf para hacer y vender limonada hoy?"], "title": "¿Qué comprar primero?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/6ad40b2c2e0471ceb46eb797ec1e710adc0e382335357f4029bbe7d7975c2613.webp"}, {"id": "vasos", "icon": "local_cafe", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/cf2539f3a8470d1d2cf979f08c7595260a5979a77e53c5b6d12ea44030223555.webp"}, {"id": "adornos", "icon": "palette", "text_md": "Adornos", "image_url": "http://localhost:4006/files/lesson-images/fb304b7220b14c6096253d5425742b194ff02d0556b92acfe1b4ea7e0a2eb61c.webp"}], "criterion_md": "Arriba: más urgente"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf aprendió que el orden de las compras importa. Con 20 pesos, ordena sus compras por prioridad.", "difficulty": 2, "explanation_md": "Los limones son lo más urgente porque sin ellos no hay limonada que vender. Los vasos vienen después para servir. Los adornos pueden esperar.", "audio_segment_id": "s1-prioridad-compras.prompt"}], "schema_version": 1}', '{"s1-prioridad-compras": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-prioridad-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/63dde24340de3bcc259db1e679f1e36761de2ee859476dc7c1e714bd74af96f4.mp3", "hash": "5bba4c9e39fc33ce79ae4a47a55d54e650b0e39f61ad1388c4c5342200e78320", "bytes": 23328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/63dde24340de3bcc259db1e679f1e36761de2ee859476dc7c1e714bd74af96f4.mp3", "duration_ms": 3840}, "s1-prioridad-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/5a5336e5f5789e59ab9a5a83d7a8149f102ba7470b369f047a48d3761f0c1df6.mp3", "hash": "c80bf06d2939f944c472c91e091a46d5a982f6a54cf629b6385026e8b247b113", "bytes": 43488, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5a5336e5f5789e59ab9a5a83d7a8149f102ba7470b369f047a48d3761f0c1df6.mp3", "duration_ms": 7200}, "s1-prioridad-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/40a2e98a759cabf46d17c6cd49fb804814d4458c6849f2e6fcd5274302e75d6d.mp3", "hash": "c4031a9b7cd2b4e59d3f0026f086663d06292556fd91928476f60340d086a8b1", "bytes": 62208, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/40a2e98a759cabf46d17c6cd49fb804814d4458c6849f2e6fcd5274302e75d6d.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Review: Profit per glass", "locale": "en-US", "subject": "mixed", "objectives": ["Review the profit per glass calculation at the lemonade stand."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-ganancia", "xp": 10, "type": "quiz_mcq", "title": "Quick profit review", "payload": {"options": [{"id": "opt-2", "text_md": "5 dollars", "rationale_md": "It seems correct because it''s the selling price, but profit is what''s left after paying for the ingredients."}, {"id": "opt-4", "text_md": "7 dollars", "rationale_md": "Adding the price and the cost gives 7, but to calculate profit you have to subtract the cost from the price, not add them."}, {"id": "opt-1", "text_md": "3 dollars"}, {"id": "opt-3", "text_md": "2 dollars", "rationale_md": "The 2 dollars are the cost of the ingredients, not the profit. Profit is what''s left over after subtracting the cost."}], "shuffle": false}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina asks Liruf: ''If you sell each glass for 5 dollars and it costs you 2 dollars to make, how much do you earn per glass?''", "difficulty": 1, "explanation_md": "The profit per glass is the selling price minus the cost: 5 - 2 = 3 dollars. That way Liruf knows how much his savings grow for each glass sold. 💰", "audio_segment_id": "s1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"s1-repaso-ganancia": {"correct_option_id": "opt-1"}}', '{"units": {"s1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/0be0fb62c34ebffd8322da086a927f36d47be07e6cbda5a5caaf3cfd782793ca.mp3", "hash": "91b2f8e046581d90de2ac4b9d5ae5b14d25aa60a20abb8fc4a1f7c816b4b03a8", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0be0fb62c34ebffd8322da086a927f36d47be07e6cbda5a5caaf3cfd782793ca.mp3", "duration_ms": 7280}, "s1-repaso-ganancia.choices": {"url": "http://localhost:4006/files/lesson-audio/07d5e0d94e83b2440536066b54760ba8bea8779574d76cf483b18c8a7da73148.mp3", "hash": "02f5114715d8c248c6172543cef5b2fdcef96659f1a810a50623073a22282e16", "bytes": 21456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/07d5e0d94e83b2440536066b54760ba8bea8779574d76cf483b18c8a7da73148.mp3", "duration_ms": 3520}, "s1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/b5266b8702cd6b509df97d973cfa0e32535793fe8ae2e95e512c95b1063ac6c1.mp3", "hash": "7ea3ccf8e2e0671840cee6b863b87312f01120ddfb54b0125597235cc5441c63", "bytes": 56448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b5266b8702cd6b509df97d973cfa0e32535793fe8ae2e95e512c95b1063ac6c1.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "speed-tap", "title": "Rápido! Escolha gastos que ajudam", "locale": "pt-BR", "subject": "money", "objectives": ["Tomar decisões rápidas sobre gastos que ajudam a vender mais limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Pense: é usado para fazer limonada ou para atrair clientes? Se não, deixe passar."], "title": "Ajuda a vender?", "payload": {"items": [{"id": "calco", "icon": "sticky_note_2", "text_md": "Adesivo de dinossauro"}, {"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/23f74254e245c3d45a9332e25c01a9ccbdb0be33eef19ca830574be9aaf8542d.webp"}, {"id": "dulce", "icon": "cookie", "text_md": "Doce", "image_url": "http://localhost:4006/files/lesson-images/dcb18c68887860dd4a4bca23749314272e34047a5f5191547ab9091dbc728e90.webp"}, {"id": "vasos", "icon": "water_bottle", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/eb87037f80540805bb8d630b9b18628287c5fc64e99fef63a9893aff61c3cd58.webp"}, {"id": "cartel", "icon": "flag", "text_md": "Cartaz", "image_url": "http://localhost:4006/files/lesson-images/9c0aa8799ba0e9e1e54f6ac58e3d235d6d825a72fbb9bcd90a35c8e4df809f39.webp"}, {"id": "juguete", "icon": "toys", "text_md": "Brinquedo", "image_url": "http://localhost:4006/files/lesson-images/e4072991efe3c4c374f5f21d1816bdb0ac07d6e047253e77ad22249845753423.webp"}, {"id": "azucar", "icon": "cookie", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/a541255ac8e9de524d4c8ac1a463eb3a5b20fb42d79df839f95aea6c062e849d.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/65cf7775d692ffee1fe707494c55f43448d200bc492e4f62bcf617874872df31.webp"}], "seconds": 25, "instruction_md": "Toque rápido as compras que ajudam."}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Rho te passa cartões voando. Toque apenas as compras que ajudam a vender MAIS limonada. Rápido!", "difficulty": 2, "explanation_md": "Limões, copos, açúcar e gelo são ingredientes da limonada. Um cartaz bonito atrai mais clientes. Um adesivo, um doce ou um brinquedo não enchem o pote de Liruf.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/724de634bb4039c8b902f1730f4c1eb93259b7ff2086f22104c23130cf17b72a.mp3", "hash": "df1e649d8921083455237b05773f8d0823ddc99b5d145b5a62fa591ff85dbf9f", "bytes": 39168, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/724de634bb4039c8b902f1730f4c1eb93259b7ff2086f22104c23130cf17b72a.mp3", "duration_ms": 6480}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/7d329136fdb7d2908b87209cdfa541cb2d17d7e3def2d0d3fd868e12d0700f96.mp3", "hash": "b8e5e26b0326d59843f94c2ecbf2a732d3c170c4fd04578f6598a9427bb849e8", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7d329136fdb7d2908b87209cdfa541cb2d17d7e3def2d0d3fd868e12d0700f96.mp3", "duration_ms": 7280}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/4674c8a949e147a39b0afd4041bb61953b2a27671757e736c1377e6c314e974f.mp3", "hash": "1ea6f1d90cd5ce95bf667379a4d4f609dce66de1f95e1b9a2b5d9de05847ff6b", "bytes": 79056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4674c8a949e147a39b0afd4041bb61953b2a27671757e736c1377e6c314e974f.mp3", "duration_ms": 13120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Conte as moedas de venda", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar o número exato de moedas em uma cena desordenada", "Associar cada moeda contada a uma venda de 5 reais"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "count-objects-sales", "xp": 5, "type": "count_objects", "title": "Conte as moedas de venda", "payload": {"scene": [{"icon": "monetization_on", "tint": "delight", "count": 8, "label": "moeda", "image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, {"icon": "cookie", "tint": "warning", "count": 3, "label": "biscoito", "image_url": "http://localhost:4006/files/lesson-images/f2975e6e8d715646e735228b20f39c19a408d57acbe156d19e08e426fad7fc66.webp"}, {"icon": "local_drink", "tint": "primary", "count": 2, "label": "copo", "image_url": "http://localhost:4006/files/lesson-images/e7f7f16426e7194c18895bfcec92b380cc27efe30ad87d400a21821b9a14d390.webp"}], "ask_icon": "monetization_on", "ask_label": "moeda", "ask_image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf derrubou o frasco das vendas. Conte apenas as moedas que caíram. Cada uma é um copo de 5 reais que ele já vendeu.", "difficulty": 1, "explanation_md": "Caíram 8 moedas. Cada uma é 5 reais! Isso significa que Liruf vendeu 8 copos de limonada hoje. Esses 8 copos se somam à sua poupança para a guitarra de 80 reais.", "audio_segment_id": "count-objects-sales.prompt"}], "schema_version": 1}', '{"count-objects-sales": {"value": 8}}', '{"units": {"count-objects-sales.prompt": {"url": "http://localhost:4006/files/lesson-audio/480a150a32fab08182badeedccb08887b1825e1139758dd70ec7f79a940f78f6.mp3", "hash": "72ed3894646f8cb87f67a1610e873b5205cd27e1de32a291847467882bb58cd4", "bytes": 49824, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/480a150a32fab08182badeedccb08887b1825e1139758dd70ec7f79a940f78f6.mp3", "duration_ms": 8240}, "count-objects-sales.explanation": {"url": "http://localhost:4006/files/lesson-audio/3b7803b73420da9eb203e0fbc01234f5986d3184beac70800feee34625a782b6.mp3", "hash": "cff1fad37b7ba1992b0f74ac93dad0bc57cff86d20f774ebd5194cbc44b2756a", "bytes": 80928, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3b7803b73420da9eb203e0fbc01234f5986d3184beac70800feee34625a782b6.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "Preços misturados", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combinar cada produto da barraca com seu preço correto."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 10, "type": "match_pairs", "title": "Preços misturados", "payload": {"left": [{"id": "vaso-chico", "icon": "local_cafe", "text_md": "Copo pequeno", "image_url": "http://localhost:4006/files/lesson-images/9702c5a83f6952c11eca3aadcd41969dbc16246f2935a48ae531e85aabbbebc9.webp"}, {"id": "jarra", "icon": "water_drop", "text_md": "Jarra", "image_url": "http://localhost:4006/files/lesson-images/6d837a16c35590a0e6c0c628d0e35c0d47439ce1ebb0f560b17aee2f17186dcc.webp"}, {"id": "galleta", "icon": "cookie", "text_md": "Biscoito", "image_url": "http://localhost:4006/files/lesson-images/0208d79e7aeaaeb5ba7bd1959b17e92b0ec66bd11c422bf8c7f7bf7b90efc0aa.webp"}], "right": [{"id": "precio-5", "text_md": "5 reais"}, {"id": "precio-20", "text_md": "20 reais"}, {"id": "precio-3", "text_md": "3 reais"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "O vento derrubou as etiquetas de preços. Devolva cada uma ao seu produto!", "difficulty": 1, "explanation_md": "O copo pequeno custa 5 reais; a jarra, 20; e o biscoito, 3. Assim a barraca fica organizada e os clientes sabem o que pagar.", "audio_segment_id": "s1-match-pairs.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["vaso-chico", "precio-5"], ["jarra", "precio-20"], ["galleta", "precio-3"]]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/00f76d2c83f584fd78caa3c7773b510e3c49ceb1c56e02d1de6eb1e6f075e20e.mp3", "hash": "e9a0f9151c2ad649b63306e998d9da34af1d5270fc96507ae4a70e019403a128", "bytes": 34848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/00f76d2c83f584fd78caa3c7773b510e3c49ceb1c56e02d1de6eb1e6f075e20e.mp3", "duration_ms": 5760}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/8ea547a5e882bf514dca8085fd97986d42ef5ef66f7bcbeb03662c1087c64c82.mp3", "hash": "6fd4f351a3e26c83464bf2136b0cc324ebeb154a021beb107cf25b30c3b5c223", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8ea547a5e882bf514dca8085fd97986d42ef5ef66f7bcbeb03662c1087c64c82.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "dialogue-choice", "title": "A barraca de limonada: Vamos negociar com os clientes!", "locale": "pt-BR", "subject": "money", "objectives": ["Escolher o que responder a um cliente que pede desconto: negociar com gentileza sem abrir mão do lucro."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-cliente", "xp": 15, "type": "dialogue_choice", "hints": [], "title": "Negocie com o cliente", "payload": {"turns": [{"id": "turn1", "npc_md": "Cliente: ''Ei, você deixa a limonada por 3 reais? Só tenho isso.''", "replies": [{"id": "r1a", "text_md": "Claro, deixo por 3 reais."}, {"id": "r1b", "text_md": "Sinto muito, não baixo o preço. Se comprar dois copos, te dou um de brinde."}, {"id": "r1c", "text_md": "Fazer o quê? São 5 reais. Se não quiser, tchau!"}]}, {"id": "turn2", "npc_md": "Uma criança se aproxima e te diz: ''Você me dá um copinho? Não tenho dinheiro.''", "replies": [{"id": "r2a", "text_md": "Claro, pegue um de graça."}, {"id": "r2b", "text_md": "Não posso dar de graça, mas se você me ajudar a distribuir panfletos, te dou um copo."}, {"id": "r2c", "text_md": "Sinto muito, preciso cobrar para economizar. Você pode trazer dinheiro amanhã!"}]}], "persona": {"name": "Liruf", "role_md": "Dono da barraca de limonada", "character": "liruf"}, "opening_md": "É um dia ensolarado e Liruf vende copos de limonada a R$5 cada um em sua barraca."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/a36c247b50458699884b93ae81561c81d5274e31b8e2cfb97e81ce57aab10551.webp", "prompt_md": "Liruf deve atender dois clientes. Toque na melhor resposta em cada caso.", "difficulty": 2, "explanation_md": "Quando um cliente pede desconto, Liruf pode oferecer mais em vez de baixar o preço. Assim todos ganham e ele continua economizando para sua guitarra.", "audio_segment_id": "s1-dialogo-cliente.prompt"}], "schema_version": 1}', '{"s1-dialogo-cliente": {"turns": [{"turn_id": "turn1", "qualities": {"r1a": 30, "r1b": 100, "r1c": 10}, "reactions": {"r1a": "¡Gracias! Eres muy amable.", "r1b": "¡Qué buena oferta! Llevo dos entonces.", "r1c": "Qué malo, me voy a otro puesto."}}, {"turn_id": "turn2", "qualities": {"r2a": 20, "r2b": 100, "r2c": 50}, "reactions": {"r2a": "¡Gracias! Eres el mejor.", "r2b": "¡Trato hecho! Dame volantes y te ayudo.", "r2c": "Está bien, entiendo. Mañana traigo dinero."}}]}}', '{"units": {"s1-dialogo-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/45fcb6cb0f7cb30c0f37b7cdcca9b8fbdec8d07bfdf1d096b11bd9f38aacd47f.mp3", "hash": "4648e87c6170b9187be626caefb28e1b5ca6fb8b4dbf939cb6b9169c9226a12f", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/45fcb6cb0f7cb30c0f37b7cdcca9b8fbdec8d07bfdf1d096b11bd9f38aacd47f.mp3", "duration_ms": 5600}, "s1-dialogo-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/5e1b780bb289aece715b4d7f520870b976168ca1ddf8b365b2e22a85c4720d4b.mp3", "hash": "127f517c78ed76c4bd3b11d48d292a97ed6b1c2c8df2ed3ed9a7b60ba3cecb6b", "bytes": 64656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5e1b780bb289aece715b4d7f520870b976168ca1ddf8b365b2e22a85c4720d4b.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "speed-tap", "title": "Quick! Choose expenses that help", "locale": "en-US", "subject": "money", "objectives": ["Make quick decisions about expenses that help sell more lemonade."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Think: Is it used to make lemonade or to attract customers? If not, skip it."], "title": "Does it help sell?", "payload": {"items": [{"id": "calco", "icon": "sticky_note_2", "text_md": "Dinosaur sticker"}, {"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/23f74254e245c3d45a9332e25c01a9ccbdb0be33eef19ca830574be9aaf8542d.webp"}, {"id": "dulce", "icon": "cookie", "text_md": "Candy", "image_url": "http://localhost:4006/files/lesson-images/dcb18c68887860dd4a4bca23749314272e34047a5f5191547ab9091dbc728e90.webp"}, {"id": "vasos", "icon": "water_bottle", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/eb87037f80540805bb8d630b9b18628287c5fc64e99fef63a9893aff61c3cd58.webp"}, {"id": "cartel", "icon": "flag", "text_md": "Poster", "image_url": "http://localhost:4006/files/lesson-images/9c0aa8799ba0e9e1e54f6ac58e3d235d6d825a72fbb9bcd90a35c8e4df809f39.webp"}, {"id": "juguete", "icon": "toys", "text_md": "Toy", "image_url": "http://localhost:4006/files/lesson-images/e4072991efe3c4c374f5f21d1816bdb0ac07d6e047253e77ad22249845753423.webp"}, {"id": "azucar", "icon": "cookie", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/a541255ac8e9de524d4c8ac1a463eb3a5b20fb42d79df839f95aea6c062e849d.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/65cf7775d692ffee1fe707494c55f43448d200bc492e4f62bcf617874872df31.webp"}], "seconds": 25, "instruction_md": "Quickly tap the purchases that help."}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Rho passes you cards quickly. Tap only the purchases that help sell MORE lemonade. Quick!", "difficulty": 2, "explanation_md": "Lemons, cups, sugar, and ice are ingredients for the lemonade. A nice poster attracts more customers. A sticker, candy, or a toy won''t fill Liruf''s jar.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e7aea0424005365fc4405ec5021c59bddd7c8b11f741e9e5f5beaf76a7160c91.mp3", "hash": "dff26a0ed9d3433352302cbe442c8c81740c1c515c875f7a62ad74a118df1802", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e7aea0424005365fc4405ec5021c59bddd7c8b11f741e9e5f5beaf76a7160c91.mp3", "duration_ms": 4640}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/a81d59404e619afe6166104b08514da8c3fc7529a43795ddd1624a6487f928e2.mp3", "hash": "8064d0493108da3dedfb5dec5ea0742c7557a56fffca4a10d39ea2aeabc0d9b5", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a81d59404e619afe6166104b08514da8c3fc7529a43795ddd1624a6487f928e2.mp3", "duration_ms": 5200}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/c16f72fc9c59f77698f9e61a1d16a51e0906d216ae8833474d375bee166e107a.mp3", "hash": "59e62ede3f32e4d2982f0cefaec52fc60be7660b49edd4e5bd630930ffa38d1b", "bytes": 58464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c16f72fc9c59f77698f9e61a1d16a51e0906d216ae8833474d375bee166e107a.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "picture-choice", "title": "¿Dónde guardar el dinero?", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el lugar más seguro para guardar las ganancias del día."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 8, "type": "picture_choice", "title": "El lugar seguro", "payload": {"options": [{"id": "opt1", "icon": "wallet", "label": "Bolsillo roto", "image_url": "http://localhost:4006/files/lesson-images/4e2abf237219b8117084640a1b04964166d8a54edd652fb5fcf751357019ea9b.webp", "rationale_md": "El dinero podría caerse por el agujero."}, {"id": "opt2", "icon": "savings", "label": "Alcancía con llave", "image_url": "http://localhost:4006/files/lesson-images/9681bc52834c92a8becdd0f2853e569f8a065b99bd2ee43b8bdacc1f103ff2d3.webp"}, {"id": "opt3", "icon": "table_restaurant", "label": "Mesa del puesto", "image_url": "http://localhost:4006/files/lesson-images/c7a7477fa0d906300135e0eb029415c13f98959267fe79c5560159025bd2faee.webp", "rationale_md": "Cualquiera que pase podría tomarlo sin que te des cuenta."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf terminó de vender limonada y tiene 20 pesos. ¿Dónde es más seguro guardarlos?", "difficulty": 1, "explanation_md": "La alcancía con llave mantiene el dinero a salvo; en el bolsillo roto podría caerse y en la mesa cualquiera lo tomaría.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt2"}}', '{"units": {"s1-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/118a4099eba2eb6e44c67fa3d29acfe26ca995f346c8fdeb576192b128deefa9.mp3", "hash": "d834382ae43d834c90714b4b6339da8db24ca1bcbf01c1d52995edcd13843f9a", "bytes": 40176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/118a4099eba2eb6e44c67fa3d29acfe26ca995f346c8fdeb576192b128deefa9.mp3", "duration_ms": 6640}, "s1-picture-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/d92771ff4141d3d788722a2b5366fe8e6eaf6da4dcc973c85448fd41708dd840.mp3", "hash": "068327cd2750ef4183b3c78a9b9988ede1039cfde718948bd147b2d79d59e78c", "bytes": 25776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d92771ff4141d3d788722a2b5366fe8e6eaf6da4dcc973c85448fd41708dd840.mp3", "duration_ms": 4240}, "s1-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/d0ddc6fe0a89f3a36f28780debb78bf627ede910b418c89167ea7494b9d642f2.mp3", "hash": "38cfb5899fdc9457f5b5ed4a4467b437a3884df0fe99231f41b44ace914b0f31", "bytes": 48816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d0ddc6fe0a89f3a36f28780debb78bf627ede910b418c89167ea7494b9d642f2.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "best-decision", "title": "The best decision when giving change", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the best decision when a customer pays with a $20 bill for a $5 glass: counting the change calmly (not guessing or keeping it)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 10, "type": "best_decision", "title": "Liruf''s change", "payload": {"options": [{"id": "count-change", "text_md": "Count the change: 15 dollars in coins", "rationale_md": "Counting the change calmly ensures the customer receives the exact amount and maintains trust in the stand."}, {"id": "guess-change", "text_md": "Guessing and giving 10 dollars", "rationale_md": "It is tempting to guess to be quick, but you would give $5 less and the customer would leave with less money than they deserve."}, {"id": "keep-change", "text_md": "Keeping the bill and not giving change", "rationale_md": "It is tempting to keep everything, but it is dishonest and the customer would get angry, plus you would lose a customer."}], "scenario_md": "Liruf is at his lemonade stand. The first customer arrives and asks for a $5 glass. She hands him a $20 bill. Liruf feels nervous, but he must give the correct change."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cc47c359a84dd0eafde1bda6a8e9076e41f27e33f53112d10df9eaa2136f9160.webp", "prompt_md": "The customer pays with a $20 bill for a $5 glass. What should Liruf do?", "difficulty": 1, "explanation_md": "Counting the $15 change calmly is the best decision: the customer gets the right amount and Liruf gains confidence.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"keep-change": 0, "count-change": 100, "guess-change": 30}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/d962aba10046cc47a524541a44fdc62abff5700296539f10a2c33107e9677bb4.mp3", "hash": "888bc9a181d2b7b061bf9538a098f6cabd7b04d11588f2d701236b0bc00be111", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d962aba10046cc47a524541a44fdc62abff5700296539f10a2c33107e9677bb4.mp3", "duration_ms": 4960}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/0bf61d57fa8e8e839f51831b0de3c95051bb45b51c77aa4da4140c1b1bc8d93e.mp3", "hash": "7234f9a06545712921271cbe464113b9cb79130531e247cb878359611af5a295", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0bf61d57fa8e8e839f51831b0de3c95051bb45b51c77aa4da4140c1b1bc8d93e.mp3", "duration_ms": 6320}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/96ad1ba5d33552f9869105c596476bad9f4c7fa56a15f79746e29906363f23b5.mp3", "hash": "a1f5f2b9b0b41b067630dbeb44e6b07f89bfc55114053a6e80e84056b8ed5a62", "bytes": 40608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/96ad1ba5d33552f9869105c596476bad9f4c7fa56a15f79746e29906363f23b5.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Needs and wants at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separate the needs of the lemonade stand from personal wants."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "needs-wants-1", "xp": 10, "type": "needs_wants", "hints": ["Hint: Can Liruf sell lemonade without this? If not, it''s a need."], "title": "Needs and wants", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/1be5b55a4cacf2174b4ed0c13f4e27f7e86f095fe85a2da912c97830ae354bad.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/6266599e8d76c27c9bf369b2b0c59010493415893dfd34b51499e18c816e21fe.webp"}, {"id": "vasos", "icon": "water_drop", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/abf95f91e3e5d0a6225fd83557a45c2886dab03b058449c9551713bd93eb4633.webp"}, {"id": "paleta", "icon": "icecream", "text_md": "Lollipop", "image_url": "http://localhost:4006/files/lesson-images/6a902c8bd79a972f87a4f03ad2a48e351c138e92a4443deaf5dd1f094f099495.webp"}, {"id": "comic", "icon": "auto_stories", "text_md": "Comic", "image_url": "http://localhost:4006/files/lesson-images/ede5b71ddfb77514ed873c22f9d5659644892e52893ff67ed4595dac793f64a7.webp"}, {"id": "juguete", "icon": "toys", "text_md": "Toy", "image_url": "http://localhost:4006/files/lesson-images/16161313c663e9e7c70417e58de7dbe663ca8f05bff00c9837b942381fbb9a09.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf buys things for his lemonade stand. Touch each item and choose: need for the stand or personal want?", "difficulty": 1, "explanation_md": "The lemons, ice, and cups are needs because without them Liruf can''t make or sell lemonade 🍋. The lollipop, comic, and toy are wants he can buy later, when the stand earns money.", "audio_segment_id": "needs-wants-1.prompt"}], "schema_version": 1}', '{"needs-wants-1": {"needs_ids": ["limones", "hielo", "vasos"]}}', '{"units": {"needs-wants-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c27336ee6d17756657d5eeae4d67b423ea91ae2924dd38b78e07fe9cd1bd0d30.mp3", "hash": "12818abeb989d358dd1b2014961171e3324a422d29f3e60f2efd0220100cc274", "bytes": 23904, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c27336ee6d17756657d5eeae4d67b423ea91ae2924dd38b78e07fe9cd1bd0d30.mp3", "duration_ms": 3920}, "needs-wants-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/8095355faaed7bdbfd07072b8f00975803232c45c8d3cf4dbd3659aa7a467e6a.mp3", "hash": "a40ca90edc80f930cde000c4433fd39be40b563194fa1fad74fbd7dd3af60435", "bytes": 36864, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8095355faaed7bdbfd07072b8f00975803232c45c8d3cf4dbd3659aa7a467e6a.mp3", "duration_ms": 6080}, "needs-wants-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/0768aabf8c875fb939a056e2b0e46e4517c9ba1a89c0e35faa1be978b871ffdd.mp3", "hash": "df32011a59798b23cdf28021144928eb2a2e678dd8b069fb0daf95943db64193", "bytes": 62784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0768aabf8c875fb939a056e2b0e46e4517c9ba1a89c0e35faa1be978b871ffdd.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "number-line", "title": "The savings number line", "locale": "en-US", "subject": "mixed", "objectives": ["Place on the number line from 0 to 100 where Liruf''s savings (20 dollars) and the goal (80) go: see how much is left."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 5, "type": "number_line", "title": "How much is left?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "After grouping coins and bills, Liruf wants to see how much he is missing. He places his savings (20 dollars) on the number line.", "difficulty": 1, "explanation_md": "Liruf already has 20 dollars. The goal is 80, which is much further to the right. He needs 60 more dollars for the skateboard! 🎉", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 0, "zero_credit_delta": 10}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/84043aad1b09f3d712dc88d585bd9fac2f45ee3bbe9e4ba4750a474b3d412d80.mp3", "hash": "f357288ae795ed07fa957b384e2d7422372a70bef7d623b5719843ff8069d685", "bytes": 59904, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/84043aad1b09f3d712dc88d585bd9fac2f45ee3bbe9e4ba4750a474b3d412d80.mp3", "duration_ms": 9920}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/34cc848c9a1791e32388e0eb69a323cca5d6b12b31faca0c5ac3e0b060c71cb5.mp3", "hash": "8b745f9d5da8fe395f15d1fc857f9cbb7107cd623e3f727fdb28d88898281cac", "bytes": 54144, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/34cc848c9a1791e32388e0eb69a323cca5d6b12b31faca0c5ac3e0b060c71cb5.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "code-order", "title": "Rho''s cardboard cash register", "locale": "en-US", "subject": "mixed", "objectives": ["Arrange the steps to use a homemade cash register"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "code-order-1", "xp": 5, "type": "code_order", "title": "Cash register instructions", "payload": {"blocks": [{"id": "recibir", "text_md": "Receive payment"}, {"id": "verificar", "text_md": "Verify amount"}, {"id": "dar_cambio", "text_md": "Give change"}, {"id": "anotar", "text_md": "Record the sale"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho invented a cardboard cash register. Tap the blocks in the correct order to use it.", "difficulty": 1, "explanation_md": "The correct order is: receive payment, verify the amount, give change, and record the sale. That''s how Rho''s cardboard cash register works without mistakes!", "audio_segment_id": "code-order-1.prompt"}], "schema_version": 1}', '{"code-order-1": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"code-order-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/0684a3f508edb8cec22964c6108478a4842d60affe243ff21a318a955e92e44e.mp3", "hash": "a3c5e7384d66cda9102ab4303d46de9749d6347bebf6b8f5e48d5f052a868033", "bytes": 36288, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0684a3f508edb8cec22964c6108478a4842d60affe243ff21a318a955e92e44e.mp3", "duration_ms": 6000}, "code-order-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/34e50a1666afa4a5c04460f250cc4b3502e8c230cfb30edaeae5f1397db68ef4.mp3", "hash": "bb737e6f0b529abff8ae9af80eae6e2e4086ade7a810cfce422dd6949bcc1148", "bytes": 74304, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/34e50a1666afa4a5c04460f250cc4b3502e8c230cfb30edaeae5f1397db68ef4.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "O violão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir que o dinheiro para o violão pode ser ganho vendendo limonada, não apenas esperar um presente."], "estimated_minutes": 3}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-intro", "xp": 0, "type": "story_dialogue", "title": "O violão de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Que legal está esse violão... mas custa 80 reais. Eu não tenho tanto dinheiro.", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Ei, Liruf, e se você mesmo ganhar vendendo limonada? Você poderia juntar os 80 reais!", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Caramba! Você acha que eu consigo? Será que o pessoal compraria limonada?", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Claro que sim. Se você preparar uma boa limonada e vender a 5 reais o copo, você vai ver que rápido você junta a meta!", "character": "dina"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/13ad009caae0689b6b46350635f5cfa1004ebc7f4ef7b4b7004f176cee8bedde.webp", "prompt_md": "Escute a conversa entre Dina e Liruf.", "difficulty": 1, "audio_segment_id": "s1-intro.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-intro.line.0": {"url": "http://localhost:4006/files/lesson-audio/8d1b28c1dfea7de9c117a2a6e3b309b579209fc3598c28bae97d465fd9dc95b3.mp3", "hash": "16c69f4754185a36241ceca47c6e1c49356f0ed3f7472ed402e21ebc5bdd280c", "bytes": 35424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8d1b28c1dfea7de9c117a2a6e3b309b579209fc3598c28bae97d465fd9dc95b3.mp3", "duration_ms": 5840}, "s1-intro.line.1": {"url": "http://localhost:4006/files/lesson-audio/c1a7000ed89d77935d3e6bb114fa350a3f1d6c573f5b474189f9032eb2b1bdf4.mp3", "hash": "59809170a3508906b0a7c46956b81e19022bc8203708ba38fb9b0cbf828756d5", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c1a7000ed89d77935d3e6bb114fa350a3f1d6c573f5b474189f9032eb2b1bdf4.mp3", "duration_ms": 7040}, "s1-intro.line.2": {"url": "http://localhost:4006/files/lesson-audio/b13dee21ea94351d25c63e6eb55865f465ba48f9909429f385121c1ea7e73e09.mp3", "hash": "75fa6a433e010c7ef17a69991f7660ceb7df4b67a552306d55b97ab9b6e7b6a2", "bytes": 30096, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b13dee21ea94351d25c63e6eb55865f465ba48f9909429f385121c1ea7e73e09.mp3", "duration_ms": 4960}, "s1-intro.line.3": {"url": "http://localhost:4006/files/lesson-audio/7ee832bb1c62ba85becb58f07659c935ebecf67490b333b09eb931398a80efb5.mp3", "hash": "fa2f73ee892dac9e26ae8886aa5035f059ae33921b624c86878682fa84c84129", "bytes": 51264, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7ee832bb1c62ba85becb58f07659c935ebecf67490b333b09eb931398a80efb5.mp3", "duration_ms": 8480}, "s1-intro.prompt": {"url": "http://localhost:4006/files/lesson-audio/773cf6f7411099aecea7cbfbb93c9d0eb390f182a71295b57ab9e865fdc890f3.mp3", "hash": "2867748253d9f415ebb7b814eb154a084dfdb757b438218ef7362a0f40c7e846", "bytes": 17568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/773cf6f7411099aecea7cbfbb93c9d0eb390f182a71295b57ab9e865fdc890f3.mp3", "duration_ms": 2880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "La máquina de propinas", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir la regla de la máquina de propinas: duplica la entrada."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Compara el número que entra con el que sale. ¿Qué operación hizo la máquina?"], "title": "La máquina de la abuela", "payload": {"examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 4}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de medir los vasos, la abuela trae su máquina de propinas. Entra 1→2, entra 3→6. ¿Cuánto sale con 4?", "difficulty": 2, "explanation_md": "La máquina duplica lo que entra. Si metes 4, devuelve 8, porque 4 + 4 = 8. ¡Qué padre! 💡", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f9866b94a27e8c36d451b01bc513b429abbcd75ff4b53ff3fa073db14b5621a3.mp3", "hash": "84d351520597b559cfafc9656d0f4a1c59ec52e01e252382c2d0b8a62de3ec9f", "bytes": 26208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f9866b94a27e8c36d451b01bc513b429abbcd75ff4b53ff3fa073db14b5621a3.mp3", "duration_ms": 4320}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/9c3eb3c001526713cfe6061b35fba4ad9be423935b40e16d6b36820377e8a98e.mp3", "hash": "c28eb1c6a469ece886333e06074775ceb2b35f75afa689005070cb8db1550a53", "bytes": 58464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9c3eb3c001526713cfe6061b35fba4ad9be423935b40e16d6b36820377e8a98e.mp3", "duration_ms": 9680}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/42dd8a22b5f4595c4ca6eb4d2a459d437c94cc0fa76c8011e3a40391f19ed991.mp3", "hash": "fcd3cab230e4aceac3361f18cb5b34031a1553e5b3c86afc953abe1af3854f99", "bytes": 52128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/42dd8a22b5f4595c4ca6eb4d2a459d437c94cc0fa76c8011e3a40391f19ed991.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "A Barraca do Liruf: O que Dizem os Vizinhos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encadear várias habilidades na mesma lição: ouvir a situação, decidir, calcular e cobrar.", "Ouvir dois clientes conversarem sobre a limonada e responder duas perguntas seguidas: uma de verdadeiro/falso e outra com imagens."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "title": "Na mesa ao lado", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Você já viu a barraca de limonada do Liruf?", "character": "rho"}, {"action": "idle", "emotion": "neutral", "text_md": "Sim! Vendem a 5 reais o copo. Que barato!", "character": "zara"}, {"action": "idle", "emotion": "thinking", "text_md": "Eles gostam da minha limonada!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/5973990d23e9d6037d1f1337c4438acf809bdeca0c8fe394ad0ffded88aa6907.webp", "prompt_md": "Liruf está em sua barraca e ouve dois vizinhos.", "difficulty": 1, "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-verdadero-falso", "xp": 15, "type": "true_false", "title": "O que disseram?", "payload": {"statement_md": "O preço de um copo de limonada na barraca do Liruf é 10 reais.", "justifications": [{"id": "just-1", "text_md": "O copo custa 5 reais, como disseram os vizinhos."}, {"id": "just-2", "text_md": "É falso, mas o cliente deveria pagar 10 reais porque a limonada é premium."}]}, "prompt_md": "Os vizinhos dizem que o copo custa 10 reais?", "difficulty": 2, "explanation_md": "O copo de limonada custa 5 reais, então a afirmação é falsa.", "audio_segment_id": "s2-verdadero-falso.prompt"}, {"id": "s3-imagen", "xp": 15, "type": "picture_choice", "title": "O pagamento exato", "payload": {"options": [{"id": "coin-5", "icon": "monetization_on", "label": "Moeda de 5 reais", "image_url": "http://localhost:4006/files/lesson-images/652da598efa28187d0fceeed66bf0f59a603bfbe50aa719aebe3bc5a5ba4042c.webp"}, {"id": "coin-1", "icon": "monetization_on", "label": "Moeda de 1 real", "image_url": "http://localhost:4006/files/lesson-images/ee3d0b75d271db35c43d7e527fa6c03d5748be55399a0882abda359685c7c726.webp", "rationale_md": "Falta dinheiro: você cobriria apenas 1 real dos 5 necessários."}, {"id": "coin-10", "icon": "monetization_on", "label": "Moeda de 10 reais", "image_url": "http://localhost:4006/files/lesson-images/b555ba34ba4bab919345899f7d495c6b513ad119f0476731740013d29ffcbce9.webp", "rationale_md": "Sobraria dinheiro e não é o pagamento exato que o exercício pede."}, {"id": "coin-2", "icon": "monetization_on", "label": "Moeda de 2 reais", "image_url": "http://localhost:4006/files/lesson-images/cd4f65198305aaf25134cd8f3e095704d69c21b048a0b5109c67f3314b29e4be.webp", "rationale_md": "Falta dinheiro: você pagaria apenas 2 reais de 5."}]}, "prompt_md": "Um cliente quer pagar um copo de limonada de 5 reais com a moeda exata. Qual moeda ele deve usar?", "difficulty": 2, "explanation_md": "A moeda de 5 reais paga exatamente o que custa um copo de limonada.", "audio_segment_id": "s3-imagen.prompt"}], "schema_version": 1}', '{"s3-imagen": {"correct_option_id": "coin-5"}, "s2-verdadero-falso": {"is_true": false, "correct_justification_id": "just-1"}}', '{"units": {"s3-imagen.prompt": {"url": "http://localhost:4006/files/lesson-audio/f96e68158aec7d729e67e2ae25ab8053d6b0c65d40f74dde2aba97e6160bc9a3.mp3", "hash": "eb67e16bf998fe7adc4161961c0c161493c558e2cfe7fb01f55abdccdfc8ee0f", "bytes": 39168, "voice": "Ryan", "file_id": "lesson-audio/f96e68158aec7d729e67e2ae25ab8053d6b0c65d40f74dde2aba97e6160bc9a3.mp3", "duration_ms": 6480}, "s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/be0c32ac5fc63057d10841deb1ef9d7acc4dac4c8e5cb82fee16163afe6237fc.mp3", "hash": "807d9a856fe2d50bf9e6484e9617e4bda48cf686d0a3c46f5ed3bf05c0d257f1", "bytes": 19584, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/be0c32ac5fc63057d10841deb1ef9d7acc4dac4c8e5cb82fee16163afe6237fc.mp3", "duration_ms": 3200}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/2eb88093df12a3a54a3a76ad035550eeb443f787eacb33271d4dbe355e26326d.mp3", "hash": "88a2007d7d547277b02fe01a39013078d9fd620c983e53fb99f1ba2fcc863d98", "bytes": 23328, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/2eb88093df12a3a54a3a76ad035550eeb443f787eacb33271d4dbe355e26326d.mp3", "duration_ms": 3840}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/f91028b8dc5546f2e5fb7c853a157d8df3684e482a57ec6140c1e9e576595751.mp3", "hash": "9668f15e3cc478fb0a7274d4f0f67a8c60969530f5462c3890ba8090c26afabb", "bytes": 13248, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f91028b8dc5546f2e5fb7c853a157d8df3684e482a57ec6140c1e9e576595751.mp3", "duration_ms": 2160}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/8533614feb15e50f07884b112b16d89c2680d182446c7124122f43475c69c4fc.mp3", "hash": "bb0f1d064be70806362f1a200e939ed5a87603621d37469d9910714b2a4d0a18", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8533614feb15e50f07884b112b16d89c2680d182446c7124122f43475c69c4fc.mp3", "duration_ms": 4080}, "s3-imagen.choices": {"url": "http://localhost:4006/files/lesson-audio/d212492aa9fa4f2fc76dbf44fffdf91928caaa2b6f65f5569cdc710c0043589c.mp3", "hash": "1626a36ee7f312d87f64d2ed7676342043e2af6546972b58b8a39d5ec474b0a7", "bytes": 51264, "voice": "Ryan", "file_id": "lesson-audio/d212492aa9fa4f2fc76dbf44fffdf91928caaa2b6f65f5569cdc710c0043589c.mp3", "duration_ms": 8480}, "s3-imagen.explanation": {"url": "http://localhost:4006/files/lesson-audio/68bb29a7e82895014b3813c7ae8b8136efd06e244b80d01aa161223bf2fcbc37.mp3", "hash": "3822aad1980d66d735fcc5813add3cfab84878740196d093c6e45c2edfe795ec", "bytes": 27648, "voice": "Ryan", "file_id": "lesson-audio/68bb29a7e82895014b3813c7ae8b8136efd06e244b80d01aa161223bf2fcbc37.mp3", "duration_ms": 4560}, "s2-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/656263c17fe9bbe94f383d65a4375726823bbee59976c746df534dce0531a10c.mp3", "hash": "adfab3dc59abc2843d4b66bb9433228d065f4382fd6051a20dd5401197f4ffd6", "bytes": 19008, "voice": "Ryan", "file_id": "lesson-audio/656263c17fe9bbe94f383d65a4375726823bbee59976c746df534dce0531a10c.mp3", "duration_ms": 3120}, "s2-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/b7869f46d9ee1700d5781a2282aa7cd4d7c45dc146eed2d7da9927105e8dbea0.mp3", "hash": "d0ae55f37e199397138d351f7f1863f56159109e631f3a57e66e05c76931c6c6", "bytes": 25776, "voice": "Ryan", "file_id": "lesson-audio/b7869f46d9ee1700d5781a2282aa7cd4d7c45dc146eed2d7da9927105e8dbea0.mp3", "duration_ms": 4240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "concept-reveal", "title": "Custo e Lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender o significado de custo e lucro em um negócio de limonada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "concept-reveal-cost-ganancia", "xp": 0, "type": "concept_reveal", "title": "Custo e Lucro", "payload": {"cards": [{"icon": "shopping_bag", "back_md": "É o que você gasta para fazer a limonada: limões, açúcar, copos.", "front_md": "CUSTO", "image_url": "http://localhost:4006/files/lesson-images/7173825680a30310360248399acf0530638eac901929db1b77118bac8c141222.webp"}, {"icon": "savings", "back_md": "É o dinheiro que sobra para você depois de pagar o custo.", "front_md": "LUCRO", "image_url": "http://localhost:4006/files/lesson-images/1c3214489aab355b04677f5b88ae3587d5477eb25222f98eb5cc7febcb6cfa9b.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Para ganhar dinheiro e comprar o violão de 80 reais, você precisa conhecer o custo e o lucro. Toque em cada cartão.", "difficulty": 1, "explanation_md": "O custo é o que você gasta. O lucro é o que você ganha de verdade depois de pagar o custo. Assim você sabe se o seu negócio funciona!", "audio_segment_id": "concept-reveal-cost-ganancia.prompt"}], "schema_version": 1}', '{}', '{"units": {"concept-reveal-cost-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/972fca0cc7451ccf3d3034c296d909a5724b7c75134910dbdd866349fc6fdbb4.mp3", "hash": "f6d03ae6d6bbc53cce08ef0bbcca466f1314cf2fb5ebfa5ffaf543d0cc9733e3", "bytes": 48816, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/972fca0cc7451ccf3d3034c296d909a5724b7c75134910dbdd866349fc6fdbb4.mp3", "duration_ms": 8080}, "concept-reveal-cost-ganancia.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/a0865963ffb6798b20f500160a70a7fd24749c9e61812a941ed9f85f32985793.mp3", "hash": "5c0d08e9c441cdbcea5a68e34f58daf76656a65ab40cd57a2c819615a8031d1b", "bytes": 29664, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a0865963ffb6798b20f500160a70a7fd24749c9e61812a941ed9f85f32985793.mp3", "duration_ms": 4880}, "concept-reveal-cost-ganancia.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/d1722255c1de8e375940c2d4dc0b55fd7b35021edf89d0f43f0a81774c769f32.mp3", "hash": "2eedf869cb484d8f67e063e0c221a3919c0974f135d71db0c2e6e6dec88652b8", "bytes": 21456, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/d1722255c1de8e375940c2d4dc0b55fd7b35021edf89d0f43f0a81774c769f32.mp3", "duration_ms": 3520}, "concept-reveal-cost-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/25c8dfd1cabbfe32b84094e640e36f6d86f53bfb0dec54ea19e98b1647af6f10.mp3", "hash": "9c0f608d9914af38507e20ff434696e8b0501395fe948e4bc9df19e2ec845873", "bytes": 52704, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/25c8dfd1cabbfe32b84094e640e36f6d86f53bfb0dec54ea19e98b1647af6f10.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "best-decision", "title": "La mejor decisión al dar cambio", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir la mejor decisión cuando un cliente paga con billete de 20 por un vaso de 5: contar el cambio con calma (no adivinarlo ni quedárselo)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 10, "type": "best_decision", "title": "El cambio de Liruf", "payload": {"options": [{"id": "count-change", "text_md": "Contar el cambio: 15 pesos en monedas", "rationale_md": "Contar el cambio con calma asegura que el cliente reciba la cantidad exacta y mantiene la confianza en el puesto."}, {"id": "guess-change", "text_md": "Adivinar y dar 10 pesos", "rationale_md": "Es tentador adivinar para rápido, pero darías $5 menos y el cliente se iría con menos dinero del que le corresponde."}, {"id": "keep-change", "text_md": "Quedarse con el billete y no dar cambio", "rationale_md": "Es tentador quedarse con todo, pero es deshonesto y el cliente se enojaría, además de que perderías un cliente."}], "scenario_md": "Liruf está en su puesto de limonada. La primera clienta llega y pide un vaso de $5. Le entrega un billete de $20. Liruf siente nervios, pero debe dar el cambio correcto."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cc47c359a84dd0eafde1bda6a8e9076e41f27e33f53112d10df9eaa2136f9160.webp", "prompt_md": "La clienta paga con billete de $20 por un vaso de $5. ¿Qué debe hacer Liruf?", "difficulty": 1, "explanation_md": "Contar el cambio de $15 con calma es la mejor decisión: el cliente recibe lo justo y Liruf gana confianza.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"keep-change": 0, "count-change": 100, "guess-change": 30}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/556bf6dc48e778587eca9380491ba992b90d03a918af0c3d05d501120d2f88ba.mp3", "hash": "e7711e0d5d8261d4627ec4194be88a2377a124f82c2ba411f8b8ffd9643dda9d", "bytes": 37296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/556bf6dc48e778587eca9380491ba992b90d03a918af0c3d05d501120d2f88ba.mp3", "duration_ms": 6160}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/ce3db0e07ab326aff257e8ca3b47dcd9ed96b54b7ca126e7be873de77de19e94.mp3", "hash": "e9280375182a62a8d3069d6ccafff804b865909a7d38d6e8be037b4f0dcbeb04", "bytes": 51264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ce3db0e07ab326aff257e8ca3b47dcd9ed96b54b7ca126e7be873de77de19e94.mp3", "duration_ms": 8480}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/2087bb51595144e84b05f0d7820aefd8b9ebfd1a10b499c5a78cda3b2158bc8f.mp3", "hash": "20686e2030bc0d95649321be0d91ca53627b1b0418d6db007a29b101ee9b458c", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2087bb51595144e84b05f0d7820aefd8b9ebfd1a10b499c5a78cda3b2158bc8f.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "order-steps", "title": "Prioridade de compras na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar compras por prioridade de venda (primeiro o que gera renda)", "Distinguir entre necessidades essenciais e desejos que podem esperar"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-priority-order", "xp": 15, "type": "order_steps", "hints": ["Pense: o que Liruf precisa para vender limonada hoje?"], "title": "A ordem das compras", "payload": {"items": [{"id": "calcomanias", "icon": "sticky_note_2", "text_md": "Figurinhas", "image_url": "http://localhost:4006/files/lesson-images/fc123b0b72dab8a58fa5c6f187bd42c09dac17902915f6669601732854c960fc.webp"}, {"id": "azucar", "icon": "cookie", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/19a0bb5beaf6d69b100b43441414f87e1f2c9950d211918df0fadb7a3c1afe61.webp"}, {"id": "vasos", "icon": "local_drink", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/4ad037f5498f6f3336634dc26b700671f304edf3cee5f8580d49cb81d079bc71.webp"}, {"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/aaba518fa154db8e4e43213decf74dcc3f438cd9441885b9a5a8faf03fd2a962.webp"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Liruf tem 20 reais para comprar o que precisa para a barraca. Ordene as compras da mais urgente para a que pode esperar.", "difficulty": 2, "explanation_md": "¡Os limões e os copos são indispensáveis para vender hoje! O açúcar ajuda a limonada a ficar gostosa e vender mais, mas pode esperar depois de ter o básico. As figurinhas são um desejo que não ajuda a ganhar dinheiro hoje, então vão por último.", "audio_segment_id": "s1-priority-order.prompt"}], "schema_version": 1}', '{"s1-priority-order": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-priority-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0ff2f583e7cd46b459f925ccaeb8233fea097f4f615fa35bf9628b24b96b38ad.mp3", "hash": "46acac80d5ecfac93043bc5813c8a26f9411e3762e613f900e528273738a6651", "bytes": 24336, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0ff2f583e7cd46b459f925ccaeb8233fea097f4f615fa35bf9628b24b96b38ad.mp3", "duration_ms": 4000}, "s1-priority-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/76811bd02b70974a13ffa975d3824083e62406fb57ace762d56ff691228d8225.mp3", "hash": "3593a57b70d4ea068029f3506ebdbf0e4d42421de163f16ab515c94f4a231324", "bytes": 48384, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/76811bd02b70974a13ffa975d3824083e62406fb57ace762d56ff691228d8225.mp3", "duration_ms": 8000}, "s1-priority-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/3f37eb56004e7fafdc4e91cf615c0c24e506710bf3e12df6473529ab2e6b5d3c.mp3", "hash": "5d5f8626854b54fe2e331ff5e258b1402e2d01d9c814d93ffda882298354780e", "bytes": 93888, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/3f37eb56004e7fafdc4e91cf615c0c24e506710bf3e12df6473529ab2e6b5d3c.mp3", "duration_ms": 15600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "timeline-order", "title": "El primer día de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar los pasos de un día de venta en secuencia correcta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 5, "type": "timeline_order", "hints": [], "title": "Orden del día", "payload": {"events": [{"id": "ev-buy", "icon": "shopping_cart", "text_md": "Comprar limones y azúcar en el mercado", "image_url": "http://localhost:4006/files/lesson-images/b5257743949c3ffb95f5508b07209f4282c2ce7a2752db4fe60a162538cf2f54.webp"}, {"id": "ev-prepare", "icon": "blender", "text_md": "Preparar la limonada fresca", "image_url": "http://localhost:4006/files/lesson-images/f69d8b420be568820316e6c161e739d9713ac70d6ded82df0b593726d6a76fa7.webp"}, {"id": "ev-sell", "icon": "storefront", "text_md": "Vender vasos de limonada al mediodía", "image_url": "http://localhost:4006/files/lesson-images/7645b91a3c5675f0c17e109394272aecaf29c412d306ad2fb832141a1793a40e.webp"}, {"id": "ev-count", "icon": "calculate", "text_md": "Contar el dinero y guardar las ganancias", "image_url": "http://localhost:4006/files/lesson-images/1e2d2f4bc1bac9bf39d0bcdd5e0998b0f63cb777d94627b9e23cb6fe6b322d0a.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf recuerda su primer día completo. Ordena las fotos del día, desde la mañana hasta la noche.", "difficulty": 1, "explanation_md": "Así fue el primer día de Liruf: compró limones y azúcar en la mañana, preparó la limonada, vendió al mediodía y contó sus ganancias al cerrar.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["ev-buy", "ev-prepare", "ev-sell", "ev-count"]}}', '{"units": {"s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c0569134aa660dddec1c701a4616c4dd4dc3f09ca95b3e6eb068f0d496a0a7e.mp3", "hash": "fd7ca95f858b7d993467cb0d1dc8763ff24625a96ef7de628967923b72b9b2ec", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4c0569134aa660dddec1c701a4616c4dd4dc3f09ca95b3e6eb068f0d496a0a7e.mp3", "duration_ms": 6400}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/d2febfe7dbc1c934fb434c03e6fa86626e072fb10f29d1ed09f0b2b821831a96.mp3", "hash": "035b56395a02fd37b34473f6688731703e2d67909ddd6a10e447c1ba2b027a37", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d2febfe7dbc1c934fb434c03e6fa86626e072fb10f29d1ed09f0b2b821831a96.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Vamos montar a soma da tarde", "locale": "pt-BR", "subject": "mixed", "objectives": ["Montar a soma do dia usando fichas de números e sinais.", "Calcular o total de uma venda de vários produtos com o mesmo preço."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "eq-tarde", "xp": 10, "type": "equation_builder", "title": "Soma da tarde", "payload": {"slots": 5, "tokens": [{"id": "n1", "text": "5"}, {"id": "n2", "text": "5"}, {"id": "n3", "text": "5"}, {"id": "p1", "text": "+"}, {"id": "p2", "text": "+"}, {"id": "d_10", "text": "10"}, {"id": "d_15", "text": "15"}, {"id": "d_sub", "text": "-"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf vendeu 3 copos de limonada a 5 reais cada um. Monte a soma para saber quanto ganhou.", "difficulty": 1, "explanation_md": "Cada copo custa 5 reais. Três copos somam: 5 + 5 + 5 = 15 reais. 💰", "audio_segment_id": "eq-tarde.prompt"}], "schema_version": 1}', '{"eq-tarde": {"accepted": ["n1 p1 n2 p2 n3", "n1 p1 n3 p2 n2", "n2 p1 n1 p2 n3", "n2 p1 n3 p2 n1", "n3 p1 n1 p2 n2", "n3 p1 n2 p2 n1", "n1 p2 n2 p1 n3", "n1 p2 n3 p1 n2", "n2 p2 n1 p1 n3", "n2 p2 n3 p1 n1", "n3 p2 n1 p1 n2", "n3 p2 n2 p1 n1"]}}', '{"units": {"eq-tarde.prompt": {"url": "http://localhost:4006/files/lesson-audio/8ed2d22057a6f4200d140d9b6675763cfde64588bc1077003451fe9bcdc44278.mp3", "hash": "308984083fc3b1d0550c84f1c9935e320f56242c03711c4157894bf1a594148c", "bytes": 45504, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/8ed2d22057a6f4200d140d9b6675763cfde64588bc1077003451fe9bcdc44278.mp3", "duration_ms": 7520}, "eq-tarde.explanation": {"url": "http://localhost:4006/files/lesson-audio/1c324b350d981667abe4d4211e7153c242364ca487e5c512604f324270284376.mp3", "hash": "5f45e9c14253d97b5b31ed59109c13eb3d778323d56179116ae2eda511d9604f", "bytes": 51696, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/1c324b350d981667abe4d4211e7153c242364ca487e5c512604f324270284376.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "El patrón de vasos", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar y completar patrones visuales de repetición."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-pattern-complete", "xp": 5, "type": "pattern_complete", "hints": ["Observa cómo se repiten los colores: principal, acento, éxito..."], "title": "Completa la escalera de colores", "payload": {"options": [{"id": "opt-primary", "icon": "local_drink", "tint": "primary"}, {"id": "opt-accent", "icon": "local_drink", "tint": "accent"}, {"id": "opt-success", "icon": "local_drink", "tint": "success"}], "sequence": [{"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}, {"icon": "local_drink", "tint": "success"}, {"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "¿Qué vaso sigue en el patrón?", "difficulty": 1, "explanation_md": "El patrón de colores es: principal, acento, éxito, y se repite. Zara armó la escalera para que no te pierdas. ¡Tú completaste el hueco! 🌟", "audio_segment_id": "s1-pattern-complete.prompt"}], "schema_version": 1}', '{"s1-pattern-complete": {"correct": {"0": "opt-success"}}}', '{"units": {"s1-pattern-complete.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9c3c224326ad1692646c9e4dc09a610d1f2a1ea1c89287cbc7f72fec596b9db9.mp3", "hash": "4fce46fc92eae46e26df3d2db8aa639e98c49c66818a42c0e341609bd4987749", "bytes": 29664, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/9c3c224326ad1692646c9e4dc09a610d1f2a1ea1c89287cbc7f72fec596b9db9.mp3", "duration_ms": 4880}, "s1-pattern-complete.prompt": {"url": "http://localhost:4006/files/lesson-audio/9404ebcb8e89f4f56d742735fb4cf7bd330bdad113a7bd9cad7152bc6d5785df.mp3", "hash": "57a8b4afc5f44bf62c5a11e92c0a9ffeecf79fee2ce99d5dd40c7d26d241fa89", "bytes": 14256, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/9404ebcb8e89f4f56d742735fb4cf7bd330bdad113a7bd9cad7152bc6d5785df.mp3", "duration_ms": 2320}, "s1-pattern-complete.explanation": {"url": "http://localhost:4006/files/lesson-audio/b24d5cc434b0d54c26b9ac8f656a2cde405375e31111d709f5a7a538318a9834.mp3", "hash": "a1017244ffa012cb7a3d1e67c3fb280f43298362fb1ca29d2ce8b2fe70c80934", "bytes": 56448, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b24d5cc434b0d54c26b9ac8f656a2cde405375e31111d709f5a7a538318a9834.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "build-sentence", "title": "Liruf''s combo", "locale": "en-US", "subject": "mixed", "objectives": ["Order steps, match products with prices, and classify purchases into stand necessities and wants that can wait."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-letrero", "xp": 15, "type": "build_sentence", "hints": ["Think: how much do two cups cost if one costs 5 dollars?"], "title": "Combo sign", "payload": {"slots": 5, "tokens": [{"id": "t2", "text_md": "2"}, {"id": "tv", "text_md": "cups"}, {"id": "tp", "text_md": "for"}, {"id": "t10", "text_md": "10"}, {"id": "tpe", "text_md": "dollars"}, {"id": "t5", "text_md": "5"}, {"id": "t15", "text_md": "15"}, {"id": "t20", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf sells each cup for 5 dollars. He wants a sign: ''2 cups for ___ dollars''. Build the sign with the tokens.", "difficulty": 2, "explanation_md": "Two cups at 5 dollars each add up to 10 dollars. That''s why the sign says ''2 cups for 10 dollars.'' The 5 token forgets that it''s two; 15 is more than it costs; 20 is much more.", "audio_segment_id": "s1-letrero.prompt"}], "schema_version": 1}', '{"s1-letrero": {"order": ["t2", "tv", "tp", "t10", "tpe"]}}', '{"units": {"s1-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f983f851f12a5cccc219ce260a35de99c4583a8c97c554b91db8ae563864f2c8.mp3", "hash": "ceea223064cfe7d754f6ad8d1a233aba57f6372b4d9f7c238be6fee2ac651cb4", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f983f851f12a5cccc219ce260a35de99c4583a8c97c554b91db8ae563864f2c8.mp3", "duration_ms": 4080}, "s1-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/63ef877c8f38c96546009765f8184b76a6382fbb3047787850cd7a6addc747f1.mp3", "hash": "ca6caa8243808e95ad648e1aca549f4aeb6e96905255e9861db70a1078bf4c9d", "bytes": 43056, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/63ef877c8f38c96546009765f8184b76a6382fbb3047787850cd7a6addc747f1.mp3", "duration_ms": 7120}, "s1-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/1e79bd90febdc0387ba0d5ce3875fc43a0bb7c6cd731b24249971a0e942519a8.mp3", "hash": "99d531a00af88713f9eaf3f6f56f6f6bacaa07f5e2e171833f211d51a8721120", "bytes": 75168, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1e79bd90febdc0387ba0d5ce3875fc43a0bb7c6cd731b24249971a0e942519a8.mp3", "duration_ms": 12480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "Prioridade de compras", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar compras por prioridade para barraca de limonada."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-prioridad-compras", "xp": 15, "type": "rank_choices", "hints": ["Que Liruf precisa para fazer e vender limonada hoje?"], "title": "Que comprar primeiro?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/6ad40b2c2e0471ceb46eb797ec1e710adc0e382335357f4029bbe7d7975c2613.webp"}, {"id": "vasos", "icon": "local_cafe", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/cf2539f3a8470d1d2cf979f08c7595260a5979a77e53c5b6d12ea44030223555.webp"}, {"id": "adornos", "icon": "palette", "text_md": "Enfeites", "image_url": "http://localhost:4006/files/lesson-images/fb304b7220b14c6096253d5425742b194ff02d0556b92acfe1b4ea7e0a2eb61c.webp"}], "criterion_md": "Acima: mais urgente"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf aprendeu que a ordem das compras importa. Com 20 reais, ordena suas compras por prioridade.", "difficulty": 2, "explanation_md": "Os limões são o mais urgente porque sem eles não há limonada para vender. Os copos vêm depois para servir. Os enfeites podem esperar.", "audio_segment_id": "s1-prioridad-compras.prompt"}], "schema_version": 1}', '{"s1-prioridad-compras": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-prioridad-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8db2249fed7dd0e60785a5f5e94b21b640b1d8f613fae84a8b2947f252c4931f.mp3", "hash": "77557f09253cadd65fdc801488df388c8c096e29823b0c573de1a287f8331505", "bytes": 22896, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/8db2249fed7dd0e60785a5f5e94b21b640b1d8f613fae84a8b2947f252c4931f.mp3", "duration_ms": 3760}, "s1-prioridad-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d560c27cc492d4a7046da837a13b1bce31020f725ffe7c48a2c92ca51a691cb.mp3", "hash": "74ce19392986b10688a53ba8fe1251507892a6ae4c0c67534a8680ef4fdd6461", "bytes": 45936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/6d560c27cc492d4a7046da837a13b1bce31020f725ffe7c48a2c92ca51a691cb.mp3", "duration_ms": 7600}, "s1-prioridad-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/718b5776f41bfb2d2942232cfa7bffdfd3626b5e0d47874cbe547c4716568946.mp3", "hash": "74b10ab69e7ab2979439ea76c96ac35c5e28852441a2e17fc97e48fc62c5fc3b", "bytes": 62208, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/718b5776f41bfb2d2942232cfa7bffdfd3626b5e0d47874cbe547c4716568946.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "code-order", "title": "A caixa registradora de papelão de Rho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar os passos para usar uma caixa registradora caseira"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "code-order-1", "xp": 5, "type": "code_order", "title": "Instruções da caixa registradora", "payload": {"blocks": [{"id": "recibir", "text_md": "Receber pagamento"}, {"id": "verificar", "text_md": "Verificar valor"}, {"id": "dar_cambio", "text_md": "Dar troco"}, {"id": "anotar", "text_md": "Anotar a venda"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho inventou uma caixa registradora de papelão. Toque nos blocos na ordem correta para usá-la.", "difficulty": 1, "explanation_md": "A ordem correta é: receber o pagamento, verificar o valor, dar o troco e anotar a venda. Assim a caixa registradora de papelão do Rho funciona sem erros!", "audio_segment_id": "code-order-1.prompt"}], "schema_version": 1}', '{"code-order-1": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"code-order-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/078615753df27f9ba066078f6d5542f4ce92f025ce004acca223c8763c0814e8.mp3", "hash": "e57defe8df09612b1e22be847db4d621c67d145f64c4ae82cb4228e3676a4219", "bytes": 41184, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/078615753df27f9ba066078f6d5542f4ce92f025ce004acca223c8763c0814e8.mp3", "duration_ms": 6800}, "code-order-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/915632061b7bb0b2f599978ff74adc7f96bd8e9af00ac7fe25eabe4a883b22d7.mp3", "hash": "d9a38563327089cc034080646554b6923328c1894fd82180f8cf3c5841f1bac1", "bytes": 72288, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/915632061b7bb0b2f599978ff74adc7f96bd8e9af00ac7fe25eabe4a883b22d7.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "The Cup Pattern", "locale": "en-US", "subject": "mixed", "objectives": ["Identify and complete visual repetition patterns."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-pattern-complete", "xp": 5, "type": "pattern_complete", "hints": ["Observe how the colors repeat: primary, accent, success..."], "title": "Complete the color staircase", "payload": {"options": [{"id": "opt-primary", "icon": "local_drink", "tint": "primary"}, {"id": "opt-accent", "icon": "local_drink", "tint": "accent"}, {"id": "opt-success", "icon": "local_drink", "tint": "success"}], "sequence": [{"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}, {"icon": "local_drink", "tint": "success"}, {"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Which cup comes next in the pattern?", "difficulty": 1, "explanation_md": "The color pattern is: primary, accent, success, and it repeats. Zara set up the staircase so you don''t get lost. You filled in the gap! 🌟", "audio_segment_id": "s1-pattern-complete.prompt"}], "schema_version": 1}', '{"s1-pattern-complete": {"correct": {"0": "opt-success"}}}', '{"units": {"s1-pattern-complete.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1bde09992c98207edb9f55ac7af2fb1ea21a07252c2d6c040cc67212ff9d4d48.mp3", "hash": "905aac4fd4829a475e66420118b7b9be4ca2518e576ce15f11a15fd470702b07", "bytes": 26208, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/1bde09992c98207edb9f55ac7af2fb1ea21a07252c2d6c040cc67212ff9d4d48.mp3", "duration_ms": 4320}, "s1-pattern-complete.prompt": {"url": "http://localhost:4006/files/lesson-audio/a147d9ae137543f31a7271eb2b1e928662f3b09ad14a34363ea4b9034dae5a39.mp3", "hash": "8a506a80b93d701d8d1e0b54e0c19931045f4521e2857623e0cf10fd2fb7bbc0", "bytes": 14256, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a147d9ae137543f31a7271eb2b1e928662f3b09ad14a34363ea4b9034dae5a39.mp3", "duration_ms": 2320}, "s1-pattern-complete.explanation": {"url": "http://localhost:4006/files/lesson-audio/b8a4705a92acba73476a675889c1ccb4d5e66ce74eb4d879d3405c78f4cde693.mp3", "hash": "f6ce81c4d500ebf2d1563123766e0e1e3e9dc25dacf8334b1333b402fc361876", "bytes": 53136, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/b8a4705a92acba73476a675889c1ccb4d5e66ce74eb4d879d3405c78f4cde693.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "A rota do entregador", "locale": "pt-BR", "subject": "mixed", "objectives": ["Resolver desafios de construção e medição aplicados ao cargo: ordenar instruções, ler medidas e equilibrar quantidades."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 5, "type": "robot_path", "hints": ["Pense na direção que o carrinho deve tomar para ir em linha reta.", "Quantos quadradinhos há desde o início até a casa?"], "title": "A rota mais curta", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "commands": ["forward", "forward"], "max_commands": 2}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de aprender a organizar a caixa registradora, ajude Zara com seu primeiro pedido para entrega em domicílio. Programe a rota mais curta.", "difficulty": 1, "explanation_md": "A rota mais curta é ir duas vezes para frente. O carrinho dá 2 passos para chegar!", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d0cf370cf26ac4227dc33a0002e3ed417b2539bb1e1de403ba6b173474184666.mp3", "hash": "f38974f1740ab4b42c5ce1e22277320772cbfb62112f6c295971c17f4eb38a19", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d0cf370cf26ac4227dc33a0002e3ed417b2539bb1e1de403ba6b173474184666.mp3", "duration_ms": 4320}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a4544771752a98b07044d356487d1d0d3d1ee0b349cd9b63cb1e1b4f15abdcaa.mp3", "hash": "36acb1db96cf4cfb79b05711bec45845999da0abbdfa2215cf4af8c40ef58909", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a4544771752a98b07044d356487d1d0d3d1ee0b349cd9b63cb1e1b4f15abdcaa.mp3", "duration_ms": 3840}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/d255406866874c0a816516e61e64b461674403e45b3dccc181954ae19b4fc31a.mp3", "hash": "263ef07c4f4a7fd638e4414ed27942b436050725f424e79a258b406ea8955a48", "bytes": 55584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d255406866874c0a816516e61e64b461674403e45b3dccc181954ae19b4fc31a.mp3", "duration_ms": 9200}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/15cb066302f57d5f0db81bdc15b8d1e625db9737cf0cc9494899382d006c9a07.mp3", "hash": "a604af9bcd64d95f3b819e8074f314161a09f5e14435652aa30af51c5ed91e8e", "bytes": 38736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/15cb066302f57d5f0db81bdc15b8d1e625db9737cf0cc9494899382d006c9a07.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Fechando a barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encadear várias habilidades em uma mesma lição: ouvir a situação, decidir, calcular e cobrar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Subtraia 5 reais do pagamento para saber quanto devolver."], "title": "O troco justo", "payload": {"left": [{"id": "p10", "icon": "payments", "text_md": "10 reais", "image_url": "http://localhost:4006/files/lesson-images/9baaa7cbb20f7cefb150523f3cd415e9179de1be261b4761529ca8b7384e0ca1.webp"}, {"id": "p20", "icon": "payments", "text_md": "20 reais", "image_url": "http://localhost:4006/files/lesson-images/dc8e3f242a014d62dd8df5dfa0bafe892ad409e9a013af0d5c20c6b4ff358d94.webp"}, {"id": "p6", "icon": "payments", "text_md": "6 reais", "image_url": "http://localhost:4006/files/lesson-images/ea2b1573db78f9b434e1ee1c7158eabd231e5558352d3108c519704421329b98.webp"}], "right": [{"id": "c5", "text_md": "5 reais"}, {"id": "c15", "text_md": "15 reais"}, {"id": "c1", "text_md": "1 real"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "O copo custa 5 reais. Emparelhe cada pagamento com o seu troco.", "difficulty": 2, "explanation_md": "Para pagamentos de 10, 20 e 6 reais, o troco é 5, 15 e 1 real porque o copo custa 5 reais. Assim Liruf não perde dinheiro!", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-orden-ganancia", "xp": 15, "type": "order_steps", "hints": ["Pense: o que você precisa saber primeiro para fazer a subtração?"], "title": "Ordem para calcular o lucro", "payload": {"items": [{"id": "sumar", "icon": "calculate", "text_md": "Somar as vendas do dia", "image_url": "http://localhost:4006/files/lesson-images/c70f7cf8dc9313c39433c49726c853500fe2040bd830da29e7e73cf4360b9204.webp"}, {"id": "restar", "icon": "remove_circle", "text_md": "Subtrair o custo dos ingredientes", "image_url": "http://localhost:4006/files/lesson-images/8671348dd538abe9013ae5f711cfc179641b27d2b346b7a21d20f2d3726be171.webp"}, {"id": "ganancia", "icon": "savings", "text_md": "O resultado é o lucro", "image_url": "http://localhost:4006/files/lesson-images/45cf45c9cac91a219cd0309838760cde8287a6a1fde850bebf27eba2956ce9f4.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf quer saber quanto ganhou hoje. Ordene os passos para calcular o lucro corretamente.", "difficulty": 2, "explanation_md": "Primeiro você soma todas as vendas, depois subtrai o que custaram os ingredientes. O que sobra é o lucro. Assim Liruf sabe se foi bem.", "audio_segment_id": "s2-orden-ganancia.prompt"}, {"id": "s3-necesita-espera", "xp": 15, "type": "sort_buckets", "hints": ["Pense quais coisas são indispensáveis para vender limonada e quais são extras."], "title": "O que a barraca precisa amanhã?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões (10 reais)", "image_url": "http://localhost:4006/files/lesson-images/f3b04ff49abae5191a3c75fbede41d51a72ffd4f7b0aa78c812500620487d4b9.webp"}, {"id": "vasos", "icon": "local_cafe", "text_md": "Copos (8 reais)", "image_url": "http://localhost:4006/files/lesson-images/6127c9a905e57a61765ab48119fb70ffdbca9178252ab43a50758547b5086a63.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Gelo (12 reais)", "image_url": "http://localhost:4006/files/lesson-images/0ba99ecf40e8807932ac41d38f42992cf939be7259ec16c11e36aed6f01668f1.webp"}, {"id": "calcomania", "icon": "sticky_note_2", "text_md": "Adesivo (15 reais)", "image_url": "http://localhost:4006/files/lesson-images/4b9da6f02ef9f11cb53a34dd99f70e1d79323e6dec55b5fad544c1e90c226dff.webp"}], "buckets": [{"id": "needs", "label": "Precisa agora"}, {"id": "wants", "label": "Pode esperar"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Para abrir amanhã só tem 20 reais. Separe o que a barraca PRECISA AGORA do que PODE ESPERAR.", "difficulty": 2, "explanation_md": "Sem limões nem copos não se pode vender. O gelo e os adesivos são úteis, mas podem esperar. Liruf decide primeiro o essencial.", "audio_segment_id": "s3-necesita-espera.prompt"}, {"id": "s4-dia-sin-cambio", "xp": 15, "type": "timeline_order", "hints": ["Receber o pagamento do cliente antes de devolver o troco, e ter moedas prontas desde o início."], "title": "O dia sem ficar sem troco", "payload": {"events": [{"id": "e1", "icon": "savings", "text_md": "Liruf coloca 30 reais em moedas no caixa", "image_url": "http://localhost:4006/files/lesson-images/8904e25d6950dfcd66e71d24e4f7ff6269bf70ff1fc6c19c8141ea6e5cd0291e.webp"}, {"id": "e2", "icon": "payments", "text_md": "Um cliente paga com uma nota de 20"}, {"id": "e3", "icon": "attach_money", "text_md": "Liruf lhe dá 15 reais de troco", "image_url": "http://localhost:4006/files/lesson-images/3a0a81d1bcc0b1992ded39ad09b75f69a153f11be087eb1707076bd65c9181f4.webp"}, {"id": "e4", "icon": "shopping_cart", "text_md": "Liruf usa 10 reais para comprar limões", "image_url": "http://localhost:4006/files/lesson-images/90f4f7950c1680f200f06fa716ca4ddf425405bc227d2d6798237bce7b93d9de.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Organize os momentos do dia para que o caixa nunca fique sem troco.", "difficulty": 2, "explanation_md": "Assim Liruf sempre tem dinheiro suficiente: começa com troco, recebe a nota, devolve o troco justo e depois gasta em ingredientes. O caixa nunca fica vazio!", "audio_segment_id": "s4-dia-sin-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["p10", "c5"], ["p20", "c15"], ["p6", "c1"]]}, "s2-orden-ganancia": {"order": ["sumar", "restar", "ganancia"]}, "s4-dia-sin-cambio": {"order": ["e1", "e2", "e3", "e4"]}, "s3-necesita-espera": {"assignments": {"hielo": "wants", "vasos": "needs", "limones": "needs", "calcomania": "wants"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dd262ccddfd61c43b4f07d1b0aea93e7127c08657a60ba3fffc936374e0db434.mp3", "hash": "f2dab62f6408ea396a005c32f302daf9e0156f4ca1ecf0da38b55934a8d285bd", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dd262ccddfd61c43b4f07d1b0aea93e7127c08657a60ba3fffc936374e0db434.mp3", "duration_ms": 4320}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/1dfc0854c658835acd09462038265653e7c35aff11c9613aaf95c5afc9de915b.mp3", "hash": "c95094b0ed67432d60a833b65a099d42dd8d216ed347be0720485d3d04f31c7c", "bytes": 31536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1dfc0854c658835acd09462038265653e7c35aff11c9613aaf95c5afc9de915b.mp3", "duration_ms": 5200}, "s2-orden-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b2486dd81d4aeb32f10f0894ad372668cbe193791cad788c5e174de399dcff7f.mp3", "hash": "094e3a02908154416b896e00bc22d987a211625a4dd5b8f109508940a97e1763", "bytes": 25344, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b2486dd81d4aeb32f10f0894ad372668cbe193791cad788c5e174de399dcff7f.mp3", "duration_ms": 4160}, "s2-orden-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/0d58d94a123b3a35fe457d963e9b7fc80ebaaf3af4e06a8ae754ac49d8d52a21.mp3", "hash": "1b0e973cd20288da9040084a3f549683dffbd230498b8e4d01db8817195fa72c", "bytes": 41616, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0d58d94a123b3a35fe457d963e9b7fc80ebaaf3af4e06a8ae754ac49d8d52a21.mp3", "duration_ms": 6880}, "s4-dia-sin-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4c08f1bb81fce21338b559624042859069882f4f36b3cac265e1f977a94f2752.mp3", "hash": "f298493ba0e797432169481609c9da0a9585e25c60ee490955f8b796890afb29", "bytes": 35424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4c08f1bb81fce21338b559624042859069882f4f36b3cac265e1f977a94f2752.mp3", "duration_ms": 5840}, "s4-dia-sin-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/52f02639c6623f1443a45b48532741dc0494a10eed339262e9b81e835e6a7d9d.mp3", "hash": "2ac7b2b2ebf48ef329a7171862850ce4aa3a525d0e1b9dc7ad6e67890b2e8d64", "bytes": 26208, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/52f02639c6623f1443a45b48532741dc0494a10eed339262e9b81e835e6a7d9d.mp3", "duration_ms": 4320}, "s3-necesita-espera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0f8ff307c2d9543b5b516b608cb0627fb28d0a791edff365b2ec6757f5a86f45.mp3", "hash": "afc9e96d289d4d97c436218e5766bb7017df72aad46b5b171c76a41304fca04a", "bytes": 31104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0f8ff307c2d9543b5b516b608cb0627fb28d0a791edff365b2ec6757f5a86f45.mp3", "duration_ms": 5120}, "s3-necesita-espera.prompt": {"url": "http://localhost:4006/files/lesson-audio/c7b58faf1b92bb506f7be27dd4e77749a1425665bd4cd7c420fa9a7729e2b91d.mp3", "hash": "a4c03bc6f01bc84a0844435c3e7033ee0b8bb27a7222d11010dac31ef5a8b2f9", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c7b58faf1b92bb506f7be27dd4e77749a1425665bd4cd7c420fa9a7729e2b91d.mp3", "duration_ms": 6800}, "s1-match-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/561b7f2a84f6bed608280fd5cfce21d5eb2e75bdabd26acfc8b6d7116118352d.mp3", "hash": "76aff3c9bde89e09c10abdb1312cb8ac6ceac384c067ad52c5b5f26a613ef5c0", "bytes": 64224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/561b7f2a84f6bed608280fd5cfce21d5eb2e75bdabd26acfc8b6d7116118352d.mp3", "duration_ms": 10640}, "s2-orden-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/7a9ea44a8fd67bc79871b5e9b7c558e12bcc71ad71fac23c8547b1ab134f5b0c.mp3", "hash": "1ae73da9e4dbcf953977d7a22f0f4436ca42387509c6fa4044b296880b70a547", "bytes": 60768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7a9ea44a8fd67bc79871b5e9b7c558e12bcc71ad71fac23c8547b1ab134f5b0c.mp3", "duration_ms": 10080}, "s4-dia-sin-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/42564574871e9685992619df4f6ac4f3bcad4019695efcffb9bf184c61c51cfc.mp3", "hash": "c25823e9df5876768830120b49428e9b9cbe60332c070a66f7e52d81a4664eac", "bytes": 73296, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/42564574871e9685992619df4f6ac4f3bcad4019695efcffb9bf184c61c51cfc.mp3", "duration_ms": 12160}, "s3-necesita-espera.explanation": {"url": "http://localhost:4006/files/lesson-audio/88b4daf1a36b3e160b6d9ffdf48c06686868960f9886d68b292dec86cae16c6b.mp3", "hash": "c6eb18e38ff06dbbe384ca03f78bb09395b29a8868591628fc9530001a7161ec", "bytes": 67104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/88b4daf1a36b3e160b6d9ffdf48c06686868960f9886d68b292dec86cae16c6b.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "savings-goal", "title": "Plano de poupança para a guitarra", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o número de semanas para alcançar uma meta de poupança dividindo a meta pela poupança semanal."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "savings-goal-1", "xp": 15, "type": "savings_goal", "hints": ["Pense em dividir os 80 reais em partes iguais conforme o que ele poupa por semana."], "title": "Quantas semanas para a guitarra?", "payload": {"goal": 80, "currency": "BRL", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf pode poupar 10, 20 ou 40 reais por semana para a guitarra de 80 reais. Quantas semanas cada plano leva?", "difficulty": 2, "explanation_md": "Poupando 10 reais por semana, Liruf leva 8 semanas; com 20 são 4 e com 40 apenas 2. Para o concurso em 4 semanas, os planos de R$20 e R$40 são suficientes bem a tempo. ⭐", "audio_segment_id": "savings-goal-1.prompt"}], "schema_version": 1}', '{"savings-goal-1": {}}', '{"units": {"savings-goal-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dcebeba5039a5834f6a92fcb57dfb1c16497c4fac808cd651851cdfd12c2fef1.mp3", "hash": "5268edb8ee6c18d15f6aab80797d037db7c533d82a74a37f0d8076d04d2f2932", "bytes": 37728, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/dcebeba5039a5834f6a92fcb57dfb1c16497c4fac808cd651851cdfd12c2fef1.mp3", "duration_ms": 6240}, "savings-goal-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/57d8f25fa890122694196876fc613c7e2c15a4107cea5d4c97159c2fec331d24.mp3", "hash": "b89c19053c2aba81b90eb59901ce5475920c065e18d5fc230cd9f723a73a3d21", "bytes": 54576, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/57d8f25fa890122694196876fc613c7e2c15a4107cea5d4c97159c2fec331d24.mp3", "duration_ms": 9040}, "savings-goal-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/8dfda1dd8b068db613c31626c15f0ce0fed200b942d4513bc08635dcc9c5174c.mp3", "hash": "16ed5ffdd7f458dcebffccf51a3f5f2c94f76f8a8acfcad411e58302a8c5a555", "bytes": 93456, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/8dfda1dd8b068db613c31626c15f0ce0fed200b942d4513bc08635dcc9c5174c.mp3", "duration_ms": 15520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "repaso-true-false", "title": "Quick Review: Profit or Income?", "locale": "en-US", "subject": "mixed", "objectives": ["Distinguishing between income and profit at a lemonade stand."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-true-false", "xp": 15, "type": "true_false", "hints": ["Calculate the total cost of making the 10 cups (2 dollars each) and subtract it from the 50 dollars that came in."], "title": "True or false?", "payload": {"statement_md": "Liruf earned 50 dollars.", "justifications": [{"id": "j1", "text_md": "Yes, because 10 cups × 5 dollars = 50 dollars."}, {"id": "j2", "text_md": "No, because the cost of the ingredients was 20 dollars, so they earned 30 dollars."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho says to Liruf: \\"You sold 10 cups at 5 dollars each, and each one costs 2 dollars. Did you earn 50 dollars?\\" Is it true or false?", "difficulty": 2, "explanation_md": "They earned 30 dollars, because 50 dollars in sales minus 20 dollars in costs leaves 30 dollars in profit. Don''t confuse the money that comes in with what you actually earn after paying for the ingredients.", "audio_segment_id": "s1-repaso-true-false.prompt"}], "schema_version": 1}', '{"s1-repaso-true-false": {"is_true": false, "correct_justification_id": "j2"}}', '{"units": {"s1-repaso-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9c4e3b0774b7af4fcabaa54a23766665874288acf351644552ea28dc6e1d7396.mp3", "hash": "418c89d6b4d56c97b3c98e348ddea759c64f849bb4d942de756522a0b620d5aa", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9c4e3b0774b7af4fcabaa54a23766665874288acf351644552ea28dc6e1d7396.mp3", "duration_ms": 5920}, "s1-repaso-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/024afae545ad06d1ff083285d708f3a081092cdbe9aaa80cdea3f891253666f7.mp3", "hash": "d2adf638142b6b71fde4509fb2b8dca6cc545e10b98e63d1c513ae9836059885", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/024afae545ad06d1ff083285d708f3a081092cdbe9aaa80cdea3f891253666f7.mp3", "duration_ms": 8080}, "s1-repaso-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/953f011b96e3d211e7b9bf4fdfc43338ad303ba29a9928765acaedba85ab8265.mp3", "hash": "adf00cc2464dec07bb3dd08c51ae2eaaef4ba085e081b776d1657eb36017ec3e", "bytes": 61344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/953f011b96e3d211e7b9bf4fdfc43338ad303ba29a9928765acaedba85ab8265.mp3", "duration_ms": 10160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "balance-scale", "title": "Balance the barter scale", "locale": "en-US", "subject": "mixed", "objectives": ["Balance the barter scale to achieve a fair deal."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["First, calculate the total value of the left plate: 3 glasses × 5 dollars each.", "Each cookie is worth 3 dollars. How many cookies do you need to equal the value of the left plate?"], "title": "The barter scale!", "payload": {"weights": [{"id": "g1", "label": "3-dollar cookie", "value": 3}, {"id": "g2", "label": "3-dollar cookie", "value": 3}, {"id": "g3", "label": "3-dollar cookie", "value": 3}, {"id": "g4", "label": "3-dollar cookie", "value": 3}, {"id": "g5", "label": "3-dollar cookie", "value": 3}, {"id": "g6", "label": "3-dollar cookie", "value": 3}, {"id": "g7", "label": "3-dollar cookie", "value": 3}, {"id": "g8", "label": "3-dollar cookie", "value": 3}], "left_fixed": [{"label": "glass of lemonade", "value": 5}, {"label": "glass of lemonade", "value": 5}, {"label": "glass of lemonade", "value": 5}], "unknown_label": "?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf puts 3 glasses of lemonade (5 dollars each) on one plate. He adds cookies (3 dollars) to the other plate until the scale balances.", "difficulty": 2, "explanation_md": "The 3 glasses of lemonade are worth 15 dollars (5+5+5). To balance the scale, Liruf needs 5 cookies at 3 dollars each, because 3+3+3+3+3 = 15. It''s a fair deal!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fab47e3966b2eec4182a3a11ee735f7eed86e7f2d20a9c0883a276fb7299023d.mp3", "hash": "2adf7454b0c84463939c815b1c30cb4ca93a7446ef898703db7f3d345280303d", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fab47e3966b2eec4182a3a11ee735f7eed86e7f2d20a9c0883a276fb7299023d.mp3", "duration_ms": 5520}, "s1-balance.hint.1": {"url": "http://localhost:4006/files/lesson-audio/28823f1710013ea1675e1483615b44ba555bac596a0031acd5cccbc7c5750a0b.mp3", "hash": "cd849b3df758acd0a0bb5c9703e4e91382783bb36d07e1009e65f556d0562b90", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/28823f1710013ea1675e1483615b44ba555bac596a0031acd5cccbc7c5750a0b.mp3", "duration_ms": 5360}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/5adef1f420209d08122c13de6fea5716d6ac5755133ff4eb971a230e436b9a49.mp3", "hash": "39a4f8c3199bff05e0c26332ee9802e5ac78f3b556b4f6f24c73cce5a792d8d3", "bytes": 51264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5adef1f420209d08122c13de6fea5716d6ac5755133ff4eb971a230e436b9a49.mp3", "duration_ms": 8480}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/58fdb0611816936d7b76af340181d1067bb2aa20287e0c84a7cf676d6b462d36.mp3", "hash": "5ce9612035433e6b9d5256e612b33985a865d9225abac76355b2a5d6b10be3b9", "bytes": 81936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/58fdb0611816936d7b76af340181d1067bb2aa20287e0c84a7cf676d6b462d36.mp3", "duration_ms": 13600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "memory-flip", "title": "Booth Price Memory Game", "locale": "en-US", "subject": "mixed", "objectives": ["Match each product with the exact payment using the booth prices."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "memory-flip-prices", "xp": 15, "type": "memory_flip", "hints": ["Yesterday''s prices: cookie 3, small cup 5, pitcher 20."], "title": "Match the prices", "payload": {"pairs": [{"a_md": "Cookie", "b_md": "1 and 2 dollars", "a_icon": "cookie", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/7e08eb104527f9e19b43e6f4c46fde6f687edc06508a674a213c437a2c701052.webp", "b_image_url": "http://localhost:4006/files/lesson-images/e612cd7c6ecc289a9dc1586e5016094c1bf5a4a67f986825c198db17d1822f4b.webp"}, {"a_md": "Small cup", "b_md": "5 dollars", "a_icon": "local_drink", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/c4981a45d33ffb26545f219cc83c32f909327aab9e0dffe06b21aa4828b8feac.webp", "b_image_url": "http://localhost:4006/files/lesson-images/e0347735f17251ad0deaff00ce72847ee14f922161da80b671936a4bab1502ef.webp"}, {"a_md": "Large pitcher", "b_md": "10 and 10 dollars", "a_icon": "local_bar", "b_icon": "currency_exchange", "a_image_url": "http://localhost:4006/files/lesson-images/73e4853ef3cef5374997f20b8ace852298c49c69573a6c420466638c0e6e57a7.webp", "b_image_url": "http://localhost:4006/files/lesson-images/cffded90b4eb127e36abec5e5b25c697762bb2b09e64fbf01bf6fe8ab0495a2d.webp"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Match each product with the coins that pay for it.", "difficulty": 2, "explanation_md": "The cookie costs 3 dollars, the small cup 5 and the pitcher 20. Knowing prices by heart makes you a fast cashier!", "audio_segment_id": "memory-flip-prices.prompt"}], "schema_version": 1}', '{}', '{"units": {"memory-flip-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/834fb0148cbbeaf41c01ba241fcef3e74f54ae2f2e445acddc9c94e481fb2106.mp3", "hash": "678f133d0f3767c7878f71b791c611c4e081182417f15f7bb405c393cd0d1a84", "bytes": 30096, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/834fb0148cbbeaf41c01ba241fcef3e74f54ae2f2e445acddc9c94e481fb2106.mp3", "duration_ms": 4960}, "memory-flip-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/d3b6bbf1cac992ae069144bf8c23d193c16641ad9e0564c40b4a3bef7c8002b2.mp3", "hash": "b198c19a910167a3e911b1668fe14118443e9952f911ccaa9376d562019e9bd1", "bytes": 19008, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/d3b6bbf1cac992ae069144bf8c23d193c16641ad9e0564c40b4a3bef7c8002b2.mp3", "duration_ms": 3120}, "memory-flip-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/228b40dbd4c62262177cc2f46cfaf3a17f7907b32efefc4c589e8779894c6e71.mp3", "hash": "bbb9e370304d4aba78ebd6f92e5ecc5a2aca270310eb0f6a4c0108d8714eede8", "bytes": 49824, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/228b40dbd4c62262177cc2f46cfaf3a17f7907b32efefc4c589e8779894c6e71.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "checkpoint", "title": "Earning money starts with an idea", "locale": "en-US", "subject": "mixed", "objectives": ["Understanding that money is earned by offering something others want, and that a clear goal (the 80-dollar guitar) helps you get started."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "title": "Liruf''s big idea", "payload": {"recap_md": "Liruf wants a toy guitar that costs 80 dollars. To earn that money, he decided to sell lemonade for 5 dollars a glass. From each glass he sells, what''s left after paying the cost (lemons, sugar, cups) is his profit, and that profit goes straight to his jar... getting closer and closer to the guitar!", "mood_prompt_md": "Do you think Liruf already feels the guitar is closer? 🌟"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Review Liruf''s plan.", "difficulty": 1, "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/9701516f4fe9ebf058ca4d216c800f77bfc467d6076552e0b1ddbd28389814c0.mp3", "hash": "5a83259fc1a7f4437541683edd9aaebcfa269f1d25a04024ba9fe0b8530b6ef7", "bytes": 98784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9701516f4fe9ebf058ca4d216c800f77bfc467d6076552e0b1ddbd28389814c0.mp3", "duration_ms": 16400}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/f14b1ecfe87efa12215748556db5bf046adeb30efa83d83ccd8612bf028146e3.mp3", "hash": "f72bf8b64c0a5e194a7ec232e415b4129e86d1a0394e34041eeb01509b1a14c8", "bytes": 10944, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f14b1ecfe87efa12215748556db5bf046adeb30efa83d83ccd8612bf028146e3.mp3", "duration_ms": 1760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Necesidades y gustos en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar necesidades del puesto de limonada de los gustos personales."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "needs-wants-1", "xp": 10, "type": "needs_wants", "hints": ["Pista: ¿Sin esto puede Liruf vender limonada? Si no, es una necesidad."], "title": "Necesidades y gustos", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/1be5b55a4cacf2174b4ed0c13f4e27f7e86f095fe85a2da912c97830ae354bad.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/6266599e8d76c27c9bf369b2b0c59010493415893dfd34b51499e18c816e21fe.webp"}, {"id": "vasos", "icon": "water_drop", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/abf95f91e3e5d0a6225fd83557a45c2886dab03b058449c9551713bd93eb4633.webp"}, {"id": "paleta", "icon": "icecream", "text_md": "Paleta", "image_url": "http://localhost:4006/files/lesson-images/6a902c8bd79a972f87a4f03ad2a48e351c138e92a4443deaf5dd1f094f099495.webp"}, {"id": "comic", "icon": "auto_stories", "text_md": "Cómic", "image_url": "http://localhost:4006/files/lesson-images/ede5b71ddfb77514ed873c22f9d5659644892e52893ff67ed4595dac793f64a7.webp"}, {"id": "juguete", "icon": "toys", "text_md": "Juguete", "image_url": "http://localhost:4006/files/lesson-images/16161313c663e9e7c70417e58de7dbe663ca8f05bff00c9837b942381fbb9a09.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf compra para su puesto de limonada. Toca cada cosa y elige: ¿necesidad para el puesto o gusto personal?", "difficulty": 1, "explanation_md": "Los limones, el hielo y los vasos son necesidades porque sin ellos Liruf no puede preparar ni vender limonada 🍋. La paleta, el cómic y el juguete son gustos que puede comprar después, cuando el puesto gane dinero.", "audio_segment_id": "needs-wants-1.prompt"}], "schema_version": 1}', '{"needs-wants-1": {"needs_ids": ["limones", "hielo", "vasos"]}}', '{"units": {"needs-wants-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4291a81a8cf44d54038ed098e5adfcd85efd49a71790816d15d57b769d344c7d.mp3", "hash": "f0f6796ce53ac7b908bad786d15cf2ca6e911b96e1d5223054a97e2eba23427d", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4291a81a8cf44d54038ed098e5adfcd85efd49a71790816d15d57b769d344c7d.mp3", "duration_ms": 5760}, "needs-wants-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/4083cadcf326e61dee4c01f0108e71e7f101652e11ac1d55453d75e344b3393d.mp3", "hash": "4dc57d641ed35767d8f88068a9d2cad1bc048f4493995e7fd83aeacfa85062d4", "bytes": 45504, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4083cadcf326e61dee4c01f0108e71e7f101652e11ac1d55453d75e344b3393d.mp3", "duration_ms": 7520}, "needs-wants-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/7bd83b6e77e358ec0fa451caedbbb84e5ebb362801b59103683e86bb0144b658.mp3", "hash": "034606d29e64681deca98a3af275f50469f3a61fceb50952330e8ee1668d09d3", "bytes": 88128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7bd83b6e77e358ec0fa451caedbbb84e5ebb362801b59103683e86bb0144b658.mp3", "duration_ms": 14640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Let''s build the afternoon sum", "locale": "en-US", "subject": "mixed", "objectives": ["Build the day''s sum using number and sign tokens.", "Calculate the total of a sale of several products of the same price."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "eq-tarde", "xp": 10, "type": "equation_builder", "title": "Afternoon sum", "payload": {"slots": 5, "tokens": [{"id": "n1", "text": "5"}, {"id": "n2", "text": "5"}, {"id": "n3", "text": "5"}, {"id": "p1", "text": "+"}, {"id": "p2", "text": "+"}, {"id": "d_10", "text": "10"}, {"id": "d_15", "text": "15"}, {"id": "d_sub", "text": "-"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf sold 3 glasses of lemonade at 5 dollars each. Build the sum to find out how much they earned.", "difficulty": 1, "explanation_md": "Each glass costs 5 dollars. Three glasses add up to: 5 + 5 + 5 = 15 dollars. 💰", "audio_segment_id": "eq-tarde.prompt"}], "schema_version": 1}', '{"eq-tarde": {"accepted": ["n1 p1 n2 p2 n3", "n1 p1 n3 p2 n2", "n2 p1 n1 p2 n3", "n2 p1 n3 p2 n1", "n3 p1 n1 p2 n2", "n3 p1 n2 p2 n1", "n1 p2 n2 p1 n3", "n1 p2 n3 p1 n2", "n2 p2 n1 p1 n3", "n2 p2 n3 p1 n1", "n3 p2 n1 p1 n2", "n3 p2 n2 p1 n1"]}}', '{"units": {"eq-tarde.prompt": {"url": "http://localhost:4006/files/lesson-audio/8063189b1fe8a1bee6bba0bd63d32bd724956b3e8d22a72944291ebe8c0e2f89.mp3", "hash": "2fb3da475da8740734752d25ab573e0325b8736554fc96165e56920978581c9a", "bytes": 46368, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/8063189b1fe8a1bee6bba0bd63d32bd724956b3e8d22a72944291ebe8c0e2f89.mp3", "duration_ms": 7680}, "eq-tarde.explanation": {"url": "http://localhost:4006/files/lesson-audio/3db8c1ebba6b65049035bc96d86030b139b77e39bf58c93971d797d92998f8e3.mp3", "hash": "1bfa585e185b654622a7e1fd80450f8b2322e73785d803d89a244dcd00ada8e3", "bytes": 50688, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3db8c1ebba6b65049035bc96d86030b139b77e39bf58c93971d797d92998f8e3.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "True or false? Growing savings", "locale": "en-US", "subject": "money", "objectives": ["Decide if the statement about savings is true or false."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "tf-ahorro", "xp": 10, "type": "true_false", "title": "Catch the phrase", "payload": {"statement_md": "If I save 5 dollars from each sale, my savings grow every day.", "justifications": [{"id": "j1", "text_md": "Savings only grow if you save the whole sale, 5 dollars isn''t enough."}, {"id": "j2", "text_md": "Each sale adds 5 dollars to the savings, so little by little it keeps increasing."}, {"id": "j3", "text_md": "5 dollars is very little money; savings don''t grow from small change."}, {"id": "j4", "text_md": "It only grows if you sell every day, and the phrase doesn''t say that."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Zara says: ''If I save 5 dollars from each sale, my savings grow every day.'' Is it true or false?", "difficulty": 1, "explanation_md": "Saving 5 dollars from each sale does make your savings grow, because each 5 dollars adds up. That way, day by day the total saved increases. Little by little, a lot is achieved!", "audio_segment_id": "tf-ahorro.prompt"}], "schema_version": 1}', '{"tf-ahorro": {"is_true": true, "correct_justification_id": "j2"}}', '{"units": {"tf-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/a7a966fd3a5ac4d6f589d9a7c3c9c851d7c15d372af5b5b364488885d40aff87.mp3", "hash": "383391fcc968caa7733edad3611da560ca5caf80cf074c9ed73c81a751202623", "bytes": 40608, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/a7a966fd3a5ac4d6f589d9a7c3c9c851d7c15d372af5b5b364488885d40aff87.mp3", "duration_ms": 6720}, "tf-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/e30339f84e04ce9bc131f863908ebbde009e810245dccc88cf01e0bf74cd3f0d.mp3", "hash": "63bc440674885bd764aff3b0c3dfca7bbe55a499ef1cb8c897037ff8db0d96da", "bytes": 66096, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e30339f84e04ce9bc131f863908ebbde009e810245dccc88cf01e0bf74cd3f0d.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Does it help or not?", "locale": "en-US", "subject": "mixed", "objectives": ["Making simple money decisions by comparing options: fair price, a safe place to store it, and distinguishing a good deal from a bad one."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 25, "type": "yes_no_cases", "hints": ["Think: if you buy this, does it help you make more lemonade or sell more?", "Expenses that don''t help the stand won''t bring you more money."], "title": "Expenses that help the stand", "payload": {"cases": [{"id": "c1", "icon": "eco", "text_md": "More lemons", "image_url": "http://localhost:4006/files/lesson-images/955e4f80e4c7384ac08886b5553fa555adec21de7ad26d190e21a81335f7d17a.webp"}, {"id": "c2", "icon": "emoji_objects", "text_md": "A new toy", "image_url": "http://localhost:4006/files/lesson-images/8054ead296dd0a5b0b8ea33bea639f333c1aa41948435d21f358e6aaad20bf0b.webp"}, {"id": "c3", "icon": "local_cafe", "text_md": "Plastic cups", "image_url": "http://localhost:4006/files/lesson-images/3818e7f79ddd9376bc369a651642533f74a3c5426c897b460e779476fc2cc649.webp"}, {"id": "c4", "icon": "icecream", "text_md": "A candy lollipop", "image_url": "http://localhost:4006/files/lesson-images/f15bd865f72931445f6294e51726e53d627f9ad6599408a65f47c485287824e7.webp"}, {"id": "c5", "icon": "ac_unit", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/b871b823e74f2e0ab53bafbedcce60ab0c087a15ff1a90c2ac522a37ce9ed2c7.webp"}, {"id": "c6", "icon": "sticky_note_2", "text_md": "A sign to advertise", "image_url": "http://localhost:4006/files/lesson-images/bc3a1368c1355f5a7a642d797747a809e54bcb9e4ff8cb65ecda234fdedf6bed.webp"}], "rule_md": "Spend money only on things that help sell more lemonade."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After counting the fair change, Liruf reviews his expenses. Do they help sell more lemonade?", "difficulty": 3, "explanation_md": "Liruf learned to spend on what helps the stand! A new toy won''t give him more sales. 🍋", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3", "c5", "c6"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a00bc71ec9e10a51be0bd37655fa813efda9b55c6861c5dfa3f24c8da025e789.mp3", "hash": "c6acc5d1b32b631a9224e89dafdd1f3f837d8d6f81a23fa9cad2cf89611bd4a7", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a00bc71ec9e10a51be0bd37655fa813efda9b55c6861c5dfa3f24c8da025e789.mp3", "duration_ms": 3840}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2fdfc73ad15541551161112a6b7a196a0cedf1b62b9d45fe26bfdd776711640a.mp3", "hash": "d8ddd93babd41f826aa9540c7b328bb915d3174ee3be7bf9bf3ba1d06ae9c33f", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2fdfc73ad15541551161112a6b7a196a0cedf1b62b9d45fe26bfdd776711640a.mp3", "duration_ms": 3120}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/615d571d57150d2438eaed8de6d760948862d067a4de9c361b5a0a64dc04a230.mp3", "hash": "67714e588b1dedfad411a707cae42a7a404d4997ca550aebfd6a95abe2672e19", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/615d571d57150d2438eaed8de6d760948862d067a4de9c361b5a0a64dc04a230.mp3", "duration_ms": 5440}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/ec2af5fb4b62e3ffdeae64a2aa286b91b9f20cee6100f183863999781658a358.mp3", "hash": "605c784282536c8b2d5533b0dc24243edd7e64c8ccefe2084157e1c72bfe60be", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ec2af5fb4b62e3ffdeae64a2aa286b91b9f20cee6100f183863999781658a358.mp3", "duration_ms": 5920}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/faaed32a0a08c4fee4d194f44e85a592a7e537fc62c34b6890840417c58929a5.mp3", "hash": "b27594857bb9179eb7a98f1da800cf58747bffbfbb9ef436818678ba1c33372f", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/faaed32a0a08c4fee4d194f44e85a592a7e537fc62c34b6890840417c58929a5.mp3", "duration_ms": 4880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimate the glasses", "locale": "en-US", "subject": "mixed", "objectives": ["Estimate with the bar how many glasses you can fill from a large pitcher."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-cups", "xp": 15, "type": "estimate_slider", "hints": ["Imagine the size of a common pitcher at home and the glasses you use. How many would you fill?"], "title": "How many glasses does it fill?", "payload": {"max": 20, "min": 0, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "excited", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/4e19821d41322fa6ac9721b7cdf6f33027e8e7b198351670b0c25a3f7e679255.webp", "prompt_md": "Zara prepared the day''s pitcher. Without counting, estimate how many glasses she can fill.", "difficulty": 2, "explanation_md": "Zara knows that her pitcher yields about 8 glasses. Good eye! 🎉", "audio_segment_id": "s1-estimate-cups.prompt"}], "schema_version": 1}', '{"s1-estimate-cups": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-cups.hint.0": {"url": "http://localhost:4006/files/lesson-audio/112bf9f59fd732a02175116e7b8be879b3a709321ec0d6eb098439399ea40abd.mp3", "hash": "b2a88dd2e5a7b767e798fbf89a567e71d01b68760e6bfed97caf0e0dbb5de422", "bytes": 41184, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/112bf9f59fd732a02175116e7b8be879b3a709321ec0d6eb098439399ea40abd.mp3", "duration_ms": 6800}, "s1-estimate-cups.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ce0dade8ac54b5725231a6eacbabca4c46ba0afc482ee17f9dedeb9b93e24fc.mp3", "hash": "0fb1259081efce5f2e8f80dbba5326b8bd8cf725fb88c57f3c5eac35a4b856de", "bytes": 35424, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/5ce0dade8ac54b5725231a6eacbabca4c46ba0afc482ee17f9dedeb9b93e24fc.mp3", "duration_ms": 5840}, "s1-estimate-cups.explanation": {"url": "http://localhost:4006/files/lesson-audio/bcb94a35a99f78f4a419545731ab00161046e34d8ccdf6ac13831a00057c9129.mp3", "hash": "696a006f42f032aba2c5cdb57fde9eb5c8aca61849a6379f732a0080dacc05fa", "bytes": 26208, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/bcb94a35a99f78f4a419545731ab00161046e34d8ccdf6ac13831a00057c9129.mp3", "duration_ms": 4320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Arregla el cartel de la promo", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar y corregir un error en un cartel de promoción usando matemáticas de dinero."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-cartel", "xp": 15, "type": "debug_hunt", "hints": ["Compara cuánto cuestan los vasos sueltos con el precio de la promo."], "title": "El cartel de la promo", "payload": {"blocks": [{"id": "precio-normal", "text_md": "1 vaso de limonada cuesta 5 pesos."}, {"id": "promo-dos", "text_md": "Promoción: 2 vasos por 8 pesos."}, {"id": "calculo-separado", "text_md": "Si compras 2 vasos sueltos, pagas 5 × 2 = 10 pesos."}, {"id": "conclusion-erronea", "text_md": "¡Así que la promo es más cara!"}], "intro_md": "Liruf ya tiene listas la ruta de reparto, la balanza de trueques, la jarra medidora y la máquina registradora. Ahora puso este cartel de promoción, pero tiene un error. ¡Ayúdalo a encontrarlo!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Toca el renglón del cartel que tiene un error.", "difficulty": 2, "explanation_md": "El vaso cuesta 5 pesos. Dos sueltos cuestan 10, pero la promo los da por 8. ¡8 es menos que 10, así que la promo es más barata, no más cara! 😉", "audio_segment_id": "s1-debug-cartel.prompt"}], "schema_version": 1}', '{"s1-debug-cartel": {"fix_md": "El renglón debe decir: ''¡Así que la promo es más barata!'' Ya que 8 pesos es menor que 10 pesos.", "bug_ids": ["conclusion-erronea"]}}', '{"units": {"s1-debug-cartel.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7ea5ba53c42f4b2e9ab938c5c592453e247cf5c37de515282a8e6fcb398c0b10.mp3", "hash": "eda9e743ad29163f353d9470e51d174631fbb95d53e4f37f4fced5b5653c24de", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7ea5ba53c42f4b2e9ab938c5c592453e247cf5c37de515282a8e6fcb398c0b10.mp3", "duration_ms": 3600}, "s1-debug-cartel.prompt": {"url": "http://localhost:4006/files/lesson-audio/f3bd2b13cf11183e7605e61e35b545b08a7bf77c775dad9bea4d367ebdd8e166.mp3", "hash": "fced8606547169a380bda79cbfe6483ebbb4f629128874083c37a87ecf047339", "bytes": 18144, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f3bd2b13cf11183e7605e61e35b545b08a7bf77c775dad9bea4d367ebdd8e166.mp3", "duration_ms": 2960}, "s1-debug-cartel.explanation": {"url": "http://localhost:4006/files/lesson-audio/af19a62cea087c7c5c6bf3466af260045852991c1180f23d0136d5193fa4fe86.mp3", "hash": "2657536a6abfec0d61845e764ae2ea612b6005336ec23dff7b3c522af8651f25", "bytes": 62784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/af19a62cea087c7c5c6bf3466af260045852991c1180f23d0136d5193fa4fe86.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Fix the promo poster", "locale": "en-US", "subject": "mixed", "objectives": ["Find and fix an error on a promotion poster using money math."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-cartel", "xp": 15, "type": "debug_hunt", "hints": ["Compare how much the individual cups cost with the promo price."], "title": "The promo poster", "payload": {"blocks": [{"id": "precio-normal", "text_md": "1 glass of lemonade costs 5 dollars."}, {"id": "promo-dos", "text_md": "Promotion: 2 glasses for 8 dollars."}, {"id": "calculo-separado", "text_md": "If you buy 2 individual glasses, you pay 5 × 2 = 10 dollars."}, {"id": "conclusion-erronea", "text_md": "So the promo is more expensive!"}], "intro_md": "Liruf already has the delivery route, the barter scale, the measuring pitcher, and the cash register ready. Now he put up this promotion poster, but it has an error. Help him find it!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Tap the line on the poster that has an error.", "difficulty": 2, "explanation_md": "The cup costs 5 dollars. Two individual cups cost 10, but the promo gives them for 8. 8 is less than 10, so the promo is cheaper, not more expensive! 😉", "audio_segment_id": "s1-debug-cartel.prompt"}], "schema_version": 1}', '{"s1-debug-cartel": {"fix_md": "El renglón debe decir: ''¡Así que la promo es más barata!'' Ya que 8 pesos es menor que 10 pesos.", "bug_ids": ["conclusion-erronea"]}}', '{"units": {"s1-debug-cartel.hint.0": {"url": "http://localhost:4006/files/lesson-audio/34d0f56e2992b5b69d71f8db5efaae534c139e9523a3d0cb9d01a479b5cd8142.mp3", "hash": "9551b6f50bebd02811ee2a29ba965c5bfabefefe3f6ce438fea257d1c97a0fbb", "bytes": 20016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/34d0f56e2992b5b69d71f8db5efaae534c139e9523a3d0cb9d01a479b5cd8142.mp3", "duration_ms": 3280}, "s1-debug-cartel.prompt": {"url": "http://localhost:4006/files/lesson-audio/57cd46de6a5c09338bfe1408e512c6e69dcf0c6a100e08f9af0aa7c547253a8a.mp3", "hash": "b843bbe5bc973f8025059eda6549c3c4ca438b3ebc888f48abe03edbeec0c755", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/57cd46de6a5c09338bfe1408e512c6e69dcf0c6a100e08f9af0aa7c547253a8a.mp3", "duration_ms": 2400}, "s1-debug-cartel.explanation": {"url": "http://localhost:4006/files/lesson-audio/c54ff2188dda902f01556e71551984377318c16d44f804cb5713e281863e59f5.mp3", "hash": "bcb6b8d781305413df633bc7ea2af6b25bf6022b3fc82a7300fd1a70370dbec7", "bytes": 55008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c54ff2188dda902f01556e71551984377318c16d44f804cb5713e281863e59f5.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "number-line", "title": "A reta da poupança", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar na reta numérica de 0 a 100 onde vai a poupança de Liruf (20 reais) e onde a meta (80): ver quanto falta."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 5, "type": "number_line", "title": "Quanto falta?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Depois de agrupar moedas e notas, Liruf quer ver quanto falta. Coloca sua poupança (20 reais) na reta.", "difficulty": 1, "explanation_md": "Liruf já tem 20 reais. A meta é 80, que está bem mais à direita. Faltam 60 reais para o skate! 🎉", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 0, "zero_credit_delta": 10}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ac9c1893f347ae0927d2091d3913273bc064dd8dc4efdf90ea4b097b1c160d6.mp3", "hash": "963c6d54886d8ecc39f037c98303267eb63a894b123d7651d7d209b5eb113030", "bytes": 52704, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/5ac9c1893f347ae0927d2091d3913273bc064dd8dc4efdf90ea4b097b1c160d6.mp3", "duration_ms": 8720}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/2ee94af1fdeb63e6b8d46076e6e397da3d94da335afb8c0864e7b4b39c5e776b.mp3", "hash": "599f369b8aa186db4bc705c5154ba5e7738662100190d5a8f6883c6d8384d652", "bytes": 55584, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2ee94af1fdeb63e6b8d46076e6e397da3d94da335afb8c0864e7b4b39c5e776b.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "O padrão de copos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar e completar padrões visuais de repetição."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-pattern-complete", "xp": 5, "type": "pattern_complete", "hints": ["Observe como as cores se repetem: principal, acento, sucesso..."], "title": "Complete a escada de cores", "payload": {"options": [{"id": "opt-primary", "icon": "local_drink", "tint": "primary"}, {"id": "opt-accent", "icon": "local_drink", "tint": "accent"}, {"id": "opt-success", "icon": "local_drink", "tint": "success"}], "sequence": [{"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}, {"icon": "local_drink", "tint": "success"}, {"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Qual copo vem a seguir no padrão?", "difficulty": 1, "explanation_md": "O padrão de cores é: principal, acento, sucesso, e se repete. Zara montou a escada para você não se perder. Você completou o buraco! 🌟", "audio_segment_id": "s1-pattern-complete.prompt"}], "schema_version": 1}', '{"s1-pattern-complete": {"correct": {"0": "opt-success"}}}', '{"units": {"s1-pattern-complete.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ea08b722bab39cf34747a8e9f028ffaf321e6a7127d5d9cd76c06375c7cd7dc4.mp3", "hash": "8d90af2ff123a19641fa511811b3a7eb5cb1101f145bb7420c6477c63d30c831", "bytes": 29088, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/ea08b722bab39cf34747a8e9f028ffaf321e6a7127d5d9cd76c06375c7cd7dc4.mp3", "duration_ms": 4800}, "s1-pattern-complete.prompt": {"url": "http://localhost:4006/files/lesson-audio/41f9c26ef814b9c535584ece5ce1aa933e935ced765bfb57967540c87fb9442d.mp3", "hash": "55c9fadcf9669fa5589be49c6339f1c6622f15d7fc815950dc56e48e4b6a8f28", "bytes": 14256, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/41f9c26ef814b9c535584ece5ce1aa933e935ced765bfb57967540c87fb9442d.mp3", "duration_ms": 2320}, "s1-pattern-complete.explanation": {"url": "http://localhost:4006/files/lesson-audio/6241f7e3f86fff47cc4b4a0dd7dd520cc98c4b3b5f2615a6c7f9260c922f1fed.mp3", "hash": "40bc12559b5a5bb6bd5e9157a215d019ab5785850dcebf90742f3517deb6d99e", "bytes": 62784, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/6241f7e3f86fff47cc4b4a0dd7dd520cc98c4b3b5f2615a6c7f9260c922f1fed.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Cerrando el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Resta 5 pesos al pago para saber cuánto devolver."], "title": "El cambio justo", "payload": {"left": [{"id": "p10", "icon": "payments", "text_md": "10 pesos", "image_url": "http://localhost:4006/files/lesson-images/9baaa7cbb20f7cefb150523f3cd415e9179de1be261b4761529ca8b7384e0ca1.webp"}, {"id": "p20", "icon": "payments", "text_md": "20 pesos", "image_url": "http://localhost:4006/files/lesson-images/dc8e3f242a014d62dd8df5dfa0bafe892ad409e9a013af0d5c20c6b4ff358d94.webp"}, {"id": "p6", "icon": "payments", "text_md": "6 pesos", "image_url": "http://localhost:4006/files/lesson-images/ea2b1573db78f9b434e1ee1c7158eabd231e5558352d3108c519704421329b98.webp"}], "right": [{"id": "c5", "text_md": "5 pesos"}, {"id": "c15", "text_md": "15 pesos"}, {"id": "c1", "text_md": "1 peso"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "El vaso cuesta 5 pesos. Empareja cada pago con su cambio.", "difficulty": 2, "explanation_md": "Para pagos de 10, 20 y 6 pesos, el cambio es 5, 15 y 1 peso porque el vaso cuesta 5 pesos. ¡Así Liruf no pierde dinero!", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-orden-ganancia", "xp": 15, "type": "order_steps", "hints": ["Piensa: ¿qué necesitas saber primero para hacer la resta?"], "title": "Orden para sacar la ganancia", "payload": {"items": [{"id": "sumar", "icon": "calculate", "text_md": "Sumar las ventas del día", "image_url": "http://localhost:4006/files/lesson-images/c70f7cf8dc9313c39433c49726c853500fe2040bd830da29e7e73cf4360b9204.webp"}, {"id": "restar", "icon": "remove_circle", "text_md": "Restar el costo de ingredientes", "image_url": "http://localhost:4006/files/lesson-images/8671348dd538abe9013ae5f711cfc179641b27d2b346b7a21d20f2d3726be171.webp"}, {"id": "ganancia", "icon": "savings", "text_md": "El resultado es la ganancia", "image_url": "http://localhost:4006/files/lesson-images/45cf45c9cac91a219cd0309838760cde8287a6a1fde850bebf27eba2956ce9f4.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf quiere saber cuánto ganó hoy. Ordena los pasos para calcular la ganancia correctamente.", "difficulty": 2, "explanation_md": "Primero sumas todas las ventas, luego restas lo que costaron los ingredientes. Lo que queda es la ganancia. Así Liruf sabe si le fue bien.", "audio_segment_id": "s2-orden-ganancia.prompt"}, {"id": "s3-necesita-espera", "xp": 15, "type": "sort_buckets", "hints": ["Piensa qué cosas son indispensables para vender limonada y cuáles son extras."], "title": "¿Qué necesita el puesto mañana?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones (10 pesos)", "image_url": "http://localhost:4006/files/lesson-images/f3b04ff49abae5191a3c75fbede41d51a72ffd4f7b0aa78c812500620487d4b9.webp"}, {"id": "vasos", "icon": "local_cafe", "text_md": "Vasos (8 pesos)", "image_url": "http://localhost:4006/files/lesson-images/6127c9a905e57a61765ab48119fb70ffdbca9178252ab43a50758547b5086a63.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Hielo (12 pesos)", "image_url": "http://localhost:4006/files/lesson-images/0ba99ecf40e8807932ac41d38f42992cf939be7259ec16c11e36aed6f01668f1.webp"}, {"id": "calcomania", "icon": "sticky_note_2", "text_md": "Calcomanía (15 pesos)", "image_url": "http://localhost:4006/files/lesson-images/4b9da6f02ef9f11cb53a34dd99f70e1d79323e6dec55b5fad544c1e90c226dff.webp"}], "buckets": [{"id": "needs", "label": "Necesita ahora"}, {"id": "wants", "label": "Puede esperar"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Para abrir mañana solo hay 20 pesos. Separa lo que el puesto NECESITA AHORA de lo que PUEDE ESPERAR.", "difficulty": 2, "explanation_md": "Sin limones ni vasos no se puede vender. El hielo y las calcomanías son útiles, pero pueden esperar. Liruf decide primero lo esencial.", "audio_segment_id": "s3-necesita-espera.prompt"}, {"id": "s4-dia-sin-cambio", "xp": 15, "type": "timeline_order", "hints": ["Recibir el pago del cliente antes de devolverle su cambio, y tener monedas listas desde el inicio."], "title": "El día sin quedarse sin cambio", "payload": {"events": [{"id": "e1", "icon": "savings", "text_md": "Liruf pone 30 pesos en monedas en la caja", "image_url": "http://localhost:4006/files/lesson-images/8904e25d6950dfcd66e71d24e4f7ff6269bf70ff1fc6c19c8141ea6e5cd0291e.webp"}, {"id": "e2", "icon": "payments", "text_md": "Un cliente paga con un billete de 20"}, {"id": "e3", "icon": "attach_money", "text_md": "Liruf le da 15 pesos de cambio", "image_url": "http://localhost:4006/files/lesson-images/3a0a81d1bcc0b1992ded39ad09b75f69a153f11be087eb1707076bd65c9181f4.webp"}, {"id": "e4", "icon": "shopping_cart", "text_md": "Liruf usa 10 pesos para comprar limones", "image_url": "http://localhost:4006/files/lesson-images/90f4f7950c1680f200f06fa716ca4ddf425405bc227d2d6798237bce7b93d9de.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Acomoda los momentos del día para que la caja nunca se quede sin cambio.", "difficulty": 2, "explanation_md": "Así Liruf siempre tiene suficiente efectivo: empieza con cambio, recibe el billete, devuelve el cambio justo y después gasta en ingredientes. ¡La caja nunca se vacía!", "audio_segment_id": "s4-dia-sin-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["p10", "c5"], ["p20", "c15"], ["p6", "c1"]]}, "s2-orden-ganancia": {"order": ["sumar", "restar", "ganancia"]}, "s4-dia-sin-cambio": {"order": ["e1", "e2", "e3", "e4"]}, "s3-necesita-espera": {"assignments": {"hielo": "wants", "vasos": "needs", "limones": "needs", "calcomania": "wants"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/72dcac5333129b9d32abc2c39d657129bfa64993bd0949084227e1ebc8350fa6.mp3", "hash": "04e8c629e78355b812fff0e3d04ecb9451a7079a52b2c5e8428893462c1e1ce6", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/72dcac5333129b9d32abc2c39d657129bfa64993bd0949084227e1ebc8350fa6.mp3", "duration_ms": 4000}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/82ac47ae959e2382254384d84d628afefac2d185f12c5d4d399bc638d96911b1.mp3", "hash": "56819a19a5a8839705d7b82efa1358037baeacefb4b4a4ff0fa72f626a1ead26", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/82ac47ae959e2382254384d84d628afefac2d185f12c5d4d399bc638d96911b1.mp3", "duration_ms": 4560}, "s2-orden-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/91ca878947c240dd096e0ccf1df6d9c516eb88dda3d2b9036ad0d3faf66bcd68.mp3", "hash": "8582bbb6c9bb847aa7633400adfe9adeb336b66d2e16b1dc6054c33fde32849a", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/91ca878947c240dd096e0ccf1df6d9c516eb88dda3d2b9036ad0d3faf66bcd68.mp3", "duration_ms": 3840}, "s2-orden-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/d4fc64ce090cbf9efc4bf3fb0d21fba45ee2efc4b93786fb8e54e3686c624677.mp3", "hash": "d0326d9a5f207aeaa8ca489f54eb8ba45246f53d6848ea096cc78de6b7c9846a", "bytes": 41616, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d4fc64ce090cbf9efc4bf3fb0d21fba45ee2efc4b93786fb8e54e3686c624677.mp3", "duration_ms": 6880}, "s4-dia-sin-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ebe34f423018023226e4e3b4d7cd3f3a82b65975b34cc3c4f1155981467810a2.mp3", "hash": "13e1e7d2db3406fed7012e93699e7ab1f4d68ec4ec76ac6d44326af8c025109e", "bytes": 37728, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ebe34f423018023226e4e3b4d7cd3f3a82b65975b34cc3c4f1155981467810a2.mp3", "duration_ms": 6240}, "s4-dia-sin-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/e43bb24f8ef174ed674f416009cb5983c6e084efceff9fde103540471bdd886b.mp3", "hash": "fe2dcfafc71487fcad9d2bb6ac7ff471abaa6d855128f60f376396d85a3d1e38", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e43bb24f8ef174ed674f416009cb5983c6e084efceff9fde103540471bdd886b.mp3", "duration_ms": 4800}, "s3-necesita-espera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9495bee7a9804754b505a95d8741b82999f2e1dde9b0cc19e0dfdb76e0347af2.mp3", "hash": "f76d8c63c1f19ee3bd4dc2d0377045307abcc03ae53404369b57c208d5c99a56", "bytes": 31536, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9495bee7a9804754b505a95d8741b82999f2e1dde9b0cc19e0dfdb76e0347af2.mp3", "duration_ms": 5200}, "s3-necesita-espera.prompt": {"url": "http://localhost:4006/files/lesson-audio/97624c2dfddd7da3092ecfdd75ddf686d64ca8b46b867f15e01eb32ea7798037.mp3", "hash": "1f1e451238202f88f1108396a065d14de6ec22096191bed40d4e8b381fd1b7ce", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/97624c2dfddd7da3092ecfdd75ddf686d64ca8b46b867f15e01eb32ea7798037.mp3", "duration_ms": 7600}, "s1-match-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/4fe8446739f9cba96ddb246a1b5a0d892deb0de3585b3cc59528fc8271e42d25.mp3", "hash": "c747d0531a28eb0f01f008f2016efb383a16ca728b8959954f11b82c42745491", "bytes": 61344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4fe8446739f9cba96ddb246a1b5a0d892deb0de3585b3cc59528fc8271e42d25.mp3", "duration_ms": 10160}, "s2-orden-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/98c015e149102265f647af47c3ebbb71499a38dae267eea06c8246a9327bae70.mp3", "hash": "8438574eddf64330b9f88c8f9e6dcac52f0b8f040dfffc038b8b93bf9b602e69", "bytes": 66096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/98c015e149102265f647af47c3ebbb71499a38dae267eea06c8246a9327bae70.mp3", "duration_ms": 10960}, "s4-dia-sin-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c9ee38f35041337125c5d1b5d34859afb3f4a70336862e23e3b8a1a2947b787.mp3", "hash": "fcd987b3ec80581b2bc5d2a881a73a24c446a0b9e5c030e609a08a3a244e657a", "bytes": 72864, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4c9ee38f35041337125c5d1b5d34859afb3f4a70336862e23e3b8a1a2947b787.mp3", "duration_ms": 12080}, "s3-necesita-espera.explanation": {"url": "http://localhost:4006/files/lesson-audio/3c75a985566cd8251ed11d91cf0e7a5f6c8f3ef0f15e3dad3e6a5bed79cd2d02.mp3", "hash": "469784ccea0e5957a755d071069d8428b2e6a3fba75b3dd5ed4227755095d17b", "bytes": 66096, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3c75a985566cd8251ed11d91cf0e7a5f6c8f3ef0f15e3dad3e6a5bed79cd2d02.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "Verdadeiro ou falso? A poupança que cresce", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se a afirmação sobre a poupança é verdadeira ou falsa."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "tf-ahorro", "xp": 10, "type": "true_false", "title": "Pegue a frase", "payload": {"statement_md": "Se eu guardo 5 reais de cada venda, minha poupança cresce todo dia.", "justifications": [{"id": "j1", "text_md": "A poupança só cresce se você guardar tudo da venda, não bastam 5 reais."}, {"id": "j2", "text_md": "Cada venda adiciona 5 reais à poupança, então pouco a pouco vai aumentando."}, {"id": "j3", "text_md": "5 reais é muito pouquinho dinheiro; a poupança não cresce com moedas pequenas."}, {"id": "j4", "text_md": "Só cresce se você vender todos os dias, e a frase não diz isso."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Zara diz: ''Se eu guardar 5 reais de cada venda, minha poupança cresce todo dia.'' É verdadeiro ou falso?", "difficulty": 1, "explanation_md": "Guardar 5 reais de cada venda faz sim sua poupança crescer, porque cada 5 reais se somam. Assim, dia a dia o total guardado aumenta. Pouco a pouco se consegue muito!", "audio_segment_id": "tf-ahorro.prompt"}], "schema_version": 1}', '{"tf-ahorro": {"is_true": true, "correct_justification_id": "j2"}}', '{"units": {"tf-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/7ce4b549cc90ae2c187ce67e538446cad260b3f227f146bc33af4053f498769f.mp3", "hash": "837ee48fe795f881cda7aff60841c17636fe698194e327c7a04e174aa8e396a2", "bytes": 45936, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7ce4b549cc90ae2c187ce67e538446cad260b3f227f146bc33af4053f498769f.mp3", "duration_ms": 7600}, "tf-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/5c265da3af9b820d9bfa0f6113d0228825ca37d4227a92bda3188402b510f0a3.mp3", "hash": "ce7a34ddc06ca86db281ab3feec5387a2513f8509b7c1f3825af51095d52baf1", "bytes": 80064, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5c265da3af9b820d9bfa0f6113d0228825ca37d4227a92bda3188402b510f0a3.mp3", "duration_ms": 13280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Closing the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Chain several skills in the same lesson: listen to the situation, decide, calculate, and charge."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Subtract 5 dollars from the payment to know how much to give back."], "title": "The right change", "payload": {"left": [{"id": "p10", "icon": "payments", "text_md": "10 dollars", "image_url": "http://localhost:4006/files/lesson-images/9baaa7cbb20f7cefb150523f3cd415e9179de1be261b4761529ca8b7384e0ca1.webp"}, {"id": "p20", "icon": "payments", "text_md": "20 dollars", "image_url": "http://localhost:4006/files/lesson-images/dc8e3f242a014d62dd8df5dfa0bafe892ad409e9a013af0d5c20c6b4ff358d94.webp"}, {"id": "p6", "icon": "payments", "text_md": "6 dollars", "image_url": "http://localhost:4006/files/lesson-images/ea2b1573db78f9b434e1ee1c7158eabd231e5558352d3108c519704421329b98.webp"}], "right": [{"id": "c5", "text_md": "5 dollars"}, {"id": "c15", "text_md": "15 dollars"}, {"id": "c1", "text_md": "1 dollar"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "The cup costs 5 dollars. Match each payment with its change.", "difficulty": 2, "explanation_md": "For payments of 10, 20 and 6 dollars, the change is 5, 15 and 1 dollar because the cup costs 5 dollars. That way Liruf doesn''t lose money!", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-orden-ganancia", "xp": 15, "type": "order_steps", "hints": ["Think: what do you need to know first to do the subtraction?"], "title": "Order to get the profit", "payload": {"items": [{"id": "sumar", "icon": "calculate", "text_md": "Add up the day''s sales", "image_url": "http://localhost:4006/files/lesson-images/c70f7cf8dc9313c39433c49726c853500fe2040bd830da29e7e73cf4360b9204.webp"}, {"id": "restar", "icon": "remove_circle", "text_md": "Subtract the cost of ingredients", "image_url": "http://localhost:4006/files/lesson-images/8671348dd538abe9013ae5f711cfc179641b27d2b346b7a21d20f2d3726be171.webp"}, {"id": "ganancia", "icon": "savings", "text_md": "The result is the profit", "image_url": "http://localhost:4006/files/lesson-images/45cf45c9cac91a219cd0309838760cde8287a6a1fde850bebf27eba2956ce9f4.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf wants to know how much he earned today. Order the steps to calculate the profit correctly.", "difficulty": 2, "explanation_md": "First you add up all the sales, then you subtract what the ingredients cost. What''s left is the profit. That way Liruf knows if he did well.", "audio_segment_id": "s2-orden-ganancia.prompt"}, {"id": "s3-necesita-espera", "xp": 15, "type": "sort_buckets", "hints": ["Think about which things are essential for selling lemonade and which are extras."], "title": "What does the stand need tomorrow?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons (10 dollars)", "image_url": "http://localhost:4006/files/lesson-images/f3b04ff49abae5191a3c75fbede41d51a72ffd4f7b0aa78c812500620487d4b9.webp"}, {"id": "vasos", "icon": "local_cafe", "text_md": "Cups (8 dollars)", "image_url": "http://localhost:4006/files/lesson-images/6127c9a905e57a61765ab48119fb70ffdbca9178252ab43a50758547b5086a63.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Ice (12 dollars)", "image_url": "http://localhost:4006/files/lesson-images/0ba99ecf40e8807932ac41d38f42992cf939be7259ec16c11e36aed6f01668f1.webp"}, {"id": "calcomania", "icon": "sticky_note_2", "text_md": "Sticker (15 dollars)", "image_url": "http://localhost:4006/files/lesson-images/4b9da6f02ef9f11cb53a34dd99f70e1d79323e6dec55b5fad544c1e90c226dff.webp"}], "buckets": [{"id": "needs", "label": "Needs now"}, {"id": "wants", "label": "Can wait"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "To open tomorrow there are only 20 dollars. Separate what the stand NEEDS NOW from what CAN WAIT.", "difficulty": 2, "explanation_md": "Without lemons or cups you can''t sell. Ice and stickers are useful, but can wait. Liruf decides on the essentials first.", "audio_segment_id": "s3-necesita-espera.prompt"}, {"id": "s4-dia-sin-cambio", "xp": 15, "type": "timeline_order", "hints": ["Receive the customer''s payment before giving back their change, and have coins ready from the start."], "title": "The day without running out of change", "payload": {"events": [{"id": "e1", "icon": "savings", "text_md": "Liruf puts 30 dollars in coins in the cash box", "image_url": "http://localhost:4006/files/lesson-images/8904e25d6950dfcd66e71d24e4f7ff6269bf70ff1fc6c19c8141ea6e5cd0291e.webp"}, {"id": "e2", "icon": "payments", "text_md": "A customer pays with a 20 dollar bill"}, {"id": "e3", "icon": "attach_money", "text_md": "Liruf gives him 15 dollars in change", "image_url": "http://localhost:4006/files/lesson-images/3a0a81d1bcc0b1992ded39ad09b75f69a153f11be087eb1707076bd65c9181f4.webp"}, {"id": "e4", "icon": "shopping_cart", "text_md": "Liruf uses 10 dollars to buy lemons", "image_url": "http://localhost:4006/files/lesson-images/90f4f7950c1680f200f06fa716ca4ddf425405bc227d2d6798237bce7b93d9de.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Arrange the moments of the day so the cash box never runs out of change.", "difficulty": 2, "explanation_md": "That way Liruf always has enough cash: he starts with change, receives the bill, gives back the right change and then spends on ingredients. The cash box never empties!", "audio_segment_id": "s4-dia-sin-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["p10", "c5"], ["p20", "c15"], ["p6", "c1"]]}, "s2-orden-ganancia": {"order": ["sumar", "restar", "ganancia"]}, "s4-dia-sin-cambio": {"order": ["e1", "e2", "e3", "e4"]}, "s3-necesita-espera": {"assignments": {"hielo": "wants", "vasos": "needs", "limones": "needs", "calcomania": "wants"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/81c0884cb346d24cdbb9671b71864fac5ea68b6ce11572fb258d446616ad0cac.mp3", "hash": "fce16d8fba4dd0dc82552b4a83e5c03d3fd9803e2e661298dadb7501e0eb851a", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/81c0884cb346d24cdbb9671b71864fac5ea68b6ce11572fb258d446616ad0cac.mp3", "duration_ms": 3600}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/d6fcf7eb6704821429972521fe451abf667dc9dd90f926d585ad01df098d67e3.mp3", "hash": "a75cb404599c81cc98950bed594b7b5a2b0014f848ca2d3be891ec7212527285", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d6fcf7eb6704821429972521fe451abf667dc9dd90f926d585ad01df098d67e3.mp3", "duration_ms": 3600}, "s2-orden-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/34d4dd6a99ad7e3502d0a60fd2d893828a153a37297ad605b0bf9d7fe12ff601.mp3", "hash": "0ba14664db1aa7e38b59e4e699dc09d4739d115d49ef7cee98d81924770cb0ef", "bytes": 21024, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/34d4dd6a99ad7e3502d0a60fd2d893828a153a37297ad605b0bf9d7fe12ff601.mp3", "duration_ms": 3440}, "s2-orden-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/57fc58b8155cceee31052dd77e7e535b7da012b2b2d2cd7a3d6811acca4898bb.mp3", "hash": "c142c3ea973a32bef09cc584cd38a1178c63fd381e114d73ad057f271eb3ab43", "bytes": 34416, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/57fc58b8155cceee31052dd77e7e535b7da012b2b2d2cd7a3d6811acca4898bb.mp3", "duration_ms": 5680}, "s4-dia-sin-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3915c8b4a7e626bafdb5fbbd3a3c0ff9ae48d75a437e6a23c2e9f3a665f4a6cc.mp3", "hash": "5ab3f84a11d20efc85785d749c637f6526f2883d1a448ac9633250b4a0ec6404", "bytes": 32976, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/3915c8b4a7e626bafdb5fbbd3a3c0ff9ae48d75a437e6a23c2e9f3a665f4a6cc.mp3", "duration_ms": 5440}, "s4-dia-sin-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/cb0987f03754ca4be7d7f87838e20aba568eee47349989877c6fd3b67245eec6.mp3", "hash": "e7b2e7004d8dc82938db9492e5f91080ef960b34c1d1aea8b6ee9d4bc60f1a64", "bytes": 26784, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/cb0987f03754ca4be7d7f87838e20aba568eee47349989877c6fd3b67245eec6.mp3", "duration_ms": 4400}, "s3-necesita-espera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/968a2d61a27396ec00a5b51af1dd0deb43cbe5f863b653cdd15f97744bd704d6.mp3", "hash": "f9e93ce02a36cbfe0febcd696a814ee623b75036695cec6d2e32ff75c312484e", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/968a2d61a27396ec00a5b51af1dd0deb43cbe5f863b653cdd15f97744bd704d6.mp3", "duration_ms": 3840}, "s3-necesita-espera.prompt": {"url": "http://localhost:4006/files/lesson-audio/e085d0294d9439d237046084e6b5b371670c0c4364967fde08c1bef1135ed213.mp3", "hash": "a4455e9f3d98fe9448670bd5471050534f35cc86b137b28967803954d806e1ab", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e085d0294d9439d237046084e6b5b371670c0c4364967fde08c1bef1135ed213.mp3", "duration_ms": 5520}, "s1-match-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/93211bb686b818caf4ed07af350766766acfab0d1e25706d817d8fbf26b9b71f.mp3", "hash": "e32d78736d903ee792ed65e153adc32debe1b3cfeb5a8da58befc47241033624", "bytes": 54576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/93211bb686b818caf4ed07af350766766acfab0d1e25706d817d8fbf26b9b71f.mp3", "duration_ms": 9040}, "s2-orden-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/fcab62c151706388ecb0bbf24859e8df56c101cc90bb9956b7cbdff6b0cfdfe2.mp3", "hash": "41e80c5f5250c2325323e90731dff61ff352ab4ee05d2014c0224b657948d079", "bytes": 50688, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fcab62c151706388ecb0bbf24859e8df56c101cc90bb9956b7cbdff6b0cfdfe2.mp3", "duration_ms": 8400}, "s4-dia-sin-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/581a5bac95df8601093c847c263d8795ee6decb1e15ba9c9e6318f019a0a39ac.mp3", "hash": "88fd5969178d5b361f873cbd3031e0b648c222fbd22e45e35dd0e4e676ac31e6", "bytes": 63648, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/581a5bac95df8601093c847c263d8795ee6decb1e15ba9c9e6318f019a0a39ac.mp3", "duration_ms": 10560}, "s3-necesita-espera.explanation": {"url": "http://localhost:4006/files/lesson-audio/420a36942097c45a26b998afe4d418987b865036be6f98b32438dd7c725e88c5.mp3", "hash": "813a47136896bac94f573d4e21c319180bfa7074fba785e3c2bc68c97fe6a964", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/420a36942097c45a26b998afe4d418987b865036be6f98b32438dd7c725e88c5.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Conserte o cartaz da promo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar e corrigir um erro em um cartaz de promoção usando matemática do dinheiro."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-cartel", "xp": 15, "type": "debug_hunt", "hints": ["Compare quanto custam os copos avulsos com o preço da promo."], "title": "O cartaz da promo", "payload": {"blocks": [{"id": "precio-normal", "text_md": "1 copo de limonada custa 5 reais."}, {"id": "promo-dos", "text_md": "Promoção: 2 copos por 8 reais."}, {"id": "calculo-separado", "text_md": "Se comprar 2 copos avulsos, paga 5 × 2 = 10 reais."}, {"id": "conclusion-erronea", "text_md": "Então a promo é mais cara!"}], "intro_md": "Liruf já tem prontas a rota de entrega, a balança de trocas, a jarra medidora e a máquina registradora. Agora ele colocou este cartaz de promoção, mas tem um erro. Ajude-o a encontrá-lo!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Toque a linha do cartaz que tem um erro.", "difficulty": 2, "explanation_md": "O copo custa 5 reais. Dois copos avulsos custam 10, mas a promo dá dois por 8. 8 é menos que 10, então a promo é mais barata, não mais cara! 😉", "audio_segment_id": "s1-debug-cartel.prompt"}], "schema_version": 1}', '{"s1-debug-cartel": {"fix_md": "El renglón debe decir: ''¡Así que la promo es más barata!'' Ya que 8 pesos es menor que 10 pesos.", "bug_ids": ["conclusion-erronea"]}}', '{"units": {"s1-debug-cartel.hint.0": {"url": "http://localhost:4006/files/lesson-audio/12b1a2cbcb8b4338db16ef3e938e60c91a4534bc25388fbc33afde41c0d36ed8.mp3", "hash": "6eaa4570539ec5fd96628bf6df4a18128be0f9dff97240449bae54a97cc16a8c", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/12b1a2cbcb8b4338db16ef3e938e60c91a4534bc25388fbc33afde41c0d36ed8.mp3", "duration_ms": 4080}, "s1-debug-cartel.prompt": {"url": "http://localhost:4006/files/lesson-audio/c7027e54700877518f72a29263d1f2485f04646289c6d1f07be341d395f9bf34.mp3", "hash": "134654be471385d5ac6b21b6017f72896d1e3ea009f5ae3f229839d4ac91a810", "bytes": 16704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c7027e54700877518f72a29263d1f2485f04646289c6d1f07be341d395f9bf34.mp3", "duration_ms": 2720}, "s1-debug-cartel.explanation": {"url": "http://localhost:4006/files/lesson-audio/b9418c4c19873461cda7e9ba94a41b0d23809315afb58d440a72f7ea0f4027cb.mp3", "hash": "11aa4b05c16012e6e31df8ae276746e66acdd95abb264ad39c6820b61a5102b7", "bytes": 76608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b9418c4c19873461cda7e9ba94a41b0d23809315afb58d440a72f7ea0f4027cb.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "make-change", "title": "El cambio justo", "locale": "es-MX", "subject": "money", "objectives": ["Aplicar el cambio exacto con monedas mexicanas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "make-change-1", "xp": 15, "type": "make_change", "hints": ["Primero, ¿cuánto cuestan juntos el vaso y la galleta?"], "title": "El cambio de don Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1ec2980cf3606b107e29793911a8353d6e52db87692285a5a7f745091f28ee47.webp", "prompt_md": "Don Beto compró 1 vaso de limonada (5 pesos) y 1 galleta (3 pesos). Pagó con un billete de 20 pesos. Toca las monedas para darle el cambio exacto.", "difficulty": 2, "explanation_md": "La compra de don Beto sumó 8 pesos (5 del vaso + 3 de la galleta). Como pagó con 20 pesos, el cambio exacto es 20 - 8 = 12 pesos. Con las monedas que usaste le diste justo esos 12 pesos.", "audio_segment_id": "make-change-1.prompt"}], "schema_version": 1}', '{"make-change-1": {}}', '{"units": {"make-change-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9d47cbf60935c41ac3a0db0dc2cb467dffa475c832d663af8b1edbcb065fe939.mp3", "hash": "0eb0e2a1a5656c36ba657903abc5865c5a5670f8cce7990b6f98f4808a029c56", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9d47cbf60935c41ac3a0db0dc2cb467dffa475c832d663af8b1edbcb065fe939.mp3", "duration_ms": 3600}, "make-change-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/9e289c5bf72d091f93dd4b26442582a7135a4ff2a493734f3b492287532a59ba.mp3", "hash": "888fcadc6fb83a4adc596cbfc7827c56b858fb59e85b01ec697b4331d37c2466", "bytes": 73296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9e289c5bf72d091f93dd4b26442582a7135a4ff2a493734f3b492287532a59ba.mp3", "duration_ms": 12160}, "make-change-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/8110dd742be28db5ab4de02b64ef0db0f3ddead6b6f432e1a1e4e2a6eaf222f1.mp3", "hash": "b02745af4ab3d9629d7d7f1798b1524cd73c0cfaf890b89b03e844a6e750dfa4", "bytes": 85824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8110dd742be28db5ab4de02b64ef0db0f3ddead6b6f432e1a1e4e2a6eaf222f1.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "number-input", "title": "Calcular ganancias totales", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular y escribir cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno (20 pesos)."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 5, "type": "number_input", "title": "Las ganancias del puesto", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8bfcfe08cca66252ce7fe00d4a13461325c23b2e58f2af5bcecbda0e9383e6d2.webp", "prompt_md": "Después de aprender sobre ganancias, Liruf quiere calcular cuánto ganó hoy. Vendió 4 vasos a 5 pesos cada uno. ¿Cuánto ganó en total?", "difficulty": 1, "explanation_md": "Liruf vendió 4 vasos a 5 pesos cada uno, así que ganó 20 pesos en total: 4 veces 5 es igual a 20.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 20, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/4f140ff8ed13ae2f1ea01927ac204059bd157c588fa19c5ceafbc8fb5c218463.mp3", "hash": "6db005abf0a92a720f625a0f3f91517c85ece6e0642ebd40480427a8be555a41", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4f140ff8ed13ae2f1ea01927ac204059bd157c588fa19c5ceafbc8fb5c218463.mp3", "duration_ms": 9280}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/c0b5c0a11acc8476992b41f51053f2bd8643139aa6ffea2a490e63148d73c26b.mp3", "hash": "43debbab9dd1e39a509d3338630c67969ae9273c4a6f4f1f559daa3e33a1e577", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c0b5c0a11acc8476992b41f51053f2bd8643139aa6ffea2a490e63148d73c26b.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparando precios de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Comparar precios de limones y elegir la oferta más barata para maximizar ganancias."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Recuerda: para gastar menos, busca el precio más bajo por la misma cantidad de limones."], "title": "Compara precios de limones", "payload": {"offers": [{"id": "of1", "qty": 10, "unit": "limones", "label": "Limones — Doña Lula", "price": 20, "image_url": "http://localhost:4006/files/lesson-images/dec91d8435168a7ea0c6730477493ac1b39e1b9f2b0c5b285d9352c3b0b6098f.webp"}, {"id": "of2", "qty": 10, "unit": "limones", "label": "Limones — Don Pepe", "price": 25, "image_url": "http://localhost:4006/files/lesson-images/6f3c064b9fadc18c1a4b70e3ca659f1313a5b3b5edbd661047f511de46d51785.webp"}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf ya separó necesidades y deseos. Ahora compara estas ofertas de limones y toca la que le conviene más.", "difficulty": 1, "explanation_md": "El puesto de Doña Lula cuesta 20 pesos por 10 limones, 5 pesos menos que Don Pepe. Así Liruf gasta menos y le queda más para la guitarra de 80 pesos. 💡", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "of1"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f6a296614a15ff511560c5bb433d0bd5f4f0611b975cac08db0104c9e3270208.mp3", "hash": "75262933bab0bee660c921f70b906a4f9be19f18f2f002232f0729cb32d4f9c6", "bytes": 36288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f6a296614a15ff511560c5bb433d0bd5f4f0611b975cac08db0104c9e3270208.mp3", "duration_ms": 6000}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/214d73f450345da9df3d5210b6df9f5c4a5e69518c45ad27571a3f62abbc083e.mp3", "hash": "6cd85e625633e12cb96f7e57a4eeb21bedb4d8582b12272b41c4a67e90bf4bd0", "bytes": 44928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/214d73f450345da9df3d5210b6df9f5c4a5e69518c45ad27571a3f62abbc083e.mp3", "duration_ms": 7440}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/f77a4d1bb42229b4794aa45d13bad037cc275a4763167a0d903b5969e2978d31.mp3", "hash": "ea8968bb7add390f2a0d2c2a8b16178796857152b502ad1313e5cbf7c9133380", "bytes": 67104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f77a4d1bb42229b4794aa45d13bad037cc275a4763167a0d903b5969e2978d31.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "balance-scale", "title": "Equilibra la balanza del trueque", "locale": "es-MX", "subject": "mixed", "objectives": ["Equilibrar la balanza del trueque para lograr un trato justo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Primero calcula el valor total del plato izquierdo: 3 vasos × 5 pesos cada uno.", "Cada galleta vale 3 pesos. ¿Cuántas galletas necesitas para sumar lo mismo que el plato izquierdo?"], "title": "¡La balanza del trueque!", "payload": {"weights": [{"id": "g1", "label": "galleta de 3 pesos", "value": 3}, {"id": "g2", "label": "galleta de 3 pesos", "value": 3}, {"id": "g3", "label": "galleta de 3 pesos", "value": 3}, {"id": "g4", "label": "galleta de 3 pesos", "value": 3}, {"id": "g5", "label": "galleta de 3 pesos", "value": 3}, {"id": "g6", "label": "galleta de 3 pesos", "value": 3}, {"id": "g7", "label": "galleta de 3 pesos", "value": 3}, {"id": "g8", "label": "galleta de 3 pesos", "value": 3}], "left_fixed": [{"label": "vaso de limonada", "value": 5}, {"label": "vaso de limonada", "value": 5}, {"label": "vaso de limonada", "value": 5}], "unknown_label": "?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf pone 3 vasos de limonada (5 pesos c/u) en un plato. Añade galletas (3 pesos) al otro plato hasta equilibrar la balanza.", "difficulty": 2, "explanation_md": "Los 3 vasos de limonada valen 15 pesos (5+5+5). Para equilibrar la balanza, Liruf necesita 5 galletas de 3 pesos cada una, porque 3+3+3+3+3 = 15. ¡Es un trato justo!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/eec1fab9393e40dd112f98c00ca4e414752e6d76fa80157f9d173a57e64ccb4d.mp3", "hash": "2910058103358ad428c2dcc1ae2addb707492e9ed345b39217b26756699859e0", "bytes": 36864, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/eec1fab9393e40dd112f98c00ca4e414752e6d76fa80157f9d173a57e64ccb4d.mp3", "duration_ms": 6080}, "s1-balance.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b35cff89f82752bac873ff88c1252cc6f00ba723bd3d8876a337179098821036.mp3", "hash": "a88b51335ddc5fd3ace08ea6d8f6f98e1ef46fc2c6f301513435cd46ac0a82c4", "bytes": 44064, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b35cff89f82752bac873ff88c1252cc6f00ba723bd3d8876a337179098821036.mp3", "duration_ms": 7280}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/b131e71e52bf884013eac4ea5a1385334f748b66b18a83872f91524760105a96.mp3", "hash": "16e68e853b9844b330ef905eed463c0d4fb11dbf0aaa2441a6fc81c03df3efcd", "bytes": 64656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b131e71e52bf884013eac4ea5a1385334f748b66b18a83872f91524760105a96.mp3", "duration_ms": 10720}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/bea794c7ebc1a04f40050cf4589d40f08951ec95f15cc7de0868a1e4a97c0215.mp3", "hash": "85e3c6f97f5176c7239efa2109e95e357f041133223b78c8545ddf0cc46359d8", "bytes": 101664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bea794c7ebc1a04f40050cf4589d40f08951ec95f15cc7de0868a1e4a97c0215.mp3", "duration_ms": 16880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "piggy-split", "title": "Reparte la ganancia para cumplir la meta", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar dinero con monedas de 1, 2, 5 y 10, calcular cambio de un billete de 20, y planear cuántas semanas faltan para la meta.", "Repartir 10 pesos de ganancia entre las dos alcancías: una parte para la meta de la guitarra y otra para reponer ingredientes."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["¿Cuánto cuesta reponer los ingredientes? Lo que sobre lo puedes ahorrar para la guitarra."], "title": "Reparte la ganancia", "payload": {"jars": [{"id": "jar-guitarra", "icon": "savings", "label": "Alcancía de la guitarra", "hint_md": "Cada peso ahorrado aquí te acerca a la meta de 80 pesos.", "image_url": "http://localhost:4006/files/lesson-images/53bd564c088bd2b4e23cf8694d92d4fa85d0c99e75d6166e0a68eccee74a48da.webp"}, {"id": "jar-ingredientes", "icon": "shopping_cart", "label": "Gastos del puesto", "hint_md": "Los ingredientes cuestan 4 pesos. Pon esa cantidad aquí para seguir vendiendo.", "image_url": "http://localhost:4006/files/lesson-images/41a08178de9e5324fb797a97ac359c1084c0748e7fe848aaa44a3b9b19cddba5.webp"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Los ingredientes cuestan 4 pesos. Pon lo justo en cada alcancía para reponer y ahorrar para la guitarra de 80 pesos.", "difficulty": 2, "explanation_md": "Al repartir la ganancia, primero cubres los gastos del puesto (4 pesos) y lo demás va a la alcancía de la guitarra (6 pesos). Así avanzas hacia la meta de 80 pesos.", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"jar-guitarra": {"max": 6, "min": 6}, "jar-ingredientes": {"max": 4, "min": 4}}, "rationale_md": "Pusiste 4 pesos para ingredientes y 6 para la guitarra. Así el puesto sigue funcionando y avanzas 6 pesos hacia la guitarra de 80. ¡Buen plan!"}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3370423a61f7bead3c5ecff4b06c7685b945ca6cbe9c6a9c4df4d4a9e2f20e4.mp3", "hash": "b0d5d3bc79af41d670ddc98e6b321ad28f540a0d404154cb6301a8a750bbfa6e", "bytes": 39744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b3370423a61f7bead3c5ecff4b06c7685b945ca6cbe9c6a9c4df4d4a9e2f20e4.mp3", "duration_ms": 6560}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/dd249470b25960835dcc3c9f3f588366d94dc6f0e2dcbd12c860520456b48ab8.mp3", "hash": "e0bf319a4c4443ed9caf23afba03b1fe80e12424dc1bdb19adaf584a9b95c434", "bytes": 53136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dd249470b25960835dcc3c9f3f588366d94dc6f0e2dcbd12c860520456b48ab8.mp3", "duration_ms": 8800}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/c3822e97c71b9be54d7ef49658d31225235a009d13ae514dd21c5019510a5884.mp3", "hash": "9c549860aeed10d52e3d1299967a8bc93a22d94b8a09793ff209eafeae059372", "bytes": 72288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c3822e97c71b9be54d7ef49658d31225235a009d13ae514dd21c5019510a5884.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "piggy-split", "title": "Split the profit to meet the goal", "locale": "en-US", "subject": "mixed", "objectives": ["Count money with 1, 2, 5, and 10 coins, calculate change from a 20-dollar bill, and plan how many weeks until the goal.", "Split 10 dollars of profit between the two piggy banks: one part for the guitar goal and another to restock ingredients."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["How much does it cost to restock the ingredients? Whatever is left over you can save for the guitar."], "title": "Split the profit", "payload": {"jars": [{"id": "jar-guitarra", "icon": "savings", "label": "Guitar piggy bank", "hint_md": "Every dollar saved here brings you closer to the 80-dollar goal.", "image_url": "http://localhost:4006/files/lesson-images/53bd564c088bd2b4e23cf8694d92d4fa85d0c99e75d6166e0a68eccee74a48da.webp"}, {"id": "jar-ingredientes", "icon": "shopping_cart", "label": "Stand expenses", "hint_md": "The ingredients cost 4 dollars. Put that amount here to keep selling.", "image_url": "http://localhost:4006/files/lesson-images/41a08178de9e5324fb797a97ac359c1084c0748e7fe848aaa44a3b9b19cddba5.webp"}], "step": 1, "unit": "USD", "income": 10}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "The ingredients cost 4 dollars. Put the right amount in each piggy bank to restock and save for the 80-dollar guitar.", "difficulty": 2, "explanation_md": "When splitting the profit, first you cover the stand expenses (4 dollars) and the rest goes to the guitar piggy bank (6 dollars). That way you make progress toward the 80-dollar goal.", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"jar-guitarra": {"max": 6, "min": 6}, "jar-ingredientes": {"max": 4, "min": 4}}, "rationale_md": "Pusiste 4 pesos para ingredientes y 6 para la guitarra. Así el puesto sigue funcionando y avanzas 6 pesos hacia la guitarra de 80. ¡Buen plan!"}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/826e6daa07d3595da06e93ee0ddf263664cb022610c47831e3f369d99aa94584.mp3", "hash": "0a41c7de6ef0ab421a6a99a9f843fa04705afed7aa6a23b6003eb2477bf8bc70", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/826e6daa07d3595da06e93ee0ddf263664cb022610c47831e3f369d99aa94584.mp3", "duration_ms": 5440}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/963435b319604e359d04562dc6c71484ea1f5748539147380c7e7b7f148244ff.mp3", "hash": "25c048cb7d84385e04c9dd1f2ea855e401d13422ddcc20ba1e320be2b47b149d", "bytes": 37728, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/963435b319604e359d04562dc6c71484ea1f5748539147380c7e7b7f148244ff.mp3", "duration_ms": 6240}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/d189f4831d0e19aa00298ceb5808b688311f327658e00a3f7cc284dc6a08e4bc.mp3", "hash": "7414f8e53d29a2567547eff66b450b70995a4eae3cc6f7d3ac44a555cad172c5", "bytes": 57888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d189f4831d0e19aa00298ceb5808b688311f327658e00a3f7cc284dc6a08e4bc.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "savings-goal", "title": "Savings plan for the guitar", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the number of weeks to reach a savings goal by dividing the goal by the weekly savings."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "savings-goal-1", "xp": 15, "type": "savings_goal", "hints": ["Think about dividing the 80 dollars into equal parts according to what he saves per week."], "title": "How many weeks for the guitar?", "payload": {"goal": 80, "currency": "USD", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf can save 10, 20 or 40 dollars per week for the 80-dollar guitar. How many weeks does each plan take?", "difficulty": 2, "explanation_md": "Saving 10 dollars per week, Liruf takes 8 weeks; with 20 it''s 4 and with 40 only 2. For the contest in 4 weeks, the $20 and $40 plans get him there just in time. ⭐", "audio_segment_id": "savings-goal-1.prompt"}], "schema_version": 1}', '{"savings-goal-1": {}}', '{"units": {"savings-goal-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/541e19f60095b856bf5f1bb92e8620aa09a8362b53fb0941fc9dcc0efb58d918.mp3", "hash": "05096fe29096c024b7843994448f9e60a1a2d241676e7a42691c1c02fc81f607", "bytes": 37296, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/541e19f60095b856bf5f1bb92e8620aa09a8362b53fb0941fc9dcc0efb58d918.mp3", "duration_ms": 6160}, "savings-goal-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/d5649baa89ab2de7683bdfd8a683b3356e192ea44628c31426084660e936d957.mp3", "hash": "0a2e654b9c62be8dc66862aa087a9582a434046a758b64653daac09a2547864d", "bytes": 47808, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d5649baa89ab2de7683bdfd8a683b3356e192ea44628c31426084660e936d957.mp3", "duration_ms": 7920}, "savings-goal-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/92d6079d2452fde3235679aeac99c3c411c558288c2c2ee49802e78e8bf357f1.mp3", "hash": "c09ba6b27a7469c1c278e12ddb7d81ca2642c83a86357027e934bbc60fa64202", "bytes": 91008, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/92d6079d2452fde3235679aeac99c3c411c558288c2c2ee49802e78e8bf357f1.mp3", "duration_ms": 15120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "La ruta del repartidor", "locale": "es-MX", "subject": "mixed", "objectives": ["Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 5, "type": "robot_path", "hints": ["Piensa en la dirección que debe tomar el carrito para ir en línea recta.", "¿Cuántos cuadritos hay desde el inicio hasta la casa?"], "title": "La ruta más corta", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "commands": ["forward", "forward"], "max_commands": 2}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Tras aprender a ordenar la registradora, ayuda a Zara con su primer pedido a domicilio. Programa la ruta más corta.", "difficulty": 1, "explanation_md": "La ruta más corta es ir dos veces hacia adelante. ¡El carrito toma 2 pasos para llegar!", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8c4c5afeccb1459928ef231c6ce76d219be4d7e1a4acc9c0b4064f5835d38bfa.mp3", "hash": "89be116a6d11324f510a86f42d8d81f734f77e79aa55d9446d38998ea17a9bf8", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8c4c5afeccb1459928ef231c6ce76d219be4d7e1a4acc9c0b4064f5835d38bfa.mp3", "duration_ms": 4400}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e5d7ce97520daa0ffb6675b481bfe92da6472c32fe80360aead029345fc0941b.mp3", "hash": "57b152b6a08f6f0bec07855c692b24f9f81f571e0ba212c02e58d47eba71bc33", "bytes": 23328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e5d7ce97520daa0ffb6675b481bfe92da6472c32fe80360aead029345fc0941b.mp3", "duration_ms": 3840}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/4b47fa8b4470528ab4bc88f0dc371a4e3ecbfe90ad8c42886a7d497a379e0295.mp3", "hash": "8c322c1ba9dfd6b45f52f0a6987df0f4f5d37dc2c8e3ef816eb06023992df50d", "bytes": 46944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4b47fa8b4470528ab4bc88f0dc371a4e3ecbfe90ad8c42886a7d497a379e0295.mp3", "duration_ms": 7760}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/9081e9306750638dba7592432ba1503ea3a30b7ee0863da87c271ed22831993d.mp3", "hash": "d8fe9d7a29313af278013ef9e972804bbc4c965e2fb9fc9ed61cd7a49bec7185", "bytes": 36864, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9081e9306750638dba7592432ba1503ea3a30b7ee0863da87c271ed22831993d.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Necessidades e desejos na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar necessidades da barraca de limonada dos desejos pessoais."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "needs-wants-1", "xp": 10, "type": "needs_wants", "hints": ["Dica: Sem isso, Liruf pode vender limonada? Se não, é uma necessidade."], "title": "Necessidades e desejos", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/1be5b55a4cacf2174b4ed0c13f4e27f7e86f095fe85a2da912c97830ae354bad.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/6266599e8d76c27c9bf369b2b0c59010493415893dfd34b51499e18c816e21fe.webp"}, {"id": "vasos", "icon": "water_drop", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/abf95f91e3e5d0a6225fd83557a45c2886dab03b058449c9551713bd93eb4633.webp"}, {"id": "paleta", "icon": "icecream", "text_md": "Picolé", "image_url": "http://localhost:4006/files/lesson-images/6a902c8bd79a972f87a4f03ad2a48e351c138e92a4443deaf5dd1f094f099495.webp"}, {"id": "comic", "icon": "auto_stories", "text_md": "Gibi", "image_url": "http://localhost:4006/files/lesson-images/ede5b71ddfb77514ed873c22f9d5659644892e52893ff67ed4595dac793f64a7.webp"}, {"id": "juguete", "icon": "toys", "text_md": "Brinquedo", "image_url": "http://localhost:4006/files/lesson-images/16161313c663e9e7c70417e58de7dbe663ca8f05bff00c9837b942381fbb9a09.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf compra para sua barraca de limonada. Toque em cada coisa e escolha: necessidade para a barraca ou desejo pessoal?", "difficulty": 1, "explanation_md": "Os limões, o gelo e os copos são necessidades porque sem eles Liruf não pode preparar nem vender limonada 🍋. O picolé, o gibi e o brinquedo são desejos que ele pode comprar depois, quando a barraca ganhar dinheiro.", "audio_segment_id": "needs-wants-1.prompt"}], "schema_version": 1}', '{"needs-wants-1": {"needs_ids": ["limones", "hielo", "vasos"]}}', '{"units": {"needs-wants-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6da4d1f3d4e1708fa7de952438cd8c1b04a3881afb23452dd3587e2b3db0f9db.mp3", "hash": "1ccc6a52e73257f13c78e8dba5511778414d43f00331118c20b865e5e432a779", "bytes": 36864, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6da4d1f3d4e1708fa7de952438cd8c1b04a3881afb23452dd3587e2b3db0f9db.mp3", "duration_ms": 6080}, "needs-wants-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/d92b3c1c70ef48e58271d2bd1de09254620d13516576ca300fbce47aa5bcbb6c.mp3", "hash": "06628d73cff0043fb5ab1bbcf079dd48dda96423f4c2b96b46fc4a6f66ecdce3", "bytes": 50688, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d92b3c1c70ef48e58271d2bd1de09254620d13516576ca300fbce47aa5bcbb6c.mp3", "duration_ms": 8400}, "needs-wants-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/28c41bacd44e71a8decf79a83f59c343b5cf0222e022435d5994c36d5737d503.mp3", "hash": "ea3d65aa0430fd715cc81c60c5973308e15b2d71aaa7b4b474a85da73b017fe3", "bytes": 98784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/28c41bacd44e71a8decf79a83f59c343b5cf0222e022435d5994c36d5737d503.mp3", "duration_ms": 16400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Agrupa el dinero: monedas y billetes", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras por prioridad", "Agrupar monedas y billetes para facilitar el conteo"], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 8, "type": "group_sets", "title": "Agrupa monedas y billetes", "payload": {"items": [{"id": "item-1", "icon": "savings", "text_md": "Moneda de 10 pesos", "image_url": "http://localhost:4006/files/lesson-images/154671db494e6a0bffef7f2a0ec8b9a7a7aef3877d29458dcd61d6057eb2bb32.webp"}, {"id": "item-2", "icon": "payments", "text_md": "Billete de 50 pesos"}, {"id": "item-3", "icon": "savings", "text_md": "Moneda de 5 pesos", "image_url": "http://localhost:4006/files/lesson-images/b0def457698d901cba8a5c76ffeb99a3305cca1d7abbdab383d2cc6749e5c4f8.webp"}, {"id": "item-4", "icon": "payments", "text_md": "Billete de 20 pesos", "image_url": "http://localhost:4006/files/lesson-images/fec591f6177becb8e49d2cf802ce1b9ba9cdec6e791ad7988dd9c38eeef9409e.webp"}, {"id": "item-5", "icon": "savings", "text_md": "Moneda de 2 pesos", "image_url": "http://localhost:4006/files/lesson-images/15437f98aaea4301f8544412a09005610d1f80f9fd4ac4a704dc8b23deaa916d.webp"}, {"id": "item-6", "icon": "payments", "text_md": "Billete de 100 pesos", "image_url": "http://localhost:4006/files/lesson-images/474ba981e7b9e541494210079df1da02ada62506be38a240efbf358ef9c913e0.webp"}], "set_a": "Monedas", "set_b": "Billetes"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Al final del día, la caja de Liruf está revuelta. Agrupa monedas con monedas y billetes con billetes.", "difficulty": 1, "explanation_md": "Agrupar monedas con monedas y billetes con billetes hace más fácil contar el dinero. Liruf ahora puede ver cuánto juntó en monedas y cuánto en billetes.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"item-1": "a", "item-2": "b", "item-3": "a", "item-4": "b", "item-5": "a", "item-6": "b"}}}', '{"units": {"s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/b67b46aa6d3dd14d910cd23cdf7245828d500d3df92a59b4cad8cd89483f4774.mp3", "hash": "61ff29d7eda19fa8db7fa65574df8127cd16c39b8184e8499bbf513f6ea8b3d6", "bytes": 41616, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b67b46aa6d3dd14d910cd23cdf7245828d500d3df92a59b4cad8cd89483f4774.mp3", "duration_ms": 6880}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/321975d916f069ebe5e6b1c002c3d5789f54635b6e4e3b8d9eb6a52421e9cb09.mp3", "hash": "0395e4cafc0f0f34a07f2f9bd5a78298474d00d1a9ce08c9b01d86fe1e2c12bc", "bytes": 61776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/321975d916f069ebe5e6b1c002c3d5789f54635b6e4e3b8d9eb6a52421e9cb09.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparing lemon prices", "locale": "en-US", "subject": "mixed", "objectives": ["Compare lemon prices and choose the cheapest deal to maximize earnings."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Remember: to spend less, look for the lowest price for the same amount of lemons."], "title": "Compare lemon prices", "payload": {"offers": [{"id": "of1", "qty": 10, "unit": "limones", "label": "Lemons — Doña Lula", "price": 20, "image_url": "http://localhost:4006/files/lesson-images/dec91d8435168a7ea0c6730477493ac1b39e1b9f2b0c5b285d9352c3b0b6098f.webp"}, {"id": "of2", "qty": 10, "unit": "limones", "label": "Lemons — Don Pepe", "price": 25, "image_url": "http://localhost:4006/files/lesson-images/6f3c064b9fadc18c1a4b70e3ca659f1313a5b3b5edbd661047f511de46d51785.webp"}], "currency": "USD"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf already separated needs and wants. Now compare these lemon deals and tap the one that suits him best.", "difficulty": 1, "explanation_md": "Doña Lula''s stand costs 20 dollars for 10 lemons, 5 dollars less than Don Pepe. That way Liruf spends less and has more left for the 80-dollar guitar. 💡", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "of1"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fab90865396c2344e77f3216b55095324be69c478b23bfc6784baa090adb8c55.mp3", "hash": "1733663d51425e4a3356ace4cd6dcc14afc793bb575ce230f54037b4991517b3", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fab90865396c2344e77f3216b55095324be69c478b23bfc6784baa090adb8c55.mp3", "duration_ms": 4080}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/837aebd2e38ac6f72d1fb00b2c03f83d819829ac2e9b50cfb5a4c2e4f8bcdf5b.mp3", "hash": "36fffe84e7f3bcb9daac401805042070728b88cde54f3972e393a38b246f5706", "bytes": 36288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/837aebd2e38ac6f72d1fb00b2c03f83d819829ac2e9b50cfb5a4c2e4f8bcdf5b.mp3", "duration_ms": 6000}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/f3fcf7503cb49a252eacb6e5b4237fdc5cd6adab123ea91d3fe64be213b56429.mp3", "hash": "511171ecaa8c2114f2d018e738a0aa9941b911e9afde1475df02a577833141aa", "bytes": 55584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f3fcf7503cb49a252eacb6e5b4237fdc5cd6adab123ea91d3fe64be213b56429.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Clasificar compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar compras en necesidades del puesto de limonada y gustos que pueden esperar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort", "xp": 10, "type": "sort_buckets", "title": "¿Necesidad o gusto?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/7d9472b044ee532f11a80b6786f3eba28c63e2599c11c8be981b5243e2c7d5cb.webp"}, {"id": "vasos", "icon": "local_drink", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/0639608c7c8f6cd9e63e97af1b17b0cd62dae847d6a4d42848ab2143b81bacaf.webp"}, {"id": "stickers", "icon": "sticky_note_2", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/6864fbb6a2bfc7d7630f86e9709565b218e611ffb8f90b9f037396f3d34501a2.webp"}, {"id": "globos", "icon": "celebration", "text_md": "Globos", "image_url": "http://localhost:4006/files/lesson-images/3ef6823477bf5d5253cbe527dd70266b70e5dceb98d300b6949140a9545241b9.webp"}], "buckets": [{"id": "necesidad", "label": "NECESIDAD del puesto"}, {"id": "gusto", "label": "GUSTO que puede esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Clasifica cada compra: ¿necesidad del puesto de limonada o gusto que puede esperar?", "difficulty": 1, "explanation_md": "Para Liruf, los limones y los vasos son NECESIDADES porque sin ellos no puede preparar ni servir limonada. Los stickers y globos son gustos que pueden esperar.", "audio_segment_id": "s1-sort.prompt"}], "schema_version": 1}', '{"s1-sort": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort.prompt": {"url": "http://localhost:4006/files/lesson-audio/71be029518d9b25db502a8a30c41e198d2272786c5939716856155f6963b1fcc.mp3", "hash": "54016692026769247f3397667d1cf8cdf7405863474e8a12a34ff50d00d5e240", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/71be029518d9b25db502a8a30c41e198d2272786c5939716856155f6963b1fcc.mp3", "duration_ms": 5760}, "s1-sort.explanation": {"url": "http://localhost:4006/files/lesson-audio/ded71e3578b35cb05521873a8751903e27d7ab37678182494925c42255082f5d.mp3", "hash": "710413b4b30d8b9c2c574da5816f4bac58b134c0de694cfd92047c63170ae885", "bytes": 62208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ded71e3578b35cb05521873a8751903e27d7ab37678182494925c42255082f5d.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparando preços de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Comparar preços de limões e escolher a oferta mais barata para maximizar ganhos."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Lembre-se: para gastar menos, procure o preço mais baixo pela mesma quantidade de limões."], "title": "Compare preços de limões", "payload": {"offers": [{"id": "of1", "qty": 10, "unit": "limones", "label": "Limões — Dona Lula", "price": 20, "image_url": "http://localhost:4006/files/lesson-images/dec91d8435168a7ea0c6730477493ac1b39e1b9f2b0c5b285d9352c3b0b6098f.webp"}, {"id": "of2", "qty": 10, "unit": "limones", "label": "Limões — Seu Pepe", "price": 25, "image_url": "http://localhost:4006/files/lesson-images/6f3c064b9fadc18c1a4b70e3ca659f1313a5b3b5edbd661047f511de46d51785.webp"}], "currency": "BRL"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf já separou necessidades e desejos. Agora compare estas ofertas de limões e toque na que lhe convém mais.", "difficulty": 1, "explanation_md": "A barraca da Dona Lula custa 20 reais por 10 limões, 5 reais a menos que a do Seu Pepe. Assim Liruf gasta menos e sobra mais para a guitarra de 80 reais. 💡", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "of1"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f467320150927c1ffe430808cdab13ac0de03386ae07092181df12229dc9724b.mp3", "hash": "38473f347b017efe0acba74522f22dfe1046b090edb60df6c9721205c62f1fc2", "bytes": 37296, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f467320150927c1ffe430808cdab13ac0de03386ae07092181df12229dc9724b.mp3", "duration_ms": 6160}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/c9567f7b2565fc73f19b739719f645db918ee448dd1145fda54b4af60f20fdff.mp3", "hash": "a9473eb4f7af02aac9ca55685bc8643c55792c7134a9eb5d2eb535622ac95b3f", "bytes": 45936, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c9567f7b2565fc73f19b739719f645db918ee448dd1145fda54b4af60f20fdff.mp3", "duration_ms": 7600}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/0529fef405177da2fd5aa4028a98beeed9a05c8a1e901fbe1b40bcf8d84dc726.mp3", "hash": "2c6bac6d0dad41c9cbda3abdeb9e995a747fddd8980bd32d1f9b0f913d7a5a46", "bytes": 70848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0529fef405177da2fd5aa4028a98beeed9a05c8a1e901fbe1b40bcf8d84dc726.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "checkpoint", "title": "Ganhar dinheiro começa com uma ideia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que os outros querem, e que uma meta clara (o violão de 80 reais) ajuda a começar."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "title": "A grande ideia do Liruf", "payload": {"recap_md": "Liruf quer um violão de brinquedo que custa 80 reais. Para ganhar esse dinheiro, decidiu vender limonada a 5 reais o copo. De cada copo que vender, o que sobrar depois de pagar o custo (limões, açúcar, copos) é o seu lucro, e esse lucro vai direto para o seu frasco... cada vez mais perto do violão!", "mood_prompt_md": "Você acha que o Liruf já sente o violão mais perto? 🌟"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Revise o plano do Liruf.", "difficulty": 1, "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/e4e29f80489e63eda9b76e8820575bfff7631b6272749333b45da253b32ffccb.mp3", "hash": "264d9f9385fed36a1ee6f36bf7239719bbafad3e3368b13552ad99e60c3c19f9", "bytes": 126576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e4e29f80489e63eda9b76e8820575bfff7631b6272749333b45da253b32ffccb.mp3", "duration_ms": 21040}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/4401cbbda54a7b6c326c00074163093d891d5ec8e2cd359b64bd6f9b0367a4d3.mp3", "hash": "6be2135a27776df20516dcb658e458778e8c12fde1355e70ebf31e645d3c8020", "bytes": 9504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4401cbbda54a7b6c326c00074163093d891d5ec8e2cd359b64bd6f9b0367a4d3.mp3", "duration_ms": 1520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Today or next week?", "locale": "en-US", "subject": "mixed", "objectives": ["Making financial decisions with short- and long-term consequences."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "w1-dilema", "xp": 0, "type": "would_you_rather", "title": "Sell now or later", "payload": {"a": {"icon": "today", "text_md": "Sell today for 10 dollars", "image_url": "http://localhost:4006/files/lesson-images/26993af9e646e8264e32ead105433d7a9254c4b054b8c0d971b067e206666dd5.webp"}, "b": {"icon": "schedule", "text_md": "Wait a week for 20 dollars", "image_url": "http://localhost:4006/files/lesson-images/3e0f982b4b45ff9b7bcf1fa432200c01c859e94a8267078f1d0bc6410bf40c5f.webp"}, "followup_md": "Why did you choose that option?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf can sell today and earn 10 dollars, or wait a week and earn 20. What would you do?", "difficulty": 1, "explanation_md": "If you sell today, you have secure money, but you miss the chance to double it for something bigger. Waiting takes patience, but in the end you''ll have 20 dollars instead of 10. 💡", "audio_segment_id": "w1-dilema.prompt"}], "schema_version": 1}', '{"w1-dilema": {"qualities": {"a": 15, "b": 95}, "reveal_md": "Al vender hoy aseguras 10 pesos, pero pierdes la oportunidad de ganar el doble. Esperar te da 20 pesos, aunque hoy no recibes nada."}}', '{"units": {"w1-dilema.prompt": {"url": "http://localhost:4006/files/lesson-audio/f6935ff8d2e6f668198ab164ba3984d17773f379844d18c494c850899692b92d.mp3", "hash": "a9f01360bc44564e819202c4f9a6990df0f924dbc0dd730319a5e2a0cca300f2", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f6935ff8d2e6f668198ab164ba3984d17773f379844d18c494c850899692b92d.mp3", "duration_ms": 5520}, "w1-dilema.choices": {"url": "http://localhost:4006/files/lesson-audio/1f5fe8779ba281139232cb6aeb4f3a109ddf489e18dbf83750aa0dcd89603176.mp3", "hash": "bbb7fb701613fc514728be798e0acd1edcf780017692c44bd3dd5edbfef177d5", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1f5fe8779ba281139232cb6aeb4f3a109ddf489e18dbf83750aa0dcd89603176.mp3", "duration_ms": 3200}, "w1-dilema.explanation": {"url": "http://localhost:4006/files/lesson-audio/5f159e969332a8a137ddb9cba102ea4999a02ae5d1700cc2ecb8ba4e75588dac.mp3", "hash": "fc9a8ad3ac8bee2cba876b58e663d1d7a7782b90155522dbd1135c3152dda229", "bytes": 55008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5f159e969332a8a137ddb9cba102ea4999a02ae5d1700cc2ecb8ba4e75588dac.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "timeline-order", "title": "O primeiro dia de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar os passos de um dia de venda na sequência correta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 5, "type": "timeline_order", "hints": [], "title": "Ordem do dia", "payload": {"events": [{"id": "ev-buy", "icon": "shopping_cart", "text_md": "Comprar limões e açúcar no mercado", "image_url": "http://localhost:4006/files/lesson-images/b5257743949c3ffb95f5508b07209f4282c2ce7a2752db4fe60a162538cf2f54.webp"}, {"id": "ev-prepare", "icon": "blender", "text_md": "Preparar a limonada fresca", "image_url": "http://localhost:4006/files/lesson-images/f69d8b420be568820316e6c161e739d9713ac70d6ded82df0b593726d6a76fa7.webp"}, {"id": "ev-sell", "icon": "storefront", "text_md": "Vender copos de limonada ao meio-dia", "image_url": "http://localhost:4006/files/lesson-images/7645b91a3c5675f0c17e109394272aecaf29c412d306ad2fb832141a1793a40e.webp"}, {"id": "ev-count", "icon": "calculate", "text_md": "Contar o dinheiro e guardar os ganhos", "image_url": "http://localhost:4006/files/lesson-images/1e2d2f4bc1bac9bf39d0bcdd5e0998b0f63cb777d94627b9e23cb6fe6b322d0a.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf se lembra do seu primeiro dia completo. Ordene as fotos do dia, da manhã até a noite.", "difficulty": 1, "explanation_md": "Assim foi o primeiro dia do Liruf: comprou limões e açúcar de manhã, preparou a limonada, vendeu ao meio-dia e contou seus ganhos ao fechar.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["ev-buy", "ev-prepare", "ev-sell", "ev-count"]}}', '{"units": {"s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/c324532f096965db6bcb7caa16a9373ba1090916eafce90f0928bcd04c601d3c.mp3", "hash": "f2b0b5a582a1ce6a7e7c16f95d0a1a68de59daf7ac1163b35d14063f297f6dc1", "bytes": 42048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c324532f096965db6bcb7caa16a9373ba1090916eafce90f0928bcd04c601d3c.mp3", "duration_ms": 6960}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/e962f8e332eaaac2ea85b6ab0a1fff4f880d9699515bf2ae913b03a804857356.mp3", "hash": "7bbecf937bcce8f0326fd86a312eb2bd81a285725fc48b0d6794f50ea98f3fdd", "bytes": 60768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e962f8e332eaaac2ea85b6ab0a1fff4f880d9699515bf2ae913b03a804857356.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "measure-read", "title": "La jarra medidora", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer medidas en una jarra para garantizar porciones justas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-jarra", "xp": 15, "type": "measure_read", "hints": ["Cuenta las marcas cada 50 ml: 0, 50, 100... Fíjate dónde está la superficie."], "title": "La jarra medidora", "payload": {"max": 500, "min": 0, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/c78198cd49aa96de68bc80d197c016ba65b7e276a975bd12c4d3dafc6c0dffe6.webp", "prompt_md": "Rho trajo la jarra medidora. Observa hasta dónde subió el líquido. ¿Cuántos mililitros marca?", "difficulty": 2, "explanation_md": "El líquido llega a los 250 ml. Liruf se asegura de que cada vaso quede igual, ¡como la balanza del trueque!", "audio_segment_id": "s1-jarra.prompt"}], "schema_version": 1}', '{"s1-jarra": {"value": 250, "tolerance": 0}}', '{"units": {"s1-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c9a8f7bba4537dda6e35cb9c56da2277475ef53538dbe21d3656ae302e9b8003.mp3", "hash": "97b4ed92f7ffe332e5d03d7d9e140fbdc2880657cf7245401b5794d784bc615c", "bytes": 45936, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c9a8f7bba4537dda6e35cb9c56da2277475ef53538dbe21d3656ae302e9b8003.mp3", "duration_ms": 7600}, "s1-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/29464fb5d6eac0eef5428f4152756d3c09e4bc7ccab8824084b86b72ecadd9db.mp3", "hash": "7a4f22e326ade1ec8ec0112de000671bdfa9778badfc3f95347aa6763d1160a3", "bytes": 45504, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/29464fb5d6eac0eef5428f4152756d3c09e4bc7ccab8824084b86b72ecadd9db.mp3", "duration_ms": 7520}, "s1-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/c3caace4533554bde0c6ec827923f997c72831399f482644e0906652ffc47046.mp3", "hash": "d8052aeaae5919773e12a42792b377d3816d35ccab7e5d62f41cda9ad2c141bb", "bytes": 49248, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c3caace4533554bde0c6ec827923f997c72831399f482644e0906652ffc47046.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Count the sales coins", "locale": "en-US", "subject": "mixed", "objectives": ["Count the exact number of coins in a messy scene", "Associate each counted coin with a $5 sale"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "count-objects-sales", "xp": 5, "type": "count_objects", "title": "Count the sales coins", "payload": {"scene": [{"icon": "monetization_on", "tint": "delight", "count": 8, "label": "coin", "image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, {"icon": "cookie", "tint": "warning", "count": 3, "label": "cookie", "image_url": "http://localhost:4006/files/lesson-images/f2975e6e8d715646e735228b20f39c19a408d57acbe156d19e08e426fad7fc66.webp"}, {"icon": "local_drink", "tint": "primary", "count": 2, "label": "glass", "image_url": "http://localhost:4006/files/lesson-images/e7f7f16426e7194c18895bfcec92b380cc27efe30ad87d400a21821b9a14d390.webp"}], "ask_icon": "monetization_on", "ask_label": "coin", "ask_image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf knocked over the sales jar. Count only the coins that fell. Each one is a $5 glass he already sold.", "difficulty": 1, "explanation_md": "8 coins fell. Each one is $5! That means Liruf sold 8 glasses of lemonade today. Those 8 glasses add to his savings for the $80 guitar.", "audio_segment_id": "count-objects-sales.prompt"}], "schema_version": 1}', '{"count-objects-sales": {"value": 8}}', '{"units": {"count-objects-sales.prompt": {"url": "http://localhost:4006/files/lesson-audio/51341a7f7eb5670e0d95b897e39b4ab3070c014d9fe4ec2d63941bed859c0a12.mp3", "hash": "1945d1631a472fb2360984fbf36b2eb45db49eafb127672ec12c4c65abbf2da1", "bytes": 40608, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/51341a7f7eb5670e0d95b897e39b4ab3070c014d9fe4ec2d63941bed859c0a12.mp3", "duration_ms": 6720}, "count-objects-sales.explanation": {"url": "http://localhost:4006/files/lesson-audio/3080ec6a55e8b7b0f225359aeeac8d82f5126c7987235796a04454fbabe87fe6.mp3", "hash": "9fcf65e8edc11366b74aeed5d49c1c15df9603ae776fd747bf5e43c04d2f8c1e", "bytes": 66096, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/3080ec6a55e8b7b0f225359aeeac8d82f5126c7987235796a04454fbabe87fe6.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "The delivery route", "locale": "en-US", "subject": "mixed", "objectives": ["Solve building and measurement challenges applied to the job: ordering instructions, reading measurements, and balancing quantities."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 5, "type": "robot_path", "hints": ["Think about the direction the cart should take to go in a straight line.", "How many squares are there from the start to the house?"], "title": "The shortest route", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "commands": ["forward", "forward"], "max_commands": 2}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After learning how to organize the cash register, help Zara with her first home delivery. Program the shortest route.", "difficulty": 1, "explanation_md": "The shortest route is to go forward twice. The cart takes 2 steps to get there!", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/18474f798c8a77b191e73788fb30bab6e5c59aff7ef6bba3b293294869318ab9.mp3", "hash": "b1797de8c700add33c89e7ed902df177b0af461fcd631f587337c498ab054077", "bytes": 18144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/18474f798c8a77b191e73788fb30bab6e5c59aff7ef6bba3b293294869318ab9.mp3", "duration_ms": 2960}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1d9fd413ab6243229c09bd49c752526c1fd56433594c4fce5274273924c62531.mp3", "hash": "aeb3a04c48efa1d141862c7921eb9a664f67de5d16c6a10e38be3b4b39fd9ed7", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1d9fd413ab6243229c09bd49c752526c1fd56433594c4fce5274273924c62531.mp3", "duration_ms": 2640}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/bc908db69b507e07b7102b5275c03bec975bbac71de9771a377baf237e6193de.mp3", "hash": "73dfdc2f2c98b581c8a6ff25d1af88005b83ce6c07948ade9e073fbeab03c550", "bytes": 38736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bc908db69b507e07b7102b5275c03bec975bbac71de9771a377baf237e6193de.mp3", "duration_ms": 6400}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/2fc7d098ef57f34d0eeb99bbee10eb63b3d4df9790f9717a46244dcd91151743.mp3", "hash": "47228209a897fa978e7bd54742d449f759add6bb084b1fb55d7b238ffa2c6f99", "bytes": 26208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2fc7d098ef57f34d0eeb99bbee10eb63b3d4df9790f9717a46244dcd91151743.mp3", "duration_ms": 4320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "fill-blank", "title": "Complete o ganho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escrever o ganho numérico de uma venda subtraindo o custo dos ingredientes."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fill-blank", "xp": 5, "type": "fill_blank", "hints": ["Subtraia os ingredientes do preço do copo para saber quanto sobra."], "title": "Complete o ganho", "payload": {"mode": "typed", "text_md": "Vendi um copo por 5 reais, os ingredientes custaram 2, meu ganho é {{1}} reais."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina vendeu um copo a 5 reais e gastou 2 em ingredientes. Complete a frase com o ganho dela.", "difficulty": 1, "explanation_md": "O ganho é o que sobra depois de pagar os gastos: 5 reais do copo menos 2 de ingredientes deixam 3 reais.", "audio_segment_id": "s1-fill-blank.prompt"}], "schema_version": 1}', '{"s1-fill-blank": {"gaps": [{"gap": 1, "accept": ["3"]}]}}', '{"units": {"s1-fill-blank.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6a609f723e9abe6af7f421f2249d76932862c4f72e058612110cffa8d096299d.mp3", "hash": "9080c66b018ae0bd6d17029484647d9844a2471aabaf3f051226450bf5e8f700", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6a609f723e9abe6af7f421f2249d76932862c4f72e058612110cffa8d096299d.mp3", "duration_ms": 4800}, "s1-fill-blank.prompt": {"url": "http://localhost:4006/files/lesson-audio/53e065549ff72d3b07253d4d5f44651c464af598b9da5bf161f937a7bcf04e00.mp3", "hash": "5fb10dbded5e9c8662cd91b0cab96dc0a78939f233822c9e95202cc495cb6a3c", "bytes": 48384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/53e065549ff72d3b07253d4d5f44651c464af598b9da5bf161f937a7bcf04e00.mp3", "duration_ms": 8000}, "s1-fill-blank.explanation": {"url": "http://localhost:4006/files/lesson-audio/138a09282470a261946ff359e56a48aea090818c558e27b4ea8fe312bc0bd457.mp3", "hash": "94edb606fb15e950e10617d6e7a8598e56dac6b832cecd175453a971c666862a", "bytes": 47808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/138a09282470a261946ff359e56a48aea090818c558e27b4ea8fe312bc0bd457.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "spot-error", "title": "Finding the mistake in the sum", "locale": "en-US", "subject": "mixed", "objectives": ["Spotting an error in a sales sum."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1", "xp": 15, "type": "spot_error", "hints": ["Add up the prices of the three cups. Is the total that Liruf wrote down correct?"], "title": "Finding the mistake in the sum", "payload": {"steps": [{"id": "sale1", "text_md": "I sold one cup for 5 dollars"}, {"id": "sale2", "text_md": "I sold another cup for 5 dollars"}, {"id": "sale3", "text_md": "I sold a third cup for 5 dollars"}, {"id": "total", "text_md": "Daily total: 20 dollars"}], "context_md": "Liruf writes down the day''s sales in his notebook."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/05b7e5bfb7561c1c8bbdcc569c3356a8496946add9204fbe1cf09102dba9c4ad.webp", "prompt_md": "Something doesn''t add up in Liruf''s total. Tap the step where the mistake is.", "difficulty": 2, "explanation_md": "The correct total is 15 dollars, because 5+5+5=15. Liruf made a mistake by writing 20. Sharp eye for catching the mistake!", "audio_segment_id": "s1.prompt"}], "schema_version": 1}', '{"s1": {"error_ids": ["total"], "correction_md": "5+5+5 es 15, no 20. El total correcto es 15 pesos."}}', '{"units": {"s1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9ece74c57eff7aefcc14ce7bf49a116aa8230f9bd934c5586484f8fd0cc560ca.mp3", "hash": "f120fdd0143ab5c861b139d57f1e1f94a7c4491f182a8e368d9bf51db534cd76", "bytes": 25776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9ece74c57eff7aefcc14ce7bf49a116aa8230f9bd934c5586484f8fd0cc560ca.mp3", "duration_ms": 4240}, "s1.prompt": {"url": "http://localhost:4006/files/lesson-audio/e17e96712fc9f1477721555144b16edfe9eff89ac28f4c49c23217062104289e.mp3", "hash": "b911bdb536cd0359e15f90b7c465aeed3d310dac8b83096b4e151ff1745316e7", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e17e96712fc9f1477721555144b16edfe9eff89ac28f4c49c23217062104289e.mp3", "duration_ms": 4000}, "s1.explanation": {"url": "http://localhost:4006/files/lesson-audio/0957b1ff34540a67177cac8493e1ed4b527a3a19f71117baaf70e69036f908f6.mp3", "hash": "31ab2e3515fe5c6be1eb618758b7db1643b8b1bb094ca1420fac5b4f0c41b775", "bytes": 56448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0957b1ff34540a67177cac8493e1ed4b527a3a19f71117baaf70e69036f908f6.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Presupuesto para el puesto de limonada", "locale": "es-MX", "subject": "money", "objectives": ["Contar dinero con monedas de 1, 2, 5 y 10, calcular cambio de un billete de 20, y planear cuántas semanas faltan para la meta."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 25, "type": "budget_fit", "hints": ["Primero suma lo que cuestan los limones y el azúcar, luego ve cuánto te queda.", "Con lo que sobra, prueba a agregar uno por uno sin pasarte de 20."], "title": "¿Qué compramos para mañana?", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Limones", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/8e2114763dacc523d4ae74e3cb87a6557b23665ecac524fcf96298651f8b62d1.webp"}, {"id": "azucar", "icon": "coffee", "need": true, "label": "Azúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/0491cbc67e39281f347d48a3d5fbbab8a095f324096e2746453caaabb636dc86.webp"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Hielo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/9574dc6da4a543fb842926fee0c40acde530504fa7bc70718d4270fb4a8cc69f.webp"}, {"id": "popotes", "icon": "fastfood", "need": false, "label": "Popotes", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/914c8736ac650c278a905f84c142ce4aac7340881dbc35f379ad43aa78f258fb.webp"}, {"id": "jarra", "icon": "water_bottle", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/4052aa568eb6daeeedb7576aff035a3dc05800b16079ef4a7d3426062b135373.webp"}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene $20. Debe comprar limones ($8) y azúcar ($6). ¿Qué más puede llevar sin pasarse?", "difficulty": 3, "explanation_md": "Liruf se aseguró de tener limones y azúcar para hacer limonada. Si se hubiera pasado de $20, el marchante le haría devolver algo y mañana no tendrían limonada para vender. ¡Y la guitarra de 80 pesos se alejaría!", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6006cbc5f59c4421990777a1fc84fff170a86e3a40e4cf56e5980b5d23dbc07f.mp3", "hash": "21317ca883997df8c01a5eb91fceb34d8ac50efbbd526db3145c7befb8f2fcd4", "bytes": 31968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6006cbc5f59c4421990777a1fc84fff170a86e3a40e4cf56e5980b5d23dbc07f.mp3", "duration_ms": 5280}, "s1-budget-fit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3e46cf64414e4a5ef7f1a87552619f680f3a1d108d0417c2f2f733adb144e56b.mp3", "hash": "4b7a88fa35bca3e7467ab3d5153a9f95efecad04e292728b1290efe3727502b5", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3e46cf64414e4a5ef7f1a87552619f680f3a1d108d0417c2f2f733adb144e56b.mp3", "duration_ms": 4400}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/5d948ad34e26e27f4d588d93c104f7150dc5b60235049e17916968833b73b9a4.mp3", "hash": "a2ddeb29c48c44f19b17d5aa7e606f9dd1f407f01e34400292764b5bc7aa7543", "bytes": 50256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5d948ad34e26e27f4d588d93c104f7150dc5b60235049e17916968833b73b9a4.mp3", "duration_ms": 8320}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/db64bfa64234421e66584e378e93d188ba6049a5d5abd9bf2aeaeb28d3083ee0.mp3", "hash": "2b937cc99d09bf4e03281ab455abd60646de085407c9c2a78224a880bff0d6e0", "bytes": 86688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/db64bfa64234421e66584e378e93d188ba6049a5d5abd9bf2aeaeb28d3083ee0.mp3", "duration_ms": 14400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Sábado ensolarado: preço da limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ouvir a situação e decidir o preço do dia combinando história e decisão."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sabado-apertura", "xp": 0, "type": "story_scene", "title": "Abertura do sábado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/b98298940fa10b8b8ee1153cad4399da26601372cd4a4ac05e5166dbfe1be72b.webp"}, "action": "idle", "body_md": "Liruf lembra como a máquina de gorjetas dobrava: entra 1, sai 2; entra 3, sai 6. Mas hoje é sábado de verdade. Normalmente o copo custa 5 reais. E há uma fila de clientes! ☀️ Tem que decidir se muda o preço ou não.", "emotion": "happy", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf abre a barraca.", "difficulty": 1, "audio_segment_id": "s1-sabado-apertura.prompt"}, {"id": "s2-decision-precio", "xp": 15, "type": "quiz_mcq", "hints": ["Pense no preço que as pessoas já conhecem e que te dá o suficiente para seus ingredientes."], "title": "Decida o preço", "payload": {"options": [{"id": "precio-3", "text_md": "3 reais", "rationale_md": "Se você vende muito barato, pode não ganhar o suficiente para comprar mais ingredientes."}, {"id": "precio-5", "text_md": "5 reais"}, {"id": "precio-7", "text_md": "7 reais", "rationale_md": "Se você vende muito caro, talvez poucos comprem e você não ganhe mais. O preço justo atrai a todos."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "O preço normal é 5 reais. Hoje tem muita gente. Por quanto você vende cada copo?", "difficulty": 2, "explanation_md": "O preço justo de sempre, 5 reais, é conhecido e as pessoas confiam. Se você sobe para 7, arrisca perder clientes; se baixa para 3, não junta para mais ingredientes. Mantenha o equilíbrio! 🌟", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "precio-5"}}', '{"units": {"s1-sabado-apertura.body": {"url": "http://localhost:4006/files/lesson-audio/751ef406e143b2aa454a6edb270b78dfceca00f92a6fc7f54f9d14b46883c7ac.mp3", "hash": "d391cd01a62834be409a27f22309a5b2f16d741acbeba4967657dd25d0af1b76", "bytes": 101088, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/751ef406e143b2aa454a6edb270b78dfceca00f92a6fc7f54f9d14b46883c7ac.mp3", "duration_ms": 16800}, "s1-sabado-apertura.prompt": {"url": "http://localhost:4006/files/lesson-audio/1500b591cd62fad15b9db1a3548f512f2dd83c935697a1395f00174152d0c133.mp3", "hash": "d768b3c0a0e87de5b30004c7b26e52a2f8295d443d9a431cf6b152026716915e", "bytes": 10944, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1500b591cd62fad15b9db1a3548f512f2dd83c935697a1395f00174152d0c133.mp3", "duration_ms": 1760}, "s2-decision-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ec2d9fae080e56404f1cf06a052f9346277a0c474a27fa26278badab5552e048.mp3", "hash": "1cd5b6c74e73bd515f08abd17bce2143a716dad39695abeddce0e38f84911a47", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ec2d9fae080e56404f1cf06a052f9346277a0c474a27fa26278badab5552e048.mp3", "duration_ms": 5600}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/61e354f4586e05dd11f04fe32fb0379203fd9c2b93e45e8b22b4a14deff66d9a.mp3", "hash": "4690fe0b1ec7706e0475a590c2125d3462ffa8c41ab0dfe81e9766b3c6568489", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/61e354f4586e05dd11f04fe32fb0379203fd9c2b93e45e8b22b4a14deff66d9a.mp3", "duration_ms": 7200}, "s2-decision-precio.choices": {"url": "http://localhost:4006/files/lesson-audio/cbd238c276724c078f1dd7af785a76be75d876b3d00fea22da427642a1bdfa7b.mp3", "hash": "47e70a996c4e74b036d314ef07d266f42b391ebb372e19914b7a874b7161c26d", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cbd238c276724c078f1dd7af785a76be75d876b3d00fea22da427642a1bdfa7b.mp3", "duration_ms": 4080}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/d80251edd80646f67a8e7c3cb4fa9cf18a0b27c40e2ad997e091666cae73d91a.mp3", "hash": "9d4058d22e0a3fdd4ab715e65941392f9fc803fac8c47e562aa008b9ba7efae6", "bytes": 92016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d80251edd80646f67a8e7c3cb4fa9cf18a0b27c40e2ad997e091666cae73d91a.mp3", "duration_ms": 15280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "A troca é justa?", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se uma troca é justa comparando o valor do que se dá e do que se recebe."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "ft-1", "xp": 5, "type": "fair_trade", "title": "Troca com o fruteiro", "payload": {"offer_a": {"qty": 1, "icon": "local_cafe", "label": "2 copos de limonada", "image_url": "http://localhost:4006/files/lesson-images/36e3d03a16fb176bd4e532f60bbb2bd74aaa6f024e844d5bbdd26884d1602d0e.webp"}, "offer_b": {"qty": 1, "icon": "agriculture", "label": "Saco de limões", "image_url": "http://localhost:4006/files/lesson-images/2e985967622df9696797874a56c247c209e105aa3521231488d5613d0491be28.webp"}, "rate_md": "1 saco de limões = 10 reais"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf vende copos de limonada a 5 reais. O fruteiro lhe oferece: 2 copos por um saco de limões que vale 10 reais. A troca é justa?", "difficulty": 1, "explanation_md": "Os 2 copos de limonada valem 10 reais, exatamente o que custa o saco de limões! É uma troca justa.", "audio_segment_id": "ft-1.prompt"}], "schema_version": 1}', '{"ft-1": {"verdict": "fair"}}', '{"units": {"ft-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/949fc300b9080dcd3b9e0257f060f3ed266a8d7c13743e40d537bc3069ddb61a.mp3", "hash": "d0de3f4169b03d78f2fde74799786b2da20b75b1f616a74340fb08c90477ab48", "bytes": 66528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/949fc300b9080dcd3b9e0257f060f3ed266a8d7c13743e40d537bc3069ddb61a.mp3", "duration_ms": 11040}, "ft-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/42c404acd48f05f9463ac34f6a96324227b9f28290042244e3c70c5b24d939c7.mp3", "hash": "acacfa67f58311989141770bce3d59dcba269abf70be085f4a2d5755c2481217", "bytes": 48384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/42c404acd48f05f9463ac34f6a96324227b9f28290042244e3c70c5b24d939c7.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Orçamento para a barraca de limonada", "locale": "pt-BR", "subject": "money", "objectives": ["Contar dinheiro com moedas de 1, 2, 5 e 10, calcular o troco de uma nota de 20, e planejar quantas semanas faltam para a meta."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 25, "type": "budget_fit", "hints": ["Primeiro some o que custam os limões e o açúcar, depois veja quanto te sobra.", "Com o que sobrar, tente adicionar um por um sem passar de 20."], "title": "O que compramos para amanhã?", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Limões", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/8e2114763dacc523d4ae74e3cb87a6557b23665ecac524fcf96298651f8b62d1.webp"}, {"id": "azucar", "icon": "coffee", "need": true, "label": "Açúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/0491cbc67e39281f347d48a3d5fbbab8a095f324096e2746453caaabb636dc86.webp"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Gelo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/9574dc6da4a543fb842926fee0c40acde530504fa7bc70718d4270fb4a8cc69f.webp"}, {"id": "popotes", "icon": "fastfood", "need": false, "label": "Canudinhos", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/914c8736ac650c278a905f84c142ce4aac7340881dbc35f379ad43aa78f258fb.webp"}, {"id": "jarra", "icon": "water_bottle", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/4052aa568eb6daeeedb7576aff035a3dc05800b16079ef4a7d3426062b135373.webp"}], "budget": 20, "currency": "BRL", "must_buy_needs": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem R$20. Deve comprar limões (R$8) e açúcar (R$6). O que mais pode levar sem estourar o orçamento?", "difficulty": 3, "explanation_md": "Liruf se certificou de ter limões e açúcar para fazer limonada. Se tivesse passado de 20, o vendedor o faria devolver algo e amanhã não teriam limonada para vender. E o violão de 80 reais se afastaria!", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f224c608a7aed09bd06b2adcefd7168d0a4121ec5cdc00cfa4a1855919c03d2e.mp3", "hash": "4da7688fb076915cf282f90dedc4dab758bac4505a791503fdae93d543b89095", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f224c608a7aed09bd06b2adcefd7168d0a4121ec5cdc00cfa4a1855919c03d2e.mp3", "duration_ms": 5600}, "s1-budget-fit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/84643e8efacd1b303d0f82d43fab0f9e6a6e42e3c88fda2141eca8c635fc2942.mp3", "hash": "c7874ec1676169eaa97c460460802bbe1e3f3d63a3da31c3bb7d57b91ccb864b", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/84643e8efacd1b303d0f82d43fab0f9e6a6e42e3c88fda2141eca8c635fc2942.mp3", "duration_ms": 4000}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/40a3495f933c6700d953b38b9e29f13dd71aa6774fe0bc5f351ad137e89d9ba4.mp3", "hash": "55083c0b20653fd5924f95fde90053b53c503806ea7298900d7804d29d0135b4", "bytes": 61776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/40a3495f933c6700d953b38b9e29f13dd71aa6774fe0bc5f351ad137e89d9ba4.mp3", "duration_ms": 10240}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/12e8c6ee113785b2b9865f7bbfdaecf06d6ceb3430c3223883d478aaffb90865.mp3", "hash": "3146dab0b3e3ddcef6ef9ac24c90739f47a0d705154ca2bea89d24a3bcded1f3", "bytes": 89136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/12e8c6ee113785b2b9865f7bbfdaecf06d6ceb3430c3223883d478aaffb90865.mp3", "duration_ms": 14800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-branch", "title": "La decisión del precio", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar una decisión de precio viendo las consecuencias en las ganancias."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-decision", "xp": 0, "type": "story_branch", "title": "¿Cuánto cobrar?", "payload": {"nodes": [{"id": "decision", "choices": [{"id": "precio5", "next": "outcome5", "text_md": "5 pesos (el de siempre)"}, {"id": "precio3", "next": "outcome3", "text_md": "3 pesos (barata)"}, {"id": "precio10", "next": "outcome10", "text_md": "10 pesos (el doble)"}], "emotion": "thinking", "text_md": "Liruf piensa: cada vaso cuesta 2 pesos hacerlo. Si cobro más, gano más por vaso… pero ¿comprarán todos? ¿Qué precio me acerca más a la guitarra de 80 pesos?", "character": "liruf"}, {"id": "outcome5", "choices": [{"id": "fin5", "next": null, "text_md": "Continuar"}], "emotion": "happy", "text_md": "Los 6 vecinos compran. Liruf gana 3 pesos por vaso (5-2=3). En total, 18 pesos. ¡Buen avance hacia la guitarra!", "character": "dina"}, {"id": "outcome3", "choices": [{"id": "fin3", "next": null, "text_md": "Continuar"}], "emotion": "surprised", "text_md": "Los vecinos felices compran todos, pero Liruf solo gana 1 peso por vaso. Gana 6 pesos en total, casi nada hacia la guitarra.", "character": "dina"}, {"id": "outcome10", "choices": [{"id": "fin10", "next": null, "text_md": "Continuar"}], "emotion": "surprised", "text_md": "Los vecinos ponen cara de ''¡tan caro!'' y se van a la nevería. Liruf no vende nada. Cero pesos para la guitarra.", "character": "dina"}], "start_node": "decision"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f50e7c6688467e323319afec8f3e3e21ac38d982c301186f28f32cc457ef53a1.webp", "prompt_md": "Liruf tiene 6 vecinos sedientos en fila y cada vaso le cuesta 2 pesos. ¿A qué precio lo vende para acercarse a la guitarra de 80 pesos?", "difficulty": 1, "explanation_md": "Con 5 pesos, Liruf gana 18 pesos en total y avanza bien hacia la guitarra. Precios más bajos o más altos le dieron menos ganancias.", "audio_segment_id": "s1-precio-decision.prompt"}], "schema_version": 1}', '{"s1-precio-decision": {"qualities": [{"score": 100, "node_id": "decision", "choice_id": "precio5"}, {"score": 20, "node_id": "decision", "choice_id": "precio3"}, {"score": 0, "node_id": "decision", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/3ba24e3a2ab136b3495d302509ff3265e7ae59023d14b5e6de6897ea44d5bcd6.mp3", "hash": "c18e1c7558f72b0da2acf2d771f8a41b8f5080351bfcc8619cdebce3d72494a9", "bytes": 60336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3ba24e3a2ab136b3495d302509ff3265e7ae59023d14b5e6de6897ea44d5bcd6.mp3", "duration_ms": 10000}, "s1-precio-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/c07f5683535efaeb1ef98b337dc7cae7ea5b1447a48ebb4b3a21a2bc5b59405f.mp3", "hash": "496653341a3b7fa0f81ed7053d94b21df5e1d9e106b22c49c4ec1db64f3eb62d", "bytes": 59904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c07f5683535efaeb1ef98b337dc7cae7ea5b1447a48ebb4b3a21a2bc5b59405f.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "El plan de Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-scene", "xp": 0, "type": "story_scene", "title": "El plan de Liruf", "payload": {"art": {"icon": "lightbulb", "tint": "accent", "image_url": "http://localhost:4006/files/lesson-images/4b40c43d6eb57627c9d327434aadc89d402e0b4d213c0be74186f9334610e7da.webp"}, "body_md": "Después de hablar con Dina, Liruf tiene una idea brillante. 🍋 Dibuja su plan en una cartulina: cada vaso de limonada cuesta 5 pesos, y con cada venta se acerca más a su guitarra de 80 pesos. ¡Si vende vasos y más vasos, la guitarra será suya!", "emotion": "excited", "backdrop": "base", "character": "liruf"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Mira el plan de Liruf.", "difficulty": 1, "audio_segment_id": "s1-scene.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-scene.body": {"url": "http://localhost:4006/files/lesson-audio/be1e75bb5482a65ca2f327ab38d8a3f9c5ccd328d96ac58d30f71609d4b68591.mp3", "hash": "89e8bb5792ca3188b63f6fca19abdc364316a3c103ca098cbc0d222598f61870", "bytes": 101088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/be1e75bb5482a65ca2f327ab38d8a3f9c5ccd328d96ac58d30f71609d4b68591.mp3", "duration_ms": 16800}, "s1-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/1b9a566e765677a8ba222e7f13cf987e428b2f95f99ac0b39a91f7d5cc4b8767.mp3", "hash": "81301b3f445fc7507b3bfe8f6d9a75372537ac3b20e35e384ecd419446834f01", "bytes": 9936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1b9a566e765677a8ba222e7f13cf987e428b2f95f99ac0b39a91f7d5cc4b8767.mp3", "duration_ms": 1600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "key-ideas", "title": "Las reglas de oro del vendedor", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar los tres pasos básicos para ganar dinero: tener una meta, ofrecer un producto deseado y ahorrar lo ganado."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "title": "Las reglas de oro", "payload": {"ideas": [{"icon": "target", "title": "Una meta clara", "body_md": "Liruf quiere su guitarra de **80 pesos**. Una meta te dice a dónde vas.", "image_url": "http://localhost:4006/files/lesson-images/b850b0cd9eb9ae139df94402fad86c36d3bba9fee2d9b3d0c9ee9411f5913dfd.webp"}, {"icon": "storefront", "title": "Algo que la gente quiere", "body_md": "¡Limonada fría! En un día caluroso, todos quieren un vaso. Ella vende cada uno a **5 pesos**.", "image_url": "http://localhost:4006/files/lesson-images/cfaa4357cd46c80b6bc586f110f9ec924b2ef694151d2a3b6507fc6bf2e853d8.webp"}, {"icon": "savings", "title": "Guardar lo ganado", "body_md": "Cada venta la acerca a su sueño. Guarda cada moneda para la guitarra.", "image_url": "http://localhost:4006/files/lesson-images/fb43ba9343458d523575015c7c7168d6c9bc0b9180c3084a63066c92a3713d7a.webp"}]}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Las 3 reglas de oro de Liruf para ganar dinero.", "difficulty": 1, "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/2bb2ae42afabf9439d2542fca01386de0d317a6ce3e3ba2d451966175cbc3622.mp3", "hash": "16d3a97c97bfdbf0d89712429b74a5df53f324b57f42d01414f4276530c7e336", "bytes": 30528, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2bb2ae42afabf9439d2542fca01386de0d317a6ce3e3ba2d451966175cbc3622.mp3", "duration_ms": 5040}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/571c145e58321f5c3887adcfc8a18d6bf7e66faebbe3c4326f2974c4c638c3ae.mp3", "hash": "90408562b3062c4ad863da578d9e8d605e592b5559cf68a8bb9c092f8514db3a", "bytes": 44064, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/571c145e58321f5c3887adcfc8a18d6bf7e66faebbe3c4326f2974c4c638c3ae.mp3", "duration_ms": 7280}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/4d0d031275b4ed028ec2ff7b1215712ac8f308576eea781b7b8b2fdbbcfcc0ed.mp3", "hash": "691bfc40187f2f092413ee619ed237ead91e98c83c0e0fb37a3e9f945f14e8bf", "bytes": 36288, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/4d0d031275b4ed028ec2ff7b1215712ac8f308576eea781b7b8b2fdbbcfcc0ed.mp3", "duration_ms": 6000}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/249601ec6a21b628e22810737d0d983ca9776a61173a60bf69f25301e020d76b.mp3", "hash": "2a5d57107ac3c995ffc505775ec7f3f8084f278868278cc8c8a82e683fb4e848", "bytes": 22464, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/249601ec6a21b628e22810737d0d983ca9776a61173a60bf69f25301e020d76b.mp3", "duration_ms": 3680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "key-ideas", "title": "As regras de ouro do vendedor", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar os três passos básicos para ganhar dinheiro: ter uma meta, oferecer um produto desejado e poupar o ganho."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "title": "As regras de ouro", "payload": {"ideas": [{"icon": "target", "title": "Uma meta clara", "body_md": "Liruf quer sua guitarra de **80 reais**. Uma meta te diz aonde você vai.", "image_url": "http://localhost:4006/files/lesson-images/b850b0cd9eb9ae139df94402fad86c36d3bba9fee2d9b3d0c9ee9411f5913dfd.webp"}, {"icon": "storefront", "title": "Algo que as pessoas querem", "body_md": "Limonada gelada! Em um dia quente, todos querem um copo. Ela vende cada um por **5 reais**.", "image_url": "http://localhost:4006/files/lesson-images/cfaa4357cd46c80b6bc586f110f9ec924b2ef694151d2a3b6507fc6bf2e853d8.webp"}, {"icon": "savings", "title": "Guardar o ganho", "body_md": "Cada venda a aproxima de seu sonho. Guarda cada moeda para a guitarra.", "image_url": "http://localhost:4006/files/lesson-images/fb43ba9343458d523575015c7c7168d6c9bc0b9180c3084a63066c92a3713d7a.webp"}]}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "As 3 regras de ouro de Liruf para ganhar dinheiro.", "difficulty": 1, "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/57484daa21decd76ff68a624c56f0a53325b2100d62d29614793288f6c22f84b.mp3", "hash": "51e8c7ae09bd931aad7966f840818f8918ffc82d3135de0a94abcab68baa233a", "bytes": 38736, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/57484daa21decd76ff68a624c56f0a53325b2100d62d29614793288f6c22f84b.mp3", "duration_ms": 6400}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/e57c03696b50a9b59c3f9e94aa10a3935c30e59adc0456c6c4dcf3cd1724ef2e.mp3", "hash": "27927393f57c48ed2af477e36e2aaf858fba55241630fc6fe23a51fc2bad4a90", "bytes": 46368, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e57c03696b50a9b59c3f9e94aa10a3935c30e59adc0456c6c4dcf3cd1724ef2e.mp3", "duration_ms": 7680}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/eba114f3d700d5402c00a8084c54aaf5ea1dd5719e0b8099ed2ceada88046000.mp3", "hash": "a946b7fa94b91ef71c3cbe21dbae1c900a71e7ac304ffb8f0c52f3da82a0858f", "bytes": 31104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/eba114f3d700d5402c00a8084c54aaf5ea1dd5719e0b8099ed2ceada88046000.mp3", "duration_ms": 5120}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/52245acb975a8c91f107a32b5b8e4fbe3474225a832b286ce270c8565231c314.mp3", "hash": "38687f9afe8e56710495c9cd7e5f4ed4bd56134cae996b2fac14ad100badd837", "bytes": 21024, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/52245acb975a8c91f107a32b5b8e4fbe3474225a832b286ce270c8565231c314.mp3", "duration_ms": 3440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Is the trade fair?", "locale": "en-US", "subject": "money", "objectives": ["Decide if a barter is fair by comparing the value of what is given and what is received."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "ft-1", "xp": 5, "type": "fair_trade", "title": "Barter with the fruit vendor", "payload": {"offer_a": {"qty": 1, "icon": "local_cafe", "label": "2 cups of lemonade", "image_url": "http://localhost:4006/files/lesson-images/36e3d03a16fb176bd4e532f60bbb2bd74aaa6f024e844d5bbdd26884d1602d0e.webp"}, "offer_b": {"qty": 1, "icon": "agriculture", "label": "Bag of lemons", "image_url": "http://localhost:4006/files/lesson-images/2e985967622df9696797874a56c247c209e105aa3521231488d5613d0491be28.webp"}, "rate_md": "1 bag of lemons = 10 dollars"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf sells cups of lemonade for 5 dollars. The fruit vendor offers: 2 cups for a bag of lemons worth 10 dollars. Is the trade fair?", "difficulty": 1, "explanation_md": "The 2 cups of lemonade are worth 10 dollars, exactly what the bag of lemons costs! It''s a fair trade.", "audio_segment_id": "ft-1.prompt"}], "schema_version": 1}', '{"ft-1": {"verdict": "fair"}}', '{"units": {"ft-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/84f1513efb1dc9e497b5c8d1669b6a631bc3293b361ad75f25fc20b6f8490a72.mp3", "hash": "c6ed2c13046e8979cae71ad331033f84561e655e62ed8950d45fb6913543ea29", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/84f1513efb1dc9e497b5c8d1669b6a631bc3293b361ad75f25fc20b6f8490a72.mp3", "duration_ms": 7920}, "ft-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/6d11dfd8442893c48410eebf0b0dcb8673a69b3b5eb3884e2f08a2d706fdcecf.mp3", "hash": "9af68fa0369fdd53ca2a39ca39d074d93805a2a99746240e433c109ebc23f8c6", "bytes": 34416, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6d11dfd8442893c48410eebf0b0dcb8673a69b3b5eb3884e2f08a2d706fdcecf.mp3", "duration_ms": 5680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "coin-count", "title": "Contando monedas para Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Contar monedas de 1 y 2 pesos para formar 5 pesos exactos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "coin-count-1", "xp": 10, "type": "coin_count", "hints": ["Puedes combinar monedas de 1 y 2 pesos hasta llegar a 5."], "title": "¡A contar monedas!", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/39d8853ecca3654b562f001ec0a643790e936fb5734778b4d10e0dd0313ec9dc.webp", "prompt_md": "Un cliente pagó con monedas de 1 y 2 pesos. Junta las monedas para formar exactamente 5 pesos.", "difficulty": 1, "explanation_md": "El vaso cuesta 5 pesos. Con monedas de 1 y 2, una forma de juntarlos es 2+2+1 o 1+1+1+1+1. ¡Tú decides cómo!", "audio_segment_id": "coin-count-1.prompt"}], "schema_version": 1}', '{"coin-count-1": {}}', '{"units": {"coin-count-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f102f38b4daeac5de9449431179198e752272ffc9cae7b083fa54bfd9ea050fb.mp3", "hash": "6bc2ffa4c2e613d9b87309fabf6eaf7234fdac5206b27598d6ed8f9432af43e2", "bytes": 25344, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f102f38b4daeac5de9449431179198e752272ffc9cae7b083fa54bfd9ea050fb.mp3", "duration_ms": 4160}, "coin-count-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/a171c5629e9a19e3a13cfafa8a3a7148db1e87383bd09d188fda326f4f5cb3f0.mp3", "hash": "5a35ea11e0df3b215d56dbbd78760d72c3dc28cf34d3e262c96b4d87a73fc4e0", "bytes": 44496, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a171c5629e9a19e3a13cfafa8a3a7148db1e87383bd09d188fda326f4f5cb3f0.mp3", "duration_ms": 7360}, "coin-count-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/65f280733f69a6c81b18ebfc139a5e65d7f999f6318b64ca16c706059e12ca97.mp3", "hash": "55b4de2e02ed9bd5e8029fd2c27d973ce8a8da6bc78a0b9272d1eef7a07ed712", "bytes": 67968, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/65f280733f69a6c81b18ebfc139a5e65d7f999f6318b64ca16c706059e12ca97.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Group the money: coins and bills", "locale": "en-US", "subject": "mixed", "objectives": ["Sort steps, match products with prices, and classify purchases by priority", "Group coins and bills to make counting easier"], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 8, "type": "group_sets", "title": "Group coins and bills", "payload": {"items": [{"id": "item-1", "icon": "savings", "text_md": "10-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/154671db494e6a0bffef7f2a0ec8b9a7a7aef3877d29458dcd61d6057eb2bb32.webp"}, {"id": "item-2", "icon": "payments", "text_md": "50-dollar bill"}, {"id": "item-3", "icon": "savings", "text_md": "5-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/b0def457698d901cba8a5c76ffeb99a3305cca1d7abbdab383d2cc6749e5c4f8.webp"}, {"id": "item-4", "icon": "payments", "text_md": "20-dollar bill", "image_url": "http://localhost:4006/files/lesson-images/fec591f6177becb8e49d2cf802ce1b9ba9cdec6e791ad7988dd9c38eeef9409e.webp"}, {"id": "item-5", "icon": "savings", "text_md": "2-dollar coin", "image_url": "http://localhost:4006/files/lesson-images/15437f98aaea4301f8544412a09005610d1f80f9fd4ac4a704dc8b23deaa916d.webp"}, {"id": "item-6", "icon": "payments", "text_md": "100-dollar bill", "image_url": "http://localhost:4006/files/lesson-images/474ba981e7b9e541494210079df1da02ada62506be38a240efbf358ef9c913e0.webp"}], "set_a": "Coins", "set_b": "Bills"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "At the end of the day, Liruf''s cash register is a mess. Group coins with coins and bills with bills.", "difficulty": 1, "explanation_md": "Grouping coins with coins and bills with bills makes counting money easier. Liruf can now see how much they collected in coins and how much in bills.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"item-1": "a", "item-2": "b", "item-3": "a", "item-4": "b", "item-5": "a", "item-6": "b"}}}', '{"units": {"s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/12cc28eaf8f2a8d5d3e392edba42f45b1481bfdf1dd4528f1dbb23c44ea76768.mp3", "hash": "6bd82b387832da593b508f94b16c4ac81656b60b457849420517cde89ab5cc92", "bytes": 36864, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/12cc28eaf8f2a8d5d3e392edba42f45b1481bfdf1dd4528f1dbb23c44ea76768.mp3", "duration_ms": 6080}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7200845f067db9379a443583991f4f1dd4581a85a574baa045011924bcd11f7.mp3", "hash": "dcc4fa36969eac247b5c3fb311680be12cb15c103e6f2efe1c8a431d3c63de85", "bytes": 49248, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c7200845f067db9379a443583991f4f1dd4581a85a574baa045011924bcd11f7.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "El combo del dinero", "locale": "es-MX", "subject": "mixed", "objectives": ["Practicar contar monedas, dar cambio y planear ahorro para una meta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 5, "type": "coin_count", "hints": [], "title": "Cierre de caja", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/01cbd3a29d5ef2658b5ab7094bb51c960825465bd5125bd779b8c2d5a68b8731.webp", "prompt_md": "Cuenta las monedas que dejaron los clientes. ¿Cuánto juntó Liruf hoy?", "difficulty": 1, "explanation_md": "Hoy entraron 20 pesos. Dos monedas de 10 los suman rapidísimo. 💰", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 10, "type": "make_change", "hints": ["Resta el precio al billete: 20 menos 5."], "title": "Cambio para la clienta", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/64c8e964a1a3ef5ba6929adad07a1b48e0269d1a3915432224bc7a849faa8388.webp", "prompt_md": "La clienta pagó 5 pesos con billete de 20. Dale su cambio.", "difficulty": 2, "explanation_md": "El cambio exacto son 15 pesos. Con 10 y 5, o tres de 5, o cualquier combinación que dé 15. ✅", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 10, "type": "savings_goal", "hints": [], "title": "Domingos para la guitarra", "payload": {"goal": 40, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf necesita 40 pesos más. Ahorra 20 cada domingo. ¿Cuántos domingos?", "difficulty": 2, "explanation_md": "A 20 por domingo, en 2 domingos junta 40, justo el resto de la guitarra. ¡Ánimo, Liruf! 🎉", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/c9a941e2ec590e09f58b65d5cbab06bd0375ab2871a7d6fe4c3743396e859898.mp3", "hash": "e39a7a4a6c81f7d252b4640e55da06cae443b4bb17a2cebcc11ed92c2a322fe3", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c9a941e2ec590e09f58b65d5cbab06bd0375ab2871a7d6fe4c3743396e859898.mp3", "duration_ms": 5840}, "s2-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d08e55ebd92ca342ce54a68ebdf5e24b109dc81a2c043cfd88865676e64b6d6b.mp3", "hash": "864b817e59793cddc93c97f372a4b0171006965a7863bb81b84afc18e8b4e6e3", "bytes": 19584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d08e55ebd92ca342ce54a68ebdf5e24b109dc81a2c043cfd88865676e64b6d6b.mp3", "duration_ms": 3200}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/33f510cf5c5389ca0f1728dcf455ebdfc9d9117710614f9330819e50742dcfc4.mp3", "hash": "658f83ab23e94e06a5a80b5c2f1bbcc2d742d0ab728c53c346b78e3c9e8d492c", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/33f510cf5c5389ca0f1728dcf455ebdfc9d9117710614f9330819e50742dcfc4.mp3", "duration_ms": 5120}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/60f6f352e6746212f72a370a190702914b1adbc6a76496e463152c4037a11196.mp3", "hash": "d656297119c7617f08217263ba44d68d3891ea6a2fe4378d382c077a1b7dfb92", "bytes": 39168, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/60f6f352e6746212f72a370a190702914b1adbc6a76496e463152c4037a11196.mp3", "duration_ms": 6480}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/3c9bb5d8ca36c090732e29497981c66a60ae62e228b31326c9702222a2bab43b.mp3", "hash": "67a93e76dd993f6a9a49dd1c11332750b5cfa33428479e2688e6e506a04438ad", "bytes": 32976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3c9bb5d8ca36c090732e29497981c66a60ae62e228b31326c9702222a2bab43b.mp3", "duration_ms": 5440}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/dfc04d67bc36e09a1f5a5b7173ca5efad6034ae42ba66033d49f4a24247bedda.mp3", "hash": "621d8316b88b37e9e50d60bddad7596a4586a7887dba58321450ab3a9d8f4437", "bytes": 45504, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dfc04d67bc36e09a1f5a5b7173ca5efad6034ae42ba66033d49f4a24247bedda.mp3", "duration_ms": 7520}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/c9805fa7a3375afb1994924838007baa6cce8d8b8714ae8229ab40ecbf32fa26.mp3", "hash": "9b991795e60f7ecc7ca2cb58d27f8f6f03ccaf6688eb75fa443f31fb77c1c189", "bytes": 43488, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c9805fa7a3375afb1994924838007baa6cce8d8b8714ae8229ab40ecbf32fa26.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Agrupe o dinheiro: moedas e notas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar etapas, combinar produtos com preços e classificar compras por prioridade", "Agrupar moedas e notas para facilitar a contagem"], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 8, "type": "group_sets", "title": "Agrupe moedas e notas", "payload": {"items": [{"id": "item-1", "icon": "savings", "text_md": "Moeda de 10 reais", "image_url": "http://localhost:4006/files/lesson-images/154671db494e6a0bffef7f2a0ec8b9a7a7aef3877d29458dcd61d6057eb2bb32.webp"}, {"id": "item-2", "icon": "payments", "text_md": "Nota de 50 reais"}, {"id": "item-3", "icon": "savings", "text_md": "Moeda de 5 reais", "image_url": "http://localhost:4006/files/lesson-images/b0def457698d901cba8a5c76ffeb99a3305cca1d7abbdab383d2cc6749e5c4f8.webp"}, {"id": "item-4", "icon": "payments", "text_md": "Nota de 20 reais", "image_url": "http://localhost:4006/files/lesson-images/fec591f6177becb8e49d2cf802ce1b9ba9cdec6e791ad7988dd9c38eeef9409e.webp"}, {"id": "item-5", "icon": "savings", "text_md": "Moeda de 2 reais", "image_url": "http://localhost:4006/files/lesson-images/15437f98aaea4301f8544412a09005610d1f80f9fd4ac4a704dc8b23deaa916d.webp"}, {"id": "item-6", "icon": "payments", "text_md": "Nota de 100 reais", "image_url": "http://localhost:4006/files/lesson-images/474ba981e7b9e541494210079df1da02ada62506be38a240efbf358ef9c913e0.webp"}], "set_a": "Moedas", "set_b": "Notas"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "No final do dia, a caixa de Liruf está bagunçada. Agrupe moedas com moedas e notas com notas.", "difficulty": 1, "explanation_md": "Agrupar moedas com moedas e notas com notas torna mais fácil contar o dinheiro. Liruf agora pode ver quanto juntou em moedas e quanto em notas.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"item-1": "a", "item-2": "b", "item-3": "a", "item-4": "b", "item-5": "a", "item-6": "b"}}}', '{"units": {"s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/79a7ce667430c9d8ab65e1f1836a78fcaca4dafbc3abaab7c4098b595c01cc38.mp3", "hash": "c42611ded897e2fab57db62403360c317d4cd62cb5c921ff77d2ee0c32048538", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/79a7ce667430c9d8ab65e1f1836a78fcaca4dafbc3abaab7c4098b595c01cc38.mp3", "duration_ms": 7040}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/916e508afcd9a7060abecae356681e57e849f386617bc42466cc85406ebb0f98.mp3", "hash": "8b1c73b9c3996cce9ecdc4003f63a884d05e79a6692b3dc524111115f6d17a94", "bytes": 64656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/916e508afcd9a7060abecae356681e57e849f386617bc42466cc85406ebb0f98.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "cause-effect", "title": "Causa y efecto en el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Conectar eventos para entender cómo el clima afecta las ventas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 5, "type": "cause_effect", "hints": ["Piensa en el orden: ¿qué pasa primero? ¿Qué pasa después? ¿Cuál es el resultado?"], "title": "¿Qué pasó primero?", "payload": {"slots": 3, "events": [{"id": "sol", "text_md": "El día está soleado y hace calor"}, {"id": "sed", "text_md": "La gente tiene más sed"}, {"id": "ventas", "text_md": "Liruf vende más vasos de limonada"}, {"id": "precio", "text_md": "Liruf sube el precio a 10 pesos cada vaso"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ordena los eventos para mostrar cómo un día soleado afecta las ventas de Liruf.", "difficulty": 1, "explanation_md": "Cuando hace calor, la gente tiene más sed y busca bebidas frescas. Por eso Liruf vendió más limonada. ¡Qué padre! Un día soleado puede ser un buen día de ventas.", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["sol", "sed", "ventas"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/afbcc15f710b747426eaa2faaa61939755d63ef40471e8c95d72480d2b318818.mp3", "hash": "05da3c93ef1db229824ff0186bbce73ae4888d3694c819734831bae19362cda1", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/afbcc15f710b747426eaa2faaa61939755d63ef40471e8c95d72480d2b318818.mp3", "duration_ms": 5600}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/897880e8e12cf6f92a57ed3cfac934147344c76b65b240438fd25dcf35d10223.mp3", "hash": "7f9a2ea186c19a64544ec21a7c74e63a01b1ea80c1517d498e81240dda9d002d", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/897880e8e12cf6f92a57ed3cfac934147344c76b65b240438fd25dcf35d10223.mp3", "duration_ms": 5360}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d37afa1c2dff3f7579c38f1d527317e6153d584ca8842947560a3cb74c5bae6.mp3", "hash": "0934ee70d520c199a88ebd1d657db75a3a892044e41581eb8eb9b8195398b884", "bytes": 68544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0d37afa1c2dff3f7579c38f1d527317e6153d584ca8842947560a3cb74c5bae6.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "O combo do dinheiro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Praticar contar moedas, dar troco e planejar poupança para uma meta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 5, "type": "coin_count", "hints": [], "title": "Fechamento de caixa", "payload": {"target": 20, "currency": "BRL", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/01cbd3a29d5ef2658b5ab7094bb51c960825465bd5125bd779b8c2d5a68b8731.webp", "prompt_md": "Conte as moedas que os clientes deixaram. Quanto Liruf juntou hoje?", "difficulty": 1, "explanation_md": "Hoje entraram 20 reais. Duas moedas de 10 somam rapidinho. 💰", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 10, "type": "make_change", "hints": ["Subtraia o preço da nota: 20 menos 5."], "title": "Troco para a cliente", "payload": {"price": 5, "currency": "BRL", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/64c8e964a1a3ef5ba6929adad07a1b48e0269d1a3915432224bc7a849faa8388.webp", "prompt_md": "A cliente pagou 5 reais com nota de 20. Dê o troco para ela.", "difficulty": 2, "explanation_md": "O troco exato são 15 reais. Com 10 e 5, ou três de 5, ou qualquer combinação que dê 15. ✅", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 10, "type": "savings_goal", "hints": [], "title": "Domingos para o violão", "payload": {"goal": 40, "currency": "BRL", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf precisa de mais 40 reais. Economiza 20 a cada domingo. Quantos domingos?", "difficulty": 2, "explanation_md": "A 20 por domingo, em 2 domingos junta 40, exatamente o resto do violão. Vamos lá, Liruf! 🎉", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/d2ad5b9674a767d93bb9b07ade128e1b4b6ab332b1fa6b475dcff612d19d0f27.mp3", "hash": "166820076d133d88d83731de7da9276ea6f26d6a7bc0c541c7951bdedd698bf2", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d2ad5b9674a767d93bb9b07ade128e1b4b6ab332b1fa6b475dcff612d19d0f27.mp3", "duration_ms": 4880}, "s2-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8f30ee557803a0eac433e98717dee1325ed7f6817e60e443c1af4068db881ff0.mp3", "hash": "04aee37b47d88ba01746df2ed7238e8dd3aa96e04c33d3790120cf7f08a876e1", "bytes": 22896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8f30ee557803a0eac433e98717dee1325ed7f6817e60e443c1af4068db881ff0.mp3", "duration_ms": 3760}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/5de66606b3e031b124dd89d94f38605bc8fd7f87c8393dd5f656e512d0211a6c.mp3", "hash": "85303e3104bc829796b97a47875d19775b50a328f9c0d1c3e670b0bee10af39c", "bytes": 30528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5de66606b3e031b124dd89d94f38605bc8fd7f87c8393dd5f656e512d0211a6c.mp3", "duration_ms": 5040}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/a6aa7801b7870e6e1734dfc768ca9c806e9bf24dc144edfa7729c47809cf343c.mp3", "hash": "c8c6a56838e568083629f2e2e3dc803e45782c527b6b6f6296d0ad90b9c9b451", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a6aa7801b7870e6e1734dfc768ca9c806e9bf24dc144edfa7729c47809cf343c.mp3", "duration_ms": 6720}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/c64f6cbdbd35c5927f8ebf03b4e3314e38aaa3dfde463242cad896b4553d739a.mp3", "hash": "5f649501f7ff0157629538b184a8be1f99c7f47c60c463572a4ca624166dc2b1", "bytes": 32544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c64f6cbdbd35c5927f8ebf03b4e3314e38aaa3dfde463242cad896b4553d739a.mp3", "duration_ms": 5360}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/af002e97b5f8d2ea94f301236c1e5071876624f114e0f9ba4ddb93d01c06d43f.mp3", "hash": "683659b523f159b54a1e630f0c0df9a01b1313ca42565a289ce4e89d4009f285", "bytes": 49824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/af002e97b5f8d2ea94f301236c1e5071876624f114e0f9ba4ddb93d01c06d43f.mp3", "duration_ms": 8240}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/509a5281aed3d33ad22d8b7c276216365a7acbf59b77914e48b251de9856f8e8.mp3", "hash": "ef2d58a9429dc5ed54077c1b485aed1146ae01d9c81a16257d537ddbc2375dc6", "bytes": 45504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/509a5281aed3d33ad22d8b7c276216365a7acbf59b77914e48b251de9856f8e8.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "piggy-split", "title": "Divida o lucro para atingir a meta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar dinheiro com moedas de 1, 2, 5 e 10, calcular o troco de uma nota de 20, e planejar quantas semanas faltam para a meta.", "Dividir 10 reais de lucro entre os dois cofrinhos: uma parte para a meta do violão e outra para repor ingredientes."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["Quanto custa repor os ingredientes? O que sobrar você pode poupar para o violão."], "title": "Divida o lucro", "payload": {"jars": [{"id": "jar-guitarra", "icon": "savings", "label": "Cofrinho do violão", "hint_md": "Cada real poupado aqui te aproxima da meta de 80 reais.", "image_url": "http://localhost:4006/files/lesson-images/53bd564c088bd2b4e23cf8694d92d4fa85d0c99e75d6166e0a68eccee74a48da.webp"}, {"id": "jar-ingredientes", "icon": "shopping_cart", "label": "Gastos da barraquinha", "hint_md": "Os ingredientes custam 4 reais. Coloque essa quantia aqui para continuar vendendo.", "image_url": "http://localhost:4006/files/lesson-images/41a08178de9e5324fb797a97ac359c1084c0748e7fe848aaa44a3b9b19cddba5.webp"}], "step": 1, "unit": "BRL", "income": 10}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Os ingredientes custam 4 reais. Coloque a quantia certa em cada cofrinho para repor e poupar para o violão de 80 reais.", "difficulty": 2, "explanation_md": "Ao dividir o lucro, primeiro você cobre os gastos da barraquinha (4 reais) e o restante vai para o cofrinho do violão (6 reais). Assim você avança em direção à meta de 80 reais.", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"jar-guitarra": {"max": 6, "min": 6}, "jar-ingredientes": {"max": 4, "min": 4}}, "rationale_md": "Pusiste 4 pesos para ingredientes y 6 para la guitarra. Así el puesto sigue funcionando y avanzas 6 pesos hacia la guitarra de 80. ¡Buen plan!"}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/66e8e2c89a8b845ef18990421ae95e9c2080512a1da094d53d532a2232f03cf1.mp3", "hash": "ed45e542d1c303bc67b80589a981e57e7ca5f9240f2eb5c19a34b5b6cc6ace35", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/66e8e2c89a8b845ef18990421ae95e9c2080512a1da094d53d532a2232f03cf1.mp3", "duration_ms": 5440}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ca3b4d0da8cd81a6de9690d3415fbfc623535b8619999f7ddf6922a4966be08.mp3", "hash": "01f8e8718bfcef5595819efc10737d933b1cf483d4fd2b315006fff6d6ce84ba", "bytes": 58464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5ca3b4d0da8cd81a6de9690d3415fbfc623535b8619999f7ddf6922a4966be08.mp3", "duration_ms": 9680}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/5aab2a60f71b458db02493869696268fb2d632e9e442b787873ff0c9981d5fd6.mp3", "hash": "850ffb36824fb9320a94ce830c58e59c411cb3a68a5dbb391abea6469f94e908", "bytes": 78624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5aab2a60f71b458db02493869696268fb2d632e9e442b787873ff0c9981d5fd6.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparando proveedores", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer y comparar precios y cantidades en una tabla para elegir la mejor opción de compra."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 5, "type": "compare_table", "hints": ["Fíjate en cuál proveedor vende los limones más baratos."], "title": "Tabla de proveedores", "payload": {"cols": [{"id": "precio", "label": "Precio"}, {"id": "cantidad", "label": "Cantidad"}, {"id": "mejor-opcion", "label": "Mejor opción"}], "rows": [{"id": "donia-lula", "label": "Doña Lula"}, {"id": "don-pepe", "label": "Don Pepe"}], "tokens": [{"id": "t1", "text_md": "5 pesos"}, {"id": "t4", "text_md": "10 limones"}, {"id": "t2", "text_md": "12 limones"}, {"id": "t3", "text_md": "6 pesos"}, {"id": "t5", "text_md": "Doña Lula"}, {"id": "t6", "text_md": "Don Pepe"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/40cbfa7b95b10b885675502cc827869da5057251fe86cacc07e877cb073286bd.webp", "prompt_md": "Doña Lula vende 12 limones por 5 pesos. Don Pepe vende 10 limones por 6 pesos. Llena la tabla y elige la mejor opción.", "difficulty": 1, "explanation_md": "Doña Lula vende 12 limones por 5 pesos, mientras que Don Pepe vende solo 10 por 6 pesos. ¡Más limones y más barato! 🍋", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"don-pepe:precio": "t3", "don-pepe:cantidad": "t4", "donia-lula:precio": "t1", "donia-lula:cantidad": "t2", "donia-lula:mejor-opcion": "t5"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7f9738739de8f1301d7616d51bcd9f1a667e491581c2c59d94fd75c32b3d7f15.mp3", "hash": "feca59801dd9988d4d5fe5c7aea5d593d98227b7fef7cb3f27a56482d60723ff", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7f9738739de8f1301d7616d51bcd9f1a667e491581c2c59d94fd75c32b3d7f15.mp3", "duration_ms": 3920}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/1a14140ca8b75faeacba42244d34c5d329cb27b338082ef49b4285a4351bec03.mp3", "hash": "ed65b7ad59a440206061a41346e919b779d53da1b702d15eb9da93cf7265f70e", "bytes": 52128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1a14140ca8b75faeacba42244d34c5d329cb27b338082ef49b4285a4351bec03.mp3", "duration_ms": 8640}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/fb6e4db353f4a8e8f36eaa61ff9c90a664b1ce8adcb8db6b186763bfcbf3ac95.mp3", "hash": "ec4abc666de552480770d54f81cccf7fc03ef827866e7786da2b9068055e9c4f", "bytes": 54576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fb6e4db353f4a8e8f36eaa61ff9c90a664b1ce8adcb8db6b186763bfcbf3ac95.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "cause-effect", "title": "Cause and effect at the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Connect events to understand how the weather affects sales."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 5, "type": "cause_effect", "hints": ["Think about the order: what happens first? What happens next? What is the result?"], "title": "What happened first?", "payload": {"slots": 3, "events": [{"id": "sol", "text_md": "The day is sunny and hot"}, {"id": "sed", "text_md": "People are thirstier"}, {"id": "ventas", "text_md": "Liruf sells more cups of lemonade"}, {"id": "precio", "text_md": "Liruf raises the price to 10 dollars per cup"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Order the events to show how a sunny day affects Liruf''s sales.", "difficulty": 1, "explanation_md": "When it''s hot, people are thirstier and look for cool drinks. That''s why Liruf sold more lemonade. Awesome! A sunny day can be a great sales day.", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["sol", "sed", "ventas"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9bc7b7f3bdbad1e1db3fd7faa27df084e7ffa47918047026c15c149f577581bb.mp3", "hash": "aa37d645f9b1d6986710b9dfa79755fa9c92d8752bc2c1da36ea035997c49a0a", "bytes": 30528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9bc7b7f3bdbad1e1db3fd7faa27df084e7ffa47918047026c15c149f577581bb.mp3", "duration_ms": 5040}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/83a898d73d0ffdd0fad30c3ab4da28b03e638847e29e1d15ec212a202f097825.mp3", "hash": "aa46a0d0ead769f862c7fdfc667db9103bc62865ae767a2dc9599e947c6a0e43", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/83a898d73d0ffdd0fad30c3ab4da28b03e638847e29e1d15ec212a202f097825.mp3", "duration_ms": 3200}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/574f48b8b37946fc139f4a6b04ba51fcb65681a15a4aeade0ee60a60f5f62bfc.mp3", "hash": "d4f202a027629b42c2976e011a8d5451bd4dd979ac109374d4e4232d849da309", "bytes": 49824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/574f48b8b37946fc139f4a6b04ba51fcb65681a15a4aeade0ee60a60f5f62bfc.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escribe la respuesta numérica", "locale": "es-MX", "subject": "mixed", "objectives": ["Escribir respuestas numéricas exactas sobre el ahorro."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-answer", "xp": 5, "type": "type_answer", "title": "¿Cuánto ahorras?", "payload": {"max_chars": 5, "placeholder": "Escribe el número"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Vender 2 vasos da 10 pesos. Rho ahorra 15 pesos hoy y 10 mañana. ¿Total ahorrado?", "difficulty": 1, "explanation_md": "15 + 10 = 25. Ese dinero que guardas para después se llama ''ahorro''. ¡Ya tienes 25 pesos ahorrados para tu meta!", "audio_segment_id": "s1-type-answer.prompt"}], "schema_version": 1}', '{"s1-type-answer": {"accept": ["25"], "keywords": ["25", "veinticinco"], "case_sensitive": false}}', '{"units": {"s1-type-answer.prompt": {"url": "http://localhost:4006/files/lesson-audio/8a3c418f6dbf2c636bd6fca576e64ee95a74a1feeecc688a0dfbcbdb2d3b8968.mp3", "hash": "ea783cd15060cb667b29e27e01e4beda180829de1b9f9974ce996fe07f21e125", "bytes": 43056, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8a3c418f6dbf2c636bd6fca576e64ee95a74a1feeecc688a0dfbcbdb2d3b8968.mp3", "duration_ms": 7120}, "s1-type-answer.explanation": {"url": "http://localhost:4006/files/lesson-audio/3ced62352a2a3fa2e32ec3187159defbf4e9cf3e9fc87b2f1384e1b64fac0da9.mp3", "hash": "e6cd15e990012c69ba42b492674dd523ce99acd105fbd28ab5c6b1c3912e5a71", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3ced62352a2a3fa2e32ec3187159defbf4e9cf3e9fc87b2f1384e1b64fac0da9.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "odd-one-out", "title": "O que sobra", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar qual NÃO é um ingrediente da limonada (limões, açúcar, água... e uma bola?): separar o que realmente custa dinheiro produzir."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Pense no que você precisa para fazer limonada: limões, açúcar e água. Qual sobra?"], "title": "O que sobra", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/cdf4e1fb2d740d9b9f24ce284dbdccac17fe3dea62e7d624535c15b94fdbf951.webp"}, {"id": "azucar", "icon": "coffee", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/1f3d4feb4d5a87ceba75a236aebbb54959e98f39ec7f8285d0d0a2f3ae418fe5.webp"}, {"id": "agua", "icon": "water_drop", "text_md": "Água", "image_url": "http://localhost:4006/files/lesson-images/bd6a7dfc88fd007c7d8b8fdef228bd895a2ac60a311b5f7344094833df979be5.webp"}, {"id": "pelota", "icon": "toys", "text_md": "Bola", "image_url": "http://localhost:4006/files/lesson-images/3e0c38763c34a64542d91e25aac80e5c4d625d4507d53e4d4f2a2986867bd2c0.webp"}], "reasons": [{"id": "razon-1", "text_md": "Não é um ingrediente da limonada."}, {"id": "razon-2", "text_md": "É a única que se usa para brincar."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Aponte qual NÃO é um ingrediente da limonada. Depois escolha o motivo.", "difficulty": 1, "explanation_md": "A bola não é um ingrediente da limonada. É para brincar, não para cozinhar, por isso não pertence à lista de compras do Rho.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "razon-1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/924c2c9828072df0abb0da1898de91cde0eba8ee2188c7c7329e7ba9a4dabe56.mp3", "hash": "344d1fc581998d4ed9e2d7b45b5336c4b35e9794e203235fc637b0b0f8e842f0", "bytes": 43488, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/924c2c9828072df0abb0da1898de91cde0eba8ee2188c7c7329e7ba9a4dabe56.mp3", "duration_ms": 7200}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/7373f6fcb480c37878b64a7f747968c632b457e59266e2bf1104fccdb3f32dc2.mp3", "hash": "dca26987934bbeb7f5b3c389617a6f0b01c3027a1b087d3594ed32d74511f512", "bytes": 33408, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/7373f6fcb480c37878b64a7f747968c632b457e59266e2bf1104fccdb3f32dc2.mp3", "duration_ms": 5520}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/d0d75fe56854a6cddbe56bf349533153536b7556b8309148755d7da073b633b9.mp3", "hash": "b5ba5173a71400fbd7c728712c602b49ab782785d5cb1615058e22dfb4e79ae3", "bytes": 25776, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d0d75fe56854a6cddbe56bf349533153536b7556b8309148755d7da073b633b9.mp3", "duration_ms": 4240}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/85c0de9ebfb4a773170e34c50ee80c713d149d1e19b6a06caad25d5b46aef476.mp3", "hash": "5d4a30c290c8620b1d3801c17df9e8943e538131640008ae943adfa1a7fb178c", "bytes": 56016, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/85c0de9ebfb4a773170e34c50ee80c713d149d1e19b6a06caad25d5b46aef476.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "read-chart", "title": "La gráfica de ventas", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la gráfica de barras de vasos vendidos por día y responder cuál fue el mejor día de la semana"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 5, "type": "read_chart", "title": "La gráfica de Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Vasos vendidos", "points": [{"x": "Lunes", "y": 12}, {"x": "Martes", "y": 18}, {"x": "Miércoles", "y": 15}, {"x": "Jueves", "y": 22}, {"x": "Viernes", "y": 19}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Lunes"}, {"id": "martes", "text_md": "Martes"}, {"id": "miercoles", "text_md": "Miércoles"}, {"id": "jueves", "text_md": "Jueves"}, {"id": "viernes", "text_md": "Viernes"}], "prompt_md": "¿Cuál fue el mejor día de ventas?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara dibujó una gráfica de los vasos de limonada que vendió esta semana. ¿Qué día vendió más vasos?", "difficulty": 1, "explanation_md": "El jueves Zara vendió 22 vasos, la barra más alta de la gráfica. Eso significa que fue su mejor día de ventas.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "jueves"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/8b55cbcd0bd0dd8bf6220c0c8c4f439c435f85aa6e641f6b9b969138617c6c9d.mp3", "hash": "044dbc9c1580f6f6a9e358893b2decf9a08b9da4720da6c083e55ae964d92251", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8b55cbcd0bd0dd8bf6220c0c8c4f439c435f85aa6e641f6b9b969138617c6c9d.mp3", "duration_ms": 6800}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/1b0a381b36d15e168049bcc067d9e7af3fa834d04cd63be8c616feb08175a07d.mp3", "hash": "af96facf13c4d0dbd3b812ec0e946e4aede50ced1cb0b72a992b7a05084e31b6", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1b0a381b36d15e168049bcc067d9e7af3fa834d04cd63be8c616feb08175a07d.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "read-chart", "title": "The sales chart", "locale": "en-US", "subject": "mixed", "objectives": ["Read the bar graph of cups sold per day and answer which was the best day of the week"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 5, "type": "read_chart", "title": "Zara''s chart", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Cups sold", "points": [{"x": "Monday", "y": 12}, {"x": "Tuesday", "y": 18}, {"x": "Wednesday", "y": 15}, {"x": "Thursday", "y": 22}, {"x": "Friday", "y": 19}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Monday"}, {"id": "martes", "text_md": "Tuesday"}, {"id": "miercoles", "text_md": "Wednesday"}, {"id": "jueves", "text_md": "Thursday"}, {"id": "viernes", "text_md": "Friday"}], "prompt_md": "What was the best sales day?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara drew a chart of the lemonade cups she sold this week. Which day did she sell the most cups?", "difficulty": 1, "explanation_md": "On Thursday, Zara sold 22 cups, the tallest bar on the chart. That means it was her best sales day.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "jueves"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/af55bb8797e48717feacf1214de3cdcaba43515d1e8b378617fe0afb4c054d9e.mp3", "hash": "9b78bc9bb9f84b109a28c94b6aa14b2e1344c7ea97d8cc20004df647ed117e65", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/af55bb8797e48717feacf1214de3cdcaba43515d1e8b378617fe0afb4c054d9e.mp3", "duration_ms": 4960}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/99b18d3c9668c970338c17f6889c3f292b73c28e1bb19a15059d05015569f240.mp3", "hash": "84d5a5d126c3501301762aba132537d7bd746a4d70ca888d58b9e77c9fcc5875", "bytes": 36864, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/99b18d3c9668c970338c17f6889c3f292b73c28e1bb19a15059d05015569f240.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Fatos vs Opiniões na barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Diferenciar entre fatos e opiniões nas frases de uma barraca de limonada."], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "fact-opinion-1", "xp": 15, "type": "fact_opinion", "hints": ["Um fato pode ser provado se é verdade ou mentira. Uma opinião é o que alguém sente ou pensa."], "title": "Fatos vs Opiniões", "payload": {"statements": [{"id": "s1", "text_md": "O copo de limonada custa 5 reais."}, {"id": "s2", "text_md": "É a melhor limonada da cidade."}, {"id": "s3", "text_md": "Nossa receita leva açúcar, limões e água."}, {"id": "s4", "text_md": "Abrimos de segunda a sexta."}, {"id": "s5", "text_md": "Nossos clientes dizem que adoram."}, {"id": "s6", "text_md": "Tem gosto de puro verão."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/eb4e702c560cdfd7763ee9145bee9fd6e471318213ecde375f8a6c9a91027c84.webp", "prompt_md": "Para não cair em armadilhas, preste atenção no que é um fato comprovável. Toque nas frases que são FATOS na barraca de Liruf.", "difficulty": 2, "explanation_md": "Sua amiga Liruf diz que a limonada dela custa 5 reais: isso é um fato. Mas que seja ''a melhor'' é a opinião dela, porque para outros pode não ser. Preste atenção no que pode ser comprovado!", "audio_segment_id": "fact-opinion-1.prompt"}], "schema_version": 1}', '{"fact-opinion-1": {"fact_ids": ["s1", "s3", "s4"]}}', '{"units": {"fact-opinion-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ac44210c47336f24afe480768357b4af23d58fda14f7cbf949599f1c64282d2f.mp3", "hash": "c84e1164a60c1a97050d150e4dcaf5c92813462dd721b8a0104a8504e85b1c09", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ac44210c47336f24afe480768357b4af23d58fda14f7cbf949599f1c64282d2f.mp3", "duration_ms": 7200}, "fact-opinion-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/f538e6467a779455110764354b180eb4fb7db9e97da0fd7f77aed05baea30d6a.mp3", "hash": "ea39a207460f9b24e09050f1b77634fa853f0e0ee803042a074139f5ff20b76e", "bytes": 50688, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f538e6467a779455110764354b180eb4fb7db9e97da0fd7f77aed05baea30d6a.mp3", "duration_ms": 8400}, "fact-opinion-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/a60cf32f85e228b243f5a9195ebe6b2e6c3601c28b1bb9fd6bb3629342e6cdcf.mp3", "hash": "561cff55b0c520d1af4989f965ad71478be2d7c1e99c3ddcb10060c9b47de4e5", "bytes": 88128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a60cf32f85e228b243f5a9195ebe6b2e6c3601c28b1bb9fd6bb3629342e6cdcf.mp3", "duration_ms": 14640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "coin-count", "title": "Contando moedas para Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Contar moedas de 1 e 2 reais para formar 5 reais exatos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "coin-count-1", "xp": 10, "type": "coin_count", "hints": ["Você pode combinar moedas de 1 e 2 reais até chegar a 5."], "title": "Vamos contar moedas!", "payload": {"target": 5, "currency": "BRL", "denominations": [1, 2]}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/39d8853ecca3654b562f001ec0a643790e936fb5734778b4d10e0dd0313ec9dc.webp", "prompt_md": "Um cliente pagou com moedas de 1 e 2 reais. Junte as moedas para formar exatamente 5 reais.", "difficulty": 1, "explanation_md": "O copo custa 5 reais. Com moedas de 1 e 2, uma forma de juntá-las é 2+2+1 ou 1+1+1+1+1. Você decide como!", "audio_segment_id": "coin-count-1.prompt"}], "schema_version": 1}', '{"coin-count-1": {}}', '{"units": {"coin-count-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6a32d4298ea84198922bd660a93d3ae5d88f0abcfae24cd97727cbe8e27cb302.mp3", "hash": "eb78f5a0ad59820c28b35fe90f600c6085f4c38ca97fc56591997d515225c0f4", "bytes": 29088, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6a32d4298ea84198922bd660a93d3ae5d88f0abcfae24cd97727cbe8e27cb302.mp3", "duration_ms": 4800}, "coin-count-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/c121afc476ec3c5b322a68bb1b4333a2b07384d9782b875a6feea2803da16d2d.mp3", "hash": "fc1eb8ace50179ac23bac6af61384fb201066f2eb759f1de4c2c57df86d926d6", "bytes": 41616, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c121afc476ec3c5b322a68bb1b4333a2b07384d9782b875a6feea2803da16d2d.mp3", "duration_ms": 6880}, "coin-count-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/245446225c6a2df7a289e78d472cd1c70cc31be68d4afe784bb7a473aa9edcd6.mp3", "hash": "16830d963f52ce2d3567e4090f0c8787f60b2571aa89d970bfa41748c6db0a7a", "bytes": 69984, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/245446225c6a2df7a289e78d472cd1c70cc31be68d4afe784bb7a473aa9edcd6.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparando fornecedores", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler e comparar preços e quantidades em uma tabela para escolher a melhor opção de compra."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 5, "type": "compare_table", "hints": ["Veja qual fornecedor vende os limões mais baratos."], "title": "Tabela de fornecedores", "payload": {"cols": [{"id": "precio", "label": "Preço"}, {"id": "cantidad", "label": "Quantidade"}, {"id": "mejor-opcion", "label": "Melhor opção"}], "rows": [{"id": "donia-lula", "label": "Dona Lula"}, {"id": "don-pepe", "label": "Seu Pepe"}], "tokens": [{"id": "t1", "text_md": "5 reais"}, {"id": "t4", "text_md": "10 limões"}, {"id": "t2", "text_md": "12 limões"}, {"id": "t3", "text_md": "6 reais"}, {"id": "t5", "text_md": "Dona Lula"}, {"id": "t6", "text_md": "Seu Pepe"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/40cbfa7b95b10b885675502cc827869da5057251fe86cacc07e877cb073286bd.webp", "prompt_md": "Dona Lula vende 12 limões por 5 reais. Seu Pepe vende 10 limões por 6 reais. Preencha a tabela e escolha a melhor opção.", "difficulty": 1, "explanation_md": "Dona Lula vende 12 limões por 5 reais, enquanto Seu Pepe vende apenas 10 por 6 reais. Mais limões e mais barato! 🍋", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"don-pepe:precio": "t3", "don-pepe:cantidad": "t4", "donia-lula:precio": "t1", "donia-lula:cantidad": "t2", "donia-lula:mejor-opcion": "t5"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ca029f0d6767fbfc42477fd9cac15e01556fdf42eb2d7106467d7c705a45a0e2.mp3", "hash": "c6df0182d6454cfb157f7f66b06b42faafef29953563dbce77922917684a2920", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ca029f0d6767fbfc42477fd9cac15e01556fdf42eb2d7106467d7c705a45a0e2.mp3", "duration_ms": 3840}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/432b36ea72b68a8125a70d943e7baf20c1f9944e26218701ef8f1a789669c992.mp3", "hash": "27098ed64a5876ede0e14d04ce6d86e944adb7aa51d4511f40beb7161c4040ca", "bytes": 61344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/432b36ea72b68a8125a70d943e7baf20c1f9944e26218701ef8f1a789669c992.mp3", "duration_ms": 10160}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/6565821bb16c5f1fe4a917d6194da2db0ab7e8e0bfda13e12a100b361ec0749a.mp3", "hash": "c237c75e5e93947df7d1427b2dfdf10748aa9a2a4f88f62611035a9ed37e254a", "bytes": 61776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6565821bb16c5f1fe4a917d6194da2db0ab7e8e0bfda13e12a100b361ec0749a.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classificar compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Classificar compras em necessidades da barraca de limonada e desejos que podem esperar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort", "xp": 10, "type": "sort_buckets", "title": "Necessidade ou desejo?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/7d9472b044ee532f11a80b6786f3eba28c63e2599c11c8be981b5243e2c7d5cb.webp"}, {"id": "vasos", "icon": "local_drink", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/0639608c7c8f6cd9e63e97af1b17b0cd62dae847d6a4d42848ab2143b81bacaf.webp"}, {"id": "stickers", "icon": "sticky_note_2", "text_md": "Adesivos", "image_url": "http://localhost:4006/files/lesson-images/6864fbb6a2bfc7d7630f86e9709565b218e611ffb8f90b9f037396f3d34501a2.webp"}, {"id": "globos", "icon": "celebration", "text_md": "Balões", "image_url": "http://localhost:4006/files/lesson-images/3ef6823477bf5d5253cbe527dd70266b70e5dceb98d300b6949140a9545241b9.webp"}], "buckets": [{"id": "necesidad", "label": "NECESSIDADE da barraca"}, {"id": "gusto", "label": "DESEJO que pode esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Classifique cada compra: necessidade da barraca de limonada ou desejo que pode esperar?", "difficulty": 1, "explanation_md": "Para Liruf, os limões e os copos são NECESSIDADES porque sem eles não pode preparar nem servir limonada. Os adesivos e balões são desejos que podem esperar.", "audio_segment_id": "s1-sort.prompt"}], "schema_version": 1}', '{"s1-sort": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort.prompt": {"url": "http://localhost:4006/files/lesson-audio/59bd655e30a74c03388b0bcd9a1d789feb7b687ee397b29d7147da9d5df3be5b.mp3", "hash": "06310f074fdda40f495491c95763cba1cec6f5a49c77140e531e37d87c884368", "bytes": 36288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/59bd655e30a74c03388b0bcd9a1d789feb7b687ee397b29d7147da9d5df3be5b.mp3", "duration_ms": 6000}, "s1-sort.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c4a17723b038afd3af247bdc266a9d2064a7c55733d1f5d4f10f8e715eaa03a.mp3", "hash": "822c70a30864b8f2c0f6e81a249054ea890351c70d6390d409f1f184ed3707e2", "bytes": 67968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4c4a17723b038afd3af247bdc266a9d2064a7c55733d1f5d4f10f8e715eaa03a.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "savings-goal", "title": "Plan de ahorro para la guitarra", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el número de semanas para alcanzar una meta de ahorro dividiendo la meta entre el ahorro semanal."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "savings-goal-1", "xp": 15, "type": "savings_goal", "hints": ["Piensa en dividir los 80 pesos en partes iguales según lo que ahorra por semana."], "title": "¿Cuántas semanas para la guitarra?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf puede ahorrar 10, 20 o 40 pesos por semana para la guitarra de 80 pesos. ¿Cuántas semanas tarda cada plan?", "difficulty": 2, "explanation_md": "Ahorrando 10 pesos por semana, Liruf tarda 8 semanas; con 20 son 4 y con 40 solo 2. Para el concurso en 4 semanas, los planes de $20 y $40 le alcanzan justo a tiempo. ⭐", "audio_segment_id": "savings-goal-1.prompt"}], "schema_version": 1}', '{"savings-goal-1": {}}', '{"units": {"savings-goal-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/91c232fb9a04f67c7b7efac901da79feafdd01b2840699ab1be1e54a9fbff23f.mp3", "hash": "21b33f07f5f6cb91db35a0937c03ee526640f7215ed611f4286332d6c0c2939e", "bytes": 32544, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/91c232fb9a04f67c7b7efac901da79feafdd01b2840699ab1be1e54a9fbff23f.mp3", "duration_ms": 5360}, "savings-goal-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/5b678934c9a6438bb191c07c21b243ee216be0178c7e0982f117be57d4282047.mp3", "hash": "1cdf3417b02f77a9f4144d79abf6e27126214b25eed530c222458444ad18af8e", "bytes": 54144, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5b678934c9a6438bb191c07c21b243ee216be0178c7e0982f117be57d4282047.mp3", "duration_ms": 8960}, "savings-goal-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/e25fe6653201bef986388bf2d1030ee0f7dc067235e2423ae0f9854dbe875ed9.mp3", "hash": "d387d22db36679ad5ba2ad9cff8cae4beb81ee365a1f0b510ed7d112a5d4dfbc", "bytes": 85248, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e25fe6653201bef986388bf2d1030ee0f7dc067235e2423ae0f9854dbe875ed9.mp3", "duration_ms": 14160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Revisão: Ganho por copo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar o cálculo de ganho por copo na barraca de limonada."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-ganancia", "xp": 10, "type": "quiz_mcq", "title": "Revisão rápida do ganho", "payload": {"options": [{"id": "opt-2", "text_md": "5 reais", "rationale_md": "Parece correto porque é o preço de venda, mas o ganho é o que sobra depois de pagar os ingredientes."}, {"id": "opt-4", "text_md": "7 reais", "rationale_md": "Somar o preço e o custo dá 7, mas para calcular o ganho é preciso subtrair o custo do preço, não somá-los."}, {"id": "opt-1", "text_md": "3 reais"}, {"id": "opt-3", "text_md": "2 reais", "rationale_md": "Os 2 reais são o custo dos ingredientes, não o ganho. O ganho é o que sobra depois de subtrair o custo."}], "shuffle": false}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina pergunta a Liruf: ''Se você vende cada copo por 5 reais e te custa 2 reais fazer, quanto você ganha por copo?''", "difficulty": 1, "explanation_md": "O ganho por copo é o preço de venda menos o custo: 5 - 2 = 3 reais. Assim Liruf sabe quanto cresce sua poupança por cada copo vendido. 💰", "audio_segment_id": "s1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"s1-repaso-ganancia": {"correct_option_id": "opt-1"}}', '{"units": {"s1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/bdb78b055634b1edab215da0e9eaf8a64e71681156bbc993e41404ba8bb00c47.mp3", "hash": "a6702f1411a00783f5276b9c3d621259a385a39914367d58e1fb072206d06fd7", "bytes": 53568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bdb78b055634b1edab215da0e9eaf8a64e71681156bbc993e41404ba8bb00c47.mp3", "duration_ms": 8880}, "s1-repaso-ganancia.choices": {"url": "http://localhost:4006/files/lesson-audio/e90160dddc172f00eee64ffe21890c735f3119c73774b98560e3972405f24e95.mp3", "hash": "20cbf0d16f913e3175c59554231a29e783d0ad7b7a3429c61b314562d16c65dd", "bytes": 28224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e90160dddc172f00eee64ffe21890c735f3119c73774b98560e3972405f24e95.mp3", "duration_ms": 4640}, "s1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/9186435c7843ea6416c9bd4bc92e980e02282bfad50efbfee153b7734d30f730.mp3", "hash": "9cedd177ad89e21186124ae48e19e0d21946c7984ceda7c48579bd0305bb4a2b", "bytes": 69408, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9186435c7843ea6416c9bd4bc92e980e02282bfad50efbfee153b7734d30f730.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "key-ideas", "title": "The seller''s golden rules", "locale": "en-US", "subject": "mixed", "objectives": ["Identify the three basic steps to earn money: have a goal, offer a desired product, and save what you earn."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "title": "The golden rules", "payload": {"ideas": [{"icon": "target", "title": "A clear goal", "body_md": "Liruf wants her guitar for **80 dollars**. A goal tells you where you''re going.", "image_url": "http://localhost:4006/files/lesson-images/b850b0cd9eb9ae139df94402fad86c36d3bba9fee2d9b3d0c9ee9411f5913dfd.webp"}, {"icon": "storefront", "title": "Something people want", "body_md": "Cold lemonade! On a hot day, everyone wants a glass. She sells each one for **5 dollars**.", "image_url": "http://localhost:4006/files/lesson-images/cfaa4357cd46c80b6bc586f110f9ec924b2ef694151d2a3b6507fc6bf2e853d8.webp"}, {"icon": "savings", "title": "Saving what you earn", "body_md": "Each sale brings her closer to her dream. She saves every coin for the guitar.", "image_url": "http://localhost:4006/files/lesson-images/fb43ba9343458d523575015c7c7168d6c9bc0b9180c3084a63066c92a3713d7a.webp"}]}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf''s 3 golden rules to earn money.", "difficulty": 1, "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/4fa9e2a0d898c10d05fb7fc68eaa613d74e7b68d3e8056c80d0d1a8b2f1f8e91.mp3", "hash": "762f452b5d0b0a8e1e3ce9dc61c54fd57fd18057dd86e640d92d639c5a7382bb", "bytes": 30096, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4fa9e2a0d898c10d05fb7fc68eaa613d74e7b68d3e8056c80d0d1a8b2f1f8e91.mp3", "duration_ms": 4960}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/1395db5bd89b0efbbccbf830435987ab912c25076629469b4ccca012ec23ef3b.mp3", "hash": "f29f41f4151cd6ac7a29bf9fd58cdbeecfb1f5a4855d7629888d49569dbb6ff2", "bytes": 41184, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1395db5bd89b0efbbccbf830435987ab912c25076629469b4ccca012ec23ef3b.mp3", "duration_ms": 6800}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/3a2f6469f1496b915b7b7c3f27c5ddba7487f880dd190fb57cb25d81b540ae37.mp3", "hash": "48de2771953055060534ba42a0394e7e0e1aaacc493fd28618c50ff463ca0892", "bytes": 35856, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3a2f6469f1496b915b7b7c3f27c5ddba7487f880dd190fb57cb25d81b540ae37.mp3", "duration_ms": 5920}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/ff0e4144ecf6d9ab00f1d54ab795ac7adc5b728cd8947d6938b7c7c9a8fccb7c.mp3", "hash": "aa2c8673beeb9b8b7b8510622eb71f96a7a80d2b8ae947424e367ef72c20ad3c", "bytes": 19008, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/ff0e4144ecf6d9ab00f1d54ab795ac7adc5b728cd8947d6938b7c7c9a8fccb7c.mp3", "duration_ms": 3120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "evidence-hunt", "title": "Encuentra la evidencia en el recibo", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar la evidencia exacta del costo de los limones en un recibo."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 5, "type": "evidence_hunt", "title": "Encuentra la evidencia", "payload": {"claim_md": "Los limones costaron 12 pesos.", "sentences": [{"id": "e1-limones", "text_md": "Bolsa de limones — $12"}, {"id": "e1-azucar", "text_md": "Paquete de azúcar — $20"}, {"id": "e1-vasos", "text_md": "Paquete de vasos — $35"}, {"id": "e1-total", "text_md": "Total — $67"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/569cd097ec5c7c9d72094d00bcac4e6c5fa9221ecd4203a308ebc4725904c3a8.webp", "prompt_md": "Liruf encontró un recibo arrugado. Toca la línea que muestra el costo de los limones.", "difficulty": 1, "explanation_md": "La línea ''Bolsa de limones — $12'' es la evidencia de que los limones costaron 12 pesos. ¡Así Liruf puede revisar sus cuentas!", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["e1-limones"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d3aa947b9b3ce2af654e053d33b020b11ce9f65c710d9ceedce152c8f91682a.mp3", "hash": "712a458817fb94d4c40b6f8965732f8ed5ed219a97da235a1965688c5cd65241", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8d3aa947b9b3ce2af654e053d33b020b11ce9f65c710d9ceedce152c8f91682a.mp3", "duration_ms": 5600}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/05b9313f8537c5ffff337eb916de8e7cb2ddd6c0e25757adf4425d8c0ed22723.mp3", "hash": "4d576630dbd9faa61c189329a1304c14772bdf8d4ef27baf2673e8f5ce214934", "bytes": 55008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/05b9313f8537c5ffff337eb916de8e7cb2ddd6c0e25757adf4425d8c0ed22723.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Armemos la suma de la tarde", "locale": "es-MX", "subject": "mixed", "objectives": ["Armar la suma del día usando fichas de números y signos.", "Calcular el total de una venta de varios productos del mismo precio."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "eq-tarde", "xp": 10, "type": "equation_builder", "title": "Suma de la tarde", "payload": {"slots": 5, "tokens": [{"id": "n1", "text": "5"}, {"id": "n2", "text": "5"}, {"id": "n3", "text": "5"}, {"id": "p1", "text": "+"}, {"id": "p2", "text": "+"}, {"id": "d_10", "text": "10"}, {"id": "d_15", "text": "15"}, {"id": "d_sub", "text": "-"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf vendió 3 vasos de limonada a 5 pesos cada uno. Arma la suma para saber cuánto ganó.", "difficulty": 1, "explanation_md": "Cada vaso cuesta 5 pesos. Tres vasos suman: 5 + 5 + 5 = 15 pesos. 💰", "audio_segment_id": "eq-tarde.prompt"}], "schema_version": 1}', '{"eq-tarde": {"accepted": ["n1 p1 n2 p2 n3", "n1 p1 n3 p2 n2", "n2 p1 n1 p2 n3", "n2 p1 n3 p2 n1", "n3 p1 n1 p2 n2", "n3 p1 n2 p2 n1", "n1 p2 n2 p1 n3", "n1 p2 n3 p1 n2", "n2 p2 n1 p1 n3", "n2 p2 n3 p1 n1", "n3 p2 n1 p1 n2", "n3 p2 n2 p1 n1"]}}', '{"units": {"eq-tarde.prompt": {"url": "http://localhost:4006/files/lesson-audio/2e14796038d551772e28c439893cccb743c81127e022adea22d158d0d9a382bb.mp3", "hash": "fc612890786189a557da029ef4475b57f6a3ebb37e4679130c8e379c6add1715", "bytes": 43488, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2e14796038d551772e28c439893cccb743c81127e022adea22d158d0d9a382bb.mp3", "duration_ms": 7200}, "eq-tarde.explanation": {"url": "http://localhost:4006/files/lesson-audio/57c81b78af9ecfc6d56b4346e5f124c0db83569566f8d0963caee92e7213a386.mp3", "hash": "de7b89878d02ce22c478568123f976e821149690256b876771a140571e23c920", "bytes": 51696, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/57c81b78af9ecfc6d56b4346e5f124c0db83569566f8d0963caee92e7213a386.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "balance-scale", "title": "Equilibre a balança da troca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Equilibrar a balança da troca para conseguir um acordo justo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Primeiro calcula o valor total do prato esquerdo: 3 copos × 5 reais cada um.", "Cada biscoito vale 3 reais. Quantos biscoitos você precisa para somar o mesmo que o prato esquerdo?"], "title": "A balança da troca!", "payload": {"weights": [{"id": "g1", "label": "biscoito de 3 reais", "value": 3}, {"id": "g2", "label": "biscoito de 3 reais", "value": 3}, {"id": "g3", "label": "biscoito de 3 reais", "value": 3}, {"id": "g4", "label": "biscoito de 3 reais", "value": 3}, {"id": "g5", "label": "biscoito de 3 reais", "value": 3}, {"id": "g6", "label": "biscoito de 3 reais", "value": 3}, {"id": "g7", "label": "biscoito de 3 reais", "value": 3}, {"id": "g8", "label": "biscoito de 3 reais", "value": 3}], "left_fixed": [{"label": "copo de limonada", "value": 5}, {"label": "copo de limonada", "value": 5}, {"label": "copo de limonada", "value": 5}], "unknown_label": "?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf coloca 3 copos de limonada (5 reais cada) em um prato. Adiciona biscoitos (3 reais) ao outro prato até equilibrar a balança.", "difficulty": 2, "explanation_md": "Os 3 copos de limonada valem 15 reais (5+5+5). Para equilibrar a balança, Liruf precisa de 5 biscoitos de 3 reais cada um, porque 3+3+3+3+3 = 15. É um acordo justo!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/45a7a69aa7a39af663c8b291930e9e9ce51684fc2d30868bb6891c5021b2d63a.mp3", "hash": "dfde3ff1c51e4f18deca73723d5eb2913585e78849064aec16d0761b57822aee", "bytes": 39744, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/45a7a69aa7a39af663c8b291930e9e9ce51684fc2d30868bb6891c5021b2d63a.mp3", "duration_ms": 6560}, "s1-balance.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fc1ca786cb23799ae8ee8bce6ea030d3069564679b780b2aee8b03189686109f.mp3", "hash": "338c8c10dca1c811c2410db12bfa2cb72da84bdaa2955db70775dcc7ea2549a0", "bytes": 45504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fc1ca786cb23799ae8ee8bce6ea030d3069564679b780b2aee8b03189686109f.mp3", "duration_ms": 7520}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/d7524f00ddd16bd0a10f012bf54f324792c331fff3339ce0c4d651d201685728.mp3", "hash": "dd15255f7b61c4324484bf43cd1dda2cf02bd6687a58a418092993fb711faf33", "bytes": 67536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d7524f00ddd16bd0a10f012bf54f324792c331fff3339ce0c4d651d201685728.mp3", "duration_ms": 11200}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/5b073b70a2c9ddb76479669849fff7d256db0427153238f67531e08da47108c4.mp3", "hash": "63829f55b6ae53f9ea41842715e42c899232afa993158f830522d634108cc8a1", "bytes": 106848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5b073b70a2c9ddb76479669849fff7d256db0427153238f67531e08da47108c4.mp3", "duration_ms": 17760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "picture-choice", "title": "Where should you keep the money?", "locale": "en-US", "subject": "mixed", "objectives": ["Choose the safest place to keep the day''s earnings."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 8, "type": "picture_choice", "title": "The safe place", "payload": {"options": [{"id": "opt1", "icon": "wallet", "label": "Torn pocket", "image_url": "http://localhost:4006/files/lesson-images/4e2abf237219b8117084640a1b04964166d8a54edd652fb5fcf751357019ea9b.webp", "rationale_md": "The money could fall out through the hole."}, {"id": "opt2", "icon": "savings", "label": "Piggy bank with a lock", "image_url": "http://localhost:4006/files/lesson-images/9681bc52834c92a8becdd0f2853e569f8a065b99bd2ee43b8bdacc1f103ff2d3.webp"}, {"id": "opt3", "icon": "table_restaurant", "label": "The stand''s table", "image_url": "http://localhost:4006/files/lesson-images/c7a7477fa0d906300135e0eb029415c13f98959267fe79c5560159025bd2faee.webp", "rationale_md": "Anyone passing by could take it without you noticing."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf finished selling lemonade and has 20 dollars. Where is it safest to keep it?", "difficulty": 1, "explanation_md": "A piggy bank with a lock keeps money safe; in a torn pocket it could fall out, and on the table anyone could take it.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt2"}}', '{"units": {"s1-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/c66e8edbf78ae0cbabce4e26092c85956c1dd832796844edea46e74f0e041410.mp3", "hash": "76c2627cfcb442c40b21144da40edc5479498b420db0ea57e32bef3063709150", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c66e8edbf78ae0cbabce4e26092c85956c1dd832796844edea46e74f0e041410.mp3", "duration_ms": 4720}, "s1-picture-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/2e8acbfd5b6cf00209f3e3f097bedc00b21e6afd07799eae502fed1edba97644.mp3", "hash": "414d697bfc184f2b0927afd13448ccab07477b7564f5275950277ad79d0a414f", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2e8acbfd5b6cf00209f3e3f097bedc00b21e6afd07799eae502fed1edba97644.mp3", "duration_ms": 3600}, "s1-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/1427404a3cb2d01787d6c704ba7f4ea74710968d6951fd4d8cb9631bdbb014d0.mp3", "hash": "d9b62f21aebff121bfde0baf2b44fbd0e3195767757d508f9f536196cd9bbc27", "bytes": 40608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1427404a3cb2d01787d6c704ba7f4ea74710968d6951fd4d8cb9631bdbb014d0.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "¿Es justo el intercambio?", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si un trueque es justo comparando el valor de lo que se da y lo que se recibe."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "ft-1", "xp": 5, "type": "fair_trade", "title": "Trueque con el frutero", "payload": {"offer_a": {"qty": 1, "icon": "local_cafe", "label": "2 vasos de limonada", "image_url": "http://localhost:4006/files/lesson-images/36e3d03a16fb176bd4e532f60bbb2bd74aaa6f024e844d5bbdd26884d1602d0e.webp"}, "offer_b": {"qty": 1, "icon": "agriculture", "label": "Bolsa de limones", "image_url": "http://localhost:4006/files/lesson-images/2e985967622df9696797874a56c247c209e105aa3521231488d5613d0491be28.webp"}, "rate_md": "1 bolsa de limones = 10 pesos"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf vende vasos de limonada a 5 pesos. El frutero le ofrece: 2 vasos por una bolsa de limones que vale 10 pesos. ¿Es justo el trueque?", "difficulty": 1, "explanation_md": "Los 2 vasos de limonada valen 10 pesos, ¡justo lo que cuesta la bolsa de limones! Es un intercambio justo.", "audio_segment_id": "ft-1.prompt"}], "schema_version": 1}', '{"ft-1": {"verdict": "fair"}}', '{"units": {"ft-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/f97b74f699417db4033434f9ab7dc0f1f4abf2eb4e41a49a3ee7ab0ada5e51df.mp3", "hash": "0e4a0c0919b9f99f726ab00931c881a78f505307dc5cf484fc722443ed930f17", "bytes": 66096, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f97b74f699417db4033434f9ab7dc0f1f4abf2eb4e41a49a3ee7ab0ada5e51df.mp3", "duration_ms": 10960}, "ft-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/8c5ba588a6a9d9e4ddf846d8677e40b047740c07277052a0ef39797f9a335ed8.mp3", "hash": "3901822495a6d726ba5ea79c5f4a8900190d59f1435f600d5e9c629f4fe261f7", "bytes": 46944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8c5ba588a6a9d9e4ddf846d8677e40b047740c07277052a0ef39797f9a335ed8.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "spot-error", "title": "Procurando o erro na conta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1", "xp": 15, "type": "spot_error", "hints": ["Some os preços dos três copos. O total que Liruf anotou está correto?"], "title": "Procurando o erro na conta", "payload": {"steps": [{"id": "sale1", "text_md": "Vendi um copo por 5 reais"}, {"id": "sale2", "text_md": "Vendi outro copo por 5 reais"}, {"id": "sale3", "text_md": "Vendi um terceiro copo por 5 reais"}, {"id": "total", "text_md": "Total do dia: 20 reais"}], "context_md": "Liruf anota as vendas do dia no seu caderno."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/05b7e5bfb7561c1c8bbdcc569c3356a8496946add9204fbe1cf09102dba9c4ad.webp", "prompt_md": "Algo não bate na conta de Liruf. Toque no passo onde está o erro.", "difficulty": 2, "explanation_md": "O total correto é 15 reais, porque 5+5+5=15. Liruf se enganou ao escrever 20. Que olho bom para encontrar o erro!", "audio_segment_id": "s1.prompt"}], "schema_version": 1}', '{"s1": {"error_ids": ["total"], "correction_md": "5+5+5 es 15, no 20. El total correcto es 15 pesos."}}', '{"units": {"s1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b0516e24227acfe7bd742f07cbf4a1a3dcdfa0aa929e18ce548a500f7192c6db.mp3", "hash": "813ad23c4ff9da327aabcd81efd7e334ba79ebcb316112c07ca78383be95a7e4", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b0516e24227acfe7bd742f07cbf4a1a3dcdfa0aa929e18ce548a500f7192c6db.mp3", "duration_ms": 4960}, "s1.prompt": {"url": "http://localhost:4006/files/lesson-audio/1571763297778215693fb6e1317d01351e7f45d46899ec6cb39a249ecbed44bb.mp3", "hash": "df8b4aa6f27d344e638c54246e5d611a35cfe46df26bc226da9f3f5558937904", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1571763297778215693fb6e1317d01351e7f45d46899ec6cb39a249ecbed44bb.mp3", "duration_ms": 4400}, "s1.explanation": {"url": "http://localhost:4006/files/lesson-audio/a62d405c2bfcd505a034c42a4efb473121c349389502248d18f5bc325d6a3a8c.mp3", "hash": "761b92f503faf9ebbea8f5d2e020dec2b62ae47d570b890a12a67955289543c3", "bytes": 69408, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a62d405c2bfcd505a034c42a4efb473121c349389502248d18f5bc325d6a3a8c.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "build-sentence", "title": "O combo de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar passos, emparelhar produtos com preços e classificar compras entre necessidades do posto e gostos que podem esperar."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-letrero", "xp": 15, "type": "build_sentence", "hints": ["Pense: quanto custam dois copos se um custa 5 reais?"], "title": "Cartaz do combo", "payload": {"slots": 5, "tokens": [{"id": "t2", "text_md": "2"}, {"id": "tv", "text_md": "copos"}, {"id": "tp", "text_md": "por"}, {"id": "t10", "text_md": "10"}, {"id": "tpe", "text_md": "reais"}, {"id": "t5", "text_md": "5"}, {"id": "t15", "text_md": "15"}, {"id": "t20", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf vende cada copo por 5 reais. Ela quer um cartaz: ''2 copos por ___ reais''. Monte o cartaz com as fichas.", "difficulty": 2, "explanation_md": "Dois copos de 5 reais cada um somam 10 reais. Por isso o cartaz diz ''2 copos por 10 reais''. A ficha 5 esquece que são dois; 15 é mais do que custa; 20 é muito mais.", "audio_segment_id": "s1-letrero.prompt"}], "schema_version": 1}', '{"s1-letrero": {"order": ["t2", "tv", "tp", "t10", "tpe"]}}', '{"units": {"s1-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/42bc0a77763bfa678ca4637ac27cbec919144d57e9199a626a12c2889a692a86.mp3", "hash": "d3d485400ce76b4af4d995253cc7ebbc279d1f6f2f59cf2303beef4884072ed8", "bytes": 25776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/42bc0a77763bfa678ca4637ac27cbec919144d57e9199a626a12c2889a692a86.mp3", "duration_ms": 4240}, "s1-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/acec86da8fca8b4c3bed440ba960536e767ce44470f4fbfdeb5ae018b68d3f09.mp3", "hash": "2faf6c75c9c482d67eedd3e9d9bb57512e39b23b416c861180c4c342ee782741", "bytes": 52128, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/acec86da8fca8b4c3bed440ba960536e767ce44470f4fbfdeb5ae018b68d3f09.mp3", "duration_ms": 8640}, "s1-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/13248061f37334eca5710ca45b98c33cfa5ca627e0dc12406874418976334381.mp3", "hash": "10f60a022459a59305ff07a68cfb79811f21cb505eb35d795fd791c84606551c", "bytes": 82944, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/13248061f37334eca5710ca45b98c33cfa5ca627e0dc12406874418976334381.mp3", "duration_ms": 13760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "Liruf''s Plan", "locale": "en-US", "subject": "money", "objectives": ["Understand that money is earned by offering something others want, and that a clear goal (the 80-dollar guitar) helps to get started."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-scene", "xp": 0, "type": "story_scene", "title": "Liruf''s Plan", "payload": {"art": {"icon": "lightbulb", "tint": "accent", "image_url": "http://localhost:4006/files/lesson-images/4b40c43d6eb57627c9d327434aadc89d402e0b4d213c0be74186f9334610e7da.webp"}, "body_md": "After talking with Dina, Liruf has a brilliant idea. 🍋 He draws his plan on a poster board: each cup of lemonade costs 5 dollars, and with each sale, he gets closer to his 80-dollar guitar. If he sells cup after cup, the guitar will be his!", "emotion": "excited", "backdrop": "base", "character": "liruf"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Look at Liruf''s plan.", "difficulty": 1, "audio_segment_id": "s1-scene.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-scene.body": {"url": "http://localhost:4006/files/lesson-audio/51b56d1d01d585100f4863d9abb0f14e7642787087c4f8005c5586e4ee65084a.mp3", "hash": "59d9e28537f9121dc4541339cf5c227424a3c7aa24635252b36156e79d125c41", "bytes": 87264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/51b56d1d01d585100f4863d9abb0f14e7642787087c4f8005c5586e4ee65084a.mp3", "duration_ms": 14480}, "s1-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/e266a6d34c1483714ab6e8b9abfd235c82685de59ab9ca2ed3b17e9a18d77ab2.mp3", "hash": "937099a5a73302e52addefab3e6344d4b92d3ee555374a00f641c17835789fe8", "bytes": 8928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e266a6d34c1483714ab6e8b9abfd235c82685de59ab9ca2ed3b17e9a18d77ab2.mp3", "duration_ms": 1440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "concept-reveal", "title": "Costo y Ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender el significado de costo y ganancia en un negocio de limonada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "concept-reveal-cost-ganancia", "xp": 0, "type": "concept_reveal", "title": "Costo y Ganancia", "payload": {"cards": [{"icon": "shopping_bag", "back_md": "Es lo que gastas para hacer la limonada: limones, azúcar, vasos.", "front_md": "COSTO", "image_url": "http://localhost:4006/files/lesson-images/7173825680a30310360248399acf0530638eac901929db1b77118bac8c141222.webp"}, {"icon": "savings", "back_md": "Es el dinero que te queda después de pagar el costo.", "front_md": "GANANCIA", "image_url": "http://localhost:4006/files/lesson-images/1c3214489aab355b04677f5b88ae3587d5477eb25222f98eb5cc7febcb6cfa9b.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Para ganar dinero y comprar la guitarra de 80 pesos, necesitas conocer el costo y la ganancia. Toca cada tarjeta.", "difficulty": 1, "explanation_md": "El costo es lo que gastas. La ganancia es lo que ganas de verdad después de pagar el costo. ¡Así sabes si tu negocio funciona!", "audio_segment_id": "concept-reveal-cost-ganancia.prompt"}], "schema_version": 1}', '{}', '{"units": {"concept-reveal-cost-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/ef087a3b77f0afd0b464c3403946072cc8b896aa66ef0e112e9e2900f28fba73.mp3", "hash": "29ce3ee865886df151b2f63428fe66b8978f5a7f31c4151de6fe9706c9755a4f", "bytes": 46368, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/ef087a3b77f0afd0b464c3403946072cc8b896aa66ef0e112e9e2900f28fba73.mp3", "duration_ms": 7680}, "concept-reveal-cost-ganancia.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/b025ebab2975dc84df0b669c4a468f5c15211d376e220fe7bcf10cbe73ec611e.mp3", "hash": "ae60e8c4df978284d8b1bc41df5c9171a16fcd5ea0c046bffe5c0372584a0c68", "bytes": 28656, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b025ebab2975dc84df0b669c4a468f5c15211d376e220fe7bcf10cbe73ec611e.mp3", "duration_ms": 4720}, "concept-reveal-cost-ganancia.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/564d0c5e4bbba938e86eff5321cc7865404d730533248317f5a39d6f710939bc.mp3", "hash": "682e77e3391d107f76fd7d82dfbd4ba356371207e6b420012aa4bd48159131e1", "bytes": 18144, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/564d0c5e4bbba938e86eff5321cc7865404d730533248317f5a39d6f710939bc.mp3", "duration_ms": 2960}, "concept-reveal-cost-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/bbe318ffb04fb28d82961188827a97b00264a06b6e94ece17a19ab4853b6a25c.mp3", "hash": "f0dc307880ea19e2b4529e9d276b108f5be123a200523307b9dbf4bef7fa263e", "bytes": 46368, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/bbe318ffb04fb28d82961188827a97b00264a06b6e94ece17a19ab4853b6a25c.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estime os copos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Estimar com a barra quantos copos saem de uma jarra grande."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-cups", "xp": 15, "type": "estimate_slider", "hints": ["Imagine o tamanho de uma jarra comum em casa e os copos que você usa. Quantos encheria?"], "title": "Quantos copos saem?", "payload": {"max": 20, "min": 0, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "excited", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/4e19821d41322fa6ac9721b7cdf6f33027e8e7b198351670b0c25a3f7e679255.webp", "prompt_md": "Zara preparou a jarra do dia. Sem contar, estime quantos copos pode encher.", "difficulty": 2, "explanation_md": "Zara sabe que a jarra dela rende 8 copos aproximadamente. Bom olho! 🎉", "audio_segment_id": "s1-estimate-cups.prompt"}], "schema_version": 1}', '{"s1-estimate-cups": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-cups.hint.0": {"url": "http://localhost:4006/files/lesson-audio/33acd91e2e10b2e387e6a3bcbae3963c4ffa793eb3d5c04fed9140c393367cdb.mp3", "hash": "8b7f7823a842dba1bd2434d64bff8aa6d480a232950e507bbb08a12a5c6a221b", "bytes": 36864, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/33acd91e2e10b2e387e6a3bcbae3963c4ffa793eb3d5c04fed9140c393367cdb.mp3", "duration_ms": 6080}, "s1-estimate-cups.prompt": {"url": "http://localhost:4006/files/lesson-audio/1576880e67eb704e2c9e47db0f86d0de8350329a2d73682c56e9f18ba60e06b9.mp3", "hash": "6acc902f14bd2bf0c2606a4a6f8542226909a216883e0f5b105166c3674dd37f", "bytes": 34848, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/1576880e67eb704e2c9e47db0f86d0de8350329a2d73682c56e9f18ba60e06b9.mp3", "duration_ms": 5760}, "s1-estimate-cups.explanation": {"url": "http://localhost:4006/files/lesson-audio/686fa0902202a4c9aabd4b218f61b8fb7e07fd1b8bbf18aa7538fe8736fa1880.mp3", "hash": "cc2c497edab5fe30d470135ce5b6d34f3f3d15f683449c3d6f1a30f30696201a", "bytes": 35424, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/686fa0902202a4c9aabd4b218f61b8fb7e07fd1b8bbf18aa7538fe8736fa1880.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "evidence-hunt", "title": "Encontre a evidência no recibo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar a evidência exata do custo dos limões em um recibo."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 5, "type": "evidence_hunt", "title": "Encontre a evidência", "payload": {"claim_md": "Os limões custaram 12 reais.", "sentences": [{"id": "e1-limones", "text_md": "Saco de limões — R$12"}, {"id": "e1-azucar", "text_md": "Pacote de açúcar — R$20"}, {"id": "e1-vasos", "text_md": "Pacote de copos — R$35"}, {"id": "e1-total", "text_md": "Total — R$67"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/569cd097ec5c7c9d72094d00bcac4e6c5fa9221ecd4203a308ebc4725904c3a8.webp", "prompt_md": "Liruf encontrou um recibo amassado. Toque na linha que mostra o custo dos limões.", "difficulty": 1, "explanation_md": "A linha ''Saco de limões — R$12'' é a evidência de que os limões custaram 12 reais. Assim Liruf pode verificar suas contas!", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["e1-limones"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/726a21bea9ca749d9eee7f36e6ec82db3e4180492a61cae9f82e80f0b749bab7.mp3", "hash": "1d47617b17f36983eaa68bd7d6de5cbd14fee42f494d5914a3474278b20d3bb1", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/726a21bea9ca749d9eee7f36e6ec82db3e4180492a61cae9f82e80f0b749bab7.mp3", "duration_ms": 5280}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/d5933fa0f01f9987eef09cd77c6c98d0b75242091a60068b35aa8127426c6fa5.mp3", "hash": "1523303837af56927f200774f4f4aa51d68d3d62c35119701b0b846455b904aa", "bytes": 59328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d5933fa0f01f9987eef09cd77c6c98d0b75242091a60068b35aa8127426c6fa5.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "read-chart", "title": "O gráfico de vendas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler o gráfico de barras de copos vendidos por dia e responder qual foi o melhor dia da semana"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 5, "type": "read_chart", "title": "O gráfico de Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Copos vendidos", "points": [{"x": "Segunda-feira", "y": 12}, {"x": "Terça-feira", "y": 18}, {"x": "Quarta-feira", "y": 15}, {"x": "Quinta-feira", "y": 22}, {"x": "Sexta-feira", "y": 19}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Segunda-feira"}, {"id": "martes", "text_md": "Terça-feira"}, {"id": "miercoles", "text_md": "Quarta-feira"}, {"id": "jueves", "text_md": "Quinta-feira"}, {"id": "viernes", "text_md": "Sexta-feira"}], "prompt_md": "Qual foi o melhor dia de vendas?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara desenhou um gráfico dos copos de limonada que vendeu esta semana. Que dia vendeu mais copos?", "difficulty": 1, "explanation_md": "Na quinta-feira Zara vendeu 22 copos, a barra mais alta do gráfico. Isso significa que foi o seu melhor dia de vendas.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "jueves"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/42d8518eb576c5284f101a97e31c17f1612a5f982240782cf7a9cfc6aad50359.mp3", "hash": "20c870d94dd9f85943e1d0cb60d564cf96da73d08b44aa6b3e909f65f4ba3ef3", "bytes": 43056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/42d8518eb576c5284f101a97e31c17f1612a5f982240782cf7a9cfc6aad50359.mp3", "duration_ms": 7120}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/8fa069b3b1e2e21b9d4d5b30999b5bc8b0583df96622a211ffc67591d5d2035e.mp3", "hash": "7c536d7573b9a53ba05353cd43cda2c2b7aa963933182f923e16640d5825be24", "bytes": 56016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8fa069b3b1e2e21b9d4d5b30999b5bc8b0583df96622a211ffc67591d5d2035e.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Cuenta las monedas de venta", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar el número exacto de monedas en una escena desordenada", "Asociar cada moneda contada con una venta de 5 pesos"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "count-objects-sales", "xp": 5, "type": "count_objects", "title": "Cuenta las monedas de venta", "payload": {"scene": [{"icon": "monetization_on", "tint": "delight", "count": 8, "label": "moneda", "image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, {"icon": "cookie", "tint": "warning", "count": 3, "label": "galleta", "image_url": "http://localhost:4006/files/lesson-images/f2975e6e8d715646e735228b20f39c19a408d57acbe156d19e08e426fad7fc66.webp"}, {"icon": "local_drink", "tint": "primary", "count": 2, "label": "vaso", "image_url": "http://localhost:4006/files/lesson-images/e7f7f16426e7194c18895bfcec92b380cc27efe30ad87d400a21821b9a14d390.webp"}], "ask_icon": "monetization_on", "ask_label": "moneda", "ask_image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf volcó el frasco de las ventas. Cuenta solo las monedas que cayeron. Cada una es un vaso de 5 pesos que ya vendió.", "difficulty": 1, "explanation_md": "Cayeron 8 monedas. ¡Cada una es 5 pesos! Eso significa que Liruf vendió 8 vasos de limonada hoy. Esos 8 vasos se suman a su ahorro para la guitarra de 80 pesos.", "audio_segment_id": "count-objects-sales.prompt"}], "schema_version": 1}', '{"count-objects-sales": {"value": 8}}', '{"units": {"count-objects-sales.prompt": {"url": "http://localhost:4006/files/lesson-audio/218a3302f866cbd04c3f28b463b158e67064014abed4540043200f67e94888cd.mp3", "hash": "111f7c704df9d80147d0f0808db2653428c3574d406e20e6baf03e6e1cab6b5e", "bytes": 53136, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/218a3302f866cbd04c3f28b463b158e67064014abed4540043200f67e94888cd.mp3", "duration_ms": 8800}, "count-objects-sales.explanation": {"url": "http://localhost:4006/files/lesson-audio/86baf7fe07cd87b4bf4f741f51a9be68a0cb6827f40605077319187cb87d8c7b.mp3", "hash": "367b01408c6065dd5630d935aab560646fce8e466255ebfda8c1ae12caacd530", "bytes": 82368, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/86baf7fe07cd87b4bf4f741f51a9be68a0cb6827f40605077319187cb87d8c7b.mp3", "duration_ms": 13680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "make-change", "title": "The Exact Change", "locale": "en-US", "subject": "money", "objectives": ["Apply the exact change with coins."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "make-change-1", "xp": 15, "type": "make_change", "hints": ["First, how much do the cup and the cookie cost together?"], "title": "Don Beto''s change", "payload": {"price": 8, "currency": "USD", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1ec2980cf3606b107e29793911a8353d6e52db87692285a5a7f745091f28ee47.webp", "prompt_md": "Don Beto bought 1 cup of lemonade (5 dollars) and 1 cookie (3 dollars). He paid with a 20-dollar bill. Tap the coins to give him the exact change.", "difficulty": 2, "explanation_md": "Don Beto''s purchase added up to 8 dollars (5 for the cup + 3 for the cookie). Since he paid with 20 dollars, the exact change is 20 - 8 = 12 dollars. With the coins you used, you gave him exactly those 12 dollars.", "audio_segment_id": "make-change-1.prompt"}], "schema_version": 1}', '{"make-change-1": {}}', '{"units": {"make-change-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f6e83ab26df0af3fbc70da876b885e40667c0cd681c905cadf44a45b1e8c9606.mp3", "hash": "d98130f7cc9729f24e58f9a182bc78918d16900ee0e9571307165395ff5cf43a", "bytes": 20016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f6e83ab26df0af3fbc70da876b885e40667c0cd681c905cadf44a45b1e8c9606.mp3", "duration_ms": 3280}, "make-change-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/35fe1cd0f0b26c6fbd41b4fab7ee9a94857484f6c8cb6ec49ba0564fe50e8041.mp3", "hash": "1e371cb0adc1dbc402f06b467dea1dd3732d7525eb7f64553d8c7576ec0e85f5", "bytes": 52128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/35fe1cd0f0b26c6fbd41b4fab7ee9a94857484f6c8cb6ec49ba0564fe50e8041.mp3", "duration_ms": 8640}, "make-change-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/da05296b43dfa9c3b14e60da4dc10de8fe3252356b8db9809e4db759adc12b57.mp3", "hash": "2cb948514da8a08c8104d0eafb3f556bdaa8032e4462bf5a35fc130686f8c758", "bytes": 80928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/da05296b43dfa9c3b14e60da4dc10de8fe3252356b8db9809e4db759adc12b57.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Lightning round: quick change", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the exact change in lemonade sales to fill the guitar jar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-1", "xp": 15, "type": "lightning_round", "title": "Lightning round", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1_a", "icon": "paid", "text_md": "10 dollars"}, {"id": "q1_b", "icon": "paid", "text_md": "15 dollars"}, {"id": "q1_c", "icon": "paid", "text_md": "20 dollars"}, {"id": "q1_d", "icon": "paid", "text_md": "0 dollars"}], "prompt_md": "Mrs. Rosa orders 2 glasses and pays with 20 dollars. What is her change?"}, {"id": "q2", "options": [{"id": "q2_a", "icon": "paid", "text_md": "5 dollars"}, {"id": "q2_b", "icon": "paid", "text_md": "10 dollars"}, {"id": "q2_c", "icon": "paid", "text_md": "15 dollars"}, {"id": "q2_d", "icon": "paid", "text_md": "0 dollars"}], "prompt_md": "Mr. Pepe orders 1 glass and pays with 10 dollars. What is his change?"}, {"id": "q3", "options": [{"id": "q3_a", "icon": "paid", "text_md": "5 dollars"}, {"id": "q3_b", "icon": "paid", "text_md": "15 dollars"}, {"id": "q3_c", "icon": "paid", "text_md": "20 dollars"}, {"id": "q3_d", "icon": "paid", "text_md": "10 dollars"}], "prompt_md": "The girl orders 3 glasses and pays with 20 dollars. What is her change?"}, {"id": "q4", "options": [{"id": "q4_a", "icon": "paid", "text_md": "15 dollars"}, {"id": "q4_b", "icon": "paid", "text_md": "10 dollars"}, {"id": "q4_c", "icon": "paid", "text_md": "20 dollars"}, {"id": "q4_d", "icon": "paid", "text_md": "5 dollars"}], "prompt_md": "The man orders 1 glass and pays with 20 dollars. What is his change?"}, {"id": "q5", "options": [{"id": "q5_a", "icon": "cancel", "text_md": "No change needed"}, {"id": "q5_b", "icon": "paid", "text_md": "5 dollars"}, {"id": "q5_c", "icon": "paid", "text_md": "10 dollars"}, {"id": "q5_d", "icon": "paid", "text_md": "15 dollars"}], "prompt_md": "Mrs. Lula orders 2 glasses and pays with 10 exact dollars. What is her change?"}], "seconds_per_q": 15}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Zara sings the orders: each glass costs 5 dollars. Calculate the change quickly before the customer leaves!", "difficulty": 2, "explanation_md": "First add the cost of the glasses: 1 glass = 5 dollars, 2 glasses = 10 dollars, 3 glasses = 15 dollars. Then subtract that total from the bill they paid with. For example, if they pay with 20 for 2 glasses: 20 - 10 = 10 dollars change. Every correct answer brings the 80-dollar guitar closer!", "audio_segment_id": "lightning-round-1.prompt"}], "schema_version": 1}', '{"lightning-round-1": {"correct": {"q1": "q1_a", "q2": "q2_a", "q3": "q3_a", "q4": "q4_a", "q5": "q5_a"}}}', '{"units": {"lightning-round-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/9f8927528fe2e18b24bb7e53a731d747c4489ed1cfe5a4d2c64bc0975392277f.mp3", "hash": "2825ac2790b50a153baa3aaefc16caa903c2db6d2208b678b91c6a955182d2a9", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9f8927528fe2e18b24bb7e53a731d747c4489ed1cfe5a4d2c64bc0975392277f.mp3", "duration_ms": 5920}, "lightning-round-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/1172322d0183246c7a7bc6a587e6a23f1952c968b968f927588a56a658cf4ab9.mp3", "hash": "9370381aa2b78b31b07492993f5c68bd1f8899e53f7d5b5b7f13bc469f8c3d93", "bytes": 105408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1172322d0183246c7a7bc6a587e6a23f1952c968b968f927588a56a658cf4ab9.mp3", "duration_ms": 17520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "order-steps", "title": "Prioritizing Purchases at the Stand", "locale": "en-US", "subject": "mixed", "objectives": ["Sort purchases by sales priority (what generates income first)", "Distinguish between essential needs and wants that can wait"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-priority-order", "xp": 15, "type": "order_steps", "hints": ["Think: what does Liruf need to sell lemonade today?"], "title": "The order of purchases", "payload": {"items": [{"id": "calcomanias", "icon": "sticky_note_2", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/fc123b0b72dab8a58fa5c6f187bd42c09dac17902915f6669601732854c960fc.webp"}, {"id": "azucar", "icon": "cookie", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/19a0bb5beaf6d69b100b43441414f87e1f2c9950d211918df0fadb7a3c1afe61.webp"}, {"id": "vasos", "icon": "local_drink", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/4ad037f5498f6f3336634dc26b700671f304edf3cee5f8580d49cb81d079bc71.webp"}, {"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/aaba518fa154db8e4e43213decf74dcc3f438cd9441885b9a5a8faf03fd2a962.webp"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Liruf has 20 dollars to buy what''s needed for the stand. Sort the purchases from the most urgent to the one that can wait.", "difficulty": 2, "explanation_md": "Lemons and cups are essential to sell today! Sugar helps the lemonade taste good and sell more, but it can wait after having the basics. Stickers are a want that doesn''t help earn money today, so they go last.", "audio_segment_id": "s1-priority-order.prompt"}], "schema_version": 1}', '{"s1-priority-order": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-priority-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7aed3f0d0ceed67c543aecb91fe86b2d9e95ea7639ee9717f786f0daed8f78ab.mp3", "hash": "70e7cc531e972d8681d25f839417864246c30738b9a91ee8291f9b2d48c109de", "bytes": 23328, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7aed3f0d0ceed67c543aecb91fe86b2d9e95ea7639ee9717f786f0daed8f78ab.mp3", "duration_ms": 3840}, "s1-priority-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/37488824fe9de7c16c0d1717bc2faed53c8c52f819cdeb5510aa420fa61e532b.mp3", "hash": "2d0cd263a27bc83b528aee4e7c9aa6b1158db12341f4e8bcb0446b1e5fd19dc3", "bytes": 44064, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/37488824fe9de7c16c0d1717bc2faed53c8c52f819cdeb5510aa420fa61e532b.mp3", "duration_ms": 7280}, "s1-priority-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/f6c75278ce89b4acbe9c46173c2f62891bc9614ea80b04b52b5145c1e0cee0ce.mp3", "hash": "9024163f3fb8e87815535397a7c9ad42cbfdae5c68fe2e97b31cd91dc915608d", "bytes": 80928, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/f6c75278ce89b4acbe9c46173c2f62891bc9614ea80b04b52b5145c1e0cee0ce.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "Precios revueltos", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar cada producto del puesto con su precio correcto."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 10, "type": "match_pairs", "title": "Precios revueltos", "payload": {"left": [{"id": "vaso-chico", "icon": "local_cafe", "text_md": "Vaso chico", "image_url": "http://localhost:4006/files/lesson-images/9702c5a83f6952c11eca3aadcd41969dbc16246f2935a48ae531e85aabbbebc9.webp"}, {"id": "jarra", "icon": "water_drop", "text_md": "Jarra", "image_url": "http://localhost:4006/files/lesson-images/6d837a16c35590a0e6c0c628d0e35c0d47439ce1ebb0f560b17aee2f17186dcc.webp"}, {"id": "galleta", "icon": "cookie", "text_md": "Galleta", "image_url": "http://localhost:4006/files/lesson-images/0208d79e7aeaaeb5ba7bd1959b17e92b0ec66bd11c422bf8c7f7bf7b90efc0aa.webp"}], "right": [{"id": "precio-5", "text_md": "5 pesos"}, {"id": "precio-20", "text_md": "20 pesos"}, {"id": "precio-3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "El viento tiró las etiquetas de precios. ¡Devuelve cada una a su producto!", "difficulty": 1, "explanation_md": "El vaso chico cuesta 5 pesos; la jarra, 20; y la galleta, 3. Así el puesto está ordenado y los clientes saben qué pagar.", "audio_segment_id": "s1-match-pairs.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["vaso-chico", "precio-5"], ["jarra", "precio-20"], ["galleta", "precio-3"]]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/9c2f82161cdab65a71cf29bf76147ed91d58f56a8749b3713eeba6d431a76630.mp3", "hash": "b611b750ebd1b86d794ded97a33b1bf132fe2b35596a053dbf0ddf06ca8b92a6", "bytes": 30528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9c2f82161cdab65a71cf29bf76147ed91d58f56a8749b3713eeba6d431a76630.mp3", "duration_ms": 5040}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/8b0a25ac2c4cb94c88e93e890833985874a5716111e1e6ec9a1e74e7901b5788.mp3", "hash": "04f6ee6e49a6dfe1fa9e9e3edd8a6a19470407ce94a9f98bd421a97eb08756be", "bytes": 58896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8b0a25ac2c4cb94c88e93e890833985874a5716111e1e6ec9a1e74e7901b5788.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Rodada relâmpago: troco rápido", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco exato nas vendas de limonada para encher o frasco da guitarra."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-1", "xp": 15, "type": "lightning_round", "title": "Rodada relâmpago", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1_a", "icon": "paid", "text_md": "10 reais"}, {"id": "q1_b", "icon": "paid", "text_md": "15 reais"}, {"id": "q1_c", "icon": "paid", "text_md": "20 reais"}, {"id": "q1_d", "icon": "paid", "text_md": "0 reais"}], "prompt_md": "Dona Rosa pede 2 copos e paga com 20 reais. Qual é o troco dela?"}, {"id": "q2", "options": [{"id": "q2_a", "icon": "paid", "text_md": "5 reais"}, {"id": "q2_b", "icon": "paid", "text_md": "10 reais"}, {"id": "q2_c", "icon": "paid", "text_md": "15 reais"}, {"id": "q2_d", "icon": "paid", "text_md": "0 reais"}], "prompt_md": "Seu Pepe pede 1 copo e paga com 10 reais. Qual é o troco dele?"}, {"id": "q3", "options": [{"id": "q3_a", "icon": "paid", "text_md": "5 reais"}, {"id": "q3_b", "icon": "paid", "text_md": "15 reais"}, {"id": "q3_c", "icon": "paid", "text_md": "20 reais"}, {"id": "q3_d", "icon": "paid", "text_md": "10 reais"}], "prompt_md": "A menina pede 3 copos e paga com 20 reais. Qual é o troco dela?"}, {"id": "q4", "options": [{"id": "q4_a", "icon": "paid", "text_md": "15 reais"}, {"id": "q4_b", "icon": "paid", "text_md": "10 reais"}, {"id": "q4_c", "icon": "paid", "text_md": "20 reais"}, {"id": "q4_d", "icon": "paid", "text_md": "5 reais"}], "prompt_md": "O senhor pede 1 copo e paga com 20 reais. Qual é o troco dele?"}, {"id": "q5", "options": [{"id": "q5_a", "icon": "cancel", "text_md": "Não precisa de troco"}, {"id": "q5_b", "icon": "paid", "text_md": "5 reais"}, {"id": "q5_c", "icon": "paid", "text_md": "10 reais"}, {"id": "q5_d", "icon": "paid", "text_md": "15 reais"}], "prompt_md": "Dona Lula pede 2 copos e paga com 10 reais exatos. Qual é o troco dela?"}], "seconds_per_q": 15}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Zara canta os pedidos: cada copo custa 5 reais. Calcule rápido o troco antes que o cliente vá embora!", "difficulty": 2, "explanation_md": "Primeiro some o custo dos copos: 1 copo = 5 reais, 2 copos = 10 reais, 3 copos = 15 reais. Depois subtraia esse total da nota que pagou. Por exemplo, se pagar com 20 por 2 copos: 20 - 10 = 10 reais de troco. Cada acerto aproxima a guitarra de 80 reais!", "audio_segment_id": "lightning-round-1.prompt"}], "schema_version": 1}', '{"lightning-round-1": {"correct": {"q1": "q1_a", "q2": "q2_a", "q3": "q3_a", "q4": "q4_a", "q5": "q5_a"}}}', '{"units": {"lightning-round-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/9771979c1a74cb136d577378c3e3efbbce03abd907f4f8ef8a84a2ac7c9873b4.mp3", "hash": "e6e8880e06c7166ad93ad6e0729ef533d2917484d469a41d6594bbafd2812955", "bytes": 49824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9771979c1a74cb136d577378c3e3efbbce03abd907f4f8ef8a84a2ac7c9873b4.mp3", "duration_ms": 8240}, "lightning-round-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/7bd9cf632a77ac7a6b3b7eebd42ca8107bb9d552e5eda129aea2c0f0bbd8b119.mp3", "hash": "91250eac909f64b18c00b6330b8383d22ce289a0e52f085c6023812198c8837e", "bytes": 130464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7bd9cf632a77ac7a6b3b7eebd42ca8107bb9d552e5eda129aea2c0f0bbd8b119.mp3", "duration_ms": 21680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "odd-one-out", "title": "The odd one out", "locale": "en-US", "subject": "mixed", "objectives": ["Spot which one is NOT an ingredient for lemonade (lemons, sugar, water… and a ball?): to separate the things that actually cost money to make."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Think about what you need to make lemonade: lemons, sugar, and water. Which one is the odd one out?"], "title": "The odd one out", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/cdf4e1fb2d740d9b9f24ce284dbdccac17fe3dea62e7d624535c15b94fdbf951.webp"}, {"id": "azucar", "icon": "coffee", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/1f3d4feb4d5a87ceba75a236aebbb54959e98f39ec7f8285d0d0a2f3ae418fe5.webp"}, {"id": "agua", "icon": "water_drop", "text_md": "Water", "image_url": "http://localhost:4006/files/lesson-images/bd6a7dfc88fd007c7d8b8fdef228bd895a2ac60a311b5f7344094833df979be5.webp"}, {"id": "pelota", "icon": "toys", "text_md": "Ball", "image_url": "http://localhost:4006/files/lesson-images/3e0c38763c34a64542d91e25aac80e5c4d625d4507d53e4d4f2a2986867bd2c0.webp"}], "reasons": [{"id": "razon-1", "text_md": "It is not an ingredient for lemonade."}, {"id": "razon-2", "text_md": "It''s the only one that''s used for playing."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Point out the one that is NOT an ingredient for lemonade. Then choose the reason.", "difficulty": 1, "explanation_md": "The ball is not an ingredient for lemonade. It''s for playing, not for cooking, that''s why it doesn''t belong on Rho''s shopping list.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "razon-1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e2b57ffa40dd65696dcecd4a111db4dc9c851f8047c579f4d6306bdfe83de32d.mp3", "hash": "e345255813e48a4488a28f3367321ffdcfb1517436ebb79e44fce731146ab404", "bytes": 42048, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e2b57ffa40dd65696dcecd4a111db4dc9c851f8047c579f4d6306bdfe83de32d.mp3", "duration_ms": 6960}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/308748bc6543516e0a387c8a48d250102d6c0e0fc9e05e3c6596c523f88d0f38.mp3", "hash": "dfd4ce6a0c968612c1d2e50dca56b61b340ac422f53decfbdd3c1f80a47dae3d", "bytes": 32544, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/308748bc6543516e0a387c8a48d250102d6c0e0fc9e05e3c6596c523f88d0f38.mp3", "duration_ms": 5360}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/5d30cbf67ba0f09f5a8b5d650e4c36c2ccfa4caaf35c3bac97226966d3824dac.mp3", "hash": "3e8da1da7d919271b370b33b88cfc47018742bcaa3fbd0da086a2edd01cca212", "bytes": 21024, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5d30cbf67ba0f09f5a8b5d650e4c36c2ccfa4caaf35c3bac97226966d3824dac.mp3", "duration_ms": 3440}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/3a58cdbdcdd984386bc50b73ae4dbe3ad3dacaefe165a5bfd4225d44fa506408.mp3", "hash": "262d13d198fa218011d005ad78fc12dcca8855b4c512d3d8b875e7d93bb95525", "bytes": 57888, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3a58cdbdcdd984386bc50b73ae4dbe3ad3dacaefe165a5bfd4225d44fa506408.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "A máquina de gorjetas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir a regra da máquina de gorjetas: duplica a entrada."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Compara o número que entra com o que sai. Qual operação a máquina fez?"], "title": "A máquina da avó", "payload": {"examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 4}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de medir os copos, a avó traz a sua máquina de gorjetas. Entra 1→2, entra 3→6. Quanto sai com 4?", "difficulty": 2, "explanation_md": "A máquina duplica o que entra. Se você coloca 4, devolve 8, porque 4 + 4 = 8. Que legal! 💡", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/949851480e749179dd2d1346e88e9ba4085ebad36efecc2cd95b63927e70c02b.mp3", "hash": "5c95854323d1a04e554847090b24b14d77baf8886a3a5f2faa9a8806764546cd", "bytes": 30528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/949851480e749179dd2d1346e88e9ba4085ebad36efecc2cd95b63927e70c02b.mp3", "duration_ms": 5040}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/9e93c262df54e06a38812022b739f4548d92e748174eb64ef265bb63963447f4.mp3", "hash": "de5339cda1ff0ba982e46d3547651a46e1cbff67cd4271b46416311a3a991486", "bytes": 63648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9e93c262df54e06a38812022b739f4548d92e748174eb64ef265bb63963447f4.mp3", "duration_ms": 10560}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/96beebad7f77b962f565d19344fcb8b2ebeca8ff9e2b1140207fa9432c6d6ea1.mp3", "hash": "f365ae2895980f8ad746847ae55b301c6fee4fc1be4db2d31ded723dd4467c69", "bytes": 58896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/96beebad7f77b962f565d19344fcb8b2ebeca8ff9e2b1140207fa9432c6d6ea1.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "O dinheiro paciente cresce", "locale": "pt-BR", "subject": "mixed", "objectives": ["Prever quanto cresce uma poupança quando se deixa em um cofrinho que dá uma recompensa semanal."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 15, "type": "interest_peek", "title": "Cresce de pouquinho!", "payload": {"periods": 4, "currency": "BRL", "rate_pct": 10, "principal": 20, "prediction": {"max": 50, "min": 0, "kind": "slider"}}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf coloca 20 reais no cofrinho que ''agradece'' toda semana. Quanto terá depois de 4 semanas?", "difficulty": 2, "explanation_md": "O cofrinho adicionou 2 reais toda semana. Depois de 4 semanas, Liruf tem 28 reais. A paciência fez seu dinheiro crescer rumo à guitarra.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 28, "tolerance": 2}}', '{"units": {"s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/5b9a85d8668ac3ad943bba2b5e1b88f7086c97fd414a49a5a730696e14eed7ef.mp3", "hash": "7a804abca00af11eecce3dbfa2f2e3891b0f3d4bcc95adace8de5951ce3f91bb", "bytes": 55008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5b9a85d8668ac3ad943bba2b5e1b88f7086c97fd414a49a5a730696e14eed7ef.mp3", "duration_ms": 9120}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/c4b8884f8e2459e9c43522741188898ec981d52eb0a588e5a10aa1798498b6ff.mp3", "hash": "b7ef89dbd2aea42a837c4e3990626bd0810f1a444a6e86a9e75967f4dc9b743d", "bytes": 64656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c4b8884f8e2459e9c43522741188898ec981d52eb0a588e5a10aa1798498b6ff.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "evidence-hunt", "title": "Find the evidence on the receipt", "locale": "en-US", "subject": "mixed", "objectives": ["Detect the exact evidence of the cost of the lemons on a receipt."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 5, "type": "evidence_hunt", "title": "Find the evidence", "payload": {"claim_md": "The lemons cost 12 dollars.", "sentences": [{"id": "e1-limones", "text_md": "Bag of lemons — $12"}, {"id": "e1-azucar", "text_md": "Package of sugar — $20"}, {"id": "e1-vasos", "text_md": "Package of cups — $35"}, {"id": "e1-total", "text_md": "Total — $67"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/569cd097ec5c7c9d72094d00bcac4e6c5fa9221ecd4203a308ebc4725904c3a8.webp", "prompt_md": "Liruf found a crumpled receipt. Tap the line that shows the cost of the lemons.", "difficulty": 1, "explanation_md": "The line ''Bag of lemons — $12'' is the evidence that the lemons cost 12 dollars. This way Liruf can check his accounts!", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["e1-limones"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/313d52043b0f69bf7cfd031e1389e48a385165691d506cc68454d00bf334aa03.mp3", "hash": "38285c7d30479bda6180300595c02e5f4673ffffe34bc4617bf1cbb78aec66a1", "bytes": 26784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/313d52043b0f69bf7cfd031e1389e48a385165691d506cc68454d00bf334aa03.mp3", "duration_ms": 4400}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/19a05b241421b9ad24c7ae776c813b7e611053b3506856ae6b9efdd87d4192da.mp3", "hash": "b32d6f323979a3516d7e79b9436dd26d54ffd908eba5d4bc0a4fe0c5e4a90487", "bytes": 43056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/19a05b241421b9ad24c7ae776c813b7e611053b3506856ae6b9efdd87d4192da.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Facts vs Opinions at the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Distinguish between facts and opinions in phrases at a lemonade stand."], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "fact-opinion-1", "xp": 15, "type": "fact_opinion", "hints": ["A fact can be proven true or false. An opinion is what someone feels or thinks."], "title": "Facts vs Opinions", "payload": {"statements": [{"id": "s1", "text_md": "The glass of lemonade costs 5 dollars."}, {"id": "s2", "text_md": "It''s the best lemonade in town."}, {"id": "s3", "text_md": "Our recipe includes sugar, lemons, and water."}, {"id": "s4", "text_md": "We''re open Monday through Friday."}, {"id": "s5", "text_md": "Our customers say they love it."}, {"id": "s6", "text_md": "It tastes like pure summer."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/eb4e702c560cdfd7763ee9145bee9fd6e471318213ecde375f8a6c9a91027c84.webp", "prompt_md": "To avoid falling into traps, look at what is a verifiable fact. Tap the phrases that are FACTS at Liruf''s stand.", "difficulty": 2, "explanation_md": "Your friend Liruf says her lemonade costs 5 dollars: that''s a fact. But that it''s ''the best'' is her opinion, because for others it might not be. Look at what can be proven!", "audio_segment_id": "fact-opinion-1.prompt"}], "schema_version": 1}', '{"fact-opinion-1": {"fact_ids": ["s1", "s3", "s4"]}}', '{"units": {"fact-opinion-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/29d68ed2f077b46586f759d52c73b5db6a22ceb29713e5941972417f23d16bf4.mp3", "hash": "05fd9ac2f220273a9e9ee52ab76c4af2e40ba7bc3c749ea7f7239ba0a56d7a46", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/29d68ed2f077b46586f759d52c73b5db6a22ceb29713e5941972417f23d16bf4.mp3", "duration_ms": 4640}, "fact-opinion-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/c236bf9d32fc248eedfa66e0dc7d89e1fcecdb32c2f53ea3fcc63381ef293e1e.mp3", "hash": "a712148e96e7be6b1d79611a1fa9705b99fcfef47f51a1848fc267f7ade79b1a", "bytes": 36288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c236bf9d32fc248eedfa66e0dc7d89e1fcecdb32c2f53ea3fcc63381ef293e1e.mp3", "duration_ms": 6000}, "fact-opinion-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/191f9de19068fb6a5096629565fd7a354bd0bbb0020a4b7ca95b9c5a454b968e.mp3", "hash": "10bf5b35b6a81fe2febb383dc7f4bdaf35559551de582b2a570855b1bca9317c", "bytes": 54576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/191f9de19068fb6a5096629565fd7a354bd0bbb0020a4b7ca95b9c5a454b968e.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "flash-match", "title": "Flash Match: Business Concepts", "locale": "en-US", "subject": "mixed", "objectives": ["Quickly match each business term with its example (savings → piggy bank, cost → lemons, profit → what''s left over)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "title": "Quick Match!", "payload": {"left": [{"id": "ahorro", "icon": "savings", "text_md": "Savings", "image_url": "http://localhost:4006/files/lesson-images/0ffd40525f559f89a315c28cefae3c02f0b06eb86bb5bca46e6212cc64565c29.webp"}, {"id": "costo", "icon": "payments", "text_md": "Cost", "image_url": "http://localhost:4006/files/lesson-images/0d509723d405ac4490776ca106a380b1285ea97752afcbfb4031a751741ffb42.webp"}, {"id": "ganancia", "icon": "trending_up", "text_md": "Profit", "image_url": "http://localhost:4006/files/lesson-images/9d42d4f12229d80a4c4fabb3876248a54911c4f019921e8a6490615204aadcc2.webp"}], "right": [{"id": "alcancia", "icon": "savings_outlined", "text_md": "Piggy bank"}, {"id": "limones", "icon": "eco", "text_md": "Lemons"}, {"id": "sobra", "icon": "monetization_on", "text_md": "What''s left over"}], "seconds": 20}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Match each business term with its example.", "difficulty": 1, "explanation_md": "Well done! Savings matches with piggy bank because that''s where you save money for the future. Cost matches with lemons because they are a necessary expense. Profit matches with what''s left over after paying costs.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "sobra"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/306cb8305a7752b7faceec6e988bcc08cae8d3817cccf4ca6ca44b03387adbf9.mp3", "hash": "24a9866f4a4c8fb5af6fdc6e9777d1ebb943b5979db8949ad1518bb87f47a34a", "bytes": 17568, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/306cb8305a7752b7faceec6e988bcc08cae8d3817cccf4ca6ca44b03387adbf9.mp3", "duration_ms": 2880}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/fe95437ab06c43299af36a85f617a7400e5ea26d2c8a3a729e8bc7af1422b6fe.mp3", "hash": "b51e355fc83441a1cefe6d86a6fdf1d9e31b300d90bb99fe7081ffbd7899fe6f", "bytes": 78624, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/fe95437ab06c43299af36a85f617a7400e5ea26d2c8a3a729e8bc7af1422b6fe.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Sunny Saturday: lemonade price", "locale": "en-US", "subject": "mixed", "objectives": ["Listen to the situation and decide the day''s price by combining story and decision."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sabado-apertura", "xp": 0, "type": "story_scene", "title": "Saturday''s opening", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/b98298940fa10b8b8ee1153cad4399da26601372cd4a4ac05e5166dbfe1be72b.webp"}, "action": "idle", "body_md": "Liruf remembers how the tip machine doubled: 1 in, 2 out; 3 in, 6 out. But today is real Saturday. Normally the cup costs 5 dollars. And there is a line of customers! ☀️ He has to decide whether to change the price or not.", "emotion": "happy", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf opens the stand.", "difficulty": 1, "audio_segment_id": "s1-sabado-apertura.prompt"}, {"id": "s2-decision-precio", "xp": 15, "type": "quiz_mcq", "hints": ["Think about the price that people already know and that gives you enough for your ingredients."], "title": "Decide the price", "payload": {"options": [{"id": "precio-3", "text_md": "3 dollars", "rationale_md": "If you sell too cheap, you might not earn enough to buy more ingredients."}, {"id": "precio-5", "text_md": "5 dollars"}, {"id": "precio-7", "text_md": "7 dollars", "rationale_md": "If you sell too expensive, maybe few will buy and you won''t earn more. The fair price attracts everyone."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "The normal price is 5 dollars. Today there are many people. How much do you sell each cup for?", "difficulty": 2, "explanation_md": "The always fair price, 5 dollars, is known and people trust. If you raise to 7, you risk losing customers; if you lower to 3, you won''t gather enough for more ingredients. Keep the balance! 🌟", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "precio-5"}}', '{"units": {"s1-sabado-apertura.body": {"url": "http://localhost:4006/files/lesson-audio/eb9c618ae93b042b862657e3ce0716a376e3113590bd4de682bcebdabb18702c.mp3", "hash": "a58a16049a15965921a923b81cd90b22bef1558a8f8a456f0b1f5818d2ab708c", "bytes": 85824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/eb9c618ae93b042b862657e3ce0716a376e3113590bd4de682bcebdabb18702c.mp3", "duration_ms": 14240}, "s1-sabado-apertura.prompt": {"url": "http://localhost:4006/files/lesson-audio/dd1e17764edd2281ef5b321351014942c0111df42d0ee5c54c80c43f3217586d.mp3", "hash": "e56abe21892ced325cd910bc6821ca1067994f7918a1765aeaead6adbfd16c01", "bytes": 9936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dd1e17764edd2281ef5b321351014942c0111df42d0ee5c54c80c43f3217586d.mp3", "duration_ms": 1600}, "s2-decision-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/12bab0dee8a3ad03036325a19c19a336b31aac755fa2366526004189d6ac29eb.mp3", "hash": "bc20c0a92694f9e72e9210e06c3a1749a740604c6e6efc262f51c733286d17ee", "bytes": 27648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/12bab0dee8a3ad03036325a19c19a336b31aac755fa2366526004189d6ac29eb.mp3", "duration_ms": 4560}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc77994d0519ebb04db46a12ebca7351983febe801a170fa020308cc09aa8034.mp3", "hash": "b1771c3bf406e5d1f81372ea8c8e2a3f3b5bdcac0a876488bee57eadaf554a1f", "bytes": 33984, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fc77994d0519ebb04db46a12ebca7351983febe801a170fa020308cc09aa8034.mp3", "duration_ms": 5600}, "s2-decision-precio.choices": {"url": "http://localhost:4006/files/lesson-audio/5261d5735a74ee92a57478e9db17b1026f85c476e102b3be52f559eee9c4ba57.mp3", "hash": "4fcddf7068e6d0e60673d8f500a62c90b284ff81ec1162db3bf9957ff0e31c7c", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5261d5735a74ee92a57478e9db17b1026f85c476e102b3be52f559eee9c4ba57.mp3", "duration_ms": 3040}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/9f82daea258ce414b6e3db8a43cf10814fd23457145945f6686598e564da0c33.mp3", "hash": "98e2ff3f8938a4e5519364455dd6c556ce70663ffacc73e2f9a4549aa1934718", "bytes": 64224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9f82daea258ce414b6e3db8a43cf10814fd23457145945f6686598e564da0c33.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "spot-error", "title": "Buscando el error en la cuenta", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1", "xp": 15, "type": "spot_error", "hints": ["Suma los precios de los tres vasos. ¿El total que anotó Liruf es correcto?"], "title": "Buscando el error en la cuenta", "payload": {"steps": [{"id": "sale1", "text_md": "Vendí un vaso por 5 pesos"}, {"id": "sale2", "text_md": "Vendí otro vaso por 5 pesos"}, {"id": "sale3", "text_md": "Vendí un tercer vaso por 5 pesos"}, {"id": "total", "text_md": "Total del día: 20 pesos"}], "context_md": "Liruf anota las ventas del día en su cuaderno."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/05b7e5bfb7561c1c8bbdcc569c3356a8496946add9204fbe1cf09102dba9c4ad.webp", "prompt_md": "Algo no cuadra en la cuenta de Liruf. Toca el paso donde está el error.", "difficulty": 2, "explanation_md": "El total correcto es 15 pesos, porque 5+5+5=15. Liruf se equivocó al escribir 20. ¡Qué buen ojo para encontrar el error!", "audio_segment_id": "s1.prompt"}], "schema_version": 1}', '{"s1": {"error_ids": ["total"], "correction_md": "5+5+5 es 15, no 20. El total correcto es 15 pesos."}}', '{"units": {"s1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5255fefcf276c32aeef96207a1d78150b65f9b6ba91e0ed790be5c35d7c16f6d.mp3", "hash": "228c44d3abaf750a7a23d17b1f40919e57c5e30aee2f0096ed37a9c2fd0b71c8", "bytes": 28656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5255fefcf276c32aeef96207a1d78150b65f9b6ba91e0ed790be5c35d7c16f6d.mp3", "duration_ms": 4720}, "s1.prompt": {"url": "http://localhost:4006/files/lesson-audio/2fbc4773549113d237f922b597f2deff3134edcad893b2c00b3ed5a9bbe44060.mp3", "hash": "4d173050c162923df99b812611fae2bfa82c5d14f81a8d97c838443c1378377e", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2fbc4773549113d237f922b597f2deff3134edcad893b2c00b3ed5a9bbe44060.mp3", "duration_ms": 4640}, "s1.explanation": {"url": "http://localhost:4006/files/lesson-audio/1a1af58ad4c06033053c842bdb916ba4836673be9838456bc5153079e7ae5e08.mp3", "hash": "2dea23e18a068370e352712f6d487180aeaccadf372706378bd471792e4e8289", "bytes": 62784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1a1af58ad4c06033053c842bdb916ba4836673be9838456bc5153079e7ae5e08.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "repaso-true-false", "title": "Repaso Rápido: ¿Ganancia o Ingreso?", "locale": "es-MX", "subject": "mixed", "objectives": ["Distinguir entre ingresos y ganancia en un puesto de limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-true-false", "xp": 15, "type": "true_false", "hints": ["Calcula el costo total de hacer los 10 vasos (2 pesos cada uno) y réstalo de los 50 pesos que entraron."], "title": "¿Verdadero o falso?", "payload": {"statement_md": "Liruf ganó 50 pesos.", "justifications": [{"id": "j1", "text_md": "Sí, porque 10 vasos × 5 pesos = 50 pesos."}, {"id": "j2", "text_md": "No, porque el costo de los ingredientes fue 20 pesos, así que ganó 30 pesos."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho le dice a Liruf: \\"Vendiste 10 vasos a 5 pesos, y cada uno cuesta 2 pesos. ¿Ganaste 50 pesos?\\" ¿Es verdadero o falso?", "difficulty": 2, "explanation_md": "Ganó 30 pesos, porque 50 pesos de venta menos 20 pesos de costo deja 30 pesos de ganancia. No confundas el dinero que entra con lo que realmente ganas después de pagar los ingredientes.", "audio_segment_id": "s1-repaso-true-false.prompt"}], "schema_version": 1}', '{"s1-repaso-true-false": {"is_true": false, "correct_justification_id": "j2"}}', '{"units": {"s1-repaso-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b7d761197f4d6e6fbbe5507f991612e3f26fe9e08f7b62f20f55fdd9519a63cd.mp3", "hash": "86608f483232653c3037d08d72e829a132dd02ea4591da6134b41e479abc9f86", "bytes": 47376, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b7d761197f4d6e6fbbe5507f991612e3f26fe9e08f7b62f20f55fdd9519a63cd.mp3", "duration_ms": 7840}, "s1-repaso-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/d8f9a3d86a8a469fb5cde4c6d9e481b8dc6a8f8f3127436443c629441d439993.mp3", "hash": "30c6cf9aeaa1873454716ff95899415513db5c6ecbb0628739ac8a00a3c10395", "bytes": 58464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d8f9a3d86a8a469fb5cde4c6d9e481b8dc6a8f8f3127436443c629441d439993.mp3", "duration_ms": 9680}, "s1-repaso-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/602dbd62c5acd13b28f274fc98e883da1f04d7e16f279c2c9f8c7d69bb4e29da.mp3", "hash": "d5ed0361778e49f9c137596b9daad9174f33f4f0f9bc04b246c886bedfaec966", "bytes": 79488, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/602dbd62c5acd13b28f274fc98e883da1f04d7e16f279c2c9f8c7d69bb4e29da.mp3", "duration_ms": 13200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "red-flags", "title": "Detecta ofertas engañosas", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar señales de alerta en ofertas demasiado buenas."], "estimated_minutes": 3}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-oferta-sospechosa", "xp": 15, "type": "red_flags", "hints": ["Piensa si la promesa es demasiado buena para ser cierta."], "title": "Oferta sospechosa", "payload": {"flags": [{"id": "f1", "text_md": "Promete $100 mañana por solo $20 hoy."}, {"id": "f2", "text_md": "Tiene un dibujo de monedas brillantes."}, {"id": "f3", "text_md": "No explica qué hará con el dinero."}, {"id": "f4", "text_md": "El cartel usa colores llamativos."}, {"id": "f5", "text_md": "Dice ''¡Solo hoy!'' para apresurar."}], "artifact_md": "Un cartel colorido dice: ¡Invierte $20 y mañana te doy $100! ¡Garantizado! Pregunta por Don Rufino. ¡Solo hoy!", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/7dc991985ab9a8e8dd7642091bb3022f8669835f494acab678b0dd1f487990d4.webp", "prompt_md": "Luego de revisar el recibo, Liruf ve este anuncio. ¿Qué señales de alerta hay? Toca las frases sospechosas.", "difficulty": 2, "explanation_md": "Las ofertas que prometen mucho dinero rápido sin explicar cómo, suelen ser engañosas. Es importante desconfiar y no entregar dinero a desconocidos.", "audio_segment_id": "s1-oferta-sospechosa.prompt"}], "schema_version": 1}', '{"s1-oferta-sospechosa": {"redflag_ids": ["f1", "f3", "f5"]}}', '{"units": {"s1-oferta-sospechosa.hint.0": {"url": "http://localhost:4006/files/lesson-audio/851a90095d892b06150b7e0b718cf4b48c35ee9c441e16400780c0d471af377a.mp3", "hash": "5ffa6b1d58bb3a873492c0a6867ed2cd694ee11d99b58217ae801a7b585c16ee", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/851a90095d892b06150b7e0b718cf4b48c35ee9c441e16400780c0d471af377a.mp3", "duration_ms": 3600}, "s1-oferta-sospechosa.prompt": {"url": "http://localhost:4006/files/lesson-audio/c79051ac7175597166d41ab278f07eaa307a263ebe7d1f1c7a4cbd8121f93f30.mp3", "hash": "9eab2621c2252921536013c85f33c95a90eff5fc2291e283f5c375c176013a18", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c79051ac7175597166d41ab278f07eaa307a263ebe7d1f1c7a4cbd8121f93f30.mp3", "duration_ms": 7600}, "s1-oferta-sospechosa.explanation": {"url": "http://localhost:4006/files/lesson-audio/9fdc9a45aa116289c8082261306230385a54d71b747749a35ae7a7f5b2a0e20e.mp3", "hash": "d73050b59043719cd37f6bd9d0ff0923d6bf5de44e8a1fb823f1a843dbb6db90", "bytes": 57024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9fdc9a45aa116289c8082261306230385a54d71b747749a35ae7a7f5b2a0e20e.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "repaso-true-false", "title": "Revisão Rápida: Lucro ou Receita?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Distinguir entre receita e lucro em uma barraca de limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-true-false", "xp": 15, "type": "true_false", "hints": ["Calcule o custo total de fazer os 10 copos (2 reais cada um) e subtraia dos 50 reais que entraram."], "title": "Verdadeiro ou falso?", "payload": {"statement_md": "Liruf lucrou 50 reais.", "justifications": [{"id": "j1", "text_md": "Sim, porque 10 copos × 5 reais = 50 reais."}, {"id": "j2", "text_md": "Não, porque o custo dos ingredientes foi 20 reais, então lucrou 30 reais."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rho diz a Liruf: \\"Você vendeu 10 copos a 5 reais, e cada um custa 2 reais. Você lucrou 50 reais?\\" É verdadeiro ou falso?", "difficulty": 2, "explanation_md": "Lucrou 30 reais, porque 50 reais de venda menos 20 reais de custo deixa 30 reais de lucro. Não confunda o dinheiro que entra com o que você realmente ganha depois de pagar os ingredientes.", "audio_segment_id": "s1-repaso-true-false.prompt"}], "schema_version": 1}', '{"s1-repaso-true-false": {"is_true": false, "correct_justification_id": "j2"}}', '{"units": {"s1-repaso-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/aa4fc0700a48fd29606f14244ec3b11ba7e8846d7ea82d3af0ff5724f2e497d3.mp3", "hash": "336974272e023c80a92e1f043105cc4b90bc52e5a4242e18303972c9f02fc769", "bytes": 47376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/aa4fc0700a48fd29606f14244ec3b11ba7e8846d7ea82d3af0ff5724f2e497d3.mp3", "duration_ms": 7840}, "s1-repaso-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f87b892e0d839f157d32b1b7d1b5727c357773208bbb094a13de2ef79fe76c9.mp3", "hash": "9ff9307b239cad0031ba6256e8ad68de5d82c48945e3340f93adc425fec025d3", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2f87b892e0d839f157d32b1b7d1b5727c357773208bbb094a13de2ef79fe76c9.mp3", "duration_ms": 10880}, "s1-repaso-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/874cb6146d0bbb1cf59e2c21dd08d4ffac2b952d71ca98713d1095a118316957.mp3", "hash": "a9343343a4e33f7416fcc75bc77a950f67b171b7f8fcb5fe961b8a5fcd1a4717", "bytes": 84384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/874cb6146d0bbb1cf59e2c21dd08d4ffac2b952d71ca98713d1095a118316957.mp3", "duration_ms": 14000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "speed-tap", "title": "¡Rápido! Elige gastos que ayudan", "locale": "es-MX", "subject": "money", "objectives": ["Tomar decisiones rápidas sobre gastos que ayudan a vender más limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Piensa: ¿se usa para hacer limonada o para atraer clientes? Si no, déjalo pasar."], "title": "¿Ayuda a vender?", "payload": {"items": [{"id": "calco", "icon": "sticky_note_2", "text_md": "Calcomanía de dinosaurio"}, {"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/23f74254e245c3d45a9332e25c01a9ccbdb0be33eef19ca830574be9aaf8542d.webp"}, {"id": "dulce", "icon": "cookie", "text_md": "Dulce", "image_url": "http://localhost:4006/files/lesson-images/dcb18c68887860dd4a4bca23749314272e34047a5f5191547ab9091dbc728e90.webp"}, {"id": "vasos", "icon": "water_bottle", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/eb87037f80540805bb8d630b9b18628287c5fc64e99fef63a9893aff61c3cd58.webp"}, {"id": "cartel", "icon": "flag", "text_md": "Cartel", "image_url": "http://localhost:4006/files/lesson-images/9c0aa8799ba0e9e1e54f6ac58e3d235d6d825a72fbb9bcd90a35c8e4df809f39.webp"}, {"id": "juguete", "icon": "toys", "text_md": "Juguete", "image_url": "http://localhost:4006/files/lesson-images/e4072991efe3c4c374f5f21d1816bdb0ac07d6e047253e77ad22249845753423.webp"}, {"id": "azucar", "icon": "cookie", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/a541255ac8e9de524d4c8ac1a463eb3a5b20fb42d79df839f95aea6c062e849d.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/65cf7775d692ffee1fe707494c55f43448d200bc492e4f62bcf617874872df31.webp"}], "seconds": 25, "instruction_md": "Toca rápido las compras que ayudan."}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Rho te pasa tarjetas volando. Toca solo las compras que ayudan a vender MÁS limonada. ¡Rápido!", "difficulty": 2, "explanation_md": "Los limones, vasos, azúcar y hielo son ingredientes de la limonada. Un cartel bonito atrae más clientes. Una calcomanía, un dulce o un juguete no llenan el frasco de Liruf.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6b2928b4663d95cf0953928d2a7855614a12e70e60d146c021dfeb0d6d4e1778.mp3", "hash": "c60009eb8882eed95542ac283fe55e5f9b293731bc17a08f147034f8f499fc4c", "bytes": 38304, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6b2928b4663d95cf0953928d2a7855614a12e70e60d146c021dfeb0d6d4e1778.mp3", "duration_ms": 6320}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/b5aebfa5ea55d06ea6b073d9a0f425e5d702982dd5e0c441f86e96fba5aa0d73.mp3", "hash": "83cf72d0354c8631ebd9a4cf86cf70584c837c5744a152307d224b4c84f7843a", "bytes": 39744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b5aebfa5ea55d06ea6b073d9a0f425e5d702982dd5e0c441f86e96fba5aa0d73.mp3", "duration_ms": 6560}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/0ead2148a4317a2e1e746ffee88d910a8605d3823e5bcdf9cb3b09d91bcff622.mp3", "hash": "c81452bfb081ea8d15af3b84c86636e556423f53e4604cb04858eb8e01a5d2fc", "bytes": 76176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ead2148a4317a2e1e746ffee88d910a8605d3823e5bcdf9cb3b09d91bcff622.mp3", "duration_ms": 12640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "code-order", "title": "La registradora de cartón de Rho", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar los pasos para usar una registradora casera"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "code-order-1", "xp": 5, "type": "code_order", "title": "Instrucciones de la registradora", "payload": {"blocks": [{"id": "recibir", "text_md": "Recibir pago"}, {"id": "verificar", "text_md": "Verificar monto"}, {"id": "dar_cambio", "text_md": "Dar cambio"}, {"id": "anotar", "text_md": "Anotar la venta"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho inventó una registradora de cartón. Toca los bloques en el orden correcto para usarla.", "difficulty": 1, "explanation_md": "El orden correcto es: recibir el pago, verificar el monto, dar el cambio y anotar la venta. ¡Así la registradora de cartón de Rho funciona sin errores!", "audio_segment_id": "code-order-1.prompt"}], "schema_version": 1}', '{"code-order-1": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"code-order-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/89c36078255ca1acac6b9832c48d2b44015960bcf1ed3ad4977c9a0a55da806a.mp3", "hash": "cb93acbdd614efe898a0a6155bb86e78123efce0619b77b96eda2bfadc470ef2", "bytes": 40176, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/89c36078255ca1acac6b9832c48d2b44015960bcf1ed3ad4977c9a0a55da806a.mp3", "duration_ms": 6640}, "code-order-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/de79d0d0d99c6dde93531dd2874cc001bb5287b446d4f415f41b650b1ebabe5c.mp3", "hash": "8c2c585ab9f8ad4c3be733bc4087c60dd30a81308721f2995e45204c51896095", "bytes": 66528, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/de79d0d0d99c6dde93531dd2874cc001bb5287b446d4f415f41b650b1ebabe5c.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "O plano de Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem, e que uma meta clara (o violão de 80 reais) ajuda a começar."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-scene", "xp": 0, "type": "story_scene", "title": "O plano de Liruf", "payload": {"art": {"icon": "lightbulb", "tint": "accent", "image_url": "http://localhost:4006/files/lesson-images/4b40c43d6eb57627c9d327434aadc89d402e0b4d213c0be74186f9334610e7da.webp"}, "body_md": "Depois de falar com Dina, Liruf tem uma ideia brilhante. 🍋 Desenha seu plano em uma cartolina: cada copo de limonada custa 5 reais, e com cada venda ele se aproxima mais do seu violão de 80 reais. Se vender copos e mais copos, o violão será seu!", "emotion": "excited", "backdrop": "base", "character": "liruf"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Veja o plano de Liruf.", "difficulty": 1, "audio_segment_id": "s1-scene.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-scene.body": {"url": "http://localhost:4006/files/lesson-audio/7c44fce7cc3583aa02a5951c988a57bded5a8e6f46aa71e3d61126391f49a5ff.mp3", "hash": "28074331fb0bec777b4d59be84ee35e9d44b58296fa0330557f7e10acee02dd8", "bytes": 107424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7c44fce7cc3583aa02a5951c988a57bded5a8e6f46aa71e3d61126391f49a5ff.mp3", "duration_ms": 17840}, "s1-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/1e7e2f0a6cc72937d39b76cf0ddf7d5ba257c05089a97cfc15491e20a3d0feba.mp3", "hash": "30e72b69ee27c82f0069807ed3e5ecd250aa05a572f42f492c0f817854f84a84", "bytes": 10368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1e7e2f0a6cc72937d39b76cf0ddf7d5ba257c05089a97cfc15491e20a3d0feba.mp3", "duration_ms": 1680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "Patient money grows", "locale": "en-US", "subject": "mixed", "objectives": ["Predict how much savings grow when left in a piggy bank that gives a weekly reward."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 15, "type": "interest_peek", "title": "It grows little by little!", "payload": {"periods": 4, "currency": "USD", "rate_pct": 10, "principal": 20, "prediction": {"max": 50, "min": 0, "kind": "slider"}}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf puts 20 dollars into the piggy bank that ''thanks'' each week. How much will Liruf have after 4 weeks?", "difficulty": 2, "explanation_md": "The piggy bank added 2 dollars each week. After 4 weeks, Liruf has 28 dollars. Patience made Liruf''s money grow toward the guitar.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 28, "tolerance": 2}}', '{"units": {"s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/3a6d3a891daf5364ea1e184abe46b0679ac4ce337d64a81e08638371849322ee.mp3", "hash": "06701c0c6dcfccfa627d2de6c70498d7b6d58c47de011ed4c2971239ba531233", "bytes": 37296, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a6d3a891daf5364ea1e184abe46b0679ac4ce337d64a81e08638371849322ee.mp3", "duration_ms": 6160}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/9ea520d87ceb638af09e72179c6d6bdcf691884ab312cf6362ffb6e847c75463.mp3", "hash": "fe2779adafe2a51fa3931b408e5606da55abac53835e225d9531d6e07043f150", "bytes": 43488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9ea520d87ceb638af09e72179c6d6bdcf691884ab312cf6362ffb6e847c75463.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Sábado soleado: precio de la limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Escuchar la situación y decidir el precio del día combinando historia y decisión."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sabado-apertura", "xp": 0, "type": "story_scene", "title": "Apertura del sábado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/b98298940fa10b8b8ee1153cad4399da26601372cd4a4ac05e5166dbfe1be72b.webp"}, "action": "idle", "body_md": "Liruf recuerda cómo la máquina de propinas duplicaba: entra 1, sale 2; entra 3, sale 6. Pero hoy es sábado real. Normalmente el vaso cuesta 5 pesos. ¡Y hay una fila de clientes! ☀️ Tiene que decidir si cambia el precio o no.", "emotion": "happy", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf abre el puesto.", "difficulty": 1, "audio_segment_id": "s1-sabado-apertura.prompt"}, {"id": "s2-decision-precio", "xp": 15, "type": "quiz_mcq", "hints": ["Piensa en el precio que la gente ya conoce y que te da suficiente para tus ingredientes."], "title": "Decide el precio", "payload": {"options": [{"id": "precio-3", "text_md": "3 pesos", "rationale_md": "Si vendes muy barato, podrías no ganar lo suficiente para comprar más ingredientes."}, {"id": "precio-5", "text_md": "5 pesos"}, {"id": "precio-7", "text_md": "7 pesos", "rationale_md": "Si vendes muy caro, tal vez pocos compren y no ganes más. El precio justo atrae a todos."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "El precio normal es 5 pesos. Hoy hay mucha gente. ¿A cuánto vendes cada vaso?", "difficulty": 2, "explanation_md": "El precio justo de siempre, 5 pesos, es conocido y la gente confía. Si subes a 7, arriesgas perder clientes; si bajas a 3, no juntas para más ingredientes. ¡Mantén el equilibrio! 🌟", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "precio-5"}}', '{"units": {"s1-sabado-apertura.body": {"url": "http://localhost:4006/files/lesson-audio/28f568a4f3cb32bb104f62b04ab008166cc4a8ea32a7481aa0f393a87bb7e69b.mp3", "hash": "c7a86a7b684addd628d72082fc71151b568069af1b669b3281257c8527f47215", "bytes": 98208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/28f568a4f3cb32bb104f62b04ab008166cc4a8ea32a7481aa0f393a87bb7e69b.mp3", "duration_ms": 16320}, "s1-sabado-apertura.prompt": {"url": "http://localhost:4006/files/lesson-audio/4497fee52d7273d49170ebadc7970c6d3303f4b9c2d92d058e0755b0919f9502.mp3", "hash": "b964a16872040cc21068ff996f8abcd1b00b3fe52f80e3fd622f96689e6e64bb", "bytes": 10368, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4497fee52d7273d49170ebadc7970c6d3303f4b9c2d92d058e0755b0919f9502.mp3", "duration_ms": 1680}, "s2-decision-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/971c68a3dcb294d6eee02a558faac6bbde6fb56b827e1cb053808e8734a4b140.mp3", "hash": "7fd323b0a79450426264aee22f7aaf90eee9cacb07f3098a73ba1130d9df1e7c", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/971c68a3dcb294d6eee02a558faac6bbde6fb56b827e1cb053808e8734a4b140.mp3", "duration_ms": 5840}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/1bb7ab9e2cb731b5275eb77acc3ceefea03f2ccd9e78208585b594dc03d22687.mp3", "hash": "31bd5abcfb2d6a2e6c1d9b9bb121b03d23423ca6668e914805ab8475678651f8", "bytes": 36288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1bb7ab9e2cb731b5275eb77acc3ceefea03f2ccd9e78208585b594dc03d22687.mp3", "duration_ms": 6000}, "s2-decision-precio.choices": {"url": "http://localhost:4006/files/lesson-audio/0c866877f0e6b4b1ebb53f0bb49235ce74e0c4f1e4c28a0f1ec64fe6ba66c470.mp3", "hash": "7c427e23e266c93cdaf72498e1063c528dfc43410d2fa2a78ad0a0bb3d187fdd", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0c866877f0e6b4b1ebb53f0bb49235ce74e0c4f1e4c28a0f1ec64fe6ba66c470.mp3", "duration_ms": 3520}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/33ec4c432c618f67627e7b86e76028ce897752470e9cb912779d76688a3b7d5d.mp3", "hash": "60003be998d91c12401d46687e50acb1afa81edb1542fc85b99b8f9eddb529ee", "bytes": 86688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/33ec4c432c618f67627e7b86e76028ce897752470e9cb912779d76688a3b7d5d.mp3", "duration_ms": 14400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classify purchases for the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Classify purchases into lemonade stand needs and wants that can wait."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort", "xp": 10, "type": "sort_buckets", "title": "Need or want?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/7d9472b044ee532f11a80b6786f3eba28c63e2599c11c8be981b5243e2c7d5cb.webp"}, {"id": "vasos", "icon": "local_drink", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/0639608c7c8f6cd9e63e97af1b17b0cd62dae847d6a4d42848ab2143b81bacaf.webp"}, {"id": "stickers", "icon": "sticky_note_2", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/6864fbb6a2bfc7d7630f86e9709565b218e611ffb8f90b9f037396f3d34501a2.webp"}, {"id": "globos", "icon": "celebration", "text_md": "Balloons", "image_url": "http://localhost:4006/files/lesson-images/3ef6823477bf5d5253cbe527dd70266b70e5dceb98d300b6949140a9545241b9.webp"}], "buckets": [{"id": "necesidad", "label": "Stand NEED"}, {"id": "gusto", "label": "Want that can wait"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Classify each purchase: is it a lemonade stand need or a want that can wait?", "difficulty": 1, "explanation_md": "For Liruf, lemons and cups are NEEDS because without them she can''t make or serve lemonade. Stickers and balloons are wants that can wait.", "audio_segment_id": "s1-sort.prompt"}], "schema_version": 1}', '{"s1-sort": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort.prompt": {"url": "http://localhost:4006/files/lesson-audio/5fd3deaa126ad0960a9400069f18ad1867aee7e68886bfbe8e8dd87bd3d2ae0b.mp3", "hash": "d7bde5fada2bf2c141c91f74cbd0e9b30ba938b0abb51a70dc9630634ac51174", "bytes": 27648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5fd3deaa126ad0960a9400069f18ad1867aee7e68886bfbe8e8dd87bd3d2ae0b.mp3", "duration_ms": 4560}, "s1-sort.explanation": {"url": "http://localhost:4006/files/lesson-audio/bd754b7da8c7d8205ea378cd248015fe514ccded91e1f59bc7b242b2a5a42c0c.mp3", "hash": "b68d0ad9339a86f2d1f2b1e9d2a52dddd3dec4d48b0b591066f19aa8a04f5c74", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bd754b7da8c7d8205ea378cd248015fe514ccded91e1f59bc7b242b2a5a42c0c.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "Mixed-up Prices", "locale": "en-US", "subject": "mixed", "objectives": ["Match each item at the stand with its correct price."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 10, "type": "match_pairs", "title": "Mixed-up Prices", "payload": {"left": [{"id": "vaso-chico", "icon": "local_cafe", "text_md": "Small cup", "image_url": "http://localhost:4006/files/lesson-images/9702c5a83f6952c11eca3aadcd41969dbc16246f2935a48ae531e85aabbbebc9.webp"}, {"id": "jarra", "icon": "water_drop", "text_md": "Pitcher", "image_url": "http://localhost:4006/files/lesson-images/6d837a16c35590a0e6c0c628d0e35c0d47439ce1ebb0f560b17aee2f17186dcc.webp"}, {"id": "galleta", "icon": "cookie", "text_md": "Cookie", "image_url": "http://localhost:4006/files/lesson-images/0208d79e7aeaaeb5ba7bd1959b17e92b0ec66bd11c422bf8c7f7bf7b90efc0aa.webp"}], "right": [{"id": "precio-5", "text_md": "5 dollars"}, {"id": "precio-20", "text_md": "20 dollars"}, {"id": "precio-3", "text_md": "3 dollars"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "The wind blew the price tags off. Put each one back where it belongs!", "difficulty": 1, "explanation_md": "The small cup costs 5 dollars; the pitcher costs 20; and the cookie costs 3. With the stand organized, customers know what to pay.", "audio_segment_id": "s1-match-pairs.prompt"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["vaso-chico", "precio-5"], ["jarra", "precio-20"], ["galleta", "precio-3"]]}}', '{"units": {"s1-match-pairs.prompt": {"url": "http://localhost:4006/files/lesson-audio/3831689158757bc0f338105563f8f888430a36fc23d26ffa1bcaa829f2d94ed4.mp3", "hash": "c11ef4a0c198b365a90c0460dde7369325309ab118f87f65af60983cd4bdebd8", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3831689158757bc0f338105563f8f888430a36fc23d26ffa1bcaa829f2d94ed4.mp3", "duration_ms": 3760}, "s1-match-pairs.explanation": {"url": "http://localhost:4006/files/lesson-audio/14466fa7e0561997b74ba92025ba80fe494f196cb647b2cb9ad5930ae58fcdc5.mp3", "hash": "5b8b8de4adc563fdc7d158d423578d70c70b57e0b7067c8ad1b1eaad6d219bcb", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/14466fa7e0561997b74ba92025ba80fe494f196cb647b2cb9ad5930ae58fcdc5.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "The tip machine", "locale": "en-US", "subject": "mixed", "objectives": ["Discover the rule of the tip machine: it doubles the input."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Compare the number that goes in with the one that comes out. What operation did the machine do?"], "title": "Grandma''s machine", "payload": {"examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 4}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After measuring the cups, Grandma brings her tip machine. In goes 1→2, in goes 3→6. How much comes out with 4?", "difficulty": 2, "explanation_md": "The machine doubles what goes in. If you put in 4, it returns 8, because 4 + 4 = 8. Awesome! 💡", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/31a0832cdbdb92caabb40976cd7368dbc5b9369da726f6bd49b8545365f793d2.mp3", "hash": "0a80644e7561be0934eae411224666ee014b91af187ea51d6fde2a086f9d9e32", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/31a0832cdbdb92caabb40976cd7368dbc5b9369da726f6bd49b8545365f793d2.mp3", "duration_ms": 4960}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/adda4fc3d41a136fd82526b509a43046f07f0615932f9ea5f104ace8478481e4.mp3", "hash": "91eb226a5c860efdf325888132da4eb2f21fa2dcdc3d1eea3d725b38601c0b93", "bytes": 46368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/adda4fc3d41a136fd82526b509a43046f07f0615932f9ea5f104ace8478481e4.mp3", "duration_ms": 7680}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/018ffef57474e3b408d2b5ecfc104b799188c6f8502bc57e646d2f864a54100b.mp3", "hash": "f0091484aaae930a3076708a45fef80d9c1aeb27f3dce80399b4311e0147e310", "bytes": 38736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/018ffef57474e3b408d2b5ecfc104b799188c6f8502bc57e646d2f864a54100b.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "red-flags", "title": "Spot misleading offers", "locale": "en-US", "subject": "mixed", "objectives": ["Identify warning signs in offers that sound too good."], "estimated_minutes": 3}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-oferta-sospechosa", "xp": 15, "type": "red_flags", "hints": ["Think about whether the promise is too good to be true."], "title": "Suspicious offer", "payload": {"flags": [{"id": "f1", "text_md": "Promises $100 tomorrow for just $20 today."}, {"id": "f2", "text_md": "It has a drawing of shiny coins."}, {"id": "f3", "text_md": "It doesn''t explain what it will do with the money."}, {"id": "f4", "text_md": "The sign uses bright colors."}, {"id": "f5", "text_md": "It says ''Today only!'' to make you rush."}], "artifact_md": "A colorful sign says: Invest $20 and tomorrow I''ll give you $100! Guaranteed! Ask for Mr. Rufino. Today only!", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/7dc991985ab9a8e8dd7642091bb3022f8669835f494acab678b0dd1f487990d4.webp", "prompt_md": "After checking the receipt, Liruf sees this ad. What warning signs are there? Tap the suspicious phrases.", "difficulty": 2, "explanation_md": "Offers that promise lots of money fast without explaining how are usually misleading. It''s important to be cautious and not give money to strangers.", "audio_segment_id": "s1-oferta-sospechosa.prompt"}], "schema_version": 1}', '{"s1-oferta-sospechosa": {"redflag_ids": ["f1", "f3", "f5"]}}', '{"units": {"s1-oferta-sospechosa.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a93a669f5b7d08a8f7135a040c805dd951fd21f3fa8789edf3dea029fa76652f.mp3", "hash": "7a9fdbc197ead907598e9067001a78419b86ddaef39b38899dfde5053d1492b3", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a93a669f5b7d08a8f7135a040c805dd951fd21f3fa8789edf3dea029fa76652f.mp3", "duration_ms": 2560}, "s1-oferta-sospechosa.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d86df4dbab76e1c3580de7db4f351def2ba94897fbf339f6611a48fd6fb6c6d.mp3", "hash": "fda44e57b9e79fa3efd98523fc646bbb7fff1320239cb68c2b4af21299633154", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6d86df4dbab76e1c3580de7db4f351def2ba94897fbf339f6611a48fd6fb6c6d.mp3", "duration_ms": 5440}, "s1-oferta-sospechosa.explanation": {"url": "http://localhost:4006/files/lesson-audio/8237ca81197a0258bd79e49b5abd3d48fbf79c6855652fe0c4f784ecc9fa54cd.mp3", "hash": "4a6749e32c38e2e5c6c5a40de44df96c3a5a0ff1df381e2f4be0ae91b1c981fb", "bytes": 45504, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8237ca81197a0258bd79e49b5abd3d48fbf79c6855652fe0c4f784ecc9fa54cd.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "odd-one-out", "title": "El que sobra", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar cuál NO es un ingrediente de la limonada (limones, azúcar, agua… ¿y una pelota?): separar lo que sí cuesta dinero producir."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Piensa en lo que necesitas para hacer limonada: limones, azúcar y agua. ¿Cuál sobra?"], "title": "El que sobra", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/cdf4e1fb2d740d9b9f24ce284dbdccac17fe3dea62e7d624535c15b94fdbf951.webp"}, {"id": "azucar", "icon": "coffee", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/1f3d4feb4d5a87ceba75a236aebbb54959e98f39ec7f8285d0d0a2f3ae418fe5.webp"}, {"id": "agua", "icon": "water_drop", "text_md": "Agua", "image_url": "http://localhost:4006/files/lesson-images/bd6a7dfc88fd007c7d8b8fdef228bd895a2ac60a311b5f7344094833df979be5.webp"}, {"id": "pelota", "icon": "toys", "text_md": "Pelota", "image_url": "http://localhost:4006/files/lesson-images/3e0c38763c34a64542d91e25aac80e5c4d625d4507d53e4d4f2a2986867bd2c0.webp"}], "reasons": [{"id": "razon-1", "text_md": "No es un ingrediente de la limonada."}, {"id": "razon-2", "text_md": "Es la única que se usa para jugar."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Señala el que NO es un ingrediente de la limonada. Luego elige la razón.", "difficulty": 1, "explanation_md": "La pelota no es un ingrediente de la limonada. Es para jugar, no para cocinar, por eso no pertenece a la lista de compras de Rho.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "razon-1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b79b64ac504d22e4a81f42edcebccddc143b712ece280e7b9c8b95271a5e725b.mp3", "hash": "29c9ca7adc424b2fa14f63a47babb40fe37ed2cce0343e95e391ad0db22fd385", "bytes": 39168, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/b79b64ac504d22e4a81f42edcebccddc143b712ece280e7b9c8b95271a5e725b.mp3", "duration_ms": 6480}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/b7a0d03e6d594387be5b1bf31ac26faf5739346defcdf3204562a155aeb5f7c5.mp3", "hash": "af4683ac35b08777331f46cec82338703f17a3facc01355d501a27a5025f202e", "bytes": 37296, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/b7a0d03e6d594387be5b1bf31ac26faf5739346defcdf3204562a155aeb5f7c5.mp3", "duration_ms": 6160}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/1c30b4bbe37f31a60e7d8d7fe752c31c59894d4453e4a7f5c8d13e633318b59c.mp3", "hash": "a1a2bef575005d71f01810e0c5e01bc1f3b3ffeba747c0b6eca175da695f8cc5", "bytes": 21888, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/1c30b4bbe37f31a60e7d8d7fe752c31c59894d4453e4a7f5c8d13e633318b59c.mp3", "duration_ms": 3600}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/a97595fbceab40cd97547a5b6611dd1b48d9f6c7071a4817c8e882b0dbc63702.mp3", "hash": "061e54193d4849924291af9f445cd78dd94c91c1bd05d2e1c1360a03d5ead02b", "bytes": 50688, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a97595fbceab40cd97547a5b6611dd1b48d9f6c7071a4817c8e882b0dbc63702.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "memory-flip", "title": "Memorama de precios del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar cada producto con el pago exacto usando los precios del puesto."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "memory-flip-prices", "xp": 15, "type": "memory_flip", "hints": ["Los precios de ayer: galleta 3, vaso chico 5, jarra 20."], "title": "Empareja los precios", "payload": {"pairs": [{"a_md": "Galleta", "b_md": "1 y 2 pesos", "a_icon": "cookie", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/7e08eb104527f9e19b43e6f4c46fde6f687edc06508a674a213c437a2c701052.webp", "b_image_url": "http://localhost:4006/files/lesson-images/e612cd7c6ecc289a9dc1586e5016094c1bf5a4a67f986825c198db17d1822f4b.webp"}, {"a_md": "Vaso chico", "b_md": "5 pesos", "a_icon": "local_drink", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/c4981a45d33ffb26545f219cc83c32f909327aab9e0dffe06b21aa4828b8feac.webp", "b_image_url": "http://localhost:4006/files/lesson-images/e0347735f17251ad0deaff00ce72847ee14f922161da80b671936a4bab1502ef.webp"}, {"a_md": "Jarra grande", "b_md": "10 y 10 pesos", "a_icon": "local_bar", "b_icon": "currency_exchange", "a_image_url": "http://localhost:4006/files/lesson-images/73e4853ef3cef5374997f20b8ace852298c49c69573a6c420466638c0e6e57a7.webp", "b_image_url": "http://localhost:4006/files/lesson-images/cffded90b4eb127e36abec5e5b25c697762bb2b09e64fbf01bf6fe8ab0495a2d.webp"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Empareja cada producto con las monedas que lo pagan.", "difficulty": 2, "explanation_md": "La galleta cuesta 3 pesos, el vaso chico 5 y la jarra 20. ¡Saber los precios de memoria te hace un cajero veloz!", "audio_segment_id": "memory-flip-prices.prompt"}], "schema_version": 1}', '{}', '{"units": {"memory-flip-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4962c86ae14e654689363fc1878851b0dcf7be8a5520b2834bf9a613e6ac66eb.mp3", "hash": "f8038708443b480d368bce39648cb70144c3bad683945217a4534d248d8a6aee", "bytes": 29088, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/4962c86ae14e654689363fc1878851b0dcf7be8a5520b2834bf9a613e6ac66eb.mp3", "duration_ms": 4800}, "memory-flip-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/02519dfcf75cc1b535e7e2713481e5e7fe278ce9956a986c49d522d2c931dc6a.mp3", "hash": "5e941ae88fdb3e6fa29a8f6e94214405b5dc793e4a2fe5eac3439f0fa75a598f", "bytes": 18576, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/02519dfcf75cc1b535e7e2713481e5e7fe278ce9956a986c49d522d2c931dc6a.mp3", "duration_ms": 3040}, "memory-flip-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/c67b052f2f144c38e09f839a5dd68ad67f5d6cbc81aec24d5c347d6ed7d35ebc.mp3", "hash": "d285618f7ccc2769f3adaf1eb7d5d62606f3ba26f0a2562987356739bf142c9f", "bytes": 49824, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c67b052f2f144c38e09f839a5dd68ad67f5d6cbc81aec24d5c347d6ed7d35ebc.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "red-flags", "title": "Detecte ofertas enganosas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar sinais de alerta em ofertas boas demais."], "estimated_minutes": 3}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-oferta-sospechosa", "xp": 15, "type": "red_flags", "hints": ["Pense se a promessa é boa demais para ser verdade."], "title": "Oferta suspeita", "payload": {"flags": [{"id": "f1", "text_md": "Promete R$100 amanhã por apenas R$20 hoje."}, {"id": "f2", "text_md": "Tem um desenho de moedas brilhantes."}, {"id": "f3", "text_md": "Não explica o que fará com o dinheiro."}, {"id": "f4", "text_md": "O cartaz usa cores chamativas."}, {"id": "f5", "text_md": "Diz ''Só hoje!'' para apressar."}], "artifact_md": "Um cartaz colorido diz: ¡Invista R$20 e amanhã te dou R$100! ¡Garantido! Pergunte pelo Seu Rufino. ¡Só hoje!", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/7dc991985ab9a8e8dd7642091bb3022f8669835f494acab678b0dd1f487990d4.webp", "prompt_md": "Depois de revisar o recibo, Liruf vê este anúncio. Quais sinais de alerta há? Toque nas frases suspeitas.", "difficulty": 2, "explanation_md": "Ofertas que prometem muito dinheiro rápido, sem explicar como, costumam ser enganosas. É importante desconfiar e não entregar dinheiro a desconhecidos.", "audio_segment_id": "s1-oferta-sospechosa.prompt"}], "schema_version": 1}', '{"s1-oferta-sospechosa": {"redflag_ids": ["f1", "f3", "f5"]}}', '{"units": {"s1-oferta-sospechosa.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5672ae3ed4eea70b1ccfa55255900364edeb399754580719545f3604f0724f3a.mp3", "hash": "f97a77b24b8da2cbac66815791abfd438c71f209938f3fec1a7618880c86433d", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5672ae3ed4eea70b1ccfa55255900364edeb399754580719545f3604f0724f3a.mp3", "duration_ms": 4000}, "s1-oferta-sospechosa.prompt": {"url": "http://localhost:4006/files/lesson-audio/277bed063a07b9d75c4614ffc756a1a0b66d90ab18b03a5c9a0d0bd9258de750.mp3", "hash": "0faec9a58570af24ccb7efc4d41307645eb21234d8f9e7774f7fd85c40c2bdb1", "bytes": 47376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/277bed063a07b9d75c4614ffc756a1a0b66d90ab18b03a5c9a0d0bd9258de750.mp3", "duration_ms": 7840}, "s1-oferta-sospechosa.explanation": {"url": "http://localhost:4006/files/lesson-audio/106adf216256abd023b0ebf66747e8c2bfb2b176b8f85505d5427fbab95dbd40.mp3", "hash": "b9ef25af86f455e27b2624b0a9f6663f8698da912b3e33ddbf0ac7b16a70d25e", "bytes": 63648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/106adf216256abd023b0ebf66747e8c2bfb2b176b8f85505d5427fbab95dbd40.mp3", "duration_ms": 10560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
